(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("isocrates-orations-1-e", [{"sp": "HDR", "t": "Λόγοι, τόμος Αʹ"}, {"sp": "HDR", "t": "Πρὸς Δημόνικον", "st": "1"}, {"sp": "N", "t": "ἐν πολλοῖς μέν, ὦ Δημόνικε, πολὺ διεστώσας εὑρήσομεν τάς τε τῶν σπουδαίων γνώμας καὶ τὰς τῶν φαύλων διανοίας· πολὺ δὲ μεγίστην διαφορὰν εἰλήφασιν ἐν ταῖς πρὸς ἀλλήλους συνηθείαις· οἱ μὲν γὰρ τοὺς φίλους παρόντας μόνον τιμῶσιν, οἱ δὲ καὶ μακρὰν ἀπόντας ἀγαπῶσι· καὶ τὰς μὲν τῶν φαύλων συνηθείας ὀλίγος χρόνος διέλυσε, τὰς δὲ τῶν σπουδαίων φιλίας οὐδ’ ἂν ὁ πᾶς αἰὼν ἐξαλείψειεν.", "st": "1.1"}, {"sp": "N", "t": "ἡγούμενος οὖν πρέπειν τοὺς δόξης ὀρεγομένους καὶ παιδείας ἀντιποιουμένους τῶν σπουδαίων ἀλλὰ μὴ τῶν φαύλων εἶναι μιμητάς, ἀπέσταλκά σοι τόνδε τὸν λόγον δῶρον, τεκμήριον μὲν τῆς πρὸς ὑμᾶς εὐνοίας, σημεῖον δὲ τῆς πρὸς Ἱππόνικον συνηθείας· πρέπει γὰρ τοὺς παῖδας, ὥσπερ τῆς οὐσίας, οὕτω καὶ τῆς φιλίας τῆς πατρικῆς κληρονομεῖν.", "st": "1.2"}, {"sp": "N", "t": "ὁρῶ δὲ καὶ τὴν τύχην ἡμῖν συλλαμβάνουσαν καὶ τὸν παρόντα καιρὸν συναγωνιζόμενον· σὺ μὲν γὰρ παιδείας ἐπιθυμεῖς, ἐγὼ δὲ παιδεύειν ἄλλους ἐπιχειρῶ, καὶ σοὶ μὲν ἀκμὴ φιλοσοφεῖν, ἐγὼ δὲ τοὺς φιλοσοφοῦντας ἐπανορθῶ. ὅσοι μὲν οὖν πρὸς τοὺς ἑαυτῶν φίλους τοὺς προτρεπτικοὺς λόγους συγγράφουσι, καλὸν μὲν ἔργον ἐπιχειροῦσιν,", "st": "1.3"}, {"sp": "N", "t": "οὐ μὴν περί γε τὸ κράτιστον τῆς φιλοσοφίας διατρίβουσιν· ὅσοι δὲ τοῖς νεωτέροις εἰσηγοῦνται μὴ δι’ ὧν τὴν δεινότητα τὴν ἐν τοῖς λόγοις ἀσκήσουσιν, ἀλλ’ ὅπως τὰ τῶν τρόπων ἤθη σπουδαῖοι πεφυκέναι δόξουσι, τοσούτῳ μᾶλλον ἐκείνων τοὺς ἀκούοντας ὠφελοῦσιν, ὅσον οἱ μὲν ἐπὶ λόγον παρακαλοῦσιν, οἱ δὲ τὸν τρόπον αὐτῶν ἐπανορθοῦσι.", "st": "1.4"}, {"sp": "N", "t": "διόπερ ἡμεῖς οὐ παράκλησιν εὑρόντες ἀλλὰ παραίνεσιν γράψαντες, μέλλομέν σοι συμβουλεύειν ὧν χρὴ τοὺς νεωτέρους ὀρέγεσθαι καὶ τίνων ἔργων ἀπέχεσθαι καὶ ποίοις τισὶν ἀνθρώποις ὁμιλεῖν καὶ πῶς τὸν ἑαυτῶν βίον οἰκονομεῖν. ὅσοι γὰρ τοῦ βίου ταύτην τὴν ὁδὸν ἐπορεύθησαν, οὗτοι μόνοι τῆς ἀρετῆς ἐφικέσθαι γνησίως ἠδυνήθησαν, ἧς οὐδὲν κτῆμα σεμνότερον οὐδὲ βεβαιότερόν ἐστι.", "st": "1.5"}, {"sp": "N", "t": "κάλλος μὲν γὰρ ἢ χρόνος ἀνήλωσεν ἢ νόσος ἐμάρανε· πλοῦτος δὲ κακίας μᾶλλον ἢ καλοκαγαθίας ὑπηρέτης ἐστίν, ἐξουσίαν μὲν τῇ ῥᾳθυμίᾳ παρασκευάζων, ἐπὶ δὲ τὰς ἡδονὰς τοὺς νέους παρακαλῶν· ῥώμη δὲ μετὰ μὲν φρονήσεως ὠφέλησεν, ἄνευ δὲ ταύτης πλείω τοὺς ἔχοντας ἔβλαψε, καὶ τὰ μὲν σώματα τῶν ἀσκούντων ἐκόσμησε, ταῖς δὲ τῆς ψυχῆς ἐπιμελείαις ἐπεσκότησεν.", "st": "1.6"}, {"sp": "N", "t": "ἡ δὲ τῆς ἀρετῆς κτῆσις, οἷς ἂν ἀκιβδήλως ταῖς διανοίαις συναυξηθῇ, μόνη μὲν συγγηράσκει, πλούτου δὲ κρείττων, χρησιμωτέρα δὲ εὐγενείας ἐστί, τὰ μὲν τοῖς ἄλλοις ἀδύνατα δυνατὰ καθιστᾶσα, τὰ δὲ τῷ πλήθει φοβερὰ θαρσαλέως ὑπομένουσα, καὶ τὸν μὲν ὄκνον ψόγον, τὸν δὲ πόνον ἔπαινον ἡγουμένη.", "st": "1.7"}, {"sp": "N", "t": "ῥᾴδιον δὲ τοῦτο καταμαθεῖν ἐστιν ἔκ τε τῶν Ἡρακλέους ἄθλων καὶ τῶν Θησέως ἔργων, οἷς ἡ τῶν τρόπων ἀρετὴ τηλικοῦτον εὐδοξίας χαρακτῆρα τοῖς ἔργοις ἐπέβαλεν, ὥστε μηδὲ τὸν ἅπαντα χρόνον δύνασθαι λήθην ἐμποιῆσαι τῶν ἐκείνοις πεπραγμένων.", "st": "1.8"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ καὶ τὰς τοῦ πατρὸς προαιρέσεις ἀναμνησθεὶς οἰκεῖον καὶ καλὸν ἕξεις παράδειγμα τῶν ὑπ’ ἐμοῦ σοι λεγομένων. οὐ γὰρ ὀλιγωρῶν τῆς ἀρετῆς οὐδὲ ῥᾳθυμῶν διετέλεσε τὸν βίον, ἀλλὰ τὸ μὲν σῶμα τοῖς πόνοις ἐγύμναζε, τῇ δὲ ψυχῇ τοὺς κινδύνους ὑπέμενεν. οὐδὲ τὸν πλοῦτον παρακαίρως ἠγάπα, ἀλλ’ ἀπέλαυε μὲν τῶν παρόντων ἀγαθῶν ὡς θνητός, ἐπεμελεῖτο δὲ τῶν ὑπαρχόντων ὡς ἀθάνατος.", "st": "1.9"}, {"sp": "N", "t": "οὐδὲ ταπεινῶς διῴκει τὸν αὑτοῦ βίον, ἀλλὰ φιλόκαλος ἦν καὶ μεγαλοπρεπὴς καὶ τοῖς φίλοις κοινός, καὶ μᾶλλον ἐθαύμαζε τοὺς περὶ αὑτὸν σπουδάζοντας ἢ τοὺς γένει προσήκοντας· ἡγεῖτο γὰρ εἶναι πρὸς ἑταιρίαν πολλῷ κρείττω φύσιν νόμου καὶ τρόπον γένους καὶ προαίρεσιν ἀνάγκης.", "st": "1.10"}, {"sp": "N", "t": "ἐπιλίποι δ’ ἂν ἡμᾶς ὁ πᾶς χρόνος, εἰ πάσας τὰς ἐκείνου πράξεις καταριθμησαίμεθα. ἀλλὰ τὸ μὲν ἀκριβὲς αὐτῶν ἐν ἑτέροις καιροῖς δηλώσομεν, δεῖγμα δὲ τῆς Ἱππονίκου φύσεως νῦν ἐξενηνόχαμεν, πρὸς ὃν δεῖ ζῆν σε ὥσπερ πρὸς παράδειγμα, νόμον μὲν τὸν ἐκείνου τρόπον ἡγησάμενον, μιμητὴν δὲ καὶ ζηλωτὴν τῆς πατρῴας ἀρετῆς γιγνόμενον· αἰσχρὸν γὰρ τοὺς μὲν γραφεῖς ἀπεικάζειν τὰ καλὰ τῶν ζῴων, τοὺς δὲ παῖδας μὴ μιμεῖσθαι τοὺς σπουδαίους τῶν γονέων.", "st": "1.11"}, {"sp": "N", "t": "ἡγοῦ δὲ μηδενὶ τῶν ἀθλητῶν οὕτω προσήκειν ἐπὶ τοὺς ἀνταγωνιστὰς ἀσκεῖν, ὡς σοὶ σκοπεῖν ὅπως ἐφάμιλλος γενήσει τοῖς τοῦ πατρὸς ἐπιτηδεύμασιν. οὕτω δὲ τὴν γνώμην οὐ δυνατὸν διατεθῆναι τὸν μὴ πολλῶν καὶ καλῶν ἀκουσμάτων πεπληρωμένον· τὰ μὲν γὰρ σώματα τοῖς συμμέτροις πόνοις, ἡ δὲ ψυχὴ τοῖς σπουδαίοις λόγοις αὔξεσθαι πέφυκε. διόπερ ἐγώ σοι πειράσομαι συντόμως ὑποθέσθαι, δι’ ὧν ἄν μοι δοκεῖς ἐπιτηδευμάτων πλεῖστον πρὸς ἀρετὴν ἐπιδοῦναι καὶ παρὰ τοῖς ἄλλοις ἅπασιν ἀνθρώποις εὐδοκιμῆσαι.", "st": "1.12"}, {"sp": "N", "t": "πρῶτον μὲν οὖν εὐσέβει τὰ πρὸς τοὺς θεούς, μὴ μόνον θύων, ἀλλὰ καὶ τοῖς ὅρκοις ἐμμένων· ἐκεῖνο μὲν γὰρ τῆς τῶν χρημάτων εὐπορίας σημεῖον, τοῦτο δὲ τῆς τῶν τρόπων καλοκαγαθίας τεκμήριον. τίμα τὸ δαιμόνιον ἀεὶ μέν, μάλιστα δὲ μετὰ τῆς πόλεως· οὕτω γὰρ δόξεις ἅμα τε τοῖς θεοῖς θύειν καὶ τοῖς νόμοις ἐμμένειν.", "st": "1.13"}, {"sp": "N", "t": "τοιοῦτος γίγνου περὶ τοὺς γονεῖς, οἵους ἂν εὔξαιο περὶ σεαυτὸν γενέσθαι τοὺς σεαυτοῦ παῖδας. ἄσκει τῶν περὶ τὸ σῶμα γυμνασίων μὴ τὰ πρὸς τὴν ῥώμην ἀλλὰ τὰ πρὸς τὴν ὑγίειαν· τούτου δ’ ἂν ἐπιτύχοις, εἰ λήγοις τῶν πόνων ἔτι πονεῖν δυνάμενος.", "st": "1.14"}, {"sp": "N", "t": "μήτε γέλωτα προπετῆ στέργε, μήτε λόγον μετὰ θράσους ἀποδέχου· τὸ μὲν γὰρ ἀνόητον, τὸ δὲ μανικόν. ἃ ποιεῖν αἰσχρόν, ταῦτα νόμιζε μηδὲ λέγειν εἶναι καλόν. ἔθιζε σεαυτὸν εἶναι μὴ σκυθρωπὸν ἀλλὰ σύννουν· δι’ ἐκεῖνο μὲν γὰρ αὐθάδης, διὰ δὲ τοῦτο φρόνιμος εἶναι δόξεις. ἡγοῦ μάλιστα σεαυτῷ πρέπειν κόσμον, αἰσχύνην δικαιοσύνην σωφροσύνην· τούτοις γὰρ ἅπασι δοκεῖ κρατεῖσθαι τὸ τῶν νεωτέρων ἦθος.", "st": "1.15"}, {"sp": "N", "t": "μηδέποτε μηδὲν αἰσχρὸν ποιήσας ἔλπιζε λήσειν· καὶ γὰρ ἂν τοὺς ἄλλους λάθῃς, σεαυτῷ συνειδήσεις. τοὺς μὲν θεοὺς φοβοῦ, τοὺς δὲ γονεῖς τίμα, τοὺς δὲ φίλους αἰσχύνου, τοῖς δὲ νόμοις πείθου. τὰς ἡδονὰς θήρευε τὰς μετὰ δόξης· τέρψις γὰρ σὺν τῷ καλῷ μὲν ἄριστον, ἄνευ δὲ τούτου κάκιστον.", "st": "1.16"}, {"sp": "N", "t": "εὐλαβοῦ τὰς διαβολάς, κἂν ψευδεῖς ὦσιν· οἱ γὰρ πολλοὶ τὴν μὲν ἀλήθειαν ἀγνοοῦσι, πρὸς δὲ τὴν δόξαν ἀποβλέπουσιν. ἅπαντα δόκει ποιεῖν ὡς μηδένα λήσων· καὶ γὰρ ἃ παραυτίκα κρύψῃς, ὕστερον ὀφθήσει. μάλιστα δ’ ἂν εὐδοκιμοίης, εἰ φαίνοιο ταῦτα μὴ πράττων, ἃ τοῖς ἄλλοις ἂν πράττουσιν ἐπιτιμῴης.", "st": "1.17"}, {"sp": "N", "t": "ἐὰν ᾖς φιλομαθής, ἔσει πολυμαθής. ἃ μὲν ἐπίστασαι, ταῦτα διαφύλαττε ταῖς μελέταις, ἃ δὲ μὴ μεμάθηκας, προσλάμβανε ταῖς ἐπιστήμαις· ὁμοίως γὰρ αἰσχρὸν ἀκούσαντα χρήσιμον λόγον μὴ μαθεῖν καὶ διδόμενόν τι ἀγαθὸν παρὰ τῶν φίλων μὴ λαβεῖν. κατανάλισκε τὴν ἐν τῷ βίῳ σχολὴν εἰς τὴν τῶν λόγων φιληκοΐαν· οὕτω γὰρ τὰ τοῖς ἄλλοις χαλεπῶς εὑρημένα συμβήσεταί σοι ῥᾳδίως μανθάνειν.", "st": "1.18"}, {"sp": "N", "t": "ἡγοῦ τῶν ἀκουσμάτων πολλὰ πολλῶν εἶναι χρημάτων κρείττω· τὰ μὲν γὰρ ταχέως ἀπολείπει, τὰ δὲ πάντα τὸν χρόνον παραμένει· σοφία γὰρ μόνον τῶν κτημάτων ἀθάνατον. μὴ κατόκνει μακρὰν ὁδὸν πορεύεσθαι πρὸς τοὺς διδάσκειν τι χρήσιμον ἐπαγγελλομένους· αἰσχρὸν γὰρ τοὺς μὲν ἐμπόρους τηλικαῦτα πελάγη διαπερᾶν ἕνεκα τοῦ πλείω ποιῆσαι τὴν ὑπάρχουσαν οὐσίαν, τοὺς δὲ νεωτέρους μηδὲ τὰς κατὰ γῆν πορείας ὑπομένειν ἐπὶ τῷ βελτίω καταστῆσαι τὴν αὑτῶν διάνοιαν.", "st": "1.19"}, {"sp": "N", "t": "τῷ μὲν τρόπῳ γίγνου φιλοπροσήγορος, τῷ δὲ λόγῳ εὐπροσήγορος. ἔστι δὲ φιλοπροσηγορίας μὲν τὸ προσφωνεῖν τοὺς ἀπαντῶντας, εὐπροσηγορίας δὲ τὸ τοῖς λόγοις αὐτοῖς οἰκείως ἐντυγχάνειν. ἡδέως μὲν ἔχε πρὸς ἅπαντας, χρῶ δὲ τοῖς βελτίστοις· οὕτω γὰρ τοῖς μὲν οὐκ ἀπεχθὴς ἔσει, τοῖς δὲ φίλος γενήσει. τὰς ἐντεύξεις μὴ ποιοῦ πυκνὰς τοῖς αὐτοῖς, μηδὲ μακρὰς περὶ τῶν αὐτῶν· πλησμονὴ γὰρ ἁπάντων.", "st": "1.20"}, {"sp": "N", "t": "γύμναζε σεαυτὸν πόνοις ἑκουσίοις, ὅπως ἂν δύνῃ καὶ τοὺς ἀκουσίους ὑπομένειν. ὑφ’ ὧν κρατεῖσθαι τὴν ψυχὴν αἰσχρόν, τούτων ἐγκράτειαν ἄσκει πάντων, κέρδους, ὀργῆς, ἡδονῆς, λύπης. ἔσει δὲ τοιοῦτος, ἐὰν κέρδη μὲν εἶναι νομίζῃς δι’ ὧν εὐδοκιμήσεις ἀλλὰ μὴ δι’ ὧν εὐπορήσεις, τῇ δὲ ὀργῇ παραπλησίως ἔχῃς πρὸς τοὺς ἁμαρτάνοντας ὥσπερ ἂν πρὸς ἑαυτὸν ἁμαρτάνοντα καὶ τοὺς ἄλλους ἔχειν ἀξιώσειας, ἐν δὲ τοῖς τερπνοῖς, ἐὰν αἰσχρὸν ὑπολάβῃς τῶν μὲν οἰκετῶν ἄρχειν ταῖς δ’ ἡδοναῖς δουλεύειν, ἐν δὲ τοῖς πονηροῖς, ἐὰν τὰς τῶν ἄλλων ἀτυχίας ἐπιβλέπῃς καὶ αὑτὸν ὡς ἄνθρωπος ὢν ὑπομιμνήσκῃς.", "st": "1.21"}, {"sp": "N", "t": "μᾶλλον τήρει τὰς τῶν λόγων ἢ τὰς τῶν χρημάτων παρακαταθήκας· δεῖ γὰρ τοὺς ἀγαθοὺς ἄνδρας τρόπον ὅρκου πιστότερον φαίνεσθαι παρεχομένους. προσήκειν ἡγοῦ τοῖς πονηροῖς ἀπιστεῖν, ὥσπερ τοῖς χρηστοῖς πιστεύειν. περὶ τῶν ἀπορρήτων μηδενὶ λέγε, πλὴν ἐὰν ὁμοίως συμφέρῃ τὰς πράξεις σιωπᾶσθαι σοί τε τῷ λέγοντι κἀκείνοις τοῖς ἀκούουσιν.", "st": "1.22"}, {"sp": "N", "t": "ὅρκον ἐπακτὸν προσδέχου διὰ δύο προφάσεις, ἢ σεαυτὸν αἰτίας αἰσχρᾶς ἀπολύων, ἢ φίλους ἐκ μεγάλων κινδύνων διασώζων. ἕνεκα δὲ χρημάτων μηδένα θεῶν ὀμόσῃς, μηδ’ ἂν εὐορκεῖν μέλλῃς· δόξεις γὰρ τοῖς μὲν ἐπιορκεῖν, τοῖς δὲ φιλοχρημάτως ἔχειν.", "st": "1.23"}, {"sp": "N", "t": "μηδένα φίλον ποιοῦ, πρὶν ἂν ἐξετάσῃς πῶς κέχρηται τοῖς πρότερον φίλοις· ἔλπιζε γὰρ αὐτὸν καὶ περὶ σὲ γενέσθαι τοιοῦτον, οἷος καὶ περὶ ἐκείνους γέγονε. βραδέως μὲν φίλος γίγνου, γενόμενος δὲ πειρῶ διαμένειν· ὁμοίως γὰρ αἰσχρὸν μηδένα φίλον ἔχειν καὶ πολλοὺς ἑταίρους μεταλλάττειν. μήτε μετὰ βλάβης πειρῶ τῶν φίλων, μήτ’ ἄπειρος εἶναι τῶν ἑταίρων θέλε. τοῦτο δὲ ποιήσεις, ἐὰν μὴ δεόμενος τὸ δεῖσθαι προσποιῇ.", "st": "1.24"}, {"sp": "N", "t": "περὶ τῶν ῥητῶν ὡς ἀπορρήτων ἀνακοινοῦ· μὴ τυχὼν μὲν γὰρ οὐδὲν βλαβήσει, τυχὼν δὲ μᾶλλον αὐτῶν τὸν τρόπον ἐπιστήσει. δοκίμαζε τοὺς φίλους ἔκ τε τῆς περὶ τὸν βίον ἀτυχίας καὶ τῆς ἐν τοῖς κινδύνοις κοινωνίας· τὸ μὲν γὰρ χρυσίον ἐν τῷ πυρὶ βασανίζομεν, τοὺς δὲ φίλους ἐν ταῖς ἀτυχίαις διαγιγνώσκομεν. οὕτως ἄριστα χρήσει τοῖς φίλοις, ἐὰν μὴ προσμένῃς τὰς παρ’ ἐκείνων δεήσεις, ἀλλ’ αὐτεπάγγελτος αὐτοῖς ἐν τοῖς καιροῖς βοηθῇς.", "st": "1.25"}, {"sp": "N", "t": "ὁμοίως αἰσχρὸν εἶναι νόμιζε τῶν ἐχθρῶν νικᾶσθαι ταῖς κακοποιίαις καὶ τῶν φίλων ἡττᾶσθαι ταῖς εὐεργεσίαις. ἀποδέχου τῶν ἑταίρων μὴ μόνον τοὺς ἐπὶ τοῖς κακοῖς δυσχεραίνοντας, ἀλλὰ καὶ τοὺς ἐπὶ τοῖς ἀγαθοῖς μὴ φθονοῦντας· πολλοὶ γὰρ ἀτυχοῦσι μὲν τοῖς φίλοις συνάχθονται, καλῶς δὲ πράττουσι φθονοῦσι. τῶν ἀπόντων φίλων μέμνησο πρὸς τοὺς παρόντας, ἵνα δοκῇς μηδὲ τούτων ἀπόντων ὀλιγωρεῖν.", "st": "1.26"}, {"sp": "N", "t": "εἶναι βούλου τὰ περὶ τὴν ἐσθῆτα φιλόκαλος, ἀλλὰ μὴ καλλωπιστής. ἔστι δὲ φιλοκάλου μὲν τὸ μεγαλοπρεπές, καλλωπιστοῦ δὲ τὸ περίεργον. ἀγάπα τῶν ὑπαρχόντων ἀγαθῶν μὴ τὴν ὑπερβάλλουσαν κτῆσιν ἀλλὰ τὴν μετρίαν ἀπόλαυσιν. καταφρόνει τῶν περὶ τὸν πλοῦτον σπουδαζόντων μέν, χρῆσθαι δὲ τοῖς ὑπάρχουσι μὴ δυναμένων· παραπλήσιον γὰρ οἱ τοιοῦτοι πάσχουσιν, ὥσπερ ἂν εἴ τις ἵππον κτήσαιτο καλὸν κακῶς ἱππεύειν ἐπιστάμενος.", "st": "1.27"}, {"sp": "N", "t": "πειρῶ τὸν πλοῦτον χρήματα καὶ κτήματα κατασκευάζειν. ἔστι δὲ χρήματα μὲν τοῖς ἀπολαύειν ἐπισταμένοις, κτήματα δὲ τοῖς κτᾶσθαι δυναμένοις. τίμα τὴν ὑπάρχουσαν οὐσίαν δυοῖν ἕνεκεν, τοῦ τε ζημίαν μεγάλην ἐκτῖσαι δύνασθαι, καὶ τοῦ φίλῳ σπουδαίῳ δυστυχοῦντι βοηθῆσαι· πρὸς δὲ τὸν ἄλλον βίον μηδὲν ὑπερβαλλόντως ἀλλὰ μετρίως αὐτὴν ἀγάπα.", "st": "1.28"}, {"sp": "N", "t": "στέργε μὲν τὰ παρόντα, ζήτει δὲ τὰ βελτίω. μηδενὶ συμφορὰν ὀνειδίσῃς· κοινὴ γὰρ ἡ τύχη καὶ τὸ μέλλον ἀόρατον. τοὺς ἀγαθοὺς εὖ ποίει· καλὸς γὰρ θησαυρὸς παρ’ ἀνδρὶ σπουδαίῳ χάρις ὀφειλομένη. τοὺς κακοὺς εὖ ποιῶν ὅμοια πείσει τοῖς τὰς ἀλλοτρίας κύνας σιτίζουσιν· ἐκεῖναί τε γὰρ τοὺς διδόντας ὥσπερ τοὺς τυχόντας ὑλακτοῦσιν, οἵ τε κακοὶ τοὺς ὠφελοῦντας ὥσπερ τοὺς βλάπτοντας ἀδικοῦσι.", "st": "1.29"}, {"sp": "N", "t": "μίσει τοὺς κολακεύοντας ὥσπερ τοὺς ἐξαπατῶντας· ἀμφότεροι γὰρ πιστευθέντες τοὺς πιστεύσαντας ἀδικοῦσιν. ἐὰν ἀποδέχῃ τῶν φίλων τοὺς πρὸς τὸ φαυλότατον χαριζομένους, οὐχ ἕξεις ἐν τῷ βίῳ τοὺς πρὸς τὸ βέλτιστον ἀπεχθανομένους. γίγνου πρὸς τοὺς πλησιάζοντας ὁμιλητικός, ἀλλὰ μὴ σεμνός· τὸν μὲν γὰρ τῶν ὑπεροπτικῶν ὄγκον μόλις ἂν οἱ δοῦλοι καρτερήσειαν, τὸν δὲ τῶν ὁμιλητικῶν τρόπον ἅπαντες ἡδέως ὑποφέρουσιν.", "st": "1.30"}, {"sp": "N", "t": "ὁμιλητικὸς δ’ ἔσει μὴ δύσερις ὢν μηδὲ δυσάρεστος μηδὲ πρὸς πάντας φιλόνικος, μηδὲ πρὸς τὰς τῶν πλησιαζόντων ὀργὰς τραχέως ἀπαντῶν, μηδ’ ἂν ἀδίκως ὀργιζόμενοι τυγχάνωσιν, ἀλλὰ θυμουμένοις μὲν αὐτοῖς εἴκων, πεπαυμένοις δὲ τῆς ὀργῆς ἐπιπλήττων· μηδὲ παρὰ τὰ γελοῖα σπουδάζων, μηδὲ παρὰ τὰ σπουδαῖα τοῖς γελοίοις χαίρων (τὸ γὰρ ἄκαιρον πανταχοῦ λυπηρόν)· μηδὲ τὰς χάριτας ἀχαρίστως χαριζόμενος, ὅπερ πάσχουσιν οἱ πολλοί, ποιοῦντες μέν, ἀηδῶς δὲ τοῖς φίλοις ὑπουργοῦντες· μηδὲ φιλαίτιος ὤν, βαρὺ γάρ, μηδὲ φιλεπιτιμητής, παροξυντικὸν γάρ.", "st": "1.31"}, {"sp": "N", "t": "μάλιστα μὲν εὐλαβοῦ τὰς ἐν τοῖς πότοις συνουσίας· ἐὰν δέ ποτέ σοι συμπέσῃ καιρός, ἐξανίστασο πρὸ μέθης. ὅταν γὰρ ὁ νοῦς ὑπὸ οἴνου διαφθαρῇ, ταὐτὰ πάσχει τοῖς ἅρμασι τοῖς τοὺς ἡνιόχους ἀποβαλοῦσιν· ἐκεῖνά τε γὰρ ἀτάκτως φέρεται διαμαρτόντα τῶν εὐθυνούντων, ἥ τε ψυχὴ πολλὰ σφάλλεται διαφθαρείσης τῆς διανοίας. ἀθάνατα μὲν φρόνει τῷ μεγαλόψυχος εἶναι, θνητὰ δὲ τῷ συμμέτρως τῶν ὑπαρχόντων ἀπολαύειν.", "st": "1.32"}, {"sp": "N", "t": "ἡγοῦ τὴν παιδείαν τοσούτῳ μεῖζον ἀγαθὸν εἶναι τῆς ἀπαιδευσίας, ὅσῳ τὰ μὲν ἄλλα μοχθηρὰ πάντες κερδαίνοντες πράττουσιν, αὕτη δὲ μόνη καὶ προσεζημίωσε τοὺς ἔχοντας· πολλάκις γάρ, ὧν τοῖς λόγοις ἐλύπησαν, τούτων τοῖς ἔργοις τὴν τιμωρίαν ἔδοσαν. οὓς ἂν βούλῃ ποιήσασθαι φίλους, ἀγαθόν τι λέγε περὶ αὐτῶν πρὸς τοὺς ἀπαγγέλλοντας· ἀρχὴ γὰρ φιλίας μὲν ἔπαινος, ἔχθρας δὲ ψόγος.", "st": "1.33"}, {"sp": "N", "t": "βουλευόμενος παραδείγματα ποιοῦ τὰ παρεληλυθότα τῶν μελλόντων· τὸ γὰρ ἀφανὲς ἐκ τοῦ φανεροῦ ταχίστην ἔχει τὴν διάγνωσιν. Βουλεύου μὲν βραδέως, ἐπιτέλει δὲ ταχέως τὰ δόξαντα. ἡγοῦ κράτιστον εἶναι παρὰ μὲν τῶν θεῶν εὐτυχίαν, παρὰ δ’ ἡμῶν αὐτῶν εὐβουλίαν. περὶ ὧν ἂν αἰσχύνῃ παρρησιάσασθαι, βούλῃ δέ τισι τῶν φίλων ἀνακοινώσασθαι, χρῶ τοῖς λόγοις ὡς περὶ ἀλλοτρίου τοῦ πράγματος· οὕτω γὰρ τὴν ἐκείνων τε γνῶσιν αἰσθήσει, καὶ σεαυτὸν οὐ καταφανῆ ποιήσεις.", "st": "1.34"}, {"sp": "N", "t": "ὅταν ὑπὲρ σεαυτοῦ μέλλῃς τινὶ συμβούλῳ χρῆσθαι, σκόπει πρῶτον πῶς τὰ ἑαυτοῦ διῴκησεν· ὁ γὰρ κακῶς διανοηθεὶς περὶ τῶν οἰκείων οὐδέποτε καλῶς βουλεύσεται περὶ τῶν ἀλλοτρίων. οὕτω δ’ ἂν μάλιστα βουλεύεσθαι παροξυνθείης, εἰ τὰς συμφορὰς τὰς ἐκ τῆς ἀβουλίας ἐπιβλέψειας· καὶ γὰρ τῆς ὑγιείας πλείστην ἐπιμέλειαν ἔχομεν, ὅταν τὰς λύπας τὰς ἐκ τῆς ἀρρωστίας ἀναμνησθῶμεν.", "st": "1.35"}, {"sp": "N", "t": "μιμοῦ τὰ τῶν βασιλέων ἤθη καὶ δίωκε τὰ ἐκείνων ἐπιτηδεύματα· δόξεις γὰρ αὐτοὺς ἀποδέχεσθαι καὶ ζηλοῦν, ὥστε σοι συμβήσεται παρά τε τῷ πλήθει μᾶλλον εὐδοκιμεῖν καὶ τὴν παρ’ ἐκείνων εὔνοιαν βεβαιοτέραν ἔχειν. πείθου μὲν καὶ τοῖς νόμοις τοῖς ὑπὸ τῶν βασιλέων κειμένοις, ἰσχυρότατον μέντοι νόμον ἡγοῦ τὸν ἐκείνων τρόπον. ὥσπερ γὰρ τὸν ἐν δημοκρατίᾳ πολιτευόμενον τὸ πλῆθος δεῖ θεραπεύειν, οὕτω καὶ τὸν ἐν μοναρχίᾳ κατοικοῦντα τὸν βασιλέα προσήκει θαυμάζειν.", "st": "1.36"}, {"sp": "N", "t": "εἰς ἀρχὴν κατασταθεὶς μηδενὶ χρῶ πονηρῷ πρὸς τὰς διοικήσεις· ὧν γὰρ ἂν ἐκεῖνος ἁμάρτῃ, σοὶ τὰς αἰτίας ἀναθήσουσιν. ἐκ τῶν κοινῶν ἐπιμελειῶν ἀπαλλάττου μὴ πλουσιώτερος ἀλλ’ ἐνδοξότερος· πολλῶν γὰρ χρημάτων κρείττων ὁ παρὰ τοῦ πλήθους ἔπαινος. μηδενὶ πονηρῷ πράγματι μήτε παρίστασο μήτε συνηγόρει· δόξεις γὰρ καὶ αὐτὸς τοιαῦτα πράττειν, οἷά περ ἂν τοῖς ἄλλοις πράττουσι βοηθῇς.", "st": "1.37"}, {"sp": "N", "t": "παρασκεύαζε σεαυτὸν πλεονεκτεῖν μὲν δύνασθαι, ἀνέχου δὲ τὸ ἴσον ἔχων, ἵνα δοκῇς ὀρέγεσθαι τῆς δικαιοσύνης μὴ δι’ ἀσθένειαν ἀλλὰ δι’ ἐπιείκειαν. μᾶλλον ἀποδέχου δικαίαν πενίαν ἢ πλοῦτον ἄδικον· τοσούτῳ γὰρ κρείττων δικαιοσύνη χρημάτων, ὅσῳ τὰ μὲν ζῶντας μόνον ὠφελεῖ, τὸ δὲ καὶ τελευτήσασι δόξαν παρασκευάζει, κἀκείνων μὲν τοῖς φαύλοις μέτεστι, τούτου δὲ τοῖς μοχθηροῖς ἀδύνατον μεταλαβεῖν.", "st": "1.38"}, {"sp": "N", "t": "μηδένα ζήλου τῶν ἐξ ἀδικίας κερδαινόντων, ἀλλὰ μᾶλλον ἀποδέχου τοὺς μετὰ δικαιοσύνης ζημιωθέντας· οἱ γὰρ δίκαιοι τῶν ἀδίκων εἰ μηδὲν ἄλλο πλεονεκτοῦσιν, ἀλλ’ οὖν ἐλπίσι γε σπουδαίαις ὑπερέχουσιν.", "st": "1.39"}, {"sp": "N", "t": "πάντων μὲν ἐπιμελοῦ τῶν περὶ τὸν βίον, μάλιστα δὲ τὴν σαυτοῦ φρόνησιν ἄσκει· μέγιστον γὰρ ἐν ἐλαχίστῳ νοῦς ἀγαθὸς ἐν ἀνθρώπου σώματι. πειρῶ τῷ μὲν σώματι εἶναι φιλόπονος, τῇ δὲ ψυχῇ φιλόσοφος, ἵνα τῷ μὲν ἐπιτελεῖν δύνῃ τὰ δόξαντα, τῇ δὲ προορᾶν ἐπίστῃ τὰ συμφέροντα.", "st": "1.40"}, {"sp": "N", "t": "πᾶν ὅ τι ἂν μέλλῃς ἐρεῖν, πρότερον ἐπισκόπει τῇ γνώμῃ· πολλοῖς γὰρ ἡ γλῶττα προτρέχει τῆς διανοίας. δύο ποιοῦ καιροὺς τοῦ λέγειν, ἢ περὶ ὧν οἶσθα σαφῶς, ἢ περὶ ὧν ἀναγκαῖον εἰπεῖν. ἐν τούτοις γὰρ μόνοις ὁ λόγος τῆς σιγῆς κρείττων, ἐν δὲ τοῖς ἄλλοις ἄμεινον σιγᾶν ἢ λέγειν.", "st": "1.41"}, {"sp": "N", "t": "νόμιζε μηδὲν εἶναι τῶν ἀνθρωπίνων βέβαιον· οὕτω γὰρ οὔτ’ εὐτυχῶν ἔσει περιχαρὴς οὔτε δυστυχῶν περίλυπος. χαῖρε μὲν ἐπὶ τοῖς συμβαίνουσι τῶν ἀγαθῶν, λυποῦ δὲ μετρίως ἐπὶ τοῖς γιγνομένοις τῶν κακῶν, γίγνου δὲ τοῖς ἄλλοις μηδ’ ἐν ἑτέροις ὢν κατάδηλος· ἄτοπον γὰρ τὴν μὲν οὐσίαν ἐν ταῖς οἰκίαις ἀποκρύπτειν, τὴν δὲ διάνοιαν φανερὰν ἔχοντα περιπατεῖν.", "st": "1.42"}, {"sp": "N", "t": "μᾶλλον εὐλαβοῦ ψόγον ἢ κίνδυνον· δεῖ γὰρ εἶναι φοβερὰν τοῖς μὲν φαύλοις τὴν τοῦ βίου τελευτήν, τοῖς δὲ σπουδαίοις τὴν ἐν τῷ ζῆν ἀδοξίαν. μάλιστα μὲν πειρῶ ζῆν κατὰ τὴν ἀσφάλειαν· ἐὰν δέ ποτέ σοι συμβῇ κινδυνεύειν, ζήτει τὴν ἐκ τοῦ πολέμου σωτηρίαν μετὰ καλῆς δόξης, ἀλλὰ μὴ μετ’ αἰσχρᾶς φήμης· τὸ μὲν γὰρ τελευτῆσαι πάντων ἡ πεπρωμένη κατέκρινε, τὸ δὲ καλῶς ἀποθανεῖν ἴδιον τοῖς σπουδαίοις ἀπένειμεν.", "st": "1.43"}, {"sp": "N", "t": "καὶ μὴ θαυμάσῃς εἰ πολλὰ τῶν εἰρημένων οὐ πρέπει σοι πρὸς τὴν νῦν παροῦσαν ἡλικίαν. οὐδὲ γὰρ ἐμὲ τοῦτο διέλαθεν· ἀλλὰ προειλόμην διὰ τῆς αὐτῆς πραγματείας ἅμα τοῦ τε παρόντος βίου συμβουλίαν ἐξενεγκεῖν καὶ τοῦ μέλλοντος χρόνου παράγγελμα καταλιπεῖν. τὴν μὲν γὰρ τούτων χρείαν ῥᾳδίως εἰδήσεις, τὸν δὲ μετ’ εὐνοίας συμβουλεύοντα χαλεπῶς εὑρήσεις. ὅπως οὖν μὴ παρ’ ἑτέρου τὰ λοιπὰ ζητῇς, ἀλλ’ ἐντεῦθεν ὥσπερ ἐκ ταμιείου προφέρῃς, ᾠήθην δεῖν μηδὲν παραλιπεῖν ὧν ἔχω σοι συμβουλεύειν.", "st": "1.44"}, {"sp": "N", "t": "πολλὴν δ’ ἂν τοῖς θεοῖς χάριν σχοίην, εἰ μὴ διαμάρτοιμι τῆς δόξης ἧς ἔχων περὶ σοῦ τυγχάνω. τῶν μὲν γὰρ ἄλλων τοὺς πλείστους εὑρήσομεν, ὥσπερ τῶν σιτίων τοῖς ἡδίστοις μᾶλλον ἢ τοῖς ὑγιεινοτάτοις χαίροντας, οὕτω καὶ τῶν φίλων τοῖς συνεξαμαρτάνουσι πλησιάζοντας, ἀλλ’ οὐ τοῖς νουθετοῦσι. σὲ δὲ νομίζω τοὐναντίον τούτων ἐγνωκέναι, τεκμηρίῳ χρώμενος τῇ περὶ τὴν ἄλλην παιδείαν φιλοπονία· τὸν γὰρ αὑτῷ τὰ βέλτιστα πράττειν ἐπιτάττοντα, τοῦτον εἰκὸς καὶ τῶν ἄλλων τοὺς ἐπὶ τὴν ἀρετὴν παρακαλοῦντας ἀποδέχεσθαι.", "st": "1.45"}, {"sp": "N", "t": "μάλιστα δ’ ἂν παροξυνθείης ὀρέγεσθαι τῶν καλῶν ἔργων, εἰ καταμάθοις ὅτι καὶ τὰς ἡδονὰς ἐκ τούτων μάλιστα γνησίως ἔχομεν. ἐν μὲν γὰρ τῷ ῥᾳθυμεῖν καὶ τὰς πλησμονὰς ἀγαπᾶν εὐθὺς αἱ λῦπαι ταῖς ἡδοναῖς παραπεπήγασι, τὸ δὲ περὶ τὴν ἀρετὴν φιλοπονεῖν καὶ σωφρόνως τὸν αὑτοῦ βίον οἰκονομεῖν ἀεὶ τὰς τέρψεις εἰλικρινεῖς καὶ βεβαιοτέρας ἀποδίδωσι·", "st": "1.46"}, {"sp": "N", "t": "κἀκεῖ μὲν πρότερον ἡσθέντες ὕστερον ἐλυπήθημεν, ἐνταῦθα δὲ μετὰ τὰς λύπας τὰς ἡδονὰς ἔχομεν. ἐν πᾶσι δὲ τοῖς ἔργοις οὐχ οὕτω τῆς ἀρχῆς μνημονεύομεν, ὡς τῆς τελευτῆς αἴσθησιν λαμβάνομεν· τὰ γὰρ πλεῖστα τῶν περὶ τὸν βίον οὐ δι’ αὐτὰ τὰ πράγματα ποιοῦμεν, ἀλλὰ τῶν ἀποβαινόντων ἕνεκεν διαπονοῦμεν.", "st": "1.47"}, {"sp": "N", "t": "ἐνθυμοῦ δ’ ὅτι τοῖς μὲν φαύλοις ἐνδέχεται τὰ τυχόντα πράττειν· εὐθὺς γὰρ τοῦ βίου τοιαύτην πεποίηνται τὴν ὑπόθεσιν· τοῖς δὲ σπουδαίοις οὐχ οἷόν τε τῆς ἀρετῆς ἀμελεῖν διὰ τὸ πολλοὺς ἔχειν τοὺς ἐπιπλήττοντας. πάντες γὰρ μισοῦσιν οὐχ οὕτω τοὺς ἐξαμαρτάνοντας ὡς τοὺς ἐπιεικεῖς μὲν φήσαντας εἶναι, μηδὲν δὲ τῶν τυχόντων διαφέροντας,", "st": "1.48"}, {"sp": "N", "t": "εἰκότως· ὅπου γὰρ τοὺς τῷ λόγῳ μόνον ψευδομένους ἀποδοκιμάζομεν, ἦ πού γε τοὺς τῷ βίῳ παντὶ ἐλαττουμένους οὐ φαύλους εἶναι φήσομεν; δικαίως δ’ ἂν τοὺς τοιούτους ὑπολάβοιμεν μὴ μόνον εἰς αὑτοὺς ἁμαρτάνειν, ἀλλὰ καὶ τῆς τύχης εἶναι προδότας· ἡ μὲν γὰρ αὐτοῖς χρήματα καὶ δόξαν καὶ φίλους ἐνεχείρισεν, οἱ δὲ σφᾶς αὐτοὺς ἀναξίους τῆς ὑπαρχούσης εὐδαιμονίας κατέστησαν.", "st": "1.49"}, {"sp": "N", "t": "εἰ δὲ δεῖ θνητὸν ὄντα τῆς τῶν θεῶν στοχάσασθαι διανοίας, ἡγοῦμαι κἀκείνους ἐπὶ τοῖς οἰκειοτάτοις μάλιστα δηλῶσαι πῶς ἔχουσι πρὸς τοὺς φαύλους καὶ τοὺς σπουδαίους τῶν ἀνθρώπων. Ζεὺς γὰρ Ἡρακλέα καὶ Τάνταλον γεννήσας, ὡς οἱ μῦθοι λέγουσι καὶ πάντες πιστεύουσι, τὸν μὲν διὰ τὴν ἀρετὴν ἀθάνατον ἐποίησε, τὸν δὲ διὰ τὴν κακίαν ταῖς μεγίσταις τιμωρίαις ἐκόλασεν.", "st": "1.50"}, {"sp": "N", "t": "οἷς δεῖ παραδείγμασι χρωμένους ὀρέγεσθαι τῆς καλοκαγαθίας, καὶ μὴ μόνον τοῖς ὑφ’ ἡμῶν εἰρημένοις ἐμμένειν, ἀλλὰ καὶ τῶν ποιητῶν τὰ βέλτιστα μανθάνειν, καὶ τῶν ἄλλων σοφιστῶν, εἴ τι χρήσιμον εἰρήκασιν,", "st": "1.51"}, {"sp": "N", "t": "ἀναγιγνώσκειν. ὥσπερ γὰρ τὴν μέλιτταν ὁρῶμεν ἐφ’ ἅπαντα μὲν τὰ βλαστήματα καθιζάνουσαν, οὕτω δεῖ καὶ τοὺς παιδείας ὀρεγομένους μηδενὸς μὲν ἀπείρως ἔχειν, πανταχόθεν δὲ τὰ χρήσιμα συλλέγειν. μόλις γὰρ ἄν τις ἐκ ταύτης τῆς ἐπιμελείας τὰς τῆς φύσεως ἁμαρτίας ἐπικρατήσειεν.", "st": "1.52"}, {"sp": "HDR", "t": "Πρὸς Νικοκλέα", "st": "2"}, {"sp": "N", "t": "οἱ μὲν εἰωθότες, ὦ Νικόκλεις, τοῖς βασιλεῦσιν ὑμῖν ἐσθῆτας ἄγειν ἢ χαλκὸν ἢ χρυσὸν εἰργασμένον ἢ τῶν ἄλλων τι τῶν τοιούτων κτημάτων, ὧν αὐτοὶ μὲν ἐνδεεῖς εἰσιν ὑμεῖς δὲ πλουτεῖτε, λίαν ἔδοξαν εἶναί μοι καταφανεῖς οὐ δόσιν ἀλλ’ ἐμπορίαν ποιούμενοι, καὶ πολὺ τεχνικώτερον αὐτὰ πωλοῦντες τῶν ὁμολογούντων καπηλεύειν·", "st": "2.1"}, {"sp": "N", "t": "ἡγησάμην δ’ ἂν γενέσθαι ταύτην καλλίστην δωρεὰν καὶ χρησιμωτάτην καὶ μάλιστα πρέπουσαν ἐμοί τε δοῦναι καὶ σοὶ λαβεῖν, εἰ δυνηθείην ὁρίσαι ποίων ἐπιτηδευμάτων ὀρεγόμενος καὶ τίνων ἀπεχόμενος ἄριστ’ ἂν καὶ τὴν πόλιν καὶ τὴν βασιλείαν διοικοίης. τοὺς μὲν γὰρ ἰδιώτας ἐστὶ πολλὰ τὰ παιδεύοντα, μάλιστα μὲν τὸ μὴ τρυφᾶν ἀλλ’ ἀναγκάζεσθαι περὶ τοῦ βίου καθ’ ἑκάστην τὴν ἡμέραν βουλεύεσθαι,", "st": "2.2"}, {"sp": "N", "t": "ἔπειθ’ οἱ νόμοι καθ’ οὓς ἕκαστοι πολιτευόμενοι τυγχάνουσιν, ἔτι δ’ ἡ παρρησία καὶ τὸ φανερῶς ἐξεῖναι τοῖς τε φίλοις ἐπιπλῆξαι καὶ τοῖς ἐχθροῖς ἐπιθέσθαι ταῖς ἀλλήλων ἁμαρτίαις· πρὸς δὲ τούτοις καὶ τῶν ποιητῶν τινες τῶν προγεγενημένων ὑποθήκας ὡς χρὴ ζῆν καταλελοίπασιν· ὥστ’ ἐξ ἁπάντων τούτων εἰκὸς αὐτοὺς βελτίους γίγνεσθαι.", "st": "2.3"}, {"sp": "N", "t": "τοῖς δὲ τυράννοις οὐδὲν ὑπάρχει τοιοῦτον, ἀλλ’ οὓς ἔδει παιδεύεσθαι μᾶλλον τῶν ἄλλων, ἐπειδὰν εἰς τὴν ἀρχὴν καταστῶσιν, ἀνουθέτητοι διατελοῦσιν· οἱ μὲν γὰρ πλεῖστοι τῶν ἀνθρώπων αὐτοῖς οὐ πλησιάζουσιν, οἱ δὲ συνόντες πρὸς χάριν ὁμιλοῦσι. καὶ γὰρ τοι κύριοι γιγνόμενοι καὶ χρημάτων πλείστων καὶ πραγμάτων μεγίστων, διὰ τὸ μὴ καλῶς χρῆσθαι ταύταις ταῖς ἀφορμαῖς πεποιήκασιν ὥστε πολλοὺς ἀμφισβητεῖν, πότερόν ἐστιν ἄξιον ἑλέσθαι τὸν βίον τὸν τῶν ἰδιωτευόντων μὲν ἐπιεικῶς δὲ πραττόντων, ἢ τὸν τῶν τυραννευόντων.", "st": "2.4"}, {"sp": "N", "t": "ὅταν μὲν γὰρ ἀποβλέψωσιν εἰς τὰς τιμὰς καὶ τοὺς πλούτους καὶ τὰς δυναστείας, ἰσοθέους ἅπαντες νομίζουσι τοὺς ἐν ταῖς μοναρχίαις ὄντας· ἐπειδὰν δ’ ἐνθυμηθῶσι τοὺς φόβους καὶ τοὺς κινδύνους, καὶ διεξιόντες ὁρῶσι τοὺς μὲν ὑφ’ ὧν ἥκιστα χρῆν διεφθαρμένους, τοὺς δ’ εἰς τοὺς οἰκειοτάτους ἐξαμαρτεῖν ἠναγκασμένους, τοῖς δ’ ἀμφότερα ταῦτα συμβεβηκότα, πάλιν ὁπωσοῦν ζῆν ἡγοῦνται λυσιτελεῖν μᾶλλον ἢ μετὰ τοιούτων συμφορῶν ἁπάσης τῆς Ἀσίας βασιλεύειν.", "st": "2.5"}, {"sp": "N", "t": "ταύτης δὲ τῆς ἀνωμαλίας καὶ τῆς ταραχῆς αἴτιόν ἐστιν, ὅτι τὴν βασιλείαν ὥσπερ ἱερωσύνην παντὸς ἀνδρὸς εἶναι νομίζουσιν, ὃ τῶν ἀνθρωπίνων πραγμάτων μέγιστόν ἐστι καὶ πλείστης προνοίας δεόμενον. καθ’ ἑκάστην μὲν οὖν τὴν πρᾶξιν, ἐξ ὧν ἄν τις μάλιστα δύναιτο κατὰ τρόπον διοικεῖν καὶ τὰ μὲν ἀγαθὰ διαφυλάττειν τὰς δὲ συμφορὰς διαφεύγειν, τῶν ἀεὶ παρόντων ἔργον ἐστὶ συμβουλεύειν· καθ’ ὅλων δὲ τῶν ἐπιτηδευμάτων, ὧν χρὴ στοχάζεσθαι καὶ περὶ ἃ δεῖ διατρίβειν, ἐγὼ πειράσομαι διελθεῖν.", "st": "2.6"}, {"sp": "N", "t": "εἰ μὲν οὖν ἔσται τὸ δῶρον ἐξεργασθὲν ἄξιον τῆς ὑποθέσεως, χαλεπὸν ἀπὸ τῆς ἀρχῆς συνιδεῖν· πολλὰ γὰρ καὶ τῶν μετὰ μέτρου ποιημάτων καὶ τῶν καταλογάδην συγγραμμάτων ἔτι μὲν ἐν ταῖς διανοίαις ὄντα τῶν συντιθέντων μεγάλας τὰς προσδοκίας παρέσχεν, ἐπιτελεσθέντα δὲ καὶ τοῖς ἄλλοις ἐπιδειχθέντα πολὺ καταδεεστέραν τὴν δόξαν τῆς ἐλπίδος ἔλαβεν.", "st": "2.7"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ τό γ’ ἐπιχείρημα καλῶς ἔχει, τὸ ζητεῖν τὰ παραλελειμμένα καὶ νομοθετεῖν ταῖς μοναρχίαις· οἱ μὲν γὰρ τοὺς ἰδιώτας παιδεύοντες ἐκείνους μόνον ὠφελοῦσιν· εἰ δέ τις τοὺς κρατοῦντας τοῦ πλήθους ἐπ’ ἀρετὴν προτρέψειεν, ἀμφοτέρους ἂν ὀνήσειε, καὶ τοὺς τὰς δυναστείας ἔχοντας καὶ τοὺς ὑπ’ αὐτοῖς ὄντας· τοῖς μὲν γὰρ ἂν τὰς ἀρχὰς ἀσφαλεστέρας, τοῖς δὲ τὰς πολιτείας πραοτέρας ποιήσειεν.", "st": "2.8"}, {"sp": "N", "t": "πρῶτον μὲν οὖν σκεπτέον τί τῶν βασιλευόντων ἔργον ἐστίν· ἂν γὰρ ἐν κεφαλαίοις τὴν δύναμιν ὅλου τοῦ πράγματος καλῶς περιλάβωμεν, ἐνταῦθ’ ἀποβλέποντες ἄμεινον καὶ περὶ τῶν μερῶν ἐροῦμεν. οἶμαι δὴ πάντας ἂν ὁμολογῆσαι προσήκειν αὐτοῖς πόλιν δυστυχοῦσαν παῦσαι καὶ καλῶς πράττουσαν διαφυλάξαι καὶ μεγάλην ἐκ μικρᾶς ποιῆσαι· τὰ γὰρ ἄλλα τὰ συμπίπτοντα κατὰ τὴν ἡμέραν ἑκάστην τούτων ἕνεκα πρακτέον ἐστί.", "st": "2.9"}, {"sp": "N", "t": "καὶ μὴν ἐκεῖνό γε φανερόν, ὅτι δεῖ τοὺς ταῦτα δυνησομένους καὶ περὶ τηλικούτων βουλευομένους μὴ ῥᾳθυμεῖν μηδ’ ἀμελεῖν, ἀλλὰ σκοπεῖν ὅπως φρονιμώτερον διακείσονται τῶν ἄλλων· δέδεικται γὰρ ὅτι τοιαύτας τὰς βασιλείας ἕξουσιν, οἵας ἂν τὰς ἑαυτῶν γνώμας παρασκευάσωσιν.", "st": "2.10"}, {"sp": "N", "t": "ὥστε οὐδενὶ τῶν ἀσκητῶν οὕτω προσήκει τὸ σῶμα γυμνάζειν, ὡς τοῖς βασιλεῦσι τὴν ψυχὴν τὴν ἑαυτῶν· ἅπασαι γὰρ αἱ πανηγύρεις οὐδὲν μέρος τιθέασιν τούτων τῶν ἄθλων, περὶ ὧν ὑμεῖς καθ’ ἑκάστην τὴν ἡμέραν ἀγωνίζεσθε. ὧν ἐνθυμούμενον χρὴ προσέχειν τὸν νοῦν, ὅπως ὅσον περ ταῖς τιμαῖς τῶν ἄλλων προέχεις, τοσοῦτον καὶ ταῖς ἀρεταῖς αὐτῶν διοίσεις.", "st": "2.11"}, {"sp": "N", "t": "καὶ μὴ νόμιζε τὴν ἐπιμέλειαν ἐν μὲν τοῖς ἄλλοις πράγμασι χρησίμην εἶναι, πρὸς δὲ τὸ βελτίους ἡμᾶς καὶ φρονιμωτέρους γίγνεσθαι μηδεμίαν δύναμιν ἔχειν· μηδὲ καταγνῷς τῶν ἀνθρώπων τοσαύτην δυστυχίαν, ὡς περὶ μὲν τὰ θηρία τέχνας εὑρήκαμεν αἷς αὐτῶν τὰς ψυχὰς ἡμεροῦμεν καὶ πλείονος ἀξίας ποιοῦμεν, ἡμᾶς δ’ αὐτοὺς οὐδὲν ἂν πρὸς ἀρετὴν ὠφελήσαιμεν. ἀλλ’ ὡς καὶ τῆς παιδεύσεως καὶ τῆς ἐπιμελείας μάλιστα δυναμένης τὴν ἡμετέραν φύσιν εὐεργετεῖν, οὕτω διάκεισο τὴν γνώμην,", "st": "2.12"}, {"sp": "N", "t": "καὶ τῶν τε παρόντων τοῖς φρονιμωτάτοις πλησίαζε καὶ τῶν ἄλλων οὓς ἂν δύνῃ μεταπέμπου, καὶ μήτε τῶν ποιητῶν τῶν εὐδοκιμούντων μήτε τῶν σοφιστῶν μηδενὸς οἴου δεῖν ἀπείρως ἔχειν, ἀλλὰ τῶν μὲν ἀκροατὴς γίγνου τῶν δὲ μαθητής, καὶ παρασκεύαζε σεαυτὸν τῶν μὲν ἐλαττόνων κριτὴν τῶν δὲ μειζόνων ἀγωνιστήν· διὰ γὰρ τούτων τῶν γυμνασίων τάχιστ’ ἂν γένοιο τοιοῦτος, οἷον ὑπεθέμεθα δεῖν εἶναι τὸν ὀρθῶς βασιλεύσοντα καὶ τὴν πόλιν ὡς χρὴ διοικήσοντα. μάλιστα δ’ ἂν αὐτὸς ὑπὸ σαυτοῦ παρακληθείης,", "st": "2.13"}, {"sp": "N", "t": "εἰ δεινὸν ἡγήσαιο τοὺς χείρους τῶν βελτιόνων ἄρχειν καὶ τοὺς ἀνοητοτέρους τοῖς φρονιμωτέροις προστάττειν· ὅσῳ γὰρ ἂν ἐρρωμενεστέρως τὴν τῶν ἄλλων ἄνοιαν ἀτιμάσῃς, τοσούτῳ μᾶλλον τὴν αὑτοῦ διάνοιαν ἀσκήσεις.", "st": "2.14"}, {"sp": "N", "t": "ἄρχεσθαι μὲν οὖν ἐντεῦθεν χρὴ τοὺς μέλλοντάς τι τῶν δεόντων ποιήσειν, πρὸς δὲ τούτοις φιλάνθρωπον εἶναι δεῖ καὶ φιλόπολιν· οὔτε γὰρ ἵππων οὔτε κυνῶν οὔτ’ ἄλλου πράγματος οὐδενὸς οἷόν τε καλῶς ἄρχειν, ἂν μή τις χαίρῃ τούτοις ὧν αὐτὸν δεῖ ποιεῖσθαι τὴν ἐπιμέλειαν. μελέτω σοι τοῦ πλήθους, καὶ περὶ παντὸς ποιοῦ κεχαρισμένως αὐτοῖς ἄρχειν,", "st": "2.15"}, {"sp": "N", "t": "γιγνώσκων ὅτι καὶ τῶν ὀλιγαρχιῶν καὶ τῶν ἄλλων πολιτειῶν αὗται πλεῖτον χρόνον διαμένουσιν, αἵ τινες ἂν ἄριστα τὸ πλῆθος θεραπεύωσιν. καλῶς δὲ δημαγωγήσεις, ἔαν μήθ’ ὑβρίζειν τὸν ὄχλον ἐᾷς μήθ’ ὑβριζόμενον περιορᾷς, ἀλλὰ σκοπῇς ὅπως οἱ βέλτιστοι μὲν τὰς τιμὰς ἕξουσιν, οἱ δ’ ἄλλοι μηδὲν ἀδικήσονται· ταῦτα γὰρ στοιχεῖα πρῶτα καὶ μέγιστα χρηστῆς πολιτείας ἐστίν.", "st": "2.16"}, {"sp": "N", "t": "τῶν προσταγμάτων καὶ τῶν ἐπιτηδευμάτων κίνει καὶ μετατίθει τὰ μὴ καλῶς καθεστῶτα, καὶ μάλιστα μὲν εὑρετὴς γίγνου τῶν βελτίστων, εἰ δὲ μή, μιμοῦ τὰ παρὰ τοῖς ἄλλοις ὀρθῶς ἔχοντα. ζήτει νόμους τὸ μὲν σύμπαν δικαίους καὶ συμφέροντας καὶ σφίσιν αὐτοῖς ὁμολογουμένους, πρὸς δὲ τούτοις οἵ τινες τὰς μὲν ἀμφισβητήσεις ὡς ἐλαχίστας τὰς δὲ διαλύσεις ὡς οἷόν τε ταχίστας τοῖς πολίταις ποιοῦσι· ταῦτα γὰρ ἅπαντα προσεῖναι δεῖ τοῖς καλῶς κειμένοις νόμοις.", "st": "2.17"}, {"sp": "N", "t": "τὰς μὲν ἐργασίας αὐτοῖς καθίστη κερδαλέας, τὰς δὲ πραγματείας ἐπιζημίους, ἵνα τὰς μὲν φεύγωσι, πρὸς δὲ τὰς προθυμότερον ἔχωσιν. τὰς κρίσεις ποιοῦ περὶ ὧν ἂν πρὸς ἀλλήλους ἀμφισβητῶσι, μὴ πρὸς χάριν μηδ’ ἐναντίας ἀλλήλαις, ἀλλ’ ἀεὶ ταὐτὰ περὶ τῶν αὐτῶν γίγνωσκε· καὶ γὰρ πρέπει καὶ συμφέρει τὴν τῶν βασιλέων γνώμην ἀκινήτως ἔχειν περὶ τῶν δικαίων, ὥσπερ τοὺς νόμους τοὺς καλῶς κειμένους. οἴκει τὴν πόλιν ὁμοίως ὥσπερ τὸν πατρῷον οἶκον,", "st": "2.18"}, {"sp": "N", "t": "ταῖς μὲν κατασκευαῖς λαμπρῶς καὶ βασιλικῶς, ταῖς δὲ πράξεσιν ἀκριβῶς, ἵν’ εὐδοκιμῇς ἅμα καὶ διαρκῇς. τὴν μεγαλοπρέπειαν ἐπιδείκνυσο μηδ’ ἐν μιᾷ τῶν πολυτελειῶν τῶν εὐθὺς ἀφανιζομένων, ἀλλ’ ἔν τε τοῖς προειρημένοις καὶ τῷ κάλλει τῶν κτημάτων καὶ ταῖς τῶν φίλων εὐεργεσίαις· τὰ γὰρ τοιαῦτα τῶν ἀναλωμάτων αὐτῷ τε σοὶ παραμενεῖ, καὶ τοῖς ἐπιγιγνομένοις πλείονος ἄξια τῶν δεδαπανημένων καταλείψεις.", "st": "2.19"}, {"sp": "N", "t": "τὰ μὲν πρὸς τοὺς θεοὺς ποίει μὲν ὡς οἱ πρόγονοι κατέδειξαν, ἡγοῦ δὲ θῦμα τοῦτο κάλλιστον εἶναι καὶ θεραπείαν μεγίστην, ἂν ὡς βέλτιστον καὶ δικαιότατον σαυτὸν παρέχῃς· μᾶλλον γὰρ ἐλπὶς τοὺς τοιούτους ἢ τοὺς ἱερεῖα πολλὰ καταβάλλοντας πράξειν τι παρὰ τῶν θεῶν ἀγαθόν. τίμα ταῖς μὲν ἀρχαῖς τῶν φίλων τοὺς οἰκειοτάτους, ταῖς δ’ ἀληθείαις αὐταῖς τοὺς εὐνουστάτους.", "st": "2.20"}, {"sp": "N", "t": "φυλακὴν ἀσφαλεστάτην ἡγοῦ τοῦ σώματος εἶναι τήν τε τῶν φίλων ἀρετὴν καὶ τὴν τῶν πολιτῶν εὔνοιαν καὶ τὴν σαυτοῦ φρόνησιν· διὰ γὰρ τούτων καὶ κτᾶσθαι καὶ σώζειν τὰς τυραννίδας μάλιστ’ ἄν τις δύναιτο. κήδου τῶν οἴκων τῶν πολιτικῶν, καὶ νόμιζε καὶ τοὺς δαπανῶντας ἀπὸ τῶν σῶν ἀναλίσκειν καὶ τοὺς ἐργαζομένους τὰ σὰ πλείω ποιεῖν· ἅπαντα γὰρ τὰ τῶν οἰκούντων τὴν πόλιν οἰκεῖα τῶν καλῶς βασιλευόντων ἐστί.", "st": "2.21"}, {"sp": "N", "t": "διὰ παντὸς τοῦ χρόνου τὴν ἀλήθειαν οὕτω φαίνου προτιμῶν, ὥστε πιστοτέρους εἶναι τοὺς σοὺς λόγους μᾶλλον ἢ τοὺς τῶν ἄλλων ὅρκους. ἅπασι μὲν τοῖς ξένοις ἀσφαλῆ τὴν πόλιν πάρεχε καὶ πρὸς τὰ συμβόλαια νόμιμον, περὶ πλείστου δὲ ποιοῦ τῶν ἀφικνουμένων μὴ τοὺς σοὶ δωρεὰς ἄγοντας, ἀλλὰ τοὺς παρὰ σοῦ λαμβάνειν ἀξιοῦντας· τιμῶν γὰρ τοὺς τοιούτους μᾶλλον παρὰ τοῖς ἄλλοις εὐδοκιμήσεις.", "st": "2.22"}, {"sp": "N", "t": "τοὺς πολλοὺς φόβους ἐξαίρει τῶν πολιτῶν, καὶ μὴ βούλου περιδεεῖς εἶναι τοὺς μηδὲν ἀδικοῦντας· ὅπως γὰρ ἂν τοὺς ἄλλους πρὸς σαυτὸν διαθῇς, οὕτω καὶ σὺ πρὸς ἐκείνους ἕξεις. ποίει μὲν μηδὲν μετ’ ὀργῆς, δόκει δὲ τοῖς ἄλλοις, ὅταν σοι καιρὸς ᾖ. δεινὸς μὲν φαίνου τῷ μηδέν σε λανθάνειν τῶν γιγνομένων, πρᾶος δὲ τῷ τὰς τιμωρίας ἐλάττους ποιεῖσθαι τῶν ἁμαρτανομένων.", "st": "2.23"}, {"sp": "N", "t": "ἀρχικὸς εἶναι βούλου μὴ χαλεπότητι μηδὲ τῷ σφόδρα κολάζειν, ἀλλὰ τῷ πάντας ἡττᾶσθαι τῆς σῆς διανοίας καὶ νομίζειν ὑπὲρ τῆς αὑτῶν σωτηρίας ἄμεινον ἑαυτῶν σὲ βουλεύεσθαι. πολεμικὸς μὲν ἴσθι ταῖς ἐπιστήμαις καὶ ταῖς παρασκευαῖς, εἰρηνικὸς δὲ τῷ μηδὲν παρὰ τὸ δίκαιον πλεονεκτεῖν. οὕτως ὁμίλει τῶν πόλεων πρὸς τὰς ἥττους, ὥσπερ ἂν τὰς κρείττους πρὸς ἑαυτὸν ἀξιώσειας.", "st": "2.24"}, {"sp": "N", "t": "φιλονείκει μὴ περὶ πάντων, ἀλλὰ περὶ ὧν ἂν κρατήσαντί σοι μέλλῃ συνοίσειν. φαύλους ἡγοῦ μὴ τοὺς συμφερόντως ἡττωμένους, ἀλλὰ τοὺς μετὰ βλάβης περιγιγνομένους. μεγαλόφρονας νόμιζε μὴ τοὺς μείζω περιβαλλομένους ὧν οἷοί τ’ εἰσὶ κατασχεῖν, ἀλλὰ τοὺς καλῶν μὲν ἐφιεμένους, ἐξεργάζεσθαι δὲ δυναμένους οἷς ἂν ἐπιχειρῶσιν.", "st": "2.25"}, {"sp": "N", "t": "ζήλου μὴ τοὺς μεγίστην ἀρχὴν κτησαμένους, ἀλλὰ τοὺς ἄριστα τῇ παρούσῃ χρησαμένους, καὶ νόμιζε τελέως εὐδαιμονήσειν οὐκ ἐὰν πάντων ἀνθρώπων μετὰ φόβων καὶ κινδύνων καὶ κακίας ἄρξῃς, ἀλλ’ ἂν τοιοῦτος ὢν οἷον χρὴ καὶ πράττων ὥσπερ ἐν τῷ παρόντι μετρίων ἐπιθυμῇς καὶ μηδενὸς τούτων ἀτυχῇς.", "st": "2.26"}, {"sp": "N", "t": "φίλους κτῶ μὴ πάντας τοὺς βουλομένους, ἀλλὰ τοὺς τῆς σῆς φύσεως ἀξίους ὄντας, μηδὲ μεθ’ ὧν ἥδιστα συνδιατρίψεις, ἀλλὰ μεθ’ ὧν ἄριστα τὴν πόλιν διοικήσεις. ἀκριβεῖς ποιοῦ τὰς δοκιμασίας τῶν συνόντων, εἰδὼς ὅτι πάντες οἱ μή σοι πλησιάσαντες ὅμοιόν σε τοῖς χρωμένοις εἶναι νομιοῦσιν. τοιούτους ἐφίστη τοῖς πράγμασι τοῖς μὴ διὰ σοῦ γιγνομένοις, ὡς αὐτὸς τὰς αἰτίας ἕξων ὧν ἂν ἐκεῖνοι πράξωσιν.", "st": "2.27"}, {"sp": "N", "t": "πιστοὺς ἡγοῦ μὴ τοὺς ἅπαν ὁ τι ἂν λέγῃς ἢ ποιῇς ἐπαινοῦντας, ἀλλὰ τοὺς τοῖς ἁμαρτανομένοις ἐπιτιμῶντας. δίδου παρρησίαν τοῖς εὖ φρονοῦσιν, ἵνα περὶ ὧν ἂν ἀμφιγνοῇς, ἔχῃς τοὺς συνδοκιμάσοντας. διόρα καὶ τοὺς τέχνῃ κολακεύοντας καὶ τοὺς μετ’ εὐνοίας θεραπεύοντας, ἵνα μὴ πλέον οἱ πονηροὶ τῶν χρηστῶν ἔχωσιν. ἄκουε τοὺς λόγους τοὺς περὶ ἀλλήλων, καὶ πειρῶ γνωρίζειν ἅμα τούς τε λέγοντας, ὁποῖοί τινές εἰσι, καὶ περὶ ὧν ἂν λέγωσιν.", "st": "2.28"}, {"sp": "N", "t": "ταῖς αὐταῖς κόλαζε ζημίαις τοὺς ψευδῶς διαβάλλοντας, αἷσπερ τοὺς ἐξαμαρτάνοντας. ἄρχε σαυτοῦ μηδὲν ἧττον ἢ τῶν ἄλλων, καὶ τοῦθ’ ἡγοῦ βασιλικώτατον, ἂν μηδεμιᾷ δουλεύῃς τῶν ἡδονῶν, ἀλλὰ κρατῆς τῶν ἐπιθυμιῶν μᾶλλον ἢ τῶν πολιτῶν. μηδεμίαν συνουσίαν εἰκῇ προσδέχου μηδ’ ἀλογίστως, ἀλλ’ ἐπ’ ἐκείναις ταῖς διατριβαῖς ἔθιζε σαυτὸν χαίρειν, ἐξ ὧν αὐτός τ’ ἐπιδώσεις καὶ τοῖς ἄλλοις βελτίων εἶναι δόξεις.", "st": "2.29"}, {"sp": "N", "t": "μὴ φαίνου φιλοτιμούμενος ἐπὶ τοῖς τοιούτοις ἃ καὶ τοῖς κακοῖς διαπράξασθαι δυνατόν ἐστιν, ἀλλ’ ἐπ’ ἀρετῇ μέγα φρονῶν, ἧς οὐδὲν μέρος τοῖς πονηροῖς μέτεστιν. νόμιζε τῶν τιμῶν ἀληθεστάτας εἶναι μὴ τὰς ἐν τῷ φανερῷ μετὰ δέους γιγνομένας, ἀλλ’ ὅταν αὐτοὶ παρ’ αὑτοῖς ὄντες μᾶλλόν σου τὴν γνώμην ἢ τὴν τύχην θαυμάζωσιν. λάνθανε μέν, ἢν ἐπὶ τῴ σοι συμβῇ τῶν φαύλων χαίρειν, ἐνδείκνυσο δὲ περὶ τὰ μέγιστα σπουδάζων.", "st": "2.30"}, {"sp": "N", "t": "μὴ τοὺς μὲν ἄλλους ἀξίου κοσμίως ζῆν τοὺς δὲ βασιλεῖς ἀτάκτως, ἀλλὰ τὴν σαυτοῦ σωφροσύνην παράδειγμα τοῖς ἄλλοις καθίστη, γιγνώσκων ὅτι τὸ τῆς πόλεως ὅλης ἦθος ὁμοιοῦται τοῖς ἄρχουσιν. σημεῖον ἔστω σοι τοῦ καλῶς βασιλεύειν, ἂν τοὺς ἀρχομένους ὁρᾷς εὐπορωτέρους καὶ σωφρονεστέρους γιγνομένους διὰ τὴν σὴν ἐπιμέλειαν.", "st": "2.31"}, {"sp": "N", "t": "περὶ πλείονος ποιοῦ δόξαν καλὴν ἢ πλοῦτον μέγαν τοῖς παισὶ καταλιπεῖν· ὁ μὲν γὰρ θνητός, ἡ δ’ ἀθάνατος, καὶ δόξῃ μὲν χρήματα κτητά, δόξα δὲ χρημάτων οὐκ ὠνητή, καὶ τὰ μὲν καὶ φαύλοις παραγίγνεται, τὴν δ’ οὐχ οἷόν τε ἀλλ’ ἢ τοὺς διενεγκόντας κτήσασθαι. τρύφα μὲν ἐν ταῖς ἐσθῆσι καὶ τοῖς περὶ τὸ σῶμα κόσμοις, καρτέρει δὲ ὡς χρὴ τοὺς βασιλεύοντας ἐν τοῖς ἄλλοις ἐπιτηδεύμασιν, ἵν’ οἱ μὲν ὁρῶντες διὰ τὴν ὄψιν ἄξιόν σε τῆς ἀρχῆς εἶναι νομίζωσιν, οἱ δὲ συνόντες διὰ τὴν τῆς ψυχῆς ῥώμην τὴν αὐτὴν ἐκείνοις γνώμην ἔχωσιν.", "st": "2.32"}, {"sp": "N", "t": "ἐπισκόπει τοὺς λόγους ἀεὶ τοὺς σαυτοῦ καὶ τὰς πράξεις, ἵν’ ὡς ἐλαχίστοις ἁμαρτήμασι περιπίπτῃς. κράτιστον μὲν τῆς ἀκμῆς τῶν καιρῶν τυγχάνειν, ἐπειδὴ δὲ δυσκαταμαθήτως ἔχουσιν, ἐλλείπειν αἱροῦ καὶ μὴ πλεονάζειν· αἱ γὰρ μετριότητες μᾶλλον ἐν ταῖς ἐνδείαις ἢ ταῖς ὑπερβολαῖς ἔνεισιν.", "st": "2.33"}, {"sp": "N", "t": "ἀστεῖος εἶναι πειρῶ καὶ σεμνός· τὸ μὲν γὰρ τῇ τυραννίδι πρέπει, τὸ δὲ πρὸς τὰς συνουσίας ἁρμόττει. χαλεπώτατον δὲ τοῦτο πάντων ἐστὶ τῶν προσταγμάτων· εὑρήσεις γὰρ ὡς ἐπὶ τὸ πολὺ τοὺς μὲν σεμνυνομένους ψυχροὺς ὄντας, τοὺς δὲ βουλομένους μένους ἀστείους εἶναι ταπεινοὺς φαινομένους. δεῖ δὲ χρῆσθαι μὲν ἀμφοτέραις ταῖς ἰδέαις ταύταις, τὴν δὲ συμφορὰν τὴν ἑκατέρᾳ προσοῦσαν διαφεύγειν.", "st": "2.34"}, {"sp": "N", "t": "ὅ τι ἂν ἀκριβῶσαι βουληθῇς ὧν ἐπίστασθαι προσήκει τοὺς βασιλεῖς, ἐμπειρίᾳ μέτιθι καὶ φιλοσοφίᾳ· τὸ μὲν γὰρ φιλοσοφεῖν τὰς ὁδούς σοι δείξει, τὸ δ’ ἐπ’ αὐτῶν τῶν ἔργων γυμνάζεσθαι δύνασθαί σε χρῆσθαι τοῖς πράγμασι ποιήσει. θεώρει τὰ γιγνόμενα καὶ τὰ συμπίπτοντα καὶ τοῖς ἰδιώταις καὶ τοῖς τυράννοις· ἂν γὰρ τὰ παρεληλυθότα μνημονεύῃς, ἄμεινον περὶ τῶν μελλόντων βουλεύσει.", "st": "2.35"}, {"sp": "N", "t": "δεινὸν ἡγοῦ τῶν μὲν ἰδιωτῶν τινας ἐθέλειν ἀποθνήσκειν, ἵνα τελευτήσαντες ἐπαινεθῶσι, τοὺς δὲ βασιλεῖς μὴ τολμᾶν χρῆσθαι τοῖς ἐπιτηδεύμασι τούτοις, ἐξ ὧν ζῶντες εὐδοκιμήσουσιν. βούλου τὰς εἰκόνας τῆς ἀρετῆς ὑπόμνημα μᾶλλον ἢ τοῦ σώματος καταλιπεῖν. μάλιστα μὲν πειρῶ τὴν ἀσφάλειαν καὶ σαυτῷ καὶ τῇ πόλει διαφυλάττειν· ἐὰν δ’ ἀναγκασθῇς κινδυνεύειν, αἱροῦ καλῶς τεθνάναι μᾶλλον ἢ ζῆν αἰσχρῶς.", "st": "2.36"}, {"sp": "N", "t": "ἐν πᾶσι τοῖς ἔργοις μέμνησο τῆς βασιλείας, καὶ φρόντιζε ὅπως μηδὲν ἀνάξιον τῆς τιμῆς ταύτης πράξεις. Μὴ περιίδῃς τὴν σαυτοῦ φύσιν ἅπασαν ἅμα διαλυθεῖσαν· ἀλλ’ ἐπειδὴ θνητοῦ σώματος ἔτυχες, πειρῶ τῆς ψυχῆς ἀθάνατον τὴν μνήμην καταλιπεῖν.", "st": "2.37"}, {"sp": "N", "t": "μελέτα περὶ καλῶν ἐπιτηδευμάτων λέγειν, ἵνα συνεθισθῇς ὅμοια τοῖς εἰρημένοις φρονεῖν. ἅττ’ ἄν σοι λογιζομένῳ φαίνηται βέλτιστα, ταῦτα τοῖς ἔργοις ἐπιτέλει. ὧν τὰς δόξας ζηλοῖς, μιμοῦ τὰς πράξεις. ἃ τοῖς αὑτοῦ παισὶν ἂν συμβουλεύσειας, τούτοις αὐτὸς ἐμμένειν ἀξίου. χρῶ τοῖς εἰρημένοις ἢ ζήτει βελτίω τούτων.", "st": "2.38"}, {"sp": "N", "t": "σοφοὺς νόμιζε μὴ τοὺς ἀκριβῶς περὶ μικρῶν ἐρίζοντας, ἀλλὰ τοὺς εὖ περὶ τῶν μεγίστων λέγοντας, μηδὲ τοὺς τοῖς μὲν ἄλλοις εὐδαιμονίαν ὑπισχνουμένους, αὐτοὺς δ’ ἐν πολλαῖς ἀπορίαις ὄντας, ἀλλὰ τοὺς μέτρια μὲν περὶ αὑτῶν λέγοντας, ὁμιλεῖν δὲ καὶ τοῖς πράγμασι καὶ τοῖς ἀνθρώποις δυναμένους, καὶ μὴ διαταραττομένους ἐν ταῖς τοῦ βίου μεταβολαῖς, ἀλλὰ καλῶς καὶ μετρίως καὶ τὰς συμφορὰς καὶ τὰς εὐτυχίας φέρειν ἐπισταμένους.", "st": "2.39"}, {"sp": "N", "t": "καὶ μὴ θαυμάσῃς, εἰ πολλὰ τῶν λεγομένων ἐστὶν ἃ καὶ σὺ γιγνώσκεις· οὐδὲ γὰρ ἐμὲ τοῦτο παρέλαθεν, ἀλλ’ ἠπιστάμην ὅτι τοσούτων ὄντων τὸ πλῆθος καὶ τῶν ἄλλων καὶ τῶν ἀρχόντων οἱ μέν τι τούτων εἰρήκασιν, οἱ δ’ ἀκηκόασιν, οἱ δ’ ἑτέρους ποιοῦντας ἑωράκασιν, οἱ δ’ αὐτοὶ τυγχάνουσιν ἐπιτηδεύοντες.", "st": "2.40"}, {"sp": "N", "t": "ἀλλὰ γὰρ οὐκ ἐν τοῖς λόγοις χρὴ τούτοις ζητεῖν τὰς καινότητας, ἐν οἷς οὔτε παράδοξον οὔτ’ ἄπιστον οὔτ’ ἔξω τῶν νομιζομένων οὐδὲν ἔξεστιν εἰπεῖν, ἀλλ’ ἡγεῖσθαι τοῦτον χαριέστατον, ὃς ἂν τῶν διεσπαρμένων ἐν ταῖς τῶν ἄλλων διανοίαις ἀθροῖσαι τὰ πλεῖστα δυνηθῇ καὶ φράσαι κάλλιστα περὶ αὐτῶν.", "st": "2.41"}, {"sp": "N", "t": "ἐπεὶ κἀκεῖνό μοι πρόδηλον ἦν, ὅτι τὰ συμβουλεύοντα καὶ τῶν ποιημάτων καὶ τῶν συγγραμμάτων μάτων χρησιμώτατα μὲν ἅπαντες νομίζουσιν, οὐ μὴν ἥδιστά γ’ αὐτῶν ἀκούουσιν, ἀλλὰ πεπόνθασιν ὅπερ πρὸς τοὺς νουθετοῦντας· καὶ γὰρ ἐκείνους ἐπαινοῦσι μέν, πλησιάζειν δὲ βούλονται τοῖς συνεξαμαρτάνουσιν ἀλλ’ οὐ τοῖς ἀποτρέπουσιν.", "st": "2.42"}, {"sp": "N", "t": "σημεῖον δ’ ἄν τις ποιήσαιτο τὴν Ἡσιόδου καὶ Θεόγνιδος καὶ Φωκυλίδου ποίησιν· καὶ γὰρ τούτους φασὶ μὲν ἀρίστους γεγενῆσθαι συμβούλους τῶ βίῳ τῷ τῶν ἀνθρώπων, ταῦτα δὲ λέγοντες αἱροῦνται συνδιατρίβειν ταῖς ἀλλήλων ἀνοίαις μᾶλλον ἢ ταῖς ἐκείνων ὑποθήκαις.", "st": "2.43"}, {"sp": "N", "t": "ἔτι δ’ εἴ τις ἐκλέξειε τῶν προεχόντων ποιητῶν τὰς καλουμένας γνώμας, ἐφ’ αἷς ἐκεῖνοι μάλιστ’ ἐσπούδασαν, ὁμοίως ἂν καὶ πρὸς ταύτας διατεθεῖεν· ἥδιον γὰρ ἂν κωμῳδίας τῆς φαυλοτάτης ἢ τῶν οὕτω τεχνικῶς πεποιημένων ἀκούσαιεν. καὶ τί δεῖ καθ’ ἓν ἕκαστον λέγοντα διατρίβειν;", "st": "2.44"}, {"sp": "N", "t": "ὅλως γὰρ εἰ ’θέλοιμεν σκοπεῖν τὰς φύσεις τὰς τῶν ἀνθρώπων, εὑρήσομεν τοὺς πολλοὺς αὐτῶν οὔτε τῶν σιτίων χαίροντας τοῖς ὑγιεινοτάτοις οὔτε τῶν ἐπιτηδευμάτων τοῖς καλλίστοις οὔτε δοκοῦντας καρτερικοὺς καὶ φιλοπόνους εἶναι τοὺς τῶν δεόντων τι ποιοῦντας·", "st": "2.45"}, {"sp": "N", "t": "ὥστε πῶς ἄν τις τοῖς τοιούτοις ἢ παραινῶν ἢ διδάσκων ἢ χρήσιμόν τι λέγων ἀρέσειεν; οἳ πρὸς τοῖς εἰρημένοις φθονοῦσι μὲν τοῖς εὖ φρονοῦσιν, ἁπλοῦς δ’ ἡγοῦνται τοὺς νοῦν οὐκ ἔχοντας, οὕτω δὲ τὰς ἀληθείας τῶν πραγμάτων φεύγουσιν, ὥστ’ οὐδὲ τὰ σφέτερ’ αὐτῶν ἴσασιν, ἀλλὰ λυποῦνται μὲν περὶ τῶν ἰδίων λογιζόμενοι, χαίρουσι δὲ περὶ τῶν ἀλλοτρίων διαλεγόμενοι, βούλοιντο δ’ ἂν τῷ σώματι κακοπαθῆσαι μᾶλλον ἢ τῇ ψυχῇ πονῆσαι καὶ σκέψασθαι περί τινος τῶν ἀναγκαίων.", "st": "2.46"}, {"sp": "N", "t": "εὕροι δ’ ἄν τις αὐτοὺς ἐν μὲν ταῖς πρὸς ἀλλήλους συνουσίαις ἢ λοιδοροῦντας ἢ λοιδορουμένους, ἐν δὲ ταῖς ἐρημίαις οὐ βουλευομένους ἀλλ’ εὐχομένους. λέγω δ’ οὐ καθ’ ἁπάντων, ἀλλὰ κατὰ τῶν ἐνόχων τοῖς εἰρημένοις ὄντων.", "st": "2.47"}, {"sp": "N", "t": "ἐκεῖνο δ’ οὖν φανερόν, ὅτι δεῖ τοὺς βουλομένους ἢ ποιεῖν ἢ γράφειν τι κεχαρισμένον τοῖς πολλοῖς μὴ τοὺς ὠφελιμωτάτους τῶν λόγων ζητεῖν, ἀλλὰ τοὺς μυθωδεστάτους· ἀκούοντες μὲν γὰρ τῶν τοιούτων χαίρουσι, θεωροῦντες δὲ τοὺς ἀγῶνας καὶ τὰς ἁμίλλας. διὸ καὶ τὴν Ὁμήρου ποίησιν καὶ τοὺς πρώτους εὑρόντας τραγῳδίαν ἄξιον θαυμάζειν, ὅτι κατιδόντες τὴν φύσιν τὴν τῶν ἀνθρώπων ἀμφοτέραις ταῖς ἰδέαις ταύταις κατεχρήσαντο πρὸς τὴν ποίησιν.", "st": "2.48"}, {"sp": "N", "t": "ὁ μὲν γὰρ τοὺς ἀγῶνας καὶ τοὺς πολέμους τοὺς τῶν ἡμιθέων ἐμυθολόγησεν, οἱ δὲ τοὺς μύθους εἰς ἀγῶνας καὶ πράξεις κατέστησαν, ὥστε μὴ μόνον ἀκουστοὺς ἡμῖν ἀλλὰ καὶ θεατοὺς γενέσθαι. τοιούτων οὖν παραδειγμάτων ὑπαρχόντων, δέδεικται τοῖς ἐπιθυμοῦσι τοὺς ἀκροωμένους ψυχαγωγεῖν, ὅτι τοῦ μὲν νουθετεῖν καὶ συμβουλεύειν βουλεύειν ἀφεκτέον, τὰ δὲ τοιαῦτα λεκτέον οἷς ὁρῶσι τοὺς ὄχλους μάλιστα χαίροντας.", "st": "2.49"}, {"sp": "N", "t": "ταῦτα δὲ διῆλθον ἡγούμενος σὲ δεῖν, τὸν οὐχ ἕνα τῶν πολλῶν ἀλλὰ πολλῶν βασιλεύοντα, μὴ τὴν αὐτὴν γνώμην ἔχειν τοῖς ἄλλοις, μηδὲ τὰ σπουδαῖα τῶν πραγμάτων μηδὲ τοὺς εὖ φρονοῦντας τῶν ἀνθρώπων ταῖς ἡδοναῖς κρίνειν, ἀλλ’ ἐπὶ τῶν πράξεων τῶν χρησίμων αὐτοὺς δοκιμάζειν,", "st": "2.50"}, {"sp": "N", "t": "ἄλλως τ’ ἐπειδὴ περὶ μὲν τῶν γυμνασίων τῶν τῆς ψυχῆς ἀμφισβητοῦσιν οἱ περὶ τὴν φιλοσοφίαν ὄντες, καί φασιν οἱ μὲν διὰ τῶν ἐριστικῶν λόγων οἱ δὲ διὰ τῶν πολιτικῶν οἱ δὲ δι’ ἄλλων τινῶν φρονιμωτέρους ἔσεσθαι τοὺς αὐτοῖς πλησιάζοντας, ἐκεῖνο δὲ πάντες ὁμολογοῦσιν, ὅτι δεῖ τὸν καλῶς πεπαιδευμένον ἐξ ἑκάστου τούτων φαίνεσθαι βουλεύεσθαι δυνάμενον.", "st": "2.51"}, {"sp": "N", "t": "χρὴ τοίνυν ἀφέμενον τῶν ἀμφισβητουμένων ἐπὶ τοῦ συνομολογουμένου λαμβάνειν αὐτῶν τὸν ἔλεγχον, καὶ μάλιστα μὲν ἐπὶ τῶν καιρῶν θεωρεῖν συμβουλεύοντας, εἰ δὲ μή, καὶ καθ’ ὅλων τῶν πραγμάτων λέγοντας. καὶ τοὺς μὲν μηδὲν γιγνώσκοντας τῶν δεόντων ἀποδοκίμαζε (δῆλον γὰρ ὡς ὁ μηδὲν ὢν αὐτὸς χρήσιμος οὐδ’ ἄν ἄλλον φρόνιμον ποιήσειεν),", "st": "2.52"}, {"sp": "N", "t": "τοὺς δὲ νοῦν ἔχοντας καὶ δυναμένους ὁρᾶν πλέον τι τῶν ἄλλων περὶ πολλοῦ ποιοῦ καὶ θεράπευε, γιγνώσκων ὅτι σύμβουλος ἀγαθὸς χρησιμώτατον καὶ τυραννικώτατον ἁπάντων τῶν κτημάτων ἐστίν. ἡγοῦ δὲ τούτους μεγίστην σοι ποιεῖν τὴν βασιλείαν, οἵ τινες ἂν τὴν διάνοιαν τὴν σὴν πλεῖστ’ ὠφελῆσαι δυνηθῶσιν.", "st": "2.53"}, {"sp": "N", "t": "ἐγὼ μὲν οὖν ἅ τε γιγνώσκω παρῄνεκα, καὶ τιμῶ σε τούτοις οἷς τυγχάνω δυνάμενος· βούλου δὲ καὶ τοὺς ἄλλους, ὅπερ εἶπον ἀρχόμενος, μὴ τὰς εἰθισμένας ἄγειν σοι δωρεάς, ἃς ὑμεῖς πολὺ πλείονος ἀγοράζετε παρὰ τῶν διδόντων ἢ παρὰ τῶν πωλούντων, ἀλλὰ τοιαύτας, αἷς κἂν σφόδρα χρῇ καὶ μηδεμίαν ἡμέραν διαλείπῃς, οὐ κατατρίψεις, ἀλλὰ μείζους καὶ πλείονος ἀξίας ποιήσεις.", "st": "2.54"}, {"sp": "HDR", "t": "Νικοκλῆς ἢ Κύπριοι", "st": "3"}, {"sp": "N", "t": "εἰσί τινες οἳ δυσκόλως ἔχουσι πρὸς τοὺς λόγους καὶ διαμέμφονται τοὺς φιλοσοφοῦντας, καί φασιν αὐτοὺς οὐκ ἀρετῆς ἀλλὰ πλεονεξίας ἕνεκα ποιεῖσθαι τὰς τοιαύτας διατριβάς. ἡδέως ἂν οὖν πυθοίμην τῶν οὕτω διακειμένων, διὰ τί τοὺς μὲν εὖ λέγειν ἐπιθυμοῦντας ψέγουσι, τοὺς δ’ ὀρθῶς πράττειν βουλομένους ἐπαινοῦσιν· εἰ γὰρ αἱ πλεονεξίαι λυποῦσιν αὐτούς, πλείους καὶ μείζους ἐκ τῶν ἔργων ἢ τῶν λόγων εὑρήσομεν γιγνομένας.", "st": "3.1"}, {"sp": "N", "t": "ἔπειτα κἀκεῖν’ ἄτοπον εἰ λέληθεν αὐτούς, ὅτι τὰ περὶ τοὺς θεοὺς εὐσεβοῦμεν καὶ τὴν δικαιοσύνην ἀσκοῦμεν καὶ τὰς ἄλλας ἀρετὰς ἐπιτηδεύομεν οὐχ ἵνα τῶν ἄλλων ἔλαττον ἔχωμεν, ἀλλ’ ὅπως ἂν ὡς μετὰ πλείστων ἀγαθῶν τὸν βίον διάγωμεν. ὥστ’ οὐ κατηγορητέον τῶν πραγμάτων τούτων ἐστί, δι’ ὧν ἄν τις μετ’ ἀρετῆς πλεονεκτήσειεν, ἀλλὰ τῶν ἀνθρώπων τῶν περὶ τὰς πράξεις ἐξαμαρτανόντων ἢ τοῖς λόγοις ἐξαπατώντων καὶ μὴ δικαίως χρωμένων αὐτοῖς.", "st": "3.2"}, {"sp": "N", "t": "θαυμάζω δὲ τῶν ταύτην τὴν γνώμην ἐχόντων, ὅπως οὐ καὶ τὸν πλοῦτον καὶ τὴν ῥώμην καὶ τὴν ἀνδρίαν κακῶς λέγουσιν. εἴπερ γὰρ διὰ τοὺς ἐξαμαρτάνοντας καὶ τοὺς ψευδομένους πρὸς τοὺς λόγους χαλεπῶς ἔχουσι, προσήκει καὶ τοῖς ἄλλοις ἀγαθοῖς αὐτοὺς ἐπιτιμᾶν· φανήσονται γάρ τινες καὶ τῶν ταῦτα κεκτημένων ἐξαμαρτάνοντες καὶ πολλοὺς διὰ τούτων κακῶς ποιοῦντες.", "st": "3.3"}, {"sp": "N", "t": "ἀλλὰ γὰρ οὐ δίκαιον, οὔτ’ εἴ τινες τοὺς ἀπαντῶντας τύπτουσι, τῆς ῥώμης κατηγορεῖν, οὔτε διὰ τοὺς ἀποκτείνοντας οὓς οὐ δεῖ τὴν ἀνδρίαν λοιδορεῖν, οὔθ’ ὅλως τὴν τῶν ἀνθρώπων πονηρίαν ἐπὶ τὰ πράγματα μεταφέρειν, ἀλλ’ αὐτοὺς ἐκείνους ψέγειν, ὅσοι τοῖς ἀγαθοῖς κακῶς χρῶνται καὶ τοῖς ὠφελεῖν δυναμένοις, τούτοις βλάπτειν τοὺς συμπολιτευομένους ἐπιχειροῦσι.", "st": "3.4"}, {"sp": "N", "t": "νῦν δ’ ἀμελήσαντες τοῦτον τὸν τρόπον περὶ ἑκάστου διορίζεσθαι πρὸς ἅπαντας τοὺς λόγους δυσκόλως διάκεινται, καὶ τοσοῦτον διημαρτήκασιν ὥστ’ οὐκ αἴσθονται τοιούτῳ πράγματι δυσμενῶς ἔχοντες, ὃ πάντων τῶν ἐνόντων ἐν τῇ τῶν ἀνθρώπων φύσει πλείστων ἀγαθῶν αἴτιόν ἐστι. τοῖς μὲν γὰρ ἄλλοις οἷς ἔχομεν οὐδὲν τῶν ἄλλων ζῴων διαφέρομεν, ἀλλὰ πολλῶν καὶ τῷ τάχει καὶ τῇ ῥώμῃ καὶ ταῖς ἄλλαις εὐπορίαις καταδεέστεροι τυγχάνομεν ὄντες·", "st": "3.5"}, {"sp": "N", "t": "ἐγγενομένου δ’ ἡμῖν τοῦ πείθειν ἀλλήλους καὶ δηλοῦν πρὸς ἡμᾶς αὐτοὺς περὶ ὧν ἂν βουληθῶμεν, οὐ μόνον τοῦ θηριωδῶς ζῆν ἀπηλλάγημεν, ἀλλὰ καὶ συνελθόντες πόλεις ᾠκίσαμεν καὶ νόμους ἐθέμεθα καὶ τέχνας εὕρομεν, καὶ σχεδὸν ἅπαντα τὰ δι’ ἡμῶν μεμηχανημένα λόγος ἡμῖν ἐστιν ὁ συγκατασκευάσας.", "st": "3.6"}, {"sp": "N", "t": "οὗτος γὰρ περὶ τῶν δικαίων καὶ τῶν ἀδίκων καὶ τῶν αἰσχρῶν καὶ τῶν καλῶν ἐνομοθέτησεν· ὧν μὴ διαταχθέντων οὐκ ἂν οἷοί τ’ ἦμεν οἰκεῖν μετ’ ἀλλήλων. τούτῳ καὶ τοὺς κακοὺς ἐξελέγχομεν καὶ τοὺς ἀγαθοὺς ἐγκωμιάζομεν. διὰ τούτου τούς τ’ ἀνοήτους παιδεύομεν καὶ τοὺς φρονίμους δοκιμάζομεν· τὸ γὰρ λέγειν ὡς δεῖ τοῦ φρονεῖν εὖ μέγιστον σημεῖον ποιούμεθα, καὶ λόγος ἀληθὴς καὶ νόμιμος καὶ δίκαιος ψυχῆς ἀγαθῆς καὶ πιστῆς εἴδωλόν ἐστιν.", "st": "3.7"}, {"sp": "N", "t": "μετὰ τούτου καὶ περὶ τῶν ἀμφισβητησίμων ἀγωνιζόμεθα καὶ περὶ τῶν ἀγνοουμένων σκοπούμεθα· ταῖς γὰρ πίστεσιν αἷς τοὺς ἄλλους λέγοντες πείθομεν, ταῖς αὐταῖς ταύταις βουλευόμενοι χρώμεθα, καὶ ῥητορικοὺς μὲν καλοῦμεν τοὺς ἐν τῷ πλήθει δυναμένους λέγειν, εὐβούλους δὲ νομίζομεν οἵτινες ἂν αὐτοὶ πρὸς αὑτοὺς ἄριστα περὶ τῶν πραγμάτων διαλεχθῶσιν.", "st": "3.8"}, {"sp": "N", "t": "εἰ δὲ δεῖ συλλήβδην περὶ τῆς δυνάμεως ταύτης εἰπεῖν, οὐδὲν τῶν φρονίμως πραττομένων εὑρήσομεν ἀλόγως γιγνόμενον, ἀλλὰ καὶ τῶν ἔργων καὶ τῶν διανοημάτων ἁπάντων ἡγεμόνα λόγον ὄντα, καὶ μάλιστα χρωμένους αὐτῷ τοὺς πλεῖστον νοῦν ἔχοντας· ὥστε τοὺς τολμῶντας βλασφημεῖν περὶ τῶν παιδευόντων καὶ φιλοσοφούντων ὁμοίως ἄξιον μισεῖν ὥσπερ τοὺς εἰς τὰ τῶν θεῶν ἐξαμαρτάνοντας.", "st": "3.9"}, {"sp": "N", "t": "ἐγὼ δ’ ἀποδέχομαι μὲν ἅπαντας τοὺς λόγους τοὺς καὶ κατὰ μικρὸν ἡμᾶς ὠφελεῖν δυναμένους, οὐ μὴν ἀλλὰ καλλίστους ἡγοῦμαι καὶ βασιλικωτάτους καὶ μάλιστα πρέποντας ἐμοὶ τοὺς περὶ τῶν ἐπιτηδευμάτων καὶ τῶν πολιτειῶν παραινοῦντας, καὶ τούτων αὐτῶν ὅσοι διδάσκουσι τούς τε δυναστεύοντας ὡς δεῖ τῷ πλήθει χρῆσθαι, καὶ τοὺς ἰδιώτας ὡς χρὴ πρὸς τοὺς ἄρχοντας διακεῖσθαι· διὰ γὰρ τούτων ὁρῶ τὰς πόλεις εὐδαιμονεστάτας καὶ μεγίστας γιγνομένας.", "st": "3.10"}, {"sp": "N", "t": "τὸν μὲν οὖν ἕτερον, ὡς χρὴ τυραννεῖν, Ἰσοκράτους ἠκούσατε, τὸν δ’ ἐχόμενον, ἃ δεῖ ποιεῖν τοὺς ἀρχομένους, ἐγὼ πειράσομαι διελθεῖν, οὐχ ὡς ἐκεῖνον ὑπερβαλούμενος, ἀλλ’ ὡς προσῆκόν μοι περὶ τούτων μάλιστα διαλεχθῆναι πρὸς ὑμᾶς. εἰ μὲν γὰρ ἐμοῦ μὴ δηλώσαντος ἃ βούλομαι ποιεῖν ὑμᾶς διαμάρτοιτε τῆς ἐμῆς γνώμης, οὐκ ἂν εἰκότως ὑμῖν ὀργιζοίμην· εἰ δὲ προειπόντος ἐμοῦ μηδὲν γίγνοιτο τούτων, δικαίως ἂν ἤδη τοῖς μὴ πειθομένοις μεμφοίμην.", "st": "3.11"}, {"sp": "N", "t": "ἡγοῦμαι δ’ οὕτως ἂν μάλιστα παρακαλέσαι καὶ προτρέψαι πρὸς τὸ μνημονεύειν ὑμᾶς τὰ ῥηθέντα καὶ πειθαρχεῖν αὐτοῖς, οὐκ εἰ περὶ τὸ συμβουλεύειν μόνον γενοίμην καὶ ταῦτ’ ἀπαριθμήσας ἀπαλλαγείην, ἀλλ’ εἰ προεπιδείξαιμι πρῶτον μὲν τὴν πολιτείαν τὴν παροῦσαν ὡς ἄξιόν ἐστιν ἀγαπᾶν οὐ μόνον διὰ τὴν ἀνάγκην, οὐδ’ ὅτι πάντα τὸν χρόνον μετὰ ταύτης οἰκοῦμεν, ἀλλ’ ὅτι βελτίστη τῶν πολιτειῶν ἐστιν,", "st": "3.12"}, {"sp": "N", "t": "ἔπειθ’ ὡς ἐγὼ ταύτην ἔχω τὴν ἀρχὴν οὐ παρανόμως οὐδ’ ἀλλοτρίαν, ἀλλ’ ὁσίως καὶ δικαίως καὶ διὰ τοὺς ἐξ ἀρχῆς προγόνους καὶ διὰ τὸν πατέρα καὶ δι’ ἐμαυτόν. τούτων γὰρ προαποδειχθέντων τίς οὐκ αὐτὸς αὑτοῦ καταγνώσεται τὴν μεγίστην ζημίαν, ἂν μὴ πειθαρχῇ τοῖς ὑπ’ ἐμοῦ συμβουλευθεῖσι καὶ προσταχθεῖσιν;", "st": "3.13"}, {"sp": "N", "t": "περὶ μὲν οὖν τῶν πολιτειῶν (ἐντεῦθεν γὰρ ὑποτιθέμενος ἠρξάμην) οἶμαι πᾶσι δοκεῖν δεινότατον μὲν εἶναι τὸ τῶν αὐτῶν ἀξιοῦσθαι τοὺς χρηστοὺς καὶ τοὺς πονηρούς, δικαιότατον δὲ τὸ διωρίσθαι περὶ τούτων καὶ μὴ τοὺς ἀνομοίους τῶν ὁμοίων τυγχάνειν, ἀλλὰ καὶ πράττειν καὶ τιμᾶσθαι κατὰ τὴν ἀξίαν ἑκάστους.", "st": "3.14"}, {"sp": "N", "t": "αἱ μὲν τοίνυν ὀλιγαρχίαι καὶ δημοκρατίαι τὰς ἰσότητας τοῖς μετέχουσι τῶν πολιτειῶν ζητοῦσι, καὶ τοῦτ’ εὐδοκιμεῖ παρ’ αὐταῖς, ἢν μηδὲν ἕτερος ἑτέρου δύνηται πλέον ἔχειν· ὃ τοῖς πονηροῖς συμφέρον ἐστίν· αἱ δὲ μοναρχίαι πλεῖστον μὲν νέμουσι τῷ βελτίστῳ, δεύτερον δὲ τῷ μετ’ ἐκεῖνον, τρίτον δὲ καὶ τέταρτον τοῖς ἄλλοις κατὰ τὸν αὐτὸν λόγον. καὶ ταῦτ’ εἰ μὴ πανταχοῦ καθέστηκεν, ἀλλὰ τό γε βούλημα τῆς πολιτείας τοιοῦτόν ἐστιν.", "st": "3.15"}, {"sp": "N", "t": "καὶ μὲν δὴ διορᾶν καὶ τὰς φύσεις τῶν ἀνθρώπων καὶ τὰς πράξεις ἅπαντες ἂν τὰς τυραννίδας μᾶλλον ὁμολογήσαιεν. καίτοι τίς οὐκ ἂν δέξαιτο τῶν εὖ φρονούντων τοιαύτης πολιτείας μετέχειν ἐν ᾗ μὴ διαλήσει χρηστὸς ὤν, μᾶλλον ἢ φέρεσθαι μετὰ τοῦ πλήθους μὴ γιγνωσκόμενος ὁποῖός τίς ἐστιν; ἀλλὰ μὴν καὶ πραοτέραν τοσούτῳ δικαίως ἂν αὐτὴν εἶναι κρίνοιμεν, ὅσῳ περ ῥᾷόν ἐστιν ἑνὸς ἀνδρὸς γνώμῃ προσέχειν τὸν νοῦν μᾶλλον ἢ πολλαῖς καὶ παντοδαπαῖς διανοίαις ζητεῖν ἀρέσκειν.", "st": "3.16"}, {"sp": "N", "t": "ὅτι μὲν οὖν ἡδίων ἐστὶ καὶ πραοτέρα καὶ δικαιοτέρα, διὰ πλειόνων μὲν ἄν τις ἀποδείξειεν, οὐ μὴν ἀλλὰ καὶ διὰ τούτων συνιδεῖν ῥᾴδιόν ἐστι· περὶ δὲ τῶν λοιπῶν, ὅσον αἱ μοναρχίαι πρὸς τὸ βουλεύεσθαι καὶ πρᾶξαί τι τῶν δεόντων διαφέρουσιν, οὕτως ἂν κάλλιστα θεωρήσαιμεν, εἰ τὰς μεγίστας τῶν πράξεων παρ’ ἀλλήλας τιθέντες ἐξετάζειν ἐπιχειρήσαιμεν αὐτάς. οἱ μὲν τοίνυν κατ’ ἐνιαυτὸν εἰς τὰς ἀρχὰς εἰσιόντες πρότερον ἰδιῶται γίγνονται, πρὶν αἰσθέσθαι τι τῶν τῆς πόλεως καὶ λαβεῖν ἐμπειρίαν αὐτῶν·", "st": "3.17"}, {"sp": "N", "t": "οἱ δ’ ἀεὶ τοῖς αὐτοῖς ἐπιστατοῦντες, ἢν καὶ τὴν φύσιν καταδεεστέραν ἔχωσιν, ἀλλ’ οὖν ταῖς γ’ ἐμπειρίαις πολὺ τῶν ἄλλων προέχουσιν. ἔπειθ’ οἱ μὲν πολλῶν καταμελοῦσιν εἰς ἀλλήλους ἀποβλέποντες, οἱ δ’ οὐδενὸς ὀλιγωροῦσιν, εἰδότες ὅτι πάντα δεῖ δι’ αὑτῶν γίγνεσθαι. πρὸς δὲ τούτοις οἱ μὲν ἐν ταῖς ὀλιγαρχίαις καὶ ταῖς δημοκρατίαις διὰ τὰς πρὸς σφᾶς αὐτοὺς φιλοτιμίας λυμαίνονται τοῖς κοινοῖς· οἱ δ’ ἐν ταῖς μοναρχίαις ὄντες, οὐκ ἔχοντες ὅτῳ φθονήσουσι, πάντων, ὡς οἷόν τ’ ἐστί, βέλτιστα πράττουσιν.", "st": "3.18"}, {"sp": "N", "t": "ἔπειθ’ οἱ μὲν ὑστερίζουσι τῶν πραγμάτων· τὸν μὲν γὰρ πλεῖστον χρόνον ἐπὶ τοῖς ἰδίοις διατρίβουσιν, ἐπειδὰν δ’ εἰς τὰ συνέδρια συνέλθωσιν, πλεονάκις ἄν τις αὐτοὺς εὕροι διαφερομένους ἢ κοινῇ βουλευομένους· οἱ δ’ οὔτε συνεδρίων οὔτε χρόνων αὐτοῖς ἀποδεδειγμένων, ἀλλὰ καὶ τὰς ἡμέρας καὶ τὰς νύκτας ἐπὶ ταῖς πράξεσιν ὄντες οὐκ ἀπολείπονται τῶν καιρῶν, ἀλλ’ ἕκαστον ἐν τῷ δέοντι πράττουσιν.", "st": "3.19"}, {"sp": "N", "t": "ἔτι δ’ οἱ μὲν δυσμενῶς ἔχουσι, καὶ βούλοιντ’ ἂν καὶ τοὺς πρὸ αὑτῶν ἄρχοντας καὶ τοὺς ἐφ’ αὑτοῖς ὡς κάκιστα διοικῆσαι τὴν πόλιν, ἵν’ ὡς μεγίστην δόξαν αὐτοὶ λάβωσιν· οἱ δὲ διὰ παντὸς τοῦ βίου κύριοι τῶν πραγμάτων ὄντες εἰς ἅπαντα τὸν χρόνον καὶ τὰς εὐνοίας ἔχουσιν.", "st": "3.20"}, {"sp": "N", "t": "τὸ δὲ μέγιστον· τοῖς γὰρ κοινοῖς οἱ μὲν ὡς ἀλλοτρίοις, οἱ δ’ ὡς ἰδίοις προσέχουσι τὸν νοῦν, καὶ συμβούλοις χρῶνται περὶ αὐτῶν οἱ μὲν τῶν ἀστῶν τοῖς τολμηροτάτοις, οἱ δ’ ἐξ ἁπάντων ἐκλεξάμενοι τοῖς φρονιμωτάτοις, καὶ τιμῶσιν οἱ μὲν τοὺς ἐν τοῖς ὄχλοις εἰπεῖν δυναμένους, οἱ δὲ τοὺς χρῆσθαι τοῖς πράγμασιν ἐπισταμένους.", "st": "3.21"}, {"sp": "N", "t": "οὐ μόνον δ’ ἐν τοῖς ἐγκυκλίοις καὶ τοῖς κατὰ τὴν ἡμέραν ἑκάστην γιγνομένοις αἱ μοναρχίαι διαφέρουσιν, ἀλλὰ καὶ τὰς ἐν τῷ πολέμῳ πλεονεξίας ἁπάσας περιειλήφασιν. καὶ γὰρ παρασκευάσασθαι δυνάμεις καὶ χρήσασθαι ταύταις, ὥστε καὶ λαθεῖν καὶ φθῆναι, καὶ τοὺς μὲν πεῖσαι, τοὺς δὲ βιάσασθαι, παρὰ δὲ τῶν ἐκπρίασθαι, τοὺς δὲ ταῖς ἄλλαις θεραπείαις προσαγαγέσθαι, μᾶλλον αἱ τυραννίδες τῶν ἄλλων πολιτειῶν οἷαί τ’ εἰσίν. καὶ ταῦτ’ ἐκ τῶν ἔργων ἄν τις οὐχ ἧττον ἢ τῶν λόγων πιστεύσειεν.", "st": "3.22"}, {"sp": "N", "t": "τοῦτο μὲν γὰρ τὴν τῶν Περσῶν δύναμιν ἅπαντες ἴσμεν τηλικαύτην τὸ μέγεθος γεγενημένην οὐ διὰ τὴν τῶν ἀνδρῶν φρόνησιν, ἀλλ’ ὅτι μᾶλλον τῶν ἄλλων τὴν βασιλείαν τιμῶσι· τοῦτο δὲ Διονύσιον τὸν τύραννον, ὅτι παραλαβὼν τὴν μὲν ἄλλην Σικελίαν ἀνάστατον γεγενημένην, τὴν δ’ αὑτοῦ πατρίδα πολιορκουμένην, οὐ μόνον αὐτὴν τῶν παρόντων κινδύνων ἀπήλλαξεν, ἀλλὰ καὶ μεγίστην τῶν Ἑλληνίδων πόλεων ἐποίησεν· ἔτι δὲ Καρχηδονίους καὶ Λακεδαιμονίους,", "st": "3.23"}, {"sp": "N", "t": "τοὺς ἄριστα τῶν ἄλλων πολιτευομένους, οἴκοι μὲν ὀλιγαρχουμένους, παρὰ δὲ τὸν πόλεμον βασιλευομένους. ἔχοι δ’ ἄν τις ἐπιδεῖξαι καὶ τὴν πόλιν, τὴν μάλιστα τὰς τυραννίδας μισοῦσαν, ὅταν μὲν πολλοὺς ἐκπέμψῃ στρατηγούς, ἀτυχοῦσαν, ὅταν δὲ δι’ ἑνὸς ποιήσηται τοὺς κινδύνους, κατορθοῦσαν.", "st": "3.24"}, {"sp": "N", "t": "καίτοι πῶς ἄν τις σαφέστερον ἐπιδείξειεν ἢ διὰ τοιούτων παραδειγμάτων πλείστου τὰς μοναρχίας ἀξίας οὔσας; φαίνονται γὰρ οἵ τε διὰ τέλους τυραννευόμενοι μεγίστας δυνάμεις ἔχοντες, οἵ τε καλῶς ὀλιγαρχούμενοι, περὶ ἃ μάλιστα σπουδάζουσιν, οἱ μὲν ἕνα μόνον στρατηγὸν οἱ δὲ βασιλέα τῶν στρατοπέδων κύριον καθιστάντες, οἵ τε μισοῦντες τὰς τυραννίδας, ὁπόταν πολλοὺς ἄρχοντας ἐκπέμψωσιν,", "st": "3.25"}, {"sp": "N", "t": "οὐδὲν τῶν δεόντων πράττοντες. εἰ δὲ δεῖ τι καὶ τῶν ἀρχαίων εἰπεῖν, λέγεται καὶ τοὺς θεοὺς ὑπὸ Διὸς βασιλεύεσθαι. περὶ ὧν εἰ μὲν ἀληθὴς ὁ λόγος ἐστί, δῆλον ὅτι κἀκεῖνοι ταύτην τὴν κατάστασιν προκρίνουσιν, εἰ δὲ τὸ μὲν σαφὲς μηδεὶς οἶδεν, αὐτοὶ δ’ εἰκάζοντες οὕτω περὶ αὐτῶν ὑπειλήφαμεν, σημεῖον ὅτι πάντες τὴν μοναρχίαν προτιμῶμεν· οὐ γὰρ ἄν ποτ’ αὐτῇ χρῆσθαι τοὺς θεοὺς ἔφαμεν, εἰ μὴ πολὺ τῶν ἄλλων αὐτὴν προέχειν ἐνομίζομεν.", "st": "3.26"}, {"sp": "N", "t": "περὶ μὲν οὖν τῶν πολιτειῶν, ὅσον ἀλλήλων διαφέρουσιν, ἅπαντα μὲν οὔθ’ εὑρεῖν οὔτ’ εἰπεῖν δυνατόν ἐστιν· οὐ μὴν ἀλλὰ πρός γε τὸ παρὸν ἀποχρώντως καὶ νῦν εἴρηται περὶ αὐτῶν. ὡς δὲ προσηκόντως τὴν ἀρχὴν ἡμεῖς ἔχομεν, πολὺ τούτου συντομώτερος καὶ μᾶλλον ὁμολογούμενος ὁ λόγος ἐστίν.", "st": "3.27"}, {"sp": "N", "t": "τίς γὰρ οὐκ οἶδεν ὅτι Τεῦκρος μὲν ὁ τοῦ γένους ἡμῶν ἀρχηγός, παραλαβὼν τοὺς τῶν ἄλλων πολιτῶν προγόνους, πλεύσας δεῦρο καὶ τὴν πόλιν αὐτοῖς ἔκτισε καὶ τὴν χώραν κατένειμεν, ὁ δὲ πατὴρ Εὐαγόρας ἀπολεσάντων ἑτέρων τὴν ἀρχὴν πάλιν ἀνέλαβεν, ὑποστὰς τοὺς μεγίστους κινδύνους, καὶ τοσοῦτον μετέστησεν ὥστε μηκέτι Φοίνικας Σαλαμινίων τυραννεῖν, ἀλλ’ ὧνπερ ἦν τὴν ἀρχήν, τούτους καὶ νῦν ἔχειν τὴν βασιλείαν;", "st": "3.28"}, {"sp": "N", "t": "λοιπὸν οὖν ἐστιν ὧν προεθέμην περὶ ἐμαυτοῦ διελθεῖν ἵν’ ἐπίστησθ’ ὅτι τοιοῦτός ἐστιν ὑμῶν ὁ βασιλεύων, ὃς οὐ μόνον διὰ τοὺς προγόνους ἀλλὰ καὶ δι’ ἐμαυτὸν δικαίως ἂν καὶ μείζονος τιμῆς ἢ τηλικαύτης ἠξιώθην. οἶμαι γὰρ ἐγὼ πάντας ἂν ὁμολογῆσαι πλείστου τῶν ἀρετῶν ἀξίας εἶναι τήν τε σωφροσύνην καὶ τὴν δικαιοσύνην.", "st": "3.29"}, {"sp": "N", "t": "οὐ γὰρ μόνον ἡμᾶς τὸ καθ’ αὑτὰς ὠφελοῦσιν, ἀλλ’ εἰ ’θέλοιμεν σκοπεῖν καὶ τὰς φύσεις καὶ τὰς δυνάμεις καὶ τὰς χρήσεις τῶν πραγμάτων, εὑρήσομεν τὰς μὲν μὴ μετεχούσας τούτων τῶν ἰδεῶν μεγάλων κακῶν αἰτίας οὔσας, τὰς δὲ μετὰ δικαιοσύνης καὶ σωφροσύνης γιγνομένας πολλὰ τὸν βίον τὸν τῶν ἀνθρώπων ὠφελούσας. εἰ δή τινες τῶν προγεγενημένων ἐπὶ ταύταις ταῖς ἀρεταῖς εὐδοκίμησαν, ἡγοῦμαι κἀμοὶ προσήκειν τῆς αὐτῆς δόξης ἐκείνοις τυγχάνειν.", "st": "3.30"}, {"sp": "N", "t": "τὴν μὲν οὖν δικαιοσύνην ἐκεῖθεν ἂν μάλιστα κατίδοιτε. παραλαβὼν γάρ, ὅτ’ εἰς τὴν ἀρχὴν καθιστάμην, τὰ μὲν βασίλεια χρημάτων κενὰ καὶ πάντα κατηναλωμένα, τὰ δὲ πράγματα ταραχῆς μεστὰ καὶ πολλῆς ἐπιμελείας δεόμενα καὶ φυλακῆς καὶ δαπάνης, εἰδὼς ἑτέρους ἐν τοῖς τοιούτοις καιροῖς ἐκ παντὸς τρόπου τὰ σφέτερ’ αὐτῶν διορθουμένους καὶ πολλὰ παρὰ τὴν φύσιν τὴν αὑτῶν πράττειν ἀναγκαζομένους, ὅμως οὐδ’ ὑφ’ ἑνὸς τούτων διεφθάρην,", "st": "3.31"}, {"sp": "N", "t": "ἀλλ’ ὁσίως καὶ καλῶς ἐπεμελήθην τῶν πραγμάτων, ὥστε μηδὲν ἐλλείπειν ἐξ ὧν οἷόν τ’ ἦν αὐξηθῆναι καὶ πρὸς εὐδαιμονίαν ἐπιδοῦναι τὴν πόλιν. πρός τε γὰρ τοὺς πολίτας μετὰ τοιαύτης πραότητος προσηνέχθην, ὥστε μήτε φυγὰς μήτε θανάτους μήτε χρημάτων ἀποβολὰς μήτ’ ἄλλην μηδεμίαν τοιαύτην συμφορὰν ἐπὶ τῆς ἐμῆς γεγενῆσθαι βασιλείας.", "st": "3.32"}, {"sp": "N", "t": "ἀβάτου δὲ τῆς Ἑλλάδος ἡμῖν οὔσης διὰ τὸν πόλεμον τὸν γεγενημένον, καὶ πανταχοῦ συλωμένων ἡμῶν, τὰ πλεῖστα τούτων διέλυσα, τοῖς μὲν ἅπαντ’ ἀποτίνων, τοῖς δὲ μέρη, τῶν δ’ ἀναβαλέσθαι δεόμενος, πρὸς δὲ τοὺς ὅπως ἠδυνάμην περὶ τῶν ἐγκλημάτων διαλλαττόμενος. ἔτι δὲ καὶ τῶν νῆσον οἰκούντων δυσκόλως πρὸς ἡμᾶς διακειμένων, καὶ βασιλέως τῷ μὲν λόγῳ διηλλαγμένου τῇ δ’ ἀληθεία τραχέως ἔχοντος,", "st": "3.33"}, {"sp": "N", "t": "ἀμφότερα ταῦτα κατεπράϋνα, τῷ μὲν προθύμως ὑπηρετῶν, πρὸς δὲ τοὺς δίκαιον ἐμαυτὸν παρέχων. τοσούτου γὰρ δέω τῶν ἀλλοτρίων ἐπιθυμεῖν, ὥσθ’ ἕτεροι μέν, ἢν καὶ μικρῷ μείζω τῶν ὁμόρων δύναμιν ἔχωσιν, ἀποτέμνονται τῆς γῆς καὶ πλεονεκτεῖν ζητοῦσιν, ἐγὼ δ’ οὐδὲ τὴν διδομένην χώραν ἠξίωσα λαβεῖν, ἀλλ’ αἱροῦμαι μετὰ δικαιοσύνης τὴν ἐμαυτοῦ μόνον ἔχειν μᾶλλον ἢ μετὰ κακίας πολλαπλασίαν τῆς ὑπαρχούσης κτήσασθαι.", "st": "3.34"}, {"sp": "N", "t": "καὶ τί δεῖ καθ’ ἓν ἕκαστον λέγοντα διατρίβειν, ἄλλως τε καὶ συντόμως ἔχοντα δηλῶσαι περὶ ἐμαυτοῦ; φανήσομαι γὰρ οὐδένα μὲν πώποτ’ ἀδικήσας, πλείους δὲ καὶ τῶν πολιτῶν καὶ τῶν ἄλλων Ἑλλήνων εὖ πεποιηκὼς καὶ μείζους δωρεὰς ἑκατέροις δεδωκὼς ἢ σύμπαντες οἱ πρὸ ἐμοῦ βασιλεύσαντες. καίτοι χρὴ τοὺς μέγα φρονοῦντας ἐπὶ δικαιοσύνῃ καὶ προσποιουμένους χρημάτων εἶναι κρείττους τοιαύτας ὑπερβολὰς ἔχειν εἰπεῖν περὶ αὑτῶν.", "st": "3.35"}, {"sp": "N", "t": "καὶ μὲν δὴ καὶ περὶ σωφροσύνης ἔτι μείζω τούτων ἔχω διελθεῖν. εἰδὼς γὰρ ἅπαντας ἀνθρώπους περὶ πλείστου ποιουμένους τοὺς παῖδας τοὺς αὑτῶν καὶ τὰς γυναῖκας, καὶ μάλιστ’ ὀργιζομένους τοῖς εἰς ταῦτ’ ἐξαμαρτάνουσι, καὶ τὴν ὕβριν τὴν περὶ ταῦτα μεγίστων κακῶν αἰτίαν γιγνομένην, καὶ πολλοὺς ἤδη καὶ τῶν ἰδιωτῶν καὶ τῶν δυναστευσάντων διὰ ταύτην ἀπολομένους, οὕτως ἔφυγον τὰς αἰτίας ταύτας, ὥστ’ ἐξ οὗ τὴν βασιλείαν ἔλαβον, οὐδενὶ φανήσομαι σώματι πεπλησιακὼς πλὴν τῆς ἐμαυτοῦ γυναικός,", "st": "3.36"}, {"sp": "N", "t": "οὐκ ἀγνοῶν ὅτι κἀκεῖνοι παρὰ τοῖς πολλοῖς εὐδοκιμοῦσιν, ὅσοι περὶ μὲν τὰ τῶν πολιτῶν δίκαιοι τυγχάνουσιν ὄντες, ἄλλοθεν δέ ποθεν αὑτοῖς ἐπορίσαντο τὰς ἡδονάς, ἀλλὰ βουλόμενος ἅμα μὲν ἐμαυτὸν ὡς πορρωτάτω ποιῆσαι τῶν τοιούτων ὑποψιῶν, ἅμα δὲ παράδειγμα καταστῆσαι τὸν τρόπον τὸν ἐμαυτοῦ τοῖς ἄλλοις πολίταις, γιγνώσκων ὅτι φιλεῖ τὸ πλῆθος ἐν τούτοις τοῖς ἐπιτηδεύμασι τὸν βίον διάγειν, ἐν οἷς ἂν τοὺς ἄρχοντας τοὺς αὑτῶν ὁρῶσι διατρίβοντας.", "st": "3.37"}, {"sp": "N", "t": "ἔπειτα καὶ προσήκειν ἡγησάμην τοσούτῳ τοὺς βασιλεῖς βελτίους εἶναι τῶν ἰδιωτῶν, ὅσῳ περ καὶ τὰς τιμὰς μείζους αὐτῶν ἔχουσι, καὶ δεινὰ ποιεῖν ὅσοι τοὺς μὲν ἄλλους κοσμίως ζῆν ἀναγκάζουσιν, αὐτοὶ δ’ αὑτοὺς μὴ σωφρονεστέρους τῶν ἀρχομένων παρέχουσιν.", "st": "3.38"}, {"sp": "N", "t": "πρὸς δὲ τούτοις τῶν μὲν ἄλλων πράξεων ἑώρων ἐγκρατεῖς τοὺς πολλοὺς γιγνομένους, τῶν δ’ ἐπιθυμιῶν τῶν περὶ τοὺς παῖδας καὶ τὰς γυναῖκας καὶ τοὺς βελτίστους ἡττωμένους· ἐβουλήθην οὖν ἐν τούτοις ἐμαυτὸν ἐπιδεῖξαι καρτερεῖν δυνάμενον, ἐν οἷς ἔμελλον οὐ μόνον τῶν ἄλλων διοίσειν, ἀλλὰ καὶ τῶν ἐπ’ ἀρετῇ μέγα φρονούντων.", "st": "3.39"}, {"sp": "N", "t": "ἔτι δὲ καὶ τῶν τοιούτων πολλὴν κακίαν κατεγίγνωσκον, ὅσοι γυναῖκας λαβόντες καὶ κοινωνίαν ποιησάμενοι παντὸς τοῦ βίου μὴ στέργουσιν οἷς ἔπραξαν, ἀλλὰ ταῖς αὑτῶν ἡδοναῖς λυποῦσι ταύτας ὑφ’ ὧν αὐτοὶ μηδὲν ἀξιοῦσι λυπεῖσθαι, καὶ περὶ μὲν ἄλλας τινὰς κοινωνίας ἐπιεικεῖς σφᾶς αὐτοὺς παρέχουσιν, ἐν δὲ ταῖς πρὸς τὰς γυναῖκας ἐξαμαρτάνουσιν· ἃς ἔδει τοσούτῳ μᾶλλον διαφυλάττειν, ὅσῳ περ οἰκειότεραι καὶ μείζους οὖσαι τῶν ἄλλων τυγχάνουσιν.", "st": "3.40"}, {"sp": "N", "t": "εἶτα λανθάνουσιν ἔνδον ἐν τοῖς βασιλείοις στάσεις καὶ διαφορὰς αὑτοῖς ἐγκαταλείποντες. καίτοι χρὴ τοὺς ὀρθῶς βασιλεύοντας μὴ μόνον τὰς πόλεις ἐν ὁμονοία πειρᾶσθαι διάγειν, ὧν ἂν ἄρχωσιν, ἀλλὰ καὶ τοὺς οἴκους τοὺς ἰδίους καὶ τοὺς τόπους ἐν οἷς ἂν κατοικῶσιν· ἅπαντα γὰρ ταῦτα σωφροσύνης ἔργα καὶ δικαιοσύνης ἐστίν.", "st": "3.41"}, {"sp": "N", "t": "οὐ τὴν αὐτὴν δὲ γνώμην ἔσχον οὐδὲ περὶ τῆς παιδοποιίας τοῖς πλείστοις τῶν βασιλέων, οὐδ’ ᾠήθην δεῖν τοὺς μὲν ἐκ ταπεινοτέρας ποιήσασθαι τῶν παίδων τοὺς δ’ ἐκ σεμνοτέρας, οὐδὲ τοὺς μὲν νόθους αὐτῶν τοὺς δὲ γνησίους καταλιπεῖν, ἀλλὰ πάντας ἔχειν τὴν αὐτὴν φύσιν καὶ πρὸς πατρὸς καὶ πρὸς μητρὸς ἀνενεγκεῖν, τῶν μὲν θνητῶν εἰς Εὐαγόραν τὸν πατέρα, τῶν δ’ ἡμιθέων εἰς Αἰακίδας, τῶν δὲ θεῶν εἰς Δία, καὶ μηδένα τῶν ἐξ ἐμοῦ γενομένων ἀποστερηθῆναι ταύτης τῆς εὐγενείας.", "st": "3.42"}, {"sp": "N", "t": "πολλῶν δέ με προτρεπόντων ἐμμένειν τοῖς ἐπιτηδεύμασι τούτοις, οὐχ ἥκιστα κἀκεῖνο παρεκάλεσεν, ὅτι τῆς μὲν ἀνδρίας καὶ τῆς δεινότητος καὶ τῶν ἄλλων τῶν εὐδοκιμούντων ἑώρων καὶ τῶν κακῶν ἀνδρῶν πολλοὺς μετέχοντας, τὴν δὲ δικαιοσύνην καὶ σωφροσύνην ἴδια κτήματα τῶν καλῶν κἀγαθῶν ὄντα. κάλλιστον οὖν ὑπέλαβον, εἴ τις δύναιτο ταύταις ταῖς ἀρεταῖς προέχειν τῶν ἄλλων, ὧν οὐδὲν μέρος τοῖς πονηροῖς μέτεστιν, ἀλλὰ γνησιώταται καὶ βεβαιόταται καὶ μεγίστων ἐπαίνων ἄξιαι τυγχάνουσιν οὖσαι.", "st": "3.43"}, {"sp": "N", "t": "τούτων ἕνεκα καὶ ταῦτα διανοηθεὶς περιττοτέρως τῶν ἄλλων ἤσκησα τὴν σωφροσύνην καὶ προειλόμην τῶν ἡδονῶν οὐ τὰς ἐπὶ τοῖς ἔργοις τοῖς μηδεμίαν τιμὴν ἔχουσιν, ἀλλὰ τὰς ἐπὶ ταῖς δόξαις ταῖς δι’ ἀνδραγαθίαν γιγνομέναις. χρὴ δὲ δοκιμάζειν τὰς ἀρετὰς οὐκ ἐν ταῖς αὐταῖς ἰδέαις ἁπάσας, ἀλλὰ τὴν μὲν δικαιοσύνην ἐν ταῖς ἀπορίαις, τὴν δὲ σωφροσύνην ἐν ταῖς δυναστείαις, τὴν δ’ ἐγκράτειαν ἐν ταῖς τῶν νεωτέρων ἡλικίαις.", "st": "3.44"}, {"sp": "N", "t": "ἐγὼ τοίνυν ἐν πᾶσι τοῖς καιροῖς φανήσομαι πεῖραν τῆς ἐμαυτοῦ φύσεως δεδωκώς. ἐνδεὴς μέν γε χρημάτων καταλειφθεὶς οὕτω δίκαιον ἐμαυτὸν παρέσχον ὥστε μηδένα λυπῆσαι τῶν πολιτῶν· λαβὼν δ’ ἐξουσίαν ὥστε ποιεῖν ὅ τι ἂν βούλωμαι, σωφρονέστερος τῶν ἰδιωτῶν ἐγενόμην· τούτων δ’ ἀμφοτέρων ἐκράτησα ταύτην ἔχων τὴν ἡλικίαν, ἐν ᾗ τοὺς πλείστους ἂν εὕροιμεν πλεῖστα περὶ τὰς πράξεις ἐξαμαρτάνοντας.", "st": "3.45"}, {"sp": "N", "t": "καὶ ταῦτ’ ἐν ἑτέροις μὲν ἴσως ἂν ὤκνουν εἰπεῖν, οὐχ ὡς οὐ φιλοτιμούμενος ἐπὶ τοῖς πεπραγμένοις, ἀλλ’ ὡς οὐκ ἂν πιστευθεὶς ἐκ τῶν λεγομένων· ὑμεῖς δ’ αὐτοί μοι μάρτυρές ἐστε πάντων τῶν εἰρημένων· ἄξιον μὲν οὖν καὶ τοὺς φύσει κοσμίους ὄντας ἐπαινεῖν καὶ θαυμάζειν, ἔτι δὲ μᾶλλον καὶ τοὺς μετὰ λογισμοῦ τοιούτους ὄντας·", "st": "3.46"}, {"sp": "N", "t": "οἱ μὲν γὰρ τύχῃ καὶ μὴ γνώμῃ σωφρονοῦντες τυχὸν ἂν καὶ μεταπεισθεῖεν· οἱ δὲ πρὸς τῳ πεφυκέναι καὶ διεγνωκότες ὅτι μέγιστόν ἐστι τῶν ἀγαθῶν ἀρετή, δῆλον ὅτι πάντα τὸν βίον ἐν ταύτῃ τῇ τάξει διαμενοῦσιν. διὰ τοῦτο δὲ πλείους ἐποιησάμην τοὺς λόγους καὶ περὶ ἐμαυτοῦ καὶ περὶ τῶν ἄλλων τῶν προειρημένων, ἵνα μηδεμίαν ὑπολίπω πρόφασιν ὡς οὐ δεῖ ποιεῖν ὑμᾶς ἑκόντας καὶ προθύμως, ἅττ’ ἂν ἐγὼ συμβουλεύσω καὶ προστάξω.", "st": "3.47"}, {"sp": "N", "t": "φημὶ δὲ χρῆναι πράττειν ἕκαστον ὑμῶν, ἐφ’ οἷς ἐφέστηκεν, ἐπιμελῶς καὶ δικαίως· καθ’ ὁπότερον γὰρ ἂν ἐλλείπητε τούτων, ἀνάγκη κακῶς σχεῖν ταύτῃ τὰς πράξεις. μηδενὸς ὀλιγωρεῖτε μηδὲ καταφρονεῖτε τῶν προστεταγμένων, ὑπολαμβάνοντες ὡς οὐ παρὰ τοῦτ’ ἐστίν, ἀλλ’ ὡς παρ’ ἕκαστον τῶν μερῶν ἢ καλῶς ἢ κακῶς τὸ σύμπαν ἕξον,", "st": "3.48"}, {"sp": "N", "t": "οὕτω σπουδάζετε περὶ αὐτῶν. κήδεσθε μηδὲν ἧττον τῶν ἐμῶν ἢ τῶν ὑμετέρων αὐτῶν, καὶ μὴ νομίζετε μικρὸν ἀγαθὸν εἶναι τὰς τιμὰς ἃς ἔχουσιν οἱ καλῶς τῶν ἡμετέρων ἐπιστατοῦντες. ἀπέχεσθε τῶν ἀλλοτρίων, ἵν’ ἀσφαλέστερον τοὺς οἴκους τοὺς ὑμετέρους αὐτῶν κεκτῆσθε. τοιούτους εἶναι χρὴ περὶ τοὺς ἄλλους, οἷόν περ ἐμὲ περὶ ὑμᾶς ἀξιοῦτε γίγνεσθαι.", "st": "3.49"}, {"sp": "N", "t": "μὴ σπεύδετε πλουτεῖν μᾶλλον ἢ χρηστοὶ δοκεῖν εἶναι, γιγνώσκοντες ὅτι καὶ τῶν Ἑλλήνων καὶ τῶν βαρβάρων οἱ μεγίστας ἐπ’ ἀρετῇ δόξας ἔχοντες πλείστων ἀγαθῶν δεσπόται καθίστανται. τοὺς χρηματισμοὺς τοὺς παρὰ τὸ δίκαιον γιγνομένους ἡγεῖσθε μὴ πλοῦτον ἀλλὰ κίνδυνον ποιήσειν. μὴ τὸ μὲν λαβεῖν κέρδος εἶναι νομίζετε, τὸ δ’ ἀναλῶσαι ζημίαν· οὐδέτερον γὰρ τούτων ἀεὶ τὴν αὐτὴν ἔχει δύναμιν, ἀλλ’ ὁπότερον ἂν ἐν καιρῷ καὶ μετ’ ἀρετῆς γίγνηται, τοῦτ’ ὠφελεῖ τοὺς ποιοῦντας.", "st": "3.50"}, {"sp": "N", "t": "μηδὲ πρὸς ἓν χαλεπῶς ἔχετε τῶν ὑπ’ ἐμοῦ προσταττομένων· ὅσοι γὰρ ἂν ὑμῶν περὶ πλεῖστα τῶν ἐμῶν χρησίμους αὑτοὺς παράσχωσιν, οὗτοι πλεῖστα τοὺς οἴκους τοὺς αὑτῶν ὠφελήσουσιν. ὅ τι ἂν ὑμῶν ἕκαστος αὐτὸς αὑτῷ τύχῃ συνειδώς, ἡγείσθω μηδ’ ἐμὲ λήσειν, ἀλλ’ ἐὰν καὶ τὸ σῶμα μὴ παρῇ, τὴν διάνοιαν τὴν ἐμὴν οἰέσθω τοῖς γιγνομένοις παρεστάναι· ταύτην γὰρ τὴν γνώμην ἔχοντες, σωφρονέστερον βουλεύσεσθε περὶ ἁπάντων.", "st": "3.51"}, {"sp": "N", "t": "μηδὲν ἀποκρύπτεσθε μήθ’ ὧν κέκτησθε μήθ’ ὧν ποιεῖτε μήθ’ ὧν μέλλετε πράττειν, εἰδότες ὅτι περὶ τὰ κεκρυμμένα τῶν πραγμάτων ἀναγκαῖόν ἐστι πολλοὺς φόβους γίγνεσθαι. μὴ τεχνικῶς ζητεῖτε πολιτεύεσθαι μηδ’ ἀφανῶς, ἀλλ’ οὕτως ἁπλῶς καὶ φανερῶς ὥστε μηδ’ ἄν τις βούληται ῥᾴδιον ὑμᾶς εἶναι διαβαλεῖν. δοκιμάζετε τὰς πράξεις, καὶ νομίζετε πονηρὰς μὲν ἃς πράττοντες λανθάνειν ἐμὲ βούλεσθε, χρηστὰς δὲ περὶ ὧν ἐγὼ μέλλω πυθόμενος βελτίους ὑμᾶς νομιεῖν.", "st": "3.52"}, {"sp": "N", "t": "μὴ κατασιωπᾶτε, ἄν τινας ὁρᾶτε περὶ τὴν ἀρχὴν τὴν ἐμὴν πονηροὺς ὄντας, ἀλλ’ ἐξελέγχετε, καὶ νομίζετε τῆς αὐτῆς ζημίας ἀξίους εἶναι τοὺς συγκρύπτοντας τοῖς ἁμαρτάνουσιν. εὐτυχεῖν νομίζετε μὴ τοὺς λανθάνοντας, ἐάν τι κακὸν ποιήσωσιν, ἀλλὰ τοὺς μηδὲν ἐξαμαρτάνοντας· τοὺς μὲν γὰρ εἰκὸς τοιαῦτα παθεῖν, οἷά περ αὐτοὶ ποιοῦσι, τοὺς δὲ χάριν ἀπολαβεῖν, ἧς ἄξιοι τυγχάνουσιν ὄντες.", "st": "3.53"}, {"sp": "N", "t": "ἑταιρείας μὴ ποιεῖσθε μηδὲ συνόδους ἄνευ τῆς ἐμῆς γνώμης· αἱ γὰρ τοιαῦται συστάσεις ἐν μὲν ταῖς ἄλλαις πολιτείαις πλεονεκτοῦσιν, ἐν δὲ ταῖς μοναρχίαις κινδυνεύουσιν. μὴ μόνον ἀπέχεσθε τῶν ἁμαρτημάτων, ἀλλὰ καὶ τῶν ἐπιτηδευμάτων τῶν τοιούτων ἐν οἷς ἀναγκαῖόν ἐστιν ὑποψίαν ἐγγίγνεσθαι. τὴν ἐμὴν φιλίαν ἀσφαλεστάτην καὶ βεβαιοτάτην εἶναι νομίζετε. διαφυλάττετε τὴν παροῦσαν κατάστασιν,", "st": "3.54"}, {"sp": "N", "t": "καὶ μηδεμιᾶς ἐπιθυμεῖτε μεταβολῆς, εἰδότες ὅτι διὰ τὰς ταραχὰς ἀναγκαῖόν ἐστι καὶ τὰς πόλεις ἀπόλλυσθαι καὶ τοὺς οἴκους τοὺς ἰδίους ἀναστάτους γίγνεσθαι. μὴ μόνον τὰς φύσεις αἰτίας νομίζετε τοῦ χαλεποὺς ἢ πράους εἶναι τοὺς τυράννους, ἀλλὰ καὶ τὸν τρόπον τὸν τῶν πολιτῶν· πολλοὶ γὰρ ἤδη διὰ τὴν τῶν ἀρχομένων κακίαν τραχύτερον ἢ κατὰ τὴν αὑτῶν γνώμην ἄρχειν ἠναγκάσθησαν.", "st": "3.55"}, {"sp": "N", "t": "θαρρεῖτε μὴ μᾶλλον διὰ τὴν πραότητα τὴν ἐμὴν ἢ διὰ τὴν ὑμετέραν αὐτῶν ἀρετήν. τὴν ἐμὴν ἀσφάλειαν ἄδειαν ὑμῖν αὐτοῖς εἶναι νομίζετε· καλῶς γὰρ τῶν περὶ ἐμὲ καθεστώτων τὸν αὐτὸν τρόπον καὶ τὰ περὶ ὑμᾶς ἕξει. ταπεινοὺς μὲν εἶναι χρὴ πρὸς τὴν ἀρχὴν τὴν ἐμήν, ἐμμένοντας τοῖς ἔθεσι καὶ διαφυλάττοντας τοὺς νόμους τοὺς βασιλικούς, λαμπροὺς δ’ ἐν ταῖς ὑπὲρ τῆς πόλεως λειτουργίαις καὶ τοῖς ἄλλοις τοῖς ὑπ’ ἐμοῦ προσταττομένοις.", "st": "3.56"}, {"sp": "N", "t": "προτρέπετε τοὺς νεωτέρους ἐπ’ ἀρετὴν μὴ μόνον παραινοῦντες, ἀλλὰ καὶ περὶ τὰς πράξεις ὑποδεικνύοντες αὐτοῖς οἵους εἶναι χρὴ τοὺς ἄνδρας τοὺς ἀγαθούς. διδάσκετε τοὺς παῖδας τοὺς ὑμετέρους αὐτῶν πειθαρχεῖν, καὶ περὶ τὴν παίδευσιν τὴν εἰρημένην ἐθίζετ’ αὐτοὺς ὡς μάλιστα διατρίβειν· ἢν γὰρ καλῶς ἄρχεσθαι μάθωσι, πολλῶν ἄρχειν δυνήσονται, καὶ πιστοὶ μὲν ὄντες καὶ δίκαιοι μεθέξουσι τῶν ἡμετέρων ἀγαθῶν, κακοὶ δὲ γενόμενοι κινδυνεύσουσι περὶ τῶν ὑπαρχόντων.", "st": "3.57"}, {"sp": "N", "t": "μέγιστον ἡγεῖσθε καὶ βεβαιότατον τοῖς παισὶ πλοῦτον παραδώσειν, ἢν αὐτοῖς δύνησθε τὴν ἡμετέραν εὔνοιαν καταλείπειν. ἀθλιωτάτους ἡγεῖσθε καὶ δυστυχεστάτους, ὅσοι περὶ τοὺς πιστεύοντας ἄπιστοι γεγόνασιν· ἀνάγκη γὰρ τοὺς τοιούτους ἀθύμως ἔχοντας καὶ φοβουμένους ἅπαντα καὶ μηδὲν μᾶλλον πιστεύοντας τοῖς φίλοις ἢ τοῖς ἐχθροῖς τὸν ἐπίλοιπον χρόνον διάγειν.", "st": "3.58"}, {"sp": "N", "t": "ζηλοῦτε μὴ τοὺς πλεῖστα κεκτημένους, ἀλλὰ τοὺς μηδὲν κακὸν σφίσιν αὐτοῖς συνειδότας· μετὰ γὰρ τοιαύτης ψυχῆς ἥδιστ’ ἄν τις δύναιτο τὸν βίον διαγαγεῖν. μὴ τὴν κακίαν οἴεσθε δύνασθαι μὲν πλείω τῆς ἀρετῆς ὠφελεῖν, τὸ δ’ ὄνομα δυσχερέστερον ἔχειν, ἀλλ’ οἵων περ ὀνομάτων ἕκαστον τῶν πραγμάτων τετύχηκε, τοιαύτας ἡγεῖσθε καὶ τὰς δυνάμεις αὐτῶν εἶναι.", "st": "3.59"}, {"sp": "N", "t": "μὴ φθονεῖτε τοῖς παρ’ ἐμοὶ πρωτεύουσιν ἀλλ’ ἁμιλλᾶσθε, καὶ πειρᾶσθε χρηστοὺς ὑμᾶς αὐτοὺς παρέχοντες ἐξισοῦσθαι τοῖς προέχουσιν. φιλεῖν οἴεσθε δεῖν καὶ τιμᾶν οὕσπερ ἂν καὶ ὁ βασιλεύς, ἵνα καὶ παρ’ ἐμοῦ τυγχάνητε τῶν αὐτῶν τούτων. οἷά περ παρόντος μου λέγετε, τοιαῦτα καὶ περὶ ἀπόντος φρονεῖτε.", "st": "3.60"}, {"sp": "N", "t": "τὴν εὔνοιαν τὴν πρὸς ἡμᾶς ἐν τοῖς ἔργοις ἐνδείκνυσθε μᾶλλον ἢ ἐν τοῖς λόγοις. ἃ πάσχοντες ὑφ’ ἑτέρων ὀργίζεσθε, ταῦτα τοὺς ἄλλους μὴ ποιεῖτε. περὶ ὧν ἂν ἐν τοῖς λόγοις κατηγορῆτε, μηδὲν τούτων ἐν τοῖς ἔργοις ἐπιτηδεύετε. τοιαῦτα προσδοκᾶτε πράξειν, οἷ’ ἂν περὶ ἡμῶν διανοῆσθε. μὴ μόνον ἐπαινεῖτε τοὺς ἀγαθοὺς ἀλλὰ καὶ μιμεῖσθε.", "st": "3.61"}, {"sp": "N", "t": "τοὺς λόγους τοὺς ἐμοὺς νόμους εἶναι νομίζοντες πειρᾶσθε τούτοις ἐμμένειν, εἰδότες ὅτι τοῖς μάλιστα ποιοῦσιν ὑμῶν ἁγὼ βούλομαι, τάχιστα τούτοις ἐξέσται ζῆν ὡς αὐτοὶ βούλονται. κεφάλαιον δὲ τῶν εἰρημένων· οἵους περ τοὺς ὑφ’ ὑμῶν ἀρχομένους οἴεσθε δεῖν περὶ ὑμᾶς εἶναι, τοιούτους χρὴ καὶ περὶ τὴν ἀρχὴν τὴν ἐμὴν ὑμᾶς γίγνεσθαι.", "st": "3.62"}, {"sp": "N", "t": "καὶ ταῦτ’ ἂν ποιῆτε, τί δεῖ περὶ τῶν συμβησομένων μακρολογεῖν; ἢν γὰρ ἐγώ τε παρέχω τοιοῦτον ἐμαυτὸν οἷόν περ ἐν τῷ παρελθόντι χρόνῳ, καὶ τὰ παρ’ ὑμῶν ὑπηρετῆται, ταχέως ὄψεσθε καὶ τὸν βίον τὸν ὑμέτερον αὐτῶν ἐπιδεδωκότα καὶ τὴν ἀρχὴν τὴν ἐμὴν ηὐξημένην καὶ τὴν πόλιν εὐδαίμονα γεγενημένην.", "st": "3.63"}, {"sp": "N", "t": "ἄξιον μὲν οὖν τηλικούτων ἀγαθῶν ἕνεκα μηδὲν ἐλλείπειν, ἀλλὰ καὶ πόνους καὶ κινδύνους οὑστινασοῦν ὑπενεγκεῖν· ὑμῖν δ’ ἔξεστι μηδὲν ταλαιπωρηθεῖσιν, ἀλλὰ πιστοῖς μόνον καὶ δικαίοις οὖσιν, ἅπαντα ταῦτα διαπράξασθαι.", "st": "3.64"}, {"sp": "HDR", "t": "Πανηγυρικός", "st": "4"}, {"sp": "N", "t": "πολλάκις ἐθαύμασα τῶν τὰς πανηγύρεις συναγαγόντων καὶ τοὺς γυμνικοὺς ἀγῶνας καταστησάντων, ὅτι τὰς μὲν τῶν σωμάτων εὐτυχίας οὕτω μεγάλων δωρεῶν ἠξίωσαν, τοῖς δ’ ὑπὲρ τῶν κοινῶν ἰδίᾳ πονήσασι καὶ τὰς ἑαυτῶν ψυχὰς οὕτω παρασκευάσασιν ὥστε καὶ τοὺς ἄλλους ὠφελεῖν δύνασθαι,", "st": "4.1"}, {"sp": "N", "t": "τούτοις δ’ οὐδεμίαν τιμὴν ἀπένειμαν· ὧν εἰκὸς ἦν αὐτοὺς μᾶλλον ποιήσασθαι πρόνοιαν· τῶν μὲν γὰρ ἀθλητῶν δὶς τοσαύτην ῥώμην λαβόντων οὐδὲν ἂν πλέον γένοιτο τοῖς ἄλλοις, ἑνὸς δὲ ἀνδρὸς εὖ φρονήσαντος ἅπαντες ἂν ἀπολαύσειαν οἱ βουλόμενοι κοινωνεῖν τῆς ἐκείνου διανοίας.", "st": "4.2"}, {"sp": "N", "t": "οὐ μὴν ἐπὶ τούτοις ἀθυμήσας εἱλόμην ῥᾳθυμεῖν, ἀλλ’ ἱκανὸν νομίσας ἆθλον ἔσεσθαί μοι τὴν δόξαν τὴν ἀπ’ αὐτοῦ λόγου γενησομένην ἥκω συμβουλεύσων περί τε τοῦ πολέμου τοῦ πρὸς τοὺς βαρβάρους καὶ τῆς ὁμονοίας τῆς πρὸς ἡμᾶς αὐτούς, οὐκ ἀγνοῶν ὅτι πολλοὶ τῶν προσποιησαμένων εἶναι σοφιστῶν ἐπὶ τοῦτον τὸν λόγον ὥρμησαν,", "st": "4.3"}, {"sp": "N", "t": "ἀλλ’ ἅμα μὲν ἐλπίζων τοσοῦτον διοίσειν ὥστε τοῖς ἄλλοις μηδὲν πώποτε δοκεῖν εἰρῆσθαι περὶ αὐτῶν, ἅμα δὲ προκρίνας τούτους καλλίστους εἶναι τῶν λόγων, οἵτινες περὶ μεγίστων τυγχάνουσιν ὄντες καὶ τούς τε λέγοντας μάλιστ’ ἐπιδεικνύουσι καὶ τοὺς ἀκούοντας πλεῖστ’ ὠφελοῦσιν,", "st": "4.4"}, {"sp": "N", "t": "ὧν εἷς οὗτός ἐστιν. ἔπειτ’ οὐδ’ οἱ καιροί πω παρεληλύθασιν, ὥστ’ ἤδη μάτην εἶναι τὸ μεμνῆσθαι περὶ τούτων. τότε γὰρ χρὴ παύεσθαι λέγοντας, ὅταν ἢ τὰ πράγματα λάβῃ τέλος καὶ μηκέτι δέῃ βουλεύεσθαι περὶ αὐτῶν, ἢ τὸν λόγον ἴδῃ τις ἔχοντα πέρας, ὥστε μηδεμίαν λελεῖφθαι τοῖς ἄλλοις ὑπερβολήν.", "st": "4.5"}, {"sp": "N", "t": "ἕως δ’ τὰ μὲν ὁμοίως ὥσπερ πρότερον φέρηται, τὰ δ’ εἰρημένα φαύλως ἔχοντα τυγχάνῃ, πῶς οὐ χρὴ σκοπεῖν καὶ φιλοσοφεῖν τοῦτον τὸν λόγον, ὃς ἢν κατορθωθῇ, καὶ τοῦ πολέμου τοῦ πρὸς ἀλλήλους καὶ τῆς ταραχῆς τῆς παρούσης καὶ τῶν μεγίστων κακῶν ἡμᾶς ἀπαλλάξει;", "st": "4.6"}, {"sp": "N", "t": "πρὸς δὲ τούτοις, εἰ μὲν μηδαμῶς ἄλλως οἷόν τ’ ἦν δηλοῦν τὰς αὐτὰς πράξεις ἀλλ’ ἢ διὰ μιᾶς ἰδέας, εἶχεν ἄν τις ὑπολαβεῖν ὡς περίεργόν ἐστι τὸν αὐτὸν τρόπον ἐκείνοις λέγοντα πάλιν ἐνοχλεῖν τοῖς ἀκούουσιν· ἐπειδὴ δ’ οἱ λόγοι τοιαύτην ἔχουσι τὴν φύσιν,", "st": "4.7"}, {"sp": "N", "t": "ὥσθ’ οἷόν τ’ εἶναι περὶ τῶν αὐτῶν πολλαχῶς ἐξηγήσασθαι, καὶ τά τε μεγάλα ταπεινὰ ποιῆσαι καὶ τοῖς μικροῖς μέγεθος περιθεῖναι, καὶ τά τε παλαιὰ καινῶς διελθεῖν καὶ περὶ τῶν νεωστὶ γεγενημένων ἀρχαίως εἰπεῖν, οὐκέτι φευκτέον ταῦτ’ ἐστὶ περὶ ὧν ἕτεροι πρότερον εἰρήκασιν, ἀλλ’ ἄμεινον ἐκείνων εἰπεῖν πειρατέον.", "st": "4.8"}, {"sp": "N", "t": "αἱ μὲν γὰρ πράξεις αἱ προγεγενημέναι κοιναὶ πᾶσιν ἡμῖν κατελείφθησαν, τὸ δ’ ἐν καιρῷ ταύταις καταχρήσασθαι καὶ τὰ προσήκοντα περὶ ἑκάστης ἐνθυμηθῆναι καὶ τοῖς ὀνόμασιν εὖ διαθέσθαι τῶν εὖ φρονούντων ἴδιόν ἐστιν.", "st": "4.9"}, {"sp": "N", "t": "ἡγοῦμαι δ’ οὕτως ἂν μεγίστην ἐπίδοσιν λαμβάνειν καὶ τὰς ἄλλας τέχνας καὶ τὴν περὶ τοὺς λόγους φιλοσοφίαν, εἴ τις θαυμάζοι καὶ τιμῴη μὴ τοὺς πρώτους τῶν ἔργων ἀρχομένους, ἀλλὰ τοὺς ἄρισθ’ ἕκαστον αὐτῶν ἐξεργαζομένους, μηδὲ τοὺς περὶ τούτων ζητοῦντας λέγειν περὶ ὧν μηδεὶς πρότερον εἴρηκεν, ἀλλὰ τοὺς οὕτως ἐπισταμένους εἰπεῖν ὡς οὐδεὶς ἂν ἄλλος δύναιτο.", "st": "4.10"}, {"sp": "N", "t": "καίτοι τινὲς ἐπιτιμῶσι τῶν λόγων τοῖς ὑπὲρ τοὺς ἰδιώτας ἔχουσι καὶ λίαν ἀπηκριβωμένοις, καὶ τοσοῦτον διημαρτήκασιν ὥστε τοὺς πρὸς ὑπερβολὴν πεποιημένους πρὸς τοὺς ἀγῶνας τοὺς περὶ τῶν ἰδίων συμβολαίων σκοποῦσιν, ὥσπερ ὁμοίως δέον ἀμφοτέρους ἔχειν, ἀλλ’ οὐ τοὺς μὲν ἀσφαλῶς τοὺς δ’ ἐπιδεικτικῶς, ἢ σφᾶς μὲν διορῶντας τὰς μετριότητας, τὸν δ’ ἀκριβῶς ἐπιστάμενον λέγειν ἁπλῶς οὐκ ἂν δυνάμενον εἰπεῖν.", "st": "4.11"}, {"sp": "N", "t": "μὲν οὖν οὐ λελήθασιν ὅτι τούτους ἐπαινοῦσιν ὧν ἐγγὺς αὐτοὶ τυγχάνουσιν ὄντες· ἐμοὶ δ’ οὐδὲν πρὸς τοὺς τοιούτους ἀλλὰ πρὸς ἐκείνους ἐστί, τοὺς οὐδὲν ἀποδεξομένους τῶν εἰκῇ λεγομένων, ἀλλὰ δυσχερανοῦντας καὶ ζητήσοντας ἰδεῖν τι τοιοῦτον ἐν τοῖς ἐμοῖς, οἷον παρὰ τοῖς ἄλλοις οὐχ εὑρήσουσιν. πρὸς οὓς ἔτι μικρὸν ὑπὲρ ἐμαυτοῦ θρασυνάμενος, ἤδη περὶ τοῦ πράγματος ποιήσομαι τοὺς λόγους.", "st": "4.12"}, {"sp": "N", "t": "τοὺς μὲν γὰρ ἄλλους ἐν τοῖς προοιμίοις ὁρῶ καταπραΰνοντας τοὺς ἀκροατάς, καὶ προφασιζομένους ὑπὲρ τῶν μελλόντων ῥηθήσεσθαι, καὶ λέγοντας τοὺς μὲν ὡς ἐξ ὑπογυίου γέγονεν αὐτοῖς ἡ παρασκευή, τοὺς δ’ ὡς χαλεπόν ἐστιν ἴσους τοὺς λόγους τῷ μεγέθει τῶν ἔργων ἐξευρεῖν.", "st": "4.13"}, {"sp": "N", "t": "ἐγὼ δ’ ἢν μὴ καὶ τοῦ πράγματος ἀξίως εἴπω καὶ τῆς δόξης τῆς ἐμαυτοῦ καὶ τοῦ χρόνου, μὴ μόνον τοῦ περὶ τὸν λόγον ἡμῖν διατριφθέντος ἀλλὰ καὶ σύμπαντος οὗ βεβίωκα, παρακελεύομαι μηδεμίαν συγγνώμην ἔχειν, ἀλλὰ καταγελᾶν καὶ καταφρονεῖν· οὐδὲν γὰρ ὅ τι τῶν τοιούτων οὐκ ἄξιός εἰμι πάσχειν, εἴπερ μηδὲν διαφέρων οὕτω μεγάλας ποιοῦμαι τὰς ὑποσχέσεις. περὶ μὲν οὖν τῶν ἰδίων ταῦτά μοι προειρήσθω. περὶ δὲ τῶν κοινῶν,", "st": "4.14"}, {"sp": "N", "t": "ὅσοι μὲν εὐθὺς ἐπελθόντες διδάσκουσιν ὡς χρὴ διαλυσαμένους τὰς πρὸς ἡμᾶς αὐτοὺς ἔχθρας ἐπὶ τὸν βάρβαρον τραπέσθαι, καὶ διεξέρχονται τάς τε συμφορὰς τὰς ἐκ τοῦ πολέμου τοῦ πρὸς ἀλλήλους ἡμῖν γεγενημένας καὶ τὰς ὠφελείας τὰς ἐκ τῆς στρατείας τῆς ἐπ’ ἐκεῖνον ἐσομένας, ἀληθῆ μὲν λέγουσιν, οὐ μὴν ἐντεῦθεν ποιοῦνται τὴν ἀρχὴν ὅθεν ἂν μάλιστα συστῆσαι ταῦτα δυνηθεῖεν.", "st": "4.15"}, {"sp": "N", "t": "τῶν γὰρ Ἑλλήνων οἱ μὲν ὑφ’ ἡμῖν οἱ δ’ ὑπὸ Λακεδαιμονίοις εἰσίν· αἱ γὰρ πολιτεῖαι, δι’ ὧν οἰκοῦσι τὰς πόλεις, οὕτω τοὺς πλείστους αὐτῶν διειλήφασιν. ὅστις οὖν οἴεται τοὺς ἄλλους κοινῇ τι πράξειν ἀγαθόν, πρὶν ἂν τοὺς προεστῶτας αὐτῶν διαλλάξῃ, λίαν ἁπλῶς καὶ πόρρω τῶν πραγμάτων ἐστίν.", "st": "4.16"}, {"sp": "N", "t": "ἀλλὰ δεῖ τὸν μὴ μόνον ἐπίδειξιν ποιούμενον ἀλλὰ καὶ διαπράξασθαί τι βουλόμενον ἐκείνους τοὺς λόγους ζητεῖν, οἵ τινες τὼ πόλη τούτω πείσουσιν ἰσομοιρῆσαι πρὸς ἀλλήλας καὶ τάς θ’ ἡγεμονίας διελέσθαι καὶ τὰς πλεονεξίας ἃς νῦν παρὰ τῶν Ἑλλήνων ἐπιθυμοῦσιν αὑταῖς γίγνεσθαι, ταύτας παρὰ τῶν βαρβάρων ποιήσασθαι.", "st": "4.17"}, {"sp": "N", "t": "τὴν μὲν οὖν ἡμετέραν πόλιν ῥᾴδιον ἐπὶ ταῦτα προαγαγεῖν, Λακεδαιμόνιοι δὲ νῦν μὲν ἔτι δυσπείστως ἔχουσι· παρειλήφασι γὰρ ψευδῆ λόγον, ὡς ἔστιν αὐτοῖς ἡγεῖσθαι πάτριον· ἢν δ’ ἐπιδείξῃ τις αὐτοῖς ταύτην τὴν τιμὴν ἡμετέραν οὖσαν μᾶλλον ἢ ’κείνων, τάχ’ ἂν ἐάσαντες τὸ διακριβοῦσθαι περὶ τούτων ἐπὶ τὸ συμφέρον ἔλθοιεν.", "st": "4.18"}, {"sp": "N", "t": "ἐχρῆν μὲν οὖν καὶ τοὺς ἄλλους ἐντεῦθεν ἄρχεσθαι καὶ μὴ πρότερον περὶ τῶν ὁμολογουμένων συμβουλεύειν, πρὶν περὶ τῶν ἀμφισβητουμένων ἡμᾶς ἐδίδαξαν· ἐμοὶ δ’ οὖν ἀμφοτέρων ἕνεκα προσήκει περὶ ταῦτα ποιήσασθαι τὴν πλείστην διατριβήν, μάλιστα μὲν ἵνα προὔργου τι γένηται καὶ παυσάμενοι τῆς πρὸς ἡμᾶς αὐτοὺς φιλονικίας κοινῇ τοῖς βαρβάροις πολεμήσωμεν,", "st": "4.19"}, {"sp": "N", "t": "εἰ δὲ τοῦτ’ ἐστὶν ἀδύνατον, ἵνα δηλώσω τοὺς ἐμποδὼν ὄντας τῇ τῶν Ἑλλήνων εὐδαιμονία, καὶ πᾶσι γένηται φανερὸν ὅτι καὶ πρότερον ἡ πόλις ἡμῶν δικαίως τῆς θαλάττης ἦρξε καὶ νῦν οὐκ ἀδίκως ἀμφισβητεῖ τῆς ἡγεμονίας.", "st": "4.20"}, {"sp": "N", "t": "τοῦτο μὲν γὰρ εἰ δεῖ τούτους ἐφ’ ἑκάστῳ τιμᾶσθαι τῶν ἔργων, τοὺς ἐμπειροτάτους ὄντας καὶ μεγίστην δύναμιν ἔχοντας, ἀναμφισβητήτως ἡμῖν προσήκει τὴν ἡγεμονίαν ἀπολαβεῖν, ἥν περ πρότερον ἐτυγχάνομεν ἔχοντες· οὐδεὶς γὰρ ἂν ἑτέραν πόλιν ἐπιδείξειε τοσοῦτον ἐν τῷ πολέμῳ τῷ κατὰ γῆν ὑπερέχουσαν, ὅσον τὴν ἡμετέραν ἐν τοῖς κινδύνοις τοῖς κατὰ θάλατταν διαφέρουσαν.", "st": "4.21"}, {"sp": "N", "t": "τοῦτο δ’ εἴ τινες ταύτην μὲν μὴ νομίζουσι δικαίαν εἶναι τὴν κρίσιν, ἀλλὰ πολλὰς τὰς μεταβολὰς γίγνεσθαι (τὰς γὰρ δυναστείας οὐδέποτε τοῖς αὐτοῖς παραμένειν), ἀξιοῦσι δὲ τὴν ἡγεμονίαν ἔχειν ὥσπερ ἄλλο τι γέρας ἢ τοὺς πρώτους τυχόντας ταύτης τῆς τιμῆς ἢ τοὺς πλείστων ἀγαθῶν αἰτίους τοῖς Ἕλλησιν ὄντας, ἡγοῦμαι καὶ τούτους εἶναι μεθ’ ἡμῶν·", "st": "4.22"}, {"sp": "N", "t": "ὅσῳ γὰρ ἄν τις πορρωτέρωθεν σκοπῇ περὶ τούτων ἀμφοτέρων, τοσούτῳ πλέον ἀπολείψομεν τοὺς ἀμφισβητοῦντας. ὁμολογεῖται μὲν γὰρ τὴν πόλιν ἡμῶν ἀρχαιοτάτην εἶναι καὶ μεγίστην καὶ παρὰ πᾶσιν ἀνθρώποις ὀνομαστοτάτην· οὕτω δὲ καλῆς τῆς ὑποθέσεως οὔσης, ἐπὶ τοῖς ἐχομένοις τούτων ἔτι μᾶλλον ἡμᾶς προσήκει τιμᾶσθαι.", "st": "4.23"}, {"sp": "N", "t": "ταύτην γὰρ οἰκοῦμεν οὐχ ἑτέρους ἐκβαλόντες οὐδ’ ἐρήμην καταλαβόντες οὐδ’ ἐκ πολλῶν ἐθνῶν μιγάδες συλλεγέντες, ἀλλ’ οὕτω καλῶς καὶ γνησίως γεγόναμεν, ὥστ’ ἐξ ἧσπερ ἔφυμεν, ταύτην ἔχοντες ἅπαντα τὸν χρόνον διατελοῦμεν, αὐτόχθονες ὄντες καὶ τῶν ὀνομάτων τοῖς αὐτοῖς, οἷσπερ τοὺς οἰκειοτάτους,", "st": "4.24"}, {"sp": "N", "t": "τὴν πόλιν ἔχοντες προσειπεῖν· μόνοις γὰρ ἡμῖν τῶν Ἑλλήνων τὴν αὐτὴν τροφὸν καὶ πατρίδα καὶ μητέρα καλέσαι προσήκει. καίτοι χρὴ τοὺς εὐλόγως μέγα φρονοῦντας καὶ περὶ τῆς ἡγεμονίας δικαίως ἀμφισβητοῦντας καὶ τῶν πατρίων πολλάκις μεμνημένους τοιαύτην τὴν ἀρχὴν τοῦ γένους ἔχοντας φαίνεσθαι.", "st": "4.25"}, {"sp": "N", "t": "τὰ μὲν οὖν ἐξ ἀρχῆς ὑπάρξαντα καὶ παρὰ τῆς τύχης δωρηθέντα τηλικαῦθ’ ἡμῖν τὸ μέγεθός ἐστιν· ὅσων δὲ τοῖς ἄλλοις ἀγαθῶν αἴτιοι γεγόναμεν, οὕτως ἂν κάλλιστ’ ἐξετάσαιμεν, εἰ τόν τε χρόνον ἀπ’ ἀρχῆς καὶ τὰς πράξεις τὰς τῆς πόλεως ἐφεξῆς διέλθοιμεν· εὑρήσομεν γὰρ αὐτὴν οὐ μόνον τῶν πρὸς τὸν πόλεμον κινδύνων ἀλλὰ καὶ τῆς ἄλλης κατασκευῆς,", "st": "4.26"}, {"sp": "N", "t": "ἐν ᾗ κατοικοῦμεν καὶ μεθ’ ἧς πολιτευόμεθα καὶ δι’ ἣν ζῆν δυνάμεθα, σχεδὸν ἁπάσης αἰτίαν οὖσαν. ἀνάγκη δὲ προαιρεῖσθαι τῶν εὐεργεσιῶν μὴ τὰς διὰ μικρότητα διαλαθούσας καὶ κατασιωπηθείσας, ἀλλὰ τὰς διὰ τὸ μέγεθος ὑπὸ πάντων ἀνθρώπων καὶ πάλαι καὶ νῦν καὶ πανταχοῦ καὶ λεγομένας καὶ μνημονευομένας.", "st": "4.27"}, {"sp": "N", "t": "πρῶτον μὲν τοίνυν, οὗ πρῶτον ἡ φύσις ἡμῶν ἐδεήθη, διὰ τῆς πόλεως τῆς ἡμετέρας ἐπορίσθη· καὶ γὰρ εἰ μυθώδης ὁ λόγος γέγονεν, ὅμως αὐτῷ καὶ νῦν ῥηθῆναι προσήκει. Δήμητρος γὰρ ἀφικομένης εἰς τὴν χώραν ὅτ’ ἐπλανήθη τῆς Κόρης ἁρπασθείσης, καὶ πρὸς τοὺς προγόνους ἡμῶν εὐμενῶς διατεθείσης ἐκ τῶν εὐεργεσιῶν ἃς οὐχ οἷόν τ’ ἄλλοις ἢ τοῖς μεμυημένοις ἀκούειν, καὶ δούσης δωρεὰς διττὰς αἵπερ μέγισται τυγχάνουσιν οὖσαι, τούς τε καρπούς, οἳ τοῦ μὴ θηριωδῶς ζῆν ἡμᾶς αἴτιοι γεγόνασι, καὶ τὴν τελετήν, ἧς οἱ μετασχόντες περί τε τῆς τοῦ βίου τελευτῆς καὶ τοῦ σύμπαντος αἰῶνος ἡδίους τὰς ἐλπίδας ἔχουσιν,", "st": "4.28"}, {"sp": "N", "t": "οὕτως ἡ πόλις ἡμῶν οὐ μόνον θεοφιλῶς ἀλλὰ καὶ φιλανθρώπως ἔσχεν, ὥστε κυρία γενομένη τοσούτων ἀγαθῶν οὐκ ἐφθόνησε τοῖς ἄλλοις, ἀλλ’ ὧν ἔλαβεν ἅπασι μετέδωκεν. καὶ τὰ μὲν ἔτι καὶ νῦν καθ’ ἕκαστον τὸν ἐνιαυτὸν δείκνυμεν, τῶν δὲ συλλήβδην τάς τε χρείας καὶ τὰς ἐργασίας καὶ τὰς ὠφελίας τὰς ἀπ’ αὐτῶν γιγνομένας ἐδίδαξεν.", "st": "4.29"}, {"sp": "N", "t": "καὶ τούτοις ἀπιστεῖν μικρῶν ἔτι προστεθέντων οὐδεὶς ἂν ἀξιώσειεν. πρῶτον μὲν γάρ, ἐξ ὧν ἄν τις καταφρονήσειε τῶν λεγομένων ὡς ἀρχαίων ὄντων, ἐκ τῶν αὐτῶν τούτων εἰκότως ἂν καὶ τὰς πράξεις γεγενῆσθαι νομίσειεν· διὰ γὰρ τὸ πολλοὺς εἰρηκέναι καὶ πάντας ἀκηκοέναι προσήκει μὴ καινὰ μὲν πιστὰ δὲ δοκεῖν εἶναι τὰ λεγόμενα περὶ αὐτῶν. ἔπειτ’ οὐ μόνον ἐνταῦθα καταφυγεῖν ἔχομεν, ὅτι τὸν λόγον καὶ τὴν φήμην ἐκ πολλοῦ παρειλήφαμεν, ἀλλὰ καὶ σημείοις μείζοσιν ἢ τούτοις ἔστιν ἡμῖν χρήσασθαι περὶ αὐτῶν.", "st": "4.30"}, {"sp": "N", "t": "αἱ μὲν γὰρ πλεῖσται τῶν πόλεων ὑπόμνημα τῆς παλαιᾶς εὐεργεσίας ἀπαρχὰς τοῦ σίτου καθ’ ἕκαστον τὸν ἐνιαυτὸν ὡς ἡμᾶς ἀποπέμπουσι, ταῖς δ’ ἐκλειπούσαις πολλάκις ἡ Πυθία προσέταξεν ἀποφέρειν τὰ μέρη τῶν καρπῶν καὶ ποιεῖν πρὸς τὴν πόλιν τὴν ἡμετέραν τὰ πάτρια. καίτοι περὶ τίνων χρὴ μᾶλλον πιστεύειν ἢ περὶ ὧν ὅ τε θεὸς ἀναιρεῖ καὶ πολλοῖς τῶν Ἑλλήνων συνδοκεῖ, καὶ τά τε πάλαι ῥηθέντα τοῖς παροῦσιν ἔργοις συμμαρτυρεῖ, καὶ τὰ νῦν γιγνόμενα τοῖς ὑπ’ ἐκείνων εἰρημένοις ὁμολογεῖ; χωρὶς δὲ τούτων,", "st": "4.31"}, {"sp": "N", "t": "ἢν ἅπαντα ταῦτ’ ἐάσαντες ἀπὸ τῆς ἀρχῆς σκοπῶμεν, εὑρήσομεν ὅτι τὸν βίον οἱ πρῶτοι φανέντες ἐπὶ γῆς οὐκ εὐθὺς οὕτως ὥσπερ νῦν ἔχοντα κατέλαβον, ἀλλὰ κατὰ μικρὸν αὐτοὶ συνεπορίσαντο. τίνας οὖν χρὴ μᾶλλον νομίζειν ἢ δωρεὰν παρὰ τῶν θεῶν λαβεῖν ἢ ζητοῦντας αὐτοὺς ἐντυχεῖν;", "st": "4.32"}, {"sp": "N", "t": "οὐ τοὺς ὑπὸ πάντων ὁμολογουμένους καὶ πρώτους γενομένους καὶ πρός τε τὰς τέχνας εὐφυεστάτους ὄντας καὶ πρὸς τὰ τῶν θεῶν εὐσεβέστατα διακειμένους; καὶ μὴν ὅσης προσήκει τιμῆς τυγχάνειν τοὺς τηλικούτων ἀγαθῶν αἰτίους, περίεργον διδάσκειν· οὐδεὶς γὰρ ἂν δύναιτο δωρεὰν τοσαύτην τὸ μέγεθος εὑρεῖν, ἥ τις ἴση τοῖς πεπραγμένοις ἐστίν.", "st": "4.33"}, {"sp": "N", "t": "περὶ μὲν οὖν τοῦ μεγίστου τῶν εὐεργετημάτων καὶ πρώτου γενομένου καὶ πᾶσι κοινοτάτου ταῦτ’ εἰπεῖν ἔχομεν· περὶ δὲ τοὺς αὐτοὺς χρόνους ὁρῶσα τοὺς μὲν βαρβάρους τὴν πλείστην τῆς χώρας κατέχοντας, τοὺς δ’ Ἕλληνας εἰς μικρὸν τόπον κατακεκλειμένους καὶ διὰ σπανιότητα τῆς γῆς ἐπιβουλεύοντάς τε σφίσιν αὐτοῖς καὶ στρατείας ἐπ’ ἀλλήλους ποιουμένους, καὶ τοὺς μὲν δι’ ἔνδειαν τῶν καθ’ ἡμέραν τοὺς δὲ διὰ τὸν πόλεμον ἀπολλυμένους,", "st": "4.34"}, {"sp": "N", "t": "οὐδὲ ταῦθ’ οὕτως ἔχοντα περιεῖδεν, ἀλλ’ ἡγεμόνας εἰς τὰς πόλεις ἐξέπεμψεν, οἳ παραλαβόντες τοὺς μάλιστα βίου δεομένους, στρατηγοὶ καταστάντες αὐτῶν καὶ πολέμῳ κρατήσαντες τοὺς βαρβάρους, πολλὰς μὲν ἐφ’ ἑκατέρας τῆς ἠπείρου πόλεις ἔκτισαν, ἁπάσας δὲ τὰς νήσους κατῴκισαν, ἀμφοτέρους δὲ καὶ τοὺς ἀκολουθήσαντας καὶ τοὺς ὑπομείναντας ἔσωσαν·", "st": "4.35"}, {"sp": "N", "t": "τοῖς μὲν γὰρ ἱκανὴν τὴν οἴκοι χώραν κατέλιπον, τοῖς δὲ πλείω τῆς ὑπαρχούσης ἐπόρισαν· ἅπαντα γὰρ περιεβάλοντο τὸν τόπον, ὃν νῦν τυγχάνομεν κατέχοντες. ὥστε καὶ τοῖς ὕστερον βουληθεῖσιν ἀποικίσαι τινὰς καὶ μιμήσασθαι τὴν πόλιν τὴν ἡμετέραν πολλὴν ῥᾳστώνην ἐποίησαν· οὐ γὰρ αὐτοὺς ἔδει κτωμένους χώραν διακινδυνεύειν, ἀλλ’ εἰς τὴν ὑφ’ ἡμῶν ἀφορισθεῖσαν,", "st": "4.36"}, {"sp": "N", "t": "εἰς ταύτην οἰκεῖν ἰόντας. καίτοι τίς ἂν ταύτης ἡγεμονίαν ἐπιδείξειεν ἢ πατριωτέραν, τῆς πρότερον γενομένης πρὶν τὰς πλείστας οἰκισθῆναι τῶν Ἑλληνίδων πόλεων, ἢ μᾶλλον συμφέρουσαν, τῆς τοὺς μὲν βαρβάρους ἀναστάτους ποιησάσης, τοὺς δ’ Ἕλληνας εἰς τοσαύτην εὐπορίαν προαγαγούσης;", "st": "4.37"}, {"sp": "N", "t": "οὐ τοίνυν, ἐπειδὴ τὰ μέγιστα συνδιέπραξε, τῶν ἄλλων ὠλιγώρησεν, ἀλλ’ ἀρχὴν μὲν ταύτην ἐποιήσατο τῶν εὐεργεσιῶν, τροφὴν τοῖς δεομένοις εὑρεῖν, ἥνπερ χρὴ τοὺς μέλλοντας καὶ περὶ τῶν ἄλλων καλῶς διοικήσειν, ἡγουμένη δὲ τὸν βίον τὸν ἐπὶ τούτοις μόνον οὔπω τοῦ ζῆν ἐπιθυμεῖν ἀξίως ἔχειν οὕτως ἐπεμελήθη καὶ τῶν λοιπῶν, ὥστε τῶν παρόντων τοῖς ἀνθρώποις ἀγαθῶν, ὅσα μὴ παρὰ θεῶν ἔχομεν ἀλλὰ δι’ ἀλλήλους ἡμῖν γέγονε, μηδὲν μὲν ἄνευ τῇς πόλεως τῆς ἡμετέρας εἶναι, τὰ δὲ πλεῖστα διὰ ταύτην γεγενῆσθαι.", "st": "4.38"}, {"sp": "N", "t": "παραλαβοῦσα γὰρ τοὺς Ἕλληνας ἀνόμως ζῶντας καὶ σποράδην οἰκοῦντας, καὶ τοὺς μὲν ὑπὸ δυναστειῶν ὑβριζομένους τοὺς δὲ δι’ ἀναρχίαν ἀπολλυμένους, καὶ τούτων τῶν κακῶν αὐτοὺς ἀπήλλαξε, τῶν μὲν κυρία γενομένη, τοῖς δ’ αὑτὴν παράδειγμα ποιήσασα· πρώτη γὰρ καὶ νόμους ἔθετο καὶ πολιτείαν κατεστήσατο.", "st": "4.39"}, {"sp": "N", "t": "δῆλον δ’ ἐκεῖθεν· οἱ γὰρ ἐν ἀρχῇ περὶ τῶν φονικῶν ἐγκαλέσαντες, καὶ βουληθέντες μετὰ λόγου καὶ μὴ μετὰ βίας διαλύσασθαι τὰ πρὸς ἀλλήλους, ἐν τοῖς νόμοις τοῖς ἡμετέροις τὰς κρίσεις ἐποιήσαντο περὶ αὐτῶν. καὶ μὲν δὴ καὶ τῶν τεχνῶν τάς τε πρὸς τἀναγκαῖα τοῦ βίου χρησίμας καὶ τὰς πρὸς ἡδονὴν μεμηχανημένας, τὰς μὲν εὑροῦσα τὰς δὲ δοκιμάσασα χρῆσθαι τοῖς ἄλλοις παρέδωκεν.", "st": "4.40"}, {"sp": "N", "t": "τὴν τοίνυν ἄλλην διοίκησιν οὕτω φιλοξένως κατεσκευάσατο καὶ πρὸς ἅπαντας οἰκείως, ὥστε καὶ τοῖς χρημάτων δεομένοις καὶ τοῖς ἀπολαῦσαι τῶν ὑπαρχόντων ἐπιθυμοῦσιν ἀμφοτέροις ἁρμόττειν, καὶ μήτε τοῖς εὐδαιμονοῦσι μήτε τοῖς δυστυχοῦσιν ἐν ταῖς αὑτῶν ἀχρήστως ἔχειν, ἀλλ’ ἑκατέροις αὐτῶν εἶναι παρ’ ἡμῖν, τοῖς μὲν ἡδίστας διατριβάς, τοῖς δὲ ἀσφαλεστάτην καταφυγήν.", "st": "4.41"}, {"sp": "N", "t": "ἔτι δὲ τὴν χώραν οὐκ αὐτάρκη κεκτημένων ἑκάστων, ἀλλὰ τὰ μὲν ἐλλείπουσαν τὰ δὲ πλείω τῶν ἱκανῶν φέρουσαν, καὶ πολλῆς ἀπορίας οὔσης τὰ μὲν ὅπου χρὴ διαθέσθαι τὰ δ’ ὁπόθεν εἰσαγαγέσθαι, καὶ ταύταις ταῖς συμφοραῖς ἐπήμυνεν· ἐμπόριον γὰρ ἐν μέσῳ τῆς Ἑλλάδος τὸν Πειραιᾶ κατεσκευάσατο, τοσαύτην ἔχονθ’ ὑπερβολήν, ὥσθ’ ἃ παρὰ τῶν ἄλλων ἓν παρ’ ἑκάστων χαλεπόν ἐστι λαβεῖν, ταῦθ’ ἅπαντα παρ’ αὐτῆς ῥᾴδιον εἶναι πορίσασθαι.", "st": "4.42"}, {"sp": "N", "t": "τῶν τοίνυν τὰς πανηγύρεις καταστησάντων δικαίως ἐπαινουμένων ὅτι τοιοῦτον ἔθος ἡμῖν παρέδοσαν, ὥστε σπεισαμένους πρὸς ἀλλήλους καὶ τὰς ἔχθρας τὰς ἐνεστηκυίας διαλυσαμένους συνελθεῖν εἰς ταὐτόν, καὶ μετὰ ταῦτ’ εὐχὰς καὶ θυσίας κοινὰς ποιησαμένους ἀναμνησθῆναι μὲν τῆς συγγενείας τῆς πρὸς ἀλλήλους ὑπαρχούσης, εὐμενεστέρως δ’ εἰς τὸν λοιπὸν χρόνον διατεθῆναι πρὸς ἡμᾶς αὐτούς, καὶ τάς τε παλαιὰς ξενίας ἀνανεώσασθαι καὶ καινὰς ἑτέρας ποιήσασθαι,", "st": "4.43"}, {"sp": "N", "t": "καὶ μήτε τοῖς ἰδιώταις μήτε τοῖς διενεγκοῦσι τὴν φύσιν ἀργὸν εἶναι τὴν διατριβήν, ἀλλ’ ἀθροισθέντων τῶν Ἑλλήνων ἐγγενέσθαι τοῖς μὲν ἐπιδείξασθαι τὰς αὑτῶν εὐτυχίας, τοῖς δὲ θεάσασθαι τούτους πρὸς ἀλλήλους ἀγωνιζομένους, καὶ μηδετέρους ἀθύμως διάγειν, ἀλλ’ ἑκατέρους ἔχειν ἐφ’ οἷς φιλοτιμηθῶσιν, οἱ μὲν ὅταν ἴδωσι τοὺς ἀθλητὰς αὑτῶν ἕνεκα πονοῦντας, οἱ δ’ ὅταν ἐνθυμηθῶσιν ὅτι πάντες ἐπὶ τὴν σφετέραν θεωρίαν ἥκουσι, — τοσούτων τοίνυν ἀγαθῶν διὰ τὰς συνόδους ἡμῖν γιγνομένων οὐδ’ ἐν τούτοις ἡ πόλις ἡμῶν ἀπελείφθη.", "st": "4.44"}, {"sp": "N", "t": "καὶ γὰρ θεάματα πλεῖστα καὶ κάλλιστα κέκτηται, τὰ μὲν ταῖς δαπάναις ὑπερβάλλοντα, τὰ δὲ κατὰ τὰς τέχνας εὐδοκιμοῦντα, τὰ δ’ ἀμφοτέροις τούτοις διαφέροντα, καὶ τὸ πλῆθος τῶν εἰσαφικνουμένων ὡς ἡμᾶς τοσοῦτόν ἐστιν, ὥστ’ εἴ τι ἐν τῷ πλησιάζειν ἀλλήλοις ἀγαθόν ἐστι, καὶ τοῦθ’ ὑπ’ αὐτῆς περιειλῆφθαι. πρὸς δὲ τούτοις καὶ φιλίας εὑρεῖν πιστοτάτας καὶ συνουσίαις ἐντυχεῖν παντοδαπωτάταις μάλιστα παρ’ ἡμῖν ἔστιν, ἔτι δ’ ἀγῶνας ἰδεῖν, μὴ μόνον τάχους καὶ ῥώμης, ἀλλὰ καὶ λόγων καὶ γνώμης καὶ τῶν ἄλλων ἔργων ἁπάντων, καὶ τούτων ἆθλα μέγιστα.", "st": "4.45"}, {"sp": "N", "t": "πρὸς γὰρ οἷς αὐτὴ τίθησι, καὶ τοὺς ἄλλους διδόναι συναναπείθει· τὰ γὰρ ὑφ’ ἡμῶν κριθέντα τοσαύτην λαμβάνει δόξαν ὥστε παρὰ πᾶσιν ἀνθρώποις ἀγαπᾶσθαι. χωρὶς δὲ τούτων αἱ μὲν ἄλλαι πανηγύρεις διὰ πολλοῦ χρόνου συλλεγεῖσαι ταχέως διελύθησαν, ἡ δ’ ἡμετέρα πόλις ἅπαντα τὸν αἰῶνα τοῖς ἀφικνουμένοις πανήγυρίς ἐστιν.", "st": "4.46"}, {"sp": "N", "t": "φιλοσοφίαν τοίνυν, ἣ πάντα ταῦτα συνεξεῦρε καὶ συγκατεσκεύασε, καὶ πρός τε τὰς πράξεις ἡμᾶς ἐπαίδευσε καὶ πρὸς ἀλλήλους ἐπράϋνε, καὶ τῶν συμφορῶν τάς τε δι’ ἀμαθίαν καὶ τὰς ἐξ ἀνάγκης γιγνομένας διεῖλε, καὶ τὰς μὲν φυλάξασθαι τὰς δὲ καλῶς ἐνεγκεῖν ἐδίδαξεν, ἡ πόλις ἡμῶν κατέδειξε,", "st": "4.47"}, {"sp": "N", "t": "καὶ λόγους ἐτίμησεν, ὧν πάντες μὲν ἐπιθυμοῦσι, τοῖς δ’ ἐπισταμένοις φθονοῦσι, συνειδυῖα μὲν ὅτι τοῦτο μόνον ἐξ ἁπάντων τῶν ζῴων ἴδιον ἔφυμεν ἔχοντες, καὶ διότι τούτῳ πλεονεκτήσαντες καὶ τοῖς ἄλλοις ἅπασιν αὐτῶν διηνέγκαμεν, ὁρῶσα δὲ περὶ μὲν τὰς ἄλλας πράξεις οὕτω ταραχώδεις οὔσας τὰς τύχας ὥστε πολλάκις ἐν αὐταῖς καὶ τοὺς φρονίμους ἀτυχεῖν καὶ τοὺς ἀνοήτους κατορθοῦν, τῶν δὲ λόγων τῶν καλῶς καὶ τεχνικῶς ἐχόντων οὐ μετὸν τοῖς φαύλοις, ἀλλὰ ψυχῆς εὖ φρονούσης ἔργον ὄντας,", "st": "4.48"}, {"sp": "N", "t": "καὶ τούς τε σοφοὺς καὶ τοὺς ἀμαθεῖς δοκοῦντας εἶναι ταύτῃ πλεῖστον ἀλλήλων διαφέροντας, ἔτι δὲ τοὺς εὐθὺς ἐξ ἀρχῆς ἐλευθέρως τεθραμμένους ἐκ μὲν ἀνδρίας καὶ πλούτου καὶ τῶν τοιούτων ἀγαθῶν οὐ γιγνωσκομένους, ἐκ δὲ τῶν λεγομένων μάλιστα καταφανεῖς γιγνομένους, καὶ τοῦτο σύμβολον τῆς παιδεύσεως ἡμῶν ἑκάστου πιστότατον ἀποδεδειγμένον, καὶ τοὺς λόγῳ καλῶς χρωμένους οὐ μόνον ἐν ταῖς αὑτῶν δυναμένους, ἀλλὰ καὶ παρὰ τοῖς ἄλλοις ἐντίμους ὄντας.", "st": "4.49"}, {"sp": "N", "t": "τοσοῦτον δ’ ἀπολέλοιπεν ἡ πόλις ἡμῶν περὶ τὸ φρονεῖν καὶ λέγειν τοὺς ἄλλους ἀνθρώπους, ὥσθ’ οἱ ταύτης μαθηταὶ τῶν ἄλλων διδάσκαλοι γεγόνασι, καὶ τὸ τῶν Ἑλλήνων ὄνομα πεποίηκε μηκέτι τοῦ γένους ἀλλὰ τῆς διανοίας δοκεῖν εἶναι, καὶ μᾶλλον Ἕλληνας καλεῖσθαι τοὺς τῆς παιδεύσεως τῆς ἡμετέρας ἢ τοὺς τῆς κοινῆς φύσεως μετέχοντας.", "st": "4.50"}, {"sp": "N", "t": "ἵνα δὲ μὴ δοκῶ περὶ τὰ μέρη διατρίβειν ὑπὲρ ὅλων τῶν πραγμάτων ὑποθέμενος μηδ’ ἐκ τούτων ἐγκωμιάζειν τὴν πόλιν ἀπορῶν τὰ πρὸς τὸν πόλεμον αὐτὴν ἐπαινεῖν, ταῦτα μὲν εἰρήσθω μοι πρὸς τοὺς ἐπὶ τοῖς τοιούτοις φιλοτιμουμένους, ἡγοῦμαι δὲ τοῖς προγόνοις ἡμῶν οὐχ ἧττον ἐκ τῶν κινδύνων τιμᾶσθαι προσήκειν ἢ τῶν ἄλλων εὐεργεσιῶν.", "st": "4.51"}, {"sp": "N", "t": "οὐ γὰρ μικροὺς οὐδ’ ὀλίγους οὐδ’ ἀφανεῖς ἀγῶνας ὑπέμειναν, ἀλλὰ πολλοὺς καὶ δεινοὺς καὶ μεγάλους, τοὺς μὲν ὑπὲρ τῆς αὑτῶν χώρας, τοὺς δ’ ὑπὲρ τῆς τῶν ἄλλων ἐλευθερίας· ἅπαντα γὰρ τὸν χρόνον διετέλεσαν κοινὴν πόλιν παρέχοντες καὶ τοῖς ἀδικουμένοις ἀεὶ τῶν Ἑλλήνων ἐπαμύνουσαν.", "st": "4.52"}, {"sp": "N", "t": "διὸ δὴ καὶ κατηγοροῦσί τινες ἡμῶν ὡς οὐκ ὀρθῶς βουλευομένων, ὅτι τοὺς ἀσθενεστέρους εἰθίσμεθα θεραπεύειν, ὥσπερ οὐ μετὰ τῶν ἐπαινεῖν βουλομένων ἡμᾶς τοὺς λόγους ὄντας τοὺς τοιούτους. οὐ γὰρ ἀγνοοῦντες ὅσον διαφέρουσιν αἱ μείζους τῶν συμμαχιῶν πρὸς τὴν ἀσφάλειαν οὕτως ἐβουλευόμεθα περὶ αὐτῶν, ἀλλὰ πολὺ τῶν ἄλλων ἀκριβέστερον εἰδότες τὰ συμβαίνοντ’ ἐκ τῶν τοιούτων ὅμως ᾑρούμεθα τοῖς ἀσθενεστέροις καὶ παρὰ τὸ συμφέρον βοηθεῖν μᾶλλον ἢ τοῖς κρείττοσι τοῦ λυσιτελοῦντος ἕνεκα συναδικεῖν.", "st": "4.53"}, {"sp": "N", "t": "γνοίη δ’ ἄν τις καὶ τὸν τρόπον καὶ τὴν ῥώμην τὴν τῆς πόλεως ἐκ τῶν ἱκετειῶν, ἃς ἤδη τινὲς ἡμῖν ἐποιήσαντο. τὰς μὲν οὖν ἢ νεωστὶ γεγενημένας ἢ περὶ μικρῶν ἐλθούσας παραλείψω· πολὺ δὲ πρὸ τῶν Τρωϊκῶν (ἐκεῖθεν γὰρ δίκαιον τὰς πίστεις λαμβάνειν τοὺς ὑπὲρ τῶν πατρίων ἀμφισβητοῦντας) ἦλθον οἵ θ’ Ἡρακλέους παῖδες καὶ μικρὸν πρὸ τούτων Ἄδραστος ὁ Ταλαοῦ, βασιλεὺς ὢν Ἄργους,", "st": "4.54"}, {"sp": "N", "t": "οὗτος μὲν ἐκ τῆς στρατείας τῆς ἐπὶ Θήβας δεδυστυχηκώς, καὶ τοὺς ὑπὸ τῇ Καδμείᾳ τελευτήσαντας αὐτὸς μὲν οὐ δυνάμενος ἀνελέσθαι, τὴν δὲ πόλιν ἀξιῶν βοηθεῖν ταῖς κοιναῖς τύχαις καὶ μὴ περιορᾶν τοὺς ἐν τοῖς πολέμοις ἀποθνήσκοντας ἀτάφους γιγνομένους μηδὲ παλαιὸν ἔθος καὶ πάτριον νόμον καταλυόμενον,", "st": "4.55"}, {"sp": "N", "t": "οἱ δ’ Ἡρακλέους παῖδες φεύγοντες τὴν Εὐρυσθέως ἔχθραν, καὶ τὰς μὲν ἄλλας πόλεις ὑπερορῶντες ὡς οὐκ ἂν δυναμένας βοηθῆσαι ταῖς ἑαυτῶν συμφοραῖς, τὴν δ’ ἡμετέραν ἱκανὴν νομίζοντες εἶναι μόνην ἀποδοῦναι χάριν ὑπὲρ ὧν ὁ πατὴρ αὐτῶν ἅπαντας ἀνθρώπους εὐεργέτησεν.", "st": "4.56"}, {"sp": "N", "t": "ἐκ δὴ τούτων ῥᾴδιον κατιδεῖν ὅτι καὶ κατ’ ἐκεῖνον τὸν χρόνον ἡ πόλις ἡμῶν ἡγεμονικῶς εἶχε· τίς γὰρ ἂν ἱκετεύειν τολμήσειεν ἢ τοὺς ἥττους αὑτοῦ ἢ τοὺς ὑφ’ ἑτέροις ὄντας, παραλιπὼν τοὺς μείζω δύναμιν ἔχοντας, ἄλλως τε καὶ περὶ πραγμάτων οὐκ ἰδίων ἀλλὰ κοινῶν καὶ περὶ ὧν οὐδένας ἄλλους εἰκὸς ἦν ἐπιμεληθῆναι πλὴν τοὺς προεστάναι τῶν Ἑλλήνων ἀξιοῦντας;", "st": "4.57"}, {"sp": "N", "t": "ἔπειτ’ οὐδὲ ψευσθέντες φαίνονται τῶν ἐλπίδων, δι’ ἃς κατέφυγον ἐπὶ τοὺς προγόνους ἡμῶν. ἀνελόμενοι γὰρ πόλεμον ὑπὲρ μὲν τῶν τελευτησάντων πρὸς Θηβαίους, ὑπὲρ δὲ τῶν παίδων τῶν Ἡρακλέους πρὸς τὴν Εὐρυσθέως δύναμιν, τοὺς μὲν ἐπιστρατεύσαντες ἠνάγκασαν ἀποδοῦναι θάψαι τοὺς νεκροὺς τοῖς προσήκουσι, Πελοποννησίων δὲ τοὺς μετ’ Εὐρυσθέως εἰς τὴν χώραν ἡμῶν εἰσβαλόντας ἐπεξελθόντες ἐνίκησαν μαχόμενοι κἀκεῖνον τῆς ὕβρεως ἔπαυσαν.", "st": "4.58"}, {"sp": "N", "t": "θαυμαζόμενοι δὲ καὶ διὰ τὰς ἄλλας πράξεις, ἐκ τούτων τῶν ἔργων ἔτι μᾶλλον εὐδοκίμησαν. οὐ γὰρ παρὰ μικρὸν ἐποίησαν, ἀλλὰ τοσοῦτον τὰς τύχας ἑκατέρων μετήλλαξαν, ὥσθ’ ὁ μὲν ἱκετεύειν ἡμᾶς ἀξιώσας βίᾳ τῶν ἐχθρῶν ἅπανθ’ ὅσων ἐδεήθη διαπραξάμενος ἀπῆλθεν, Εὐρυσθεὺς δὲ βιάσασθαι προσδοκήσας αὐτὸς αἰχμάλωτος γενόμενος ἱκέτης ἠναγκάσθη καταστῆναι,", "st": "4.59"}, {"sp": "N", "t": "καὶ τῷ μὲν ὑπερενεγκόντι τὴν ἀνθρωπίνην φύσιν, ὃς ἐκ Διὸς μὲν γεγονὼς ἔτι δὲ θνητὸς ὢν θεοῦ ῥώμην ἔσχε, τούτῳ μὲν ἐπιτάττων καὶ λυμαινόμενος ἅπαντα τὸν χρόνον διετέλεσεν, ἐπειδὴ δ’ εἰς ἡμᾶς ἐξήμαρτεν, εἰς τοσαύτην κατέστη μεταβολήν, ὥστ’ ἐπὶ τοῖς παισὶ τοῖς ἐκείνου γενόμενος ἐπονειδίστως τὸν βίον ἐτελεύτησεν.", "st": "4.60"}, {"sp": "N", "t": "πολλῶν δ’ ὑπαρχουσῶν ἡμῖν εὐεργεσιῶν εἰς τὴν πόλιν τὴν Λακεδαιμονίων, περὶ ταύτης μόνης μοι συμβέβηκεν εἰπεῖν· ἀφορμὴν γὰρ λαβόντες τὴν δι’ ἡμῶν αὐτοῖς γενομένην σωτηρίαν οἱ πρόγονοι μὲν τῶν νῦν ἐν Λακεδαίμονι βασιλευόντων, ἔκγονοι δ’ Ἡρακλέους, κατῆλθον μὲν εἰς Πελοπόννησον, κατέσχον δ’ Ἄργος καὶ Λακεδαίμονα καὶ Μεσσήνην, οἰκισταὶ δὲ Σπάρτης ἐγένοντο, καὶ τῶν παρόντων ἀγαθῶν αὐτοῖς ἁπάντων ἀρχηγοὶ κατέστησαν.", "st": "4.61"}, {"sp": "N", "t": "ὧν ἐχρῆν ἐκείνους μεμνημένους μηδέποτ’ εἰς τὴν χώραν ταύτην εἰσβαλεῖν, ἐξ ἧς ὁρμηθέντες τοσαύτην εὐδαιμονίαν κατεκτήσαντο, μηδ’ εἰς κινδύνους καθιστάναι τὴν πόλιν τὴν ὑπὲρ τῶν παίδων τῶν Ἡρακλέους προκινδυνεύσασαν, μηδὲ τοῖς μὲν ἀπ’ ἐκείνου γεγονόσι διδόναι τὴν βασιλείαν, τὴν δὲ τῷ γένει τῆς σωτηρίας αἰτίαν οὖσαν δουλεύειν αὑτοῖς ἀξιοῦν.", "st": "4.62"}, {"sp": "N", "t": "εἰ δὲ δεῖ τὰς χάριτας καὶ τὰς ἐπιεικείας ἀνελόντας ἐπὶ τὴν ὑπόθεσιν πάλιν ἐπανελθεῖν καὶ τὸν ἀκριβέστατον τῶν λόγων εἰπεῖν, οὐ δή που πάτριόν ἐστιν ἡγεῖσθαι τοὺς ἐπήλυδας τῶν αὐτοχθόνων, οὐδὲ τοὺς εὖ παθόντας τῶν εὖ ποιησάντων, οὐδὲ τοὺς ἱκέτας γενομένους τῶν ὑποδεξαμένων.", "st": "4.63"}, {"sp": "N", "t": "ἔτι δὲ συντομώτερον ἔχω δηλῶσαι περὶ αὐτῶν. τῶν μὲν γὰρ Ἑλληνίδων πόλεων, χωρὶς τῆς ἡμετέρας, Ἄργος καὶ Θῆβαι καὶ Λακεδαίμων καὶ τότ’ ἦσαν μέγισται καὶ νῦν ἔτι διατελοῦσι. φαίνονται δ’ ἡμῶν οἱ πρόγονοι τοσοῦτον ἁπάντων διενεγκόντες, ὥσθ’ ὑπὲρ μὲν Ἀργείων δυστυχησάντων Θηβαίοις, ὅτε μέγιστον ἐφρόνησαν, ἐπιτάττοντες,", "st": "4.64"}, {"sp": "N", "t": "ὑπὲρ δὲ τῶν παίδων τῶν Ἡρακλέους Ἀργείους καὶ τοὺς ἄλλους Πελοποννησίους μάχῃ κρατήσαντες, ἐκ δὲ τῶν πρὸς Εὐρυσθέα κινδύνων τοὺς οἰκιστὰς καὶ τοὺς ἡγεμόνας τοὺς Λακεδαιμονίων διασώσαντες. ὥστε περὶ μὲν τῆς ἐν τοῖς Ἕλλησι δυναστείας οὐκ οἶδ’ ὅπως ἄν τις σαφέστερον ἐπιδεῖξαι δυνηθείη.", "st": "4.65"}, {"sp": "N", "t": "δοκεῖ δέ μοι καὶ περὶ τῶν πρὸς τοὺς βαρβάρους τῇ πόλει πεπραγμένων προσήκειν εἰπεῖν, ἄλλως τ’ ἐπειδὴ καὶ τὸν λόγον κατεστησάμην περὶ τῆς ἡγεμονίας τῆς ἐπ’ ἐκείνους. ἅπαντας μὲν οὖν ἐξαριθμῶν τοὺς κινδύνους λίαν ἄν μακρολογοίην· ἐπὶ δὲ τῶν μεγίστων τὸν αὐτὸν τρόπον ὅν περ ὀλίγῳ πρότερον πειράσομαι καὶ περὶ τούτων διελθεῖν.", "st": "4.66"}, {"sp": "N", "t": "ἔστι γὰρ ἀρχικώτατα μὲν τῶν γενῶν καὶ μεγίστας δυναστείας ἔχοντα Σκύθαι καὶ Θρᾷκες καὶ Πέρσαι, τυγχάνουσι δ’ οὗτοι μὲν ἅπαντες ἡμῖν ἐπιβουλεύσαντες, ἡ δὲ πόλις πρὸς ἅπαντας τούτους διακινδυνεύσασα. καίτοι τί λοιπὸν ἔσται τοῖς ἀντιλέγουσιν, ἢν ἐπιδειχθῶσι τῶν μὲν Ἑλλήνων οἱ μὴ δυνάμενοι τυγχάνειν τῶν δικαίων ἡμᾶς ἱκετεύειν ἀξιοῦντες, τῶν δὲ βαρβάρων οἱ βουλόμενοι καταδουλώσασθαι τοὺς Ἕλληνας ἐφ’ ἡμᾶς πρώτους ἰόντες;", "st": "4.67"}, {"sp": "N", "t": "ἐπιφανέστατος μὲν οὖν τῶν πολέμων ὁ Περσικὸς γέγονεν, οὐ μὴν ἐλάττω τεκμήρια τὰ παλαιὰ τῶν ἔργων ἐστὶ τοῖς περὶ τῶν πατρίων ἀμφισβητοῦσιν. ἔτι γὰρ ταπεινῆς οὔσης τῆς Ἑλλάδος ἦλθον εἰς τὴν χώραν ἡμῶν Θρᾷκες μὲν μετ’ Εὐμόλπου τοῦ Ποσειδῶνος, Σκύθαι δὲ μετ’ Ἀμαζόνων τῶν Ἄρεως θυγατέρων, οὐ κατὰ τὸν αὐτὸν χρόνον, ἀλλὰ καθ’ ὃν ἑκάτεροι τῆς Εὐρώπης ἐπῆρχον, μισοῦντες μὲν ἅπαν τὸ τῶν Ἑλλήνων γένος, ἰδίᾳ δὲ πρὸς ἡμᾶς ἐγκλήματα ποιησάμενοι, νομίζοντες ἐκ τούτου τοῦ τρόπου πρὸς μίαν μὲν πόλιν κινδυνεύσειν,", "st": "4.68"}, {"sp": "N", "t": "ἁπασῶν δ’ ἅμα κρατήσειν. οὐ μὴν κατώρθωσαν, ἀλλὰ πρὸς μόνους τοὺς προγόνους τοὺς ἡμετέρους συμβαλόντες ὁμοίως διεφθάρησαν ὥσπερ ἂν εἰ πρὸς ἅπαντας ἀνθρώπους ἐπολέμησαν. δῆλον δὲ τὸ μέγεθος τῶν κακῶν τῶν γενομένων ἐκείνοις· οὐ γὰρ ἄν ποθ’ οἱ λόγοι περὶ αὐτῶν τοσοῦτον χρόνον διέμειναν, εἰ μὴ καὶ τὰ πραχθέντα πολὺ τῶν ἄλλων διήνεγκεν.", "st": "4.69"}, {"sp": "N", "t": "λέγεται δ’ οὖν περὶ μὲν Ἀμαζόνων ὡς τῶν μὲν ἐλθουσῶν οὐδεμία πάλιν ἀπῆλθεν, αἱ δ’ ὑπολειφθεῖσαι διὰ τὴν ἐνθάδε συμφορὰν ἐκ τῆς ἀρχῆς ἐξεβλήθησαν, περὶ δὲ Θρᾳκῶν ὅτι τὸν ἄλλον χρόνον ὅμοροι προσοικοῦντες ἡμῖν διὰ τὴν τότε γενομένην στρατείαν τοσοῦτον διέλιπον, ὥστ’ ἐν τῷ μεταξὺ τῆς χώρας ἔθνη πολλὰ καὶ γένη παντοδαπὰ καὶ πόλεις μεγάλας κατοικισθῆναι.", "st": "4.70"}, {"sp": "N", "t": "καλὰ μὲν οὖν καὶ ταῦτα, καὶ πρέποντα τοῖς περὶ τῆς ἡγεμονίας ἀμφισβητοῦσιν· ἀδελφὰ δὲ τῶν εἰρημένων, καὶ τοιαῦθ’ οἷά περ εἰκὸς τοὺς ἐκ τοιούτων γεγονότας, οἱ πρὸς Δαρεῖον καὶ Ξέρξην πολεμήσαντες ἔπραξαν. μεγίστου γὰρ πολέμου συστάντος ἐκείνου, καὶ πλείστων κινδύνων εἰς τὸν αὐτὸν χρόνον συμπεσόντων, καὶ τῶν μὲν πολεμίων ἀνυποστάτων οἰομένων εἶναι διὰ τὸ πλῆθος, τῶν δὲ συμμάχων ἀνυπέρβλητον ἡγουμένων ἔχειν τὴν ἀρετήν,", "st": "4.71"}, {"sp": "N", "t": "ἀμφοτέρων κρατήσαντες ὡς ἑκατέρων προσῆκεν, καὶ πρὸς ἅπαντας τοὺς κινδύνους διενεγκόντες, εὐθὺς μὲν τῶν ἀριστείων ἠξιώθησαν, οὐ πολλῶ δ’ ὕστερον τὴν ἀρχὴν τῆς θαλάττης ἔλαβον, δόντων μὲν τῶν ἄλλων Ἑλλήνων, οὐκ ἀμφισβητούντων δὲ τῶν νῦν ἡμᾶς ἀφαιρεῖσθαι ζητούντων.", "st": "4.72"}, {"sp": "N", "t": "καὶ μηδεὶς οἰέσθω μ’ ἀγνοεῖν ὅτι καὶ Λακεδαιμόνιοι περὶ τοὺς καιροὺς τούτους πολλῶν ἀγαθῶν αἴτιοι τοῖς Ἕλλησι κατέστησαν· ἀλλὰ διὰ τοῦτο καὶ μᾶλλον ἐπαινεῖν ἔχω τὴν πόλιν, ὅτι τοιούτων ἀνταγωνιστῶν τυχοῦσα τοσοῦτον αὐτῶν διήνεγκεν. βούλομαι δ’ ὀλίγῳ μακρότερα περὶ τοῖν πολέοιν εἰπεῖν καὶ μὴ ταχὺ λίαν παραδραμεῖν, ἵν’ ἀμφοτέρων ἡμῖν ὑπομνήματα γένηται, τῆς τε τῶν προγόνων ἀρετῆς καὶ τῆς πρὸς τοὺς βαρβάρους ἔχθρας.", "st": "4.73"}, {"sp": "N", "t": "καίτοι μ’ οὐ λέληθεν ὅτι χαλεπόν ἐστιν ὕστατον ἐπελθόντα λέγειν περὶ πραγμάτων πάλαι προκατειλημμένων, καὶ περὶ ὧν οἱ μάλιστα δυνηθέντες τῶν πολιτῶν εἰπεῖν ἐπὶ τοῖς δημοσίᾳ θαπτομένοις πολλάκις εἰρήκασιν· ἀνάγκη γὰρ τὰ μὲν μέγιστ’ αὐτῶν ἤδη κατακεχρῆσθαι, μικρὰ δ’ ἔτι παραλελεῖφθαι. ὅμως δ’ ἐκ τῶν ὑπολοίπων, ἐπειδὴ συμφέρει τοῖς πράγμασιν, οὐκ ὀκνητέον μνησθῆναι περὶ αὐτῶν.", "st": "4.74"}, {"sp": "N", "t": "πλείστων μὲν οὖν ἀγαθῶν αἰτίους καὶ μεγίστων ἐπαίνων ἀξίους ἡγοῦμαι γεγενῆσθαι τοὺς τοῖς σώμασιν ὑπὲρ τῆς Ἑλλάδος προκινδυνεύσαντας· οὐ μὴν οὐδὲ τῶν πρὸ τοῦ πολέμου τούτου γενομένων καὶ δυναστευσάντων ἐν ἑκατέρᾳ τοῖν πολέοιν δίκαιον ἀμνημονεῖν· ἐκεῖνοι γὰρ ἦσαν οἱ προασκήσαντες τοὺς ἐπιγιγνομένους καὶ τὰ πλήθη προτρέψαντες ἐπ’ ἀρετὴν καὶ χαλεποὺς ἀνταγωνιστὰς τοῖς βαρβάροις ποιήσαντες.", "st": "4.75"}, {"sp": "N", "t": "οὐ γὰρ ὠλιγώρουν τῶν κοινῶν, οὐδ’ ἀπέλαυον μὲν ὡς ἰδίων, ἠμέλουν δ’ ὡς ἀλλοτρίων, ἀλλ’ ἐκήδοντο μὲν ὡς οἰκείων, ἀπείχοντο δ’ ὥσπερ χρὴ τῶν μηδὲν προσηκόντων· οὐδὲ πρὸς ἀργύριον τὴν εὐδαιμονίαν ἔκρινον, ἀλλ’ οὗτος ἐδόκει πλοῦτον ἀσφαλέστατον κεκτῆσθαι καὶ κάλλιστον, ὅστις τοιαῦτα τυγχάνοι πράττων ἐξ ὧν αὐτός τε μέλλοι μάλιστ’ εὐδοκιμήσειν καὶ τοῖς παισὶ μεγίστην δόξαν καταλείψειν.", "st": "4.76"}, {"sp": "N", "t": "οὐδὲ τὰς θρασύτητας τὰς ἀλλήλων ἐζήλουν, οὐδὲ τὰς τόλμας τὰς αὑτῶν ἤσκουν, ἀλλὰ δεινότερον μὲν ἐνόμιζον εἶναι κακῶς ὑπὸ τῶν πολιτῶν ἀκούειν ἢ καλῶς ὑπὲρ τῆς πόλεως ἀποθνήσκειν, μᾶλλον δ’ ᾐσχύνοντ’ ἐπὶ τοῖς κοινοῖς ἁμαρτήμασιν ἢ νῦν ἐπὶ τοῖς ἰδίοις τοῖς σφετέροις αὐτῶν.", "st": "4.77"}, {"sp": "N", "t": "τούτων δ’ ἦν αἴτιον ὅτι τοὺς νόμους ἐσκόπουν ὅπως ἀκριβῶς καὶ καλῶς ἕξουσιν, οὐχ οὕτω τοὺς περὶ τῶν ἰδίων συμβολαίων ὡς τοὺς περὶ τῶν καθ’ ἑκάστην τὴν ἡμέραν ἐπιτηδευμάτων· ἠπίσταντο γὰρ ὅτι τοῖς καλοῖς κἀγαθοῖς τῶν ἀνθρώπων οὐδὲν δεήσει πολλῶν γραμμάτων, ἀλλ’ ἀπ’ ὀλίγων συνθημάτων ῥᾳδίως καὶ περὶ τῶν ἰδίων καὶ περὶ τῶν κοινῶν ὁμονοήσουσιν.", "st": "4.78"}, {"sp": "N", "t": "οὕτω δὲ πολιτικῶς εἶχον, ὥστε καὶ τὰς στάσεις ἐποιοῦντο πρὸς ἀλλήλους οὐχ ὁπότεροι τοὺς ἑτέρους ἀπολέσαντες τῶν λοιπῶν ἄρξουσιν, ἀλλ’ ὁπότεροι φθήσονται τὴν πόλιν ἀγαθόν τι ποιήσαντες· καὶ τὰς ἑταιρείας συνῆγον οὐχ ὑπὲρ τῶν συμφερόντων, ἀλλ’ ἐπὶ τῇ τοῦ πλήθους ὠφελείᾳ.", "st": "4.79"}, {"sp": "N", "t": "τὸν αὐτὸν δὲ τρόπον καὶ τὰ τῶν ἄλλων διῴκουν, θεραπεύοντες ἀλλ’ οὐχ ὑβρίζοντες τοὺς Ἕλληνας, καὶ στρατηγεῖν οἰόμενοι δεῖν ἀλλὰ μὴ τυραννεῖν αὐτῶν, καὶ μᾶλλον ἐπιθυμοῦντες ἡγεμόνες ἢ δεσπόται προσαγορεύεσθαι καὶ σωτῆρες ἀλλὰ μὴ λυμεῶνες ἀποκαλεῖσθαι, τῷ ποιεῖν εὖ προσαγόμενοι τὰς πόλεις, ἀλλ’ οὐ βίᾳ καταστρεφόμενοι,", "st": "4.80"}, {"sp": "N", "t": "πιστοτέροις μὲν τοῖς λόγοις ἢ νῦν τοῖς ὅρκοις χρώμενοι, ταῖς δὲ συνθήκαις ὥσπερ ἀνάγκαις ἐμμένειν ἀξιοῦντες, οὐχ οὕτως ἐπὶ ταῖς δυναστείαις μέγα φρονοῦντες, ὡς ἐπὶ τῷ σωφρόνως ζῆν φιλοτιμούμενοι, τὴν αὐτὴν ἀξιοῦντες γνώμην ἔχειν πρὸς τοὺς ἥττους ἥνπερ τοὺς κρείττους πρὸς σφᾶς αὐτούς, ἴδια μὲν ἄστη τὰς αὑτῶν πόλεις ἡγούμενοι, κοινὴν δὲ πατρίδα τὴν Ἑλλάδα νομίζοντες εἶναι.", "st": "4.81"}, {"sp": "N", "t": "τοιαύταις διανοίαις χρώμενοι, καὶ τοὺς νεωτέρους ἐν τοῖς τοιούτοις ἤθεσι παιδεύοντες, οὕτως ἄνδρας ἀγαθοὺς ἀπέδειξαν τοὺς πολεμήσαντας πρὸς τοὺς ἐκ τῆς Ἀσίας, ὥστε μηδένα πώποτε δυνηθῆναι περὶ αὐτῶν μήτε τῶν ποιητῶν μήτε τῶν σοφιστῶν ἀξίως τῶν ἐκείνοις πεπραγμένων εἰπεῖν. καὶ πολλὴν αὐτοῖς ἔχω συγγνώμην· ὁμοίως γάρ ἐστι χαλεπὸν ἐπαινεῖν τοὺς ὑπερβεβληκότας τὰς τῶν ἄλλων ἀρετὰς ὥσπερ τοὺς μηδὲν ἀγαθὸν πεποιηκότας· τοῖς μὲν γὰρ οὐχ ὕπεισι πράξεις, πρὸς δὲ τοὺς οὐκ εἰσὶν ἁρμόττοντες λόγοι.", "st": "4.82"}, {"sp": "N", "t": "πῶς γὰρ ἂν γένοιντο σύμμετροι τοιούτοις ἀνδράσιν, οἳ τοσοῦτον μὲν τῶν ἐπὶ Τροίαν στρατευσαμένων διήνεγκαν, ὅσον οἱ μὲν περὶ μίαν πόλιν ἔτη δέκα διέριψαν, οἱ δὲ τὴν ἐξ ἁπάσης τῆς Ἀσίας δύναμιν ἐν ὀλίγῳ χρόνω κατεπολέμησαν, οὐ μόνον δὲ τὰς αὑτῶν πατρίδας διέσωσαν, ἀλλὰ καὶ τὴν σύμπασαν Ἑλλάδα ἠλευθέρωσαν; ποίων δ’ ἂν ἔργων ἢ πόνων ἢ κινδύνων ἀπέστησαν ὥστε ζῶντες εὐδοκιμεῖν, οἵ τινες ὑπὲρ τῆς δόξης ἧς ἔμελλον τελευτήσαντες ἕξειν οὕτως ἑτοίμως ἤθελον ἀποθνήσκειν;", "st": "4.83"}, {"sp": "N", "t": "οἶμαι δὲ καὶ τὸν πόλεμον θεῶν τινα συναγαγεῖν ἀγασθέντα τὴν ἀρετὴν αὐτῶν, ἵνα μὴ τοιοῦτοι γενόμενοι τὴν φύσιν διαλάθοιεν μηδ’ ἀκλεῶς τὸν βίον τελευτήσαιεν, ἀλλὰ τῶν αὐτῶν τοῖς ἐκ τῶν θεῶν γεγονόσι καὶ καλουμένοις ἡμιθέοις ἀξιωθεῖεν· καὶ γὰρ ἐκείνων τὰ μὲν σώματα ταῖς τῆς φύσεως ἀνάγκαις ἀπέδοσαν, τῆς δ’ ἀρετῆς ἀθάνατον τὴν μνήμην ἐποίησαν.", "st": "4.84"}, {"sp": "N", "t": "ἀεὶ μὲν οὖν οἵ θ’ ἡμέτεροι πρόγονοι καὶ Λακεδαιμόνιοι φιλοτίμως πρὸς ἀλλήλους εἶχον, οὐ μὴν ἀλλὰ περὶ καλλίστων ἐν ἐκείνοις τοῖς χρόνοις ἐφιλονίκησαν, οὐκ ἐχθροὺς ἀλλ’ ἀνταγωνιστὰς σφᾶς αὐτοὺς εἶναι νομίζοντες, οὐδ’ ἐπὶ δουλείᾳ τῇ τῶν Ἑλλήνων τὸν βάρβαρον θεραπεύοντες, ἀλλὰ περὶ μὲν τῆς κοινῆς σωτηρίας ὁμονοοῦντες, ὁπότεροι δὲ ταύτης αἴτιοι γενήσονται, περὶ τούτου ποιούμενοι τὴν ἅμιλλαν. ἐπεδείξαντο δὲ τὰς αὑτῶν ἀρετὰς πρῶτον μὲν ἐν τοῖς ὑπὸ Δαρείου πεμφθεῖσιν.", "st": "4.85"}, {"sp": "N", "t": "ἀποβάντων γὰρ αὐτῶν εἰς τὴν Ἀττικὴν οἱ μὲν οὐ περιέμειναν τοὺς συμμάχους, ἀλλὰ τὸν κοινὸν πόλεμον ἴδιον ποιησάμενοι πρὸς τοὺς ἁπάσης τῆς Ἑλλάδος καταφρονήσαντας ἀπήντων τὴν οἰκείαν δύναμιν ἔχοντες, ὀλίγοι πρὸς πολλὰς μυριάδας, ὥσπερ ἐν ἀλλοτρίαις ψυχαῖς μέλλοντες κινδυνεύειν, οἱ δ’ οὐκ ἔφθησαν πυθόμενοι τὸν περὶ τὴν Ἀττικὴν πόλεμον, καὶ πάντων τῶν ἄλλων ἀμελήσαντες ἧκον ἡμῖν ἀμυνοῦντες, τοσαύτην ποιησάμενοι σπουδὴν ὅσην περ ἂν τῆς αὑτῶν χώρας πορθουμένης.", "st": "4.86"}, {"sp": "N", "t": "σημεῖον δὲ τοῦ τάχους καὶ τῆς ἁμίλλης· τοὺς μὲν γὰρ ἡμετέρους προγόνους φασὶ τῆς αὐτῆς ἡμέρας πυθέσθαι τε τὴν ἀπόβασιν τὴν τῶν βαρβάρων καὶ βοηθήσαντας ἐπὶ τοὺς ὅρους τῆς χώρας μάχῃ νικήσαντας τρόπαιον στῆσαι τῶν πολεμίων, τοὺς δ’ ἐν τρισὶν ἡμέραις καὶ τοσαύταις νυξὶ διακόσια καὶ χίλια στάδια διελθεῖν στρατοπέδῳ πορευομένους. οὕτω σφόδρ’ ἠπείχθησαν οἱ μὲν μετασχεῖν τῶν κινδύνων, οἱ δὲ φθῆναι συμβαλόντες πρὶν ἐλθεῖν τοὺς βοηθήσοντας.", "st": "4.87"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα γενομένης τῆς ὕστερον στρατείας, ἣν αὐτὸς Ξέρξης ἤγαγεν, ἐκλιπὼν μὲν τὰ βασίλεια, στρατηγὸς δὲ καταστῆναι τολμήσας, ἅπαντας δὲ τοὺς ἐκ τῆς Ἀσίας συναγείρας· περὶ οὗ τίς οὐχ ὑπερβολὰς προθυμηθεὶς εἰπεῖν ἐλάττω τῶν ὑπαρχόντων εἴρηκεν;", "st": "4.88"}, {"sp": "N", "t": "ὃς εἰς τοσοῦτον ἦλθεν ὑπερηφανίας, ὥστε μικρὸν μὲν ἡγησάμενος ἔργον εἶναι τὴν Ἑλλάδα χειρώσασθαι, βουληθεὶς δὲ τοιοῦτον μνημεῖον καταλιπεῖν ὃ μὴ τῆς ἀνθρωπίνης φύσεώς ἐστιν, οὐ πρότερον ἐπαύσατο πρὶν ἐξεῦρε καὶ συνηνάγκασεν ὃ πάντες θρυλοῦσιν, ὥστε τῷ στρατοπέδῳ πλεῦσαι μὲν διὰ τῆς ἠπείρου, πεζεῦσαι δὲ διὰ τῆς θαλάττης, τὸν μὲν Ἑλλήσποντον ζεύξας, τὸν δ’ Ἄθω διορύξας.", "st": "4.89"}, {"sp": "N", "t": "πρὸς δὴ τὸν οὕτω μέγα φρονήσαντα καὶ τηλικαῦτα διαπραξάμενον καὶ τοσούτων δεσπότην γενόμενον ἀπήντων διελόμενοι τὸν κίνδυνον, Λακεδαιμόνιοι μὲν εἰς Θερμοπύλας πρὸς τὸ πεζόν, χιλίους αὑτῶν ἐπιλέξαντες καὶ τῶν συμμάχων ὀλίγους παραλαβόντες, ὡς ἐν τοῖς στενοῖς κωλύσοντες αὐτοὺς περαιτέρω προελθεῖν, οἱ δ’ ἡμέτεροι πατέρες ἐπ’ Ἀρτεμίσιον, ἑξήκοντα τριήρεις πληρώσαντες πρὸς ἅπαν τὸ τῶν πολεμίων ναυτικόν.", "st": "4.90"}, {"sp": "N", "t": "ταῦτα δὲ ποιεῖν ἐτόλμων οὐχ οὕτω τῶν πολεμίων καταφρονοῦντες ὡς πρὸς ἀλλήλους ἀγωνιῶντες, Λακεδαιμόνιοι μὲν ζηλοῦντες τὴν πόλιν τῆς Μαραθῶνι μάχης, καὶ ζητοῦντες αὑτοὺς ἐξισῶσαι, καὶ δεδιότες μὴ δὶς ἐφεξῆς ἡ πόλις ἡμῶν αἰτία γένηται τοῖς Ἕλλησι τῆς σωτηρίας, οἱ δ’ ἡμέτεροι μάλιστα μὲν βουλόμενοι διαφυλάξαι τὴν παροῦσαν δόξαν, καὶ πᾶσι ποιῆσαι φανερὸν ὅτι καὶ τὸ πρότερον δι’ ἀρετὴν ἀλλ’ οὐ διὰ τύχην ἐνίκησαν, ἔπειτα καὶ προαγαγέσθαι τοὺς Ἕλληνας ἐπὶ τὸ διαναυμαχεῖν, ἐπιδείξαντες αὐτοῖς ὁμοίως ἐν τοῖς ναυτικοῖς κινδύνοις ὥσπερ ἐν τοῖς πεζοῖς τὴν ἀρετὴν τοῦ πλήθους περιγιγνομένην.", "st": "4.91"}, {"sp": "N", "t": "ἴσας δὲ τὰς τόλμας παρασχόντες οὐχ ὁμοίαις ἐχρήσαντο ταῖς τύχαις, ἀλλ’ οἱ μὲν διεφθάρησαν καὶ ταῖς ψυχαῖς νικῶντες τοῖς σώμασιν ἀπεῖπον (οὐ γὰρ δὴ τοῦτό γε θέμις εἰπεῖν, ὡς ἡττήθησαν· οὐδεὶς γὰρ αὐτῶν φυγεῖν ἠξίωσεν), οἱ δ’ ἡμέτεροι τὰς μὲν πρόπλους ἐνίκησαν, ἐπειδὴ δ’ ἤκουσαν τῆς παρόδου τοὺς πολεμίους κρατοῦντας, οἴκαδε καταπλεύσαντες οὕτως ἐβουλεύσαντο περὶ τῶν λοιπῶν, ὥστε πολλῶν καὶ καλῶν αὐτοῖς προειργασμένων ἐν τοῖς τελευταίοις τῶν κινδύνων ἔτι πλέον διήνεγκαν.", "st": "4.92"}, {"sp": "N", "t": "ἀθύμως γὰρ ἁπάντων τῶν συμμάχων διακειμένων, καὶ Πελοποννησίων μὲν διατειχιζόντων τὸν Ἰσθμὸν καὶ ζητούντων ἰδίαν αὑτοῖς σωτηρίαν, τῶν δ’ ἄλλων πόλεων ὑπὸ τοῖς βαρβάροις γεγενημένων καὶ συστρατευομένων ἐκείνοις, πλὴν εἴ τις διὰ μικρότητα παρημελήθη, προσπλεουσῶν δὲ τριήρων διακοσίων καὶ χιλίων καὶ πεζῆς στρατιᾶς ἀναριθμήτου μελλούσης εἰς τὴν Ἀττικὴν εἰσβάλλειν, οὐδεμιᾶς σωτηρίας αὐτοῖς ὑποφαινομένης, ἀλλ’ ἔρημοι συμμάχων γεγενημένοι καὶ τῶν ἐλπίδων ἁπασῶν διημαρτηκότες,", "st": "4.93"}, {"sp": "N", "t": "ἐξὸν αὐτοῖς μὴ μόνον τοὺς παρόντας κινδύνους διαφυγεῖν ἀλλὰ καὶ τιμὰς ἐξαιρέτους λαβεῖν, ἃς αὐτοῖς ἐδίδου βασιλεὺς ἡγούμενος, εἰ τὸ τῆς πόλεως προσλάβοι ναυτικόν, παραχρῆμα καὶ Πελοποννήσου κρατήσειν, οὐχ ὑπέμειναν τὰς παρ’ ἐκείνου δωρεάς, οὐδ’ ὀργισθέντες τοῖς Ἕλλησιν ὅτι προὐδόθησαν ἀσμένως ἐπὶ τὰς διαλλαγὰς τὰς πρὸς τοὺς βαρβάρους ὥρμησαν,", "st": "4.94"}, {"sp": "N", "t": "ἀλλ’ αὐτοὶ μὲν ὑπὲρ τῆς ἐλευθερίας πολεμεῖν παρεσκευάζοντο, τοῖς δ’ ἄλλοις τὴν δουλείαν αἱρουμένοις συγγνώμην εἶχον. ἡγοῦντο γὰρ ταῖς μὲν ταπειναῖς τῶν πόλεων προσήκειν ἐκ παντὸς τρόπου ζητεῖν τὴν σωτηρίαν, ταῖς δὲ προεστάναι τῆς Ἑλλάδος ἀξιούσαις οὐχ οἷόν τ’ εἶναι διαφεύγειν τοὺς κινδύνους, ἀλλ’ ὥσπερ τῶν ἀνδρῶν τοῖς καλοῖς κἀγαθοῖς αἱρετώτερόν ἐστι καλῶς ἀποθανεῖν ἢ ζῆν αἰσχρῶς, οὕτω καὶ τῶν πόλεων ταῖς ὑπερεχούσαις λυσιτελεῖν ἐξ ἀνθρώπων ἀφανισθῆναι μᾶλλον ἢ δούλαις ὀφθῆναι γενομέναις.", "st": "4.95"}, {"sp": "N", "t": "δῆλον δ’ ὅτι ταῦτα διενοήθησαν· ἐπειδὴ γὰρ οὐχ οἷοί τ’ ἦσαν πρὸς ἀμφοτέρας ἅμα παρατάξασθαι τὰς δυνάμεις, παραλαβόντες ἅπαντα τὸν ὄχλον τὸν ἐκ τῆς πόλεως εἰς τὴν ἐχομένην νῆσον ἐξέπλευσαν, ἵν’ ἐν μέρει πρὸς ἑκατέραν κινδυνεύσωσιν. καίτοι πῶς ἂν ἐκείνων ἄνδρες ἀμείνους ἢ μᾶλλον φιλέλληνες ὄντες ἐπιδειχθεῖεν, οἵτινες ἔτλησαν ἐπιδεῖν, ὥστε μὴ τοῖς λοιποῖς αἴτιοι γενέσθαι τῆς δουλείας, ἐρήμην μὲν τὴν πόλιν γενομένην, τὴν δὲ χώραν πορθουμένην, ἱερὰ δὲ συλώμενα καὶ νεὼς ἐμπιπραμένους, ἅπαντα δὲ τὸν πόλεμον περὶ τὴν πατρίδα τὴν αὑτῶν γιγνόμενον;", "st": "4.96"}, {"sp": "N", "t": "καὶ οὐδὲ ταῦτ’ ἀπέχρησεν αὐτοῖς, ἀλλὰ πρὸς χιλίας καὶ διακοσίας τριήρεις μόνοι διαναυμαχεῖν ἐμέλλησαν. οὐ μὴν εἰάθησαν· καταισχυνθέντες γὰρ Πελοποννήσιοι τὴν ἀρετὴν αὐτῶν, καὶ νομίσαντες προδιαφθαρέντων μὲν τῶν ἡμετέρων οὐδ’ αὐτοὶ σωθήσεσθαι, κατορθωσάντων δ’ εἰς ἀτιμίαν τὰς αὑτῶν πόλεις καταστήσειν, ἠναγκάσθησαν μετασχεῖν τῶν κινδύνων. καὶ τοὺς μὲν θορύβους τοὺς ἐν τῷ πράγματι γενομένους καὶ τὰς κραυγὰς καὶ τὰς παρακελεύσεις, ἃ κοινὰ πάντων ἐστὶ τῶν ναυμαχούντων, οὐκ οἶδ’ ὅ τι δεῖ λέγοντα διατρίβειν·", "st": "4.97"}, {"sp": "N", "t": "ἃ δ’ ἐστὶν ἴδια καὶ τῆς ἡγεμονίας ἄξια καὶ τοῖς προειρημένοις ὁμολογούμενα, ταῦτα δ’ ἐμὸν ἔργον ἐστὶν εἰπεῖν. τοσοῦτον γὰρ ἡ πόλις ἡμῶν διέφερεν, ὅτ’ ἦν ἀκέραιος, ὥστ’ ἀνάστατος γενομένη πλείους μὲν συνεβάλετο τριήρεις εἰς τὸν κίνδυνον τὸν ὑπὲρ τῆς Ἑλλάδος ἢ σύμπαντες οἱ ναυμαχήσαντες, οὐδεὶς δὲ πρὸς ἡμᾶς οὕτως ἔχει δυσμενῶς, ὅς τις οὐκ ἂν ὁμολογήσειε διὰ μὲν τὴν ναυμαχίαν ἡμᾶς τῷ πολέμῳ κρατῆσαι, ταύτης δὲ τὴν πόλιν αἰτίαν γενέσθαι.", "st": "4.98"}, {"sp": "N", "t": "καίτοι μελλούσης στρατείας ἐπὶ τοὺς βαρβάρους ἔσεσθαι τίνας χρὴ τὴν ἡγεμονίαν ἔχειν; οὐ τοὺς ἐν τῷ προτέρῳ πολέμῳ μάλιστ’ εὐδοκιμήσαντας, καὶ πολλάκις μὲν ἰδίᾳ προκινδυνεύσαντας, ἐν δὲ τοῖς κοινοῖς τῶν ἀγώνων ἀριστείων ἀξιωθέντας, οὐ τοὺς τὴν αὑτῶν ἐκλιπόντας ὑπὲρ τῆς τῶν ἄλλων σωτηρίας, καὶ τό τε παλαιὸν οἰκιστὰς τῶν πλείστων πόλεων γενομένους, καὶ πάλιν αὐτὰς ἐκ τῶν μεγίστων συμφορῶν διασώσαντας; πῶς δ’ οὐκ ἂν δεινὰ πάθοιμεν, εἰ τῶν κακῶν πλεῖστον μέρος μετασχόντες ἐν ταῖς τιμαῖς ἔλαττον ἔχειν ἀξιωθεῖμεν, καὶ τότε προταχθέντες ὑπὲρ ἁπάντων νῦν ἑτέροις ἀκολουθεῖν ἀναγκασθεῖμεν;", "st": "4.99"}, {"sp": "N", "t": "μέχρι μὲν οὖν τούτων οἶδ’ ὅτι πάντες ἂν ὁμολογήσειαν πλείστων ἀγαθῶν τὴν πόλιν τὴν ἡμετέραν αἰτίαν γεγενῆσθαι, καὶ δικαίως ἂν αὐτῆς τὴν ἡγεμονίαν εἶναι· μετὰ δὲ ταῦτ’ ἤδη τινὲς ἡμῶν κατηγοροῦσιν, ὡς ἐπειδὴ τὴν ἀρχὴν τῆς θαλάττης παρελάβομεν, πολλῶν κακῶν αἴτιοι τοῖς Ἕλλησι κατέστημεν, καὶ τόν τε Μηλίων ἀνδραποδισμὸν καὶ τὸν Σκιωναίων ὄλεθρον ἐν τούτοις τοῖς λόγοις ἡμῖν προφέρουσιν.", "st": "4.100"}, {"sp": "N", "t": "ἐγὼ δ’ ἡγοῦμαι πρῶτον μὲν οὐδὲν εἶναι τοῦτο σημεῖον ὡς κακῶς ἤρχομεν, εἴ τινες τῶν πολεμησάντων ἡμῖν σφόδρα φαίνονται κολασθέντες, ἀλλὰ πολὺ τόδε μεῖζον τεκμήριον ὡς καλῶς διῳκοῦμεν τὰ τῶν συμμάχων, ὅτι τῶν πόλεων τῶν ὑφ’ ἡμῖν οὐσῶν οὐδεμία ταύταις ταῖς συμφοραῖς περιέπεσεν.", "st": "4.101"}, {"sp": "N", "t": "ἔπειτ’ εἰ μὲν ἄλλοι τινὲς τῶν αὐτῶν πραγμάτων πραότερον ἐπεμελήθησαν, εἰκότως ἂν ἡμῖν ἐπιτιμῷεν· εἰ δὲ μήτε τοῦτο γέγονε μήθ’ οἷόν τ’ ἐστὶ τοσούτων πόλεων τὸ πλῆθος κρατεῖν, ἤν μή τις κολάζῃ τοὺς ἐξαμαρτάνοντας, πῶς οὐκ ἤδη δίκαιόν ἐστιν ἡμᾶς ἐπαινεῖν, οἵ τινες ἐλαχίστοις χαλεπήναντες πλεῖστον χρόνον τὴν ἀρχὴν κατασχεῖν ἠδυνήθημεν;", "st": "4.102"}, {"sp": "N", "t": "οἶμαι δὲ πᾶσι δοκεῖν τούτους κρατίστους προστάτας γενήσεσθαι τῶν Ἑλλήνων, ἐφ’ ὧν οἱ πειθαρχήσαντες ἄριστα τυγχάνουσι πράξαντες. ἐπὶ τοίνυν τῆς ἡμετέρας ἡγεμονίας εὑρήσομεν καὶ τοὺς οἴκους τοὺς ἰδίους πρὸς εὐδαιμονίαν πλεῖστον ἐπιδόντας καὶ τὰς πόλεις μεγίστας γενομένας.", "st": "4.103"}, {"sp": "N", "t": "οὐ γὰρ ἐφθονοῦμεν ταῖς αὐξανομέναις αὐτῶν, οὐδὲ ταραχὰς ἐνεποιοῦμεν πολιτείας ἐναντίας παρακαθιστάντες, ἵν’ ἀλλήλοις μὲν στασιάζοιεν, ἡμᾶς δ’ ἀμφότεροι θεραπεύοιεν, ἀλλὰ τὴν τῶν συμμάχων ὁμόνοιαν κοινὴν ὠφέλειαν νομίζοντες τοῖς αὐτοῖς νόμοις ἁπάσας τὰς πόλεις διῳκοῦμεν, συμμαχικῶς ἀλλ’ οὐ δεσποτικῶς βουλευόμενοι περὶ αὐτῶν, ὅλων μὲν τῶν πραγμάτων ἐπιστατοῦντες,", "st": "4.104"}, {"sp": "N", "t": "ἰδίᾳ δ’ ἑκάστους ἐλευθέρους ἐῶντες εἶναι, καὶ τῷ μὲν πλήθει βοηθοῦντες, ταῖς δὲ δυναστείαις πολεμοῦντες, δεινὸν ἡγούμενοι τοὺς πολλοὺς ὑπὸ τοῖς ὀλίγοις εἶναι, καὶ τοὺς ταῖς οὐσίαις ἐνδεεστέρους τὰ δ’ ἄλλα μηδὲν χείρους ὄντας ἀπελαύνεσθαι τῶν ἀρχῶν, ἔτι δὲ κοινῆς τῆς πατρίδος οὔσης τοὺς μὲν τυραννεῖν τοὺς δὲ μετοικεῖν, καὶ φύσει πολίτας ὄντας νόμῳ τῆς πολιτείας ἀποστερεῖσθαι.", "st": "4.105"}, {"sp": "N", "t": "τοιαῦτ’ ἔχοντες ταῖς ὀλιγαρχίαις ἐπιτιμᾶν καὶ πλείω τούτων, τὴν αὐτὴν πολιτείαν ἥνπερ παρ’ ἡμῖν αὐτοῖς καὶ παρὰ τοῖς ἄλλοις κατεστήσαμεν, ἣν οὐκ οἶδ’ ὅ τι δεῖ διὰ μακροτέρων ἐπαινεῖν, ἄλλως τε καὶ συντόμως ἔχοντα δηλῶσαι περὶ αὐτῆς. μετὰ γὰρ ταύτης οἰκοῦντες ἑβδομήκοντ’ ἔτη διετέλεσαν ἄπειροι μὲν τυραννίδων, ἐλεύθεροι δὲ πρὸς τοὺς βαρβάρους, ἀστασίαστοι δὲ πρὸς σφᾶς αὐτούς, εἰρήνην δ’ ἄγοντες πρὸς πάντας ἀνθρώπους.", "st": "4.106"}, {"sp": "N", "t": "ὑπὲρ ὧν προσήκει τοὺς εὖ φρονοῦντας μεγάλην χάριν ἔχειν πολὺ μᾶλλον ἢ τὰς κληρουχίας ἡμῖν ὀνειδίζειν, ἃς ἡμεῖς εἰς τὰς ἐρημουμένας τῶν πόλεων φυλακῆς ἕνεκα τῶν χωρίων, ἀλλ’ οὐ διὰ πλεονεξίαν ἐξεπέμπομεν. σημεῖον δὲ τούτων· ἔχοντες γὰρ χώραν μὲν ὡς πρὸς τὸ πλῆθος τῶν πολιτῶν ἐλαχίστην, ἀρχὴν δὲ μεγίστην, καὶ κεκτημένοι τριήρεις διπλασίας μὲν ἢ σύμπαντες οἱ ἄλλοι, δυναμένας δὲ πρὸς δὶς τοσαύτας κινδυνεύειν, ὑποκειμένης τῆς Εὐβοίας ὑπὸ τὴν Ἀττικήν,", "st": "4.107"}, {"sp": "N", "t": "ἣ καὶ πρὸς τὴν ἀρχὴν τὴν τῆς θαλάττης εὐφυῶς εἶχε καὶ τὴν ἄλλην ἀρετὴν ἁπασῶν τῶν νήσων διέφερε, κρατοῦντες αὐτῆς μᾶλλον ἢ τῆς ἡμετέρας αὐτῶν, καὶ πρὸς τούτοις εἰδότες καὶ τῶν Ἑλλήνων καὶ τῶν βαρβάρων τούτους μάλιστ’ εὐδοκιμοῦντας, οἳ τοὺς ὁμόρους ἀναστάτους ποιήσαντες ἄφθονον καὶ ῥᾴθυμον αὑτοῖς κατεστήσαντο τὸν βίον, ὅμως οὐδὲν τούτων ἡμᾶς ἐπῆρε περὶ τοὺς ἔχοντας τὴν νῆσον ἐξαμαρτεῖν,", "st": "4.108"}, {"sp": "N", "t": "ἀλλὰ μόνοι δὴ τῶν μεγάλην δύναμιν λαβόντων περιείδομεν ἡμᾶς αὐτοὺς ἀπορωτέρως ζῶντας τῶν δουλεύειν αἰτίαν ἐχόντων. καίτοι βουλόμενοι πλεονεκτεῖν οὐκ ἂν δή που τῆς μὲν Σκιωναίων γῆς ἐπεθυμήσαμεν, ἣν Πλαταιέων τοῖς ὡς ἡμᾶς καταφυγοῦσι φαινόμεθα παραδόντες, τοσαύτην δὲ χώραν παρελίπομεν, ἣ πάντας ἂν ἡμᾶς εὐπορωτέρους ἐποίησεν.", "st": "4.109"}, {"sp": "N", "t": "τοιούτων τοίνυν ἡμῶν γεγενημένων, καὶ τοσαύτην πίστιν δεδωκότων ὑπὲρ τοῦ μὴ τῶν ἀλλοτρίων ἐπιθυμεῖν, τολμῶσι κατηγορεῖν οἱ τῶν δεκαδαρχιῶν κοινωνήσαντες καὶ τὰς αὑτῶν πατρίδας διαλυμηνάμενοι καὶ μικρὰς μὲν ποιήσαντες δοκεῖν εἶναι τὰς τῶν προγεγενημένων ἀδικίας, οὐδεμίαν δὲ λιπόντες ὑπερβολὴν τοῖς αὖθις βουλομένοις γενέσθαι πονηροῖς, ἀλλὰ φάσκοντες μὲν λακωνίζειν, τἀναντία δ’ ἐκείνοις ἐπιτηδεύοντες, καὶ τὰς μὲν Μηλίων ὀδυρόμενοι συμφοράς, περὶ δὲ τοὺς αὑτῶν πολίτας ἀνήκεστα τολμήσαντες ἐξαμαρτεῖν. ποῖον γὰρ αὐτοὺς ἀδίκημα διέφυγεν;", "st": "4.110"}, {"sp": "N", "t": "ἤ τί τῶν αἰσχρῶν ἢ δεινῶν οὐ διεξῆλθον; οἳ τοὺς μὲν ἀνομωτάτους πιστοτάτους ἐνόμιζον, τοὺς δὲ προδότας ὥσπερ εὐεργέτας ἐθεράπευον, ᾑροῦντο δὲ τῶν Εἱλώτων ἑνὶ δουλεύειν ὥστ’ εἰς τὰς αὑτῶν πατρίδας ὑβρίζειν, μᾶλλον δ’ ἐτίμων τοὺς αὐτόχειρας καὶ φονέας τῶν πολιτῶν ἢ τοὺς γονέας τοὺς αὐτῶν,", "st": "4.111"}, {"sp": "N", "t": "εἰς τοῦτο δ’ ὠμότητος ἅπαντας ἡμᾶς κατέστησαν, ὥστε πρὸ τοῦ μὲν διὰ τὴν παροῦσαν εὐδαιμονίαν καὶ ταῖς μικραῖς ἀτυχίαις πολλοὺς ἕκαστον ἡμῶν ἔχειν τοὺς συμπενθήσοντας, ἐπὶ δὲ τῆς τούτων ἀρχῆς διὰ τὸ πλῆθος τῶν οἰκείων κακῶν ἐπαυσάμεθ’ ἀλλήλους ἐλεοῦντες. οὐδενὶ γὰρ τοσαύτην σχολὴν παρέλιπον ὥσθ’ ἑτέρῳ συναχθεσθῆναι.", "st": "4.112"}, {"sp": "N", "t": "τίνος γὰρ οὐκ ἐφίκοντο; ἢ τίς οὕτω πόρρω τῶν πολιτικῶν ἦν πραγμάτων, ὅστις οὐκ ἐγγὺς ἠναγκάσθη γενέσθαι τῶν συμφορῶν, εἰς ἃς αἱ τοιαῦται φύσεις ἡμᾶς κατέστησαν; εἶτ’ οὐκ αἰσχύνονται τὰς ἑαυτῶν πόλεις οὕτως ἀνόμως διαθέντες καὶ τῆς ἡμετέρας ἀδίκως κατηγοροῦντες, ἀλλὰ πρὸς τοῖς ἄλλοις καὶ περὶ τῶν δικῶν καὶ τῶν γραφῶν τῶν ποτε παρ’ ἡμῖν γενομένων λέγειν τολμῶσιν, αὐτοὶ πλείους ἐν τρισὶ μησὶν ἀκρίτους ἀποκτείναντες ὧν ἡ πόλις ἐπὶ τῆς ἀρχῆς ἁπάσης ἔκρινεν.", "st": "4.113"}, {"sp": "N", "t": "φυγὰς δὲ καὶ στάσεις καὶ νόμων συγχύσεις καὶ πολιτειῶν μεταβολάς, ἔτι δὲ παίδων ὕβρεις καὶ γυναικῶν αἰσχύνας καὶ χρημάτων ἁρπαγάς, τίς ἂν δύναιτο διεξελθεῖν; πλὴν τοσοῦτον εἰπεῖν ἔχω καθ’ ἁπάντων, ὅτι τὰ μὲν ἐφ’ ἡμῶν δεινὰ ῥᾳδίως ἄν τις ἑνὶ ψηφίσματι διέλυσε, τὰς δὲ σφαγὰς καὶ τὰς ἀνομίας τὰς ἐπὶ τούτων γενομένας οὐδεὶς ἂν ἰάσασθαι δύναιτο.", "st": "4.114"}, {"sp": "N", "t": "καὶ μὴν οὐδὲ τὴν παροῦσαν εἰρήνην, οὐδὲ τὴν αὐτονομίαν τὴν ἐν ταῖς πολιτείαις μὲν οὐκ ἐνοῦσαν ἐν δὲ ταῖς συνθήκαις ἀναγεγραμμένην, ἄξιον ἑλέσθαι μᾶλλον ἢ τὴν ἀρχὴν τὴν ἡμετέραν. τίς γὰρ ἂν τοιαύτης καταστάσεως ἐπιθυμήσειεν, ἐν ᾗ καταποντισταὶ μὲν τὴν θάλατταν κατέχουσι, πελτασταὶ δὲ τὰς πόλεις καταλαμβάνουσιν,", "st": "4.115"}, {"sp": "N", "t": "ἀντὶ δὲ τοῦ πρὸς ἑτέρους περὶ τῆς χώρας πολεμεῖν ἐντὸς τείχους οἱ πολῖται πρὸς ἀλλήλους μάχονται, πλείους δὲ πόλεις αἰχμάλωτοι γεγόνασιν ἢ πρὶν τὴν εἰρήνην ἡμᾶς ποιήσασθαι, διὰ δὲ τὴν πυκνότητα τῶν μεταβολῶν ἀθυμοτέρως διάγουσιν οἱ τὰς πόλεις οἰκοῦντες τῶν ταῖς φυγαῖς ἐζημιωμένων· οἱ μὲν γὰρ τὸ μέλλον δεδίασιν, οἱ δ’ ἀεὶ κατιέναι προσδοκῶσιν.", "st": "4.116"}, {"sp": "N", "t": "τοσοῦτον δ’ ἀπέχουσι τῆς ἐλευθερίας καὶ τῆς αὐτονομίας, ὥσθ’ αἱ μὲν ὑπὸ τυράννοις εἰσί, τὰς δ’ ἁρμοσταὶ κατέχουσιν, ἔνιαι δ’ ἀνάστατοι γεγόνασι, τῶν δ’ οἱ βάρβαροι δεσπόται καθεστήκασιν· οὓς ἡμεῖς διαβῆναι τολμήσαντας εἰς τὴν Εὐρώπην καὶ μεῖζον ἢ προσῆκεν αὐτοῖς φρονήσαντας οὕτω διέθεμεν,", "st": "4.117"}, {"sp": "N", "t": "ὥστε μὴ μόνον παύσασθαι στρατείας ἐφ’ ἡμᾶς ποιουμένους ἀλλὰ καὶ τὴν αὑτῶν χώραν ἀνέχεσθαι πορθουμένην, καὶ διακοσίαις καὶ χιλίαις ναυσὶ περιπλέοντας εἰς τοσαύτην ταπεινότητα κατεστήσαμεν, ὥστε μακρὸν πλοῖον ἐπὶ τάδε Φασήλιδος μὴ καθέλκειν, ἀλλ’ ἡσυχίαν ἄγειν καὶ τοὺς καιροὺς περιμένειν, ἀλλὰ μὴ τῇ παρούσῃ δυνάμει πιστεύειν.", "st": "4.118"}, {"sp": "N", "t": "καὶ ταῦθ’ ὅτι διὰ τὴν τῶν προγόνων τῶν ἡμετέρων ἀρετὴν οὕτως εἶχεν, αἱ τῆς πόλεως συμφοραὶ σαφῶς ἐπέδειξαν· ἅμα γὰρ ἡμεῖς τε τῆς ἀρχῆς ἀπεστερούμεθα καὶ τοῖς Ἕλλησιν ἀρχὴ τῶν κακῶν ἐγίγνετο. μετὰ γὰρ τὴν ἐν Ἑλλησπόντῳ γενομένην ἀτυχίαν ἑτέρων ἡγεμόνων καταστάντων ἐνίκησαν μὲν οἱ βάρβαροι ναυμαχοῦντες, ἦρξαν δὲ τῆς θαλάττης, κατέσχον δὲ τὰς πλείστας τῶν νήσων, ἀπέβησαν δ’ εἰς τὴν Λακωνικήν, Κύθηρα δὲ κατὰ κράτος εἷλον, ἅπασαν δὲ τὴν Πελοπόννησον κακῶς ποιοῦντες περιέπλευσαν.", "st": "4.119"}, {"sp": "N", "t": "μάλιστα δ’ ἄν τις συνίδοι τὸ μέγεθος τῆς μεταβολῆς, εἰ παραναγνοίη τὰς συνθήκας τάς τ’ ἐφ’ ἡμῶν γενομένας καὶ τὰς νῦν ἀναγεγραμμένας. τότε μὲν γὰρ ἡμεῖς φανησόμεθα τὴν ἀρχὴν τὴν βασιλέως ὁρίζοντες καὶ τῶν φόρων ἐνίους τάττοντες καὶ κωλύοντες αὐτὸν τῇ θαλάττῃ χρῆσθαι· νῦν δ’ ἐκεῖνός ἐστιν ὁ διοικῶν τὰ τῶν Ἑλλήνων, καὶ προστάττων ἃ χρὴ ποιεῖν ἑκάστους, καὶ μόνον οὐκ ἐπιστάθμους ἐν ταῖς πόλεσι καθιστάς.", "st": "4.120"}, {"sp": "N", "t": "πλὴν γὰρ τούτου τί τῶν ἄλλων ὑπόλοιπόν ἐστιν; οὐ καὶ τοῦ πολέμου κύριος ἐγένετο, καὶ τὴν εἰρήνην ἐπρυτάνευσε, καὶ τῶν παρόντων πραγμάτων ἐπιστάτης καθέστηκεν; οὐχ ὡς ἐκεῖνον πλέομεν ὥσπερ πρὸς δεσπότην, ἀλλήλων κατηγορήσοντες; οὐ βασιλέα τὸν μέγαν αὐτὸν προσαγορεύομεν, ὥσπερ αἰχμάλωτοι γεγονότες; οὐκ ἐν τοῖς πολέμοις τοῖς πρὸς ἀλλήλους ἐν ἐκείνῳ τὰς ἐλπίδας ἔχομεν τῆς σωτηρίας, ὃς ἀμφοτέρους ἡμᾶς ἡδέως ἂν ἀπολέσειεν;", "st": "4.121"}, {"sp": "N", "t": "ὧν ἄξιον ἐνθυμηθέντας ἀγανακτῆσαι μὲν ἐπὶ τοῖς παροῦσι, ποθέσαι δὲ τὴν ἡγεμονίαν τὴν ἡμετέραν, μέμψασθαι δὲ Λακεδαιμονίοις ὅτι τὴν μὲν ἀρχὴν εἰς τὸν πόλεμον κατέστησαν ὡς ἐλευθερώσοντες τοὺς Ἕλληνας, ἐπὶ δὲ τελευτῆς οὕτω πολλοὺς αὐτῶν ἐκδότους ἐποίησαν, καὶ τῆς μὲν ἡμετέρας πόλεως τοὺς Ἴωνας ἀπέστησαν, ἐξ ἧς ἀπῴκησαν καὶ δι’ ἣν πολλάκις ἐσώθησαν, τοῖς δὲ βαρβάροις αὐτοὺς ἐξέδοσαν, ὧν ἀκόντων τὴν χώραν ἔχουσι καὶ πρὸς οὓς οὐδὲ πώποτ’ ἐπαύσαντο πολεμοῦντες.", "st": "4.122"}, {"sp": "N", "t": "καὶ τότε μὲν ἠγανάκτουν, ὅθ’ ἡμεῖς νομίμως ἐπάρχειν τινῶν ἠξιοῦμεν· νῦν δ’ εἰς τοιαύτην δουλείαν καθεστώτων οὐδὲν φροντίζουσιν αὐτῶν, οἷς οὐκ ἐξαρκεῖ δασμολογεῖσθαι καὶ τὰς ἀκροπόλεις ὁρᾶν ὑπὸ τῶν ἐχθρῶν κατεχομένας, ἀλλὰ πρὸς ταῖς κοιναῖς συμφοραῖς καὶ τοῖς σώμασι δεινότερα πάσχουσι τῶν παρ’ ἡμῖν ἀργυρωνήτων· οὐδεὶς γὰρ ἡμῶν οὕτως αἰκίζεται τοὺς οἰκέτας, ὡς ἐκεῖνοι τοὺς ἐλευθέρους κολάζουσιν.", "st": "4.123"}, {"sp": "N", "t": "μέγιστον δὲ τῶν κακῶν, ὅταν ὑπὲρ αὐτῆς τῆς δουλείας ἀναγκάζωνται συστρατεύεσθαι, καὶ πολεμεῖν τοῖς ἐλευθέροις ἀξιοῦσιν εἶναι, καὶ τοιούτους κινδύνους ὑπομένειν, ἐν οἷς ἡττηθέντες μὲν παραχρῆμα διαφθαρήσονται, κατορθώσαντες δὲ μᾶλλον εἰς τὸν λοιπὸν χρόνον δουλεύσουσιν.", "st": "4.124"}, {"sp": "N", "t": "ὧν τίνας ἄλλους αἰτίους χρὴ νομίζειν ἢ Λακεδαιμονίους, οἳ τοσαύτην ἰσχὺν ἔχοντες περιορῶσι τοὺς μὲν αὑτῶν συμμάχους γενομένους οὕτω δεινὰ πάσχοντας, τὸν δὲ βάρβαρον τῇ τῶν Ἑλλήνων ῥώμῃ τὴν ἀρχὴν τὴν αὑτοῦ κατασκευαζόμενον; καὶ πρότερον μὲν τοὺς τυράννους ἐξέβαλλον, τῷ δὲ πλήθει τὰς βοηθείας ἐποιοῦντο, νῦν δὲ τοσοῦτον μεταβεβλήκασιν, ὥστε ταῖς μὲν πολιτείαις πολεμοῦσι,", "st": "4.125"}, {"sp": "N", "t": "τὰς δὲ μοναρχίας συγκαθιστᾶσι. τὴν μέν γε Μαντινέων πόλιν εἰρήνης ἤδη γεγενημένης ἀνάστατον ἐποίησαν, καὶ τὴν Θηβαίων Καδμείαν κατέλαβον, καὶ νῦν Ὀλυνθίους καὶ Φλιασίους πολιορκοῦσιν, Ἀμύντᾳ δὲ τῷ Μακεδόνων βασιλεῖ καὶ Διονυσίῳ τῷ Σικελίας τυράννῳ καὶ τῷ βαρβάρῳ τῷ τῆς Ἀσίας κρατοῦντι συμπράττουσιν ὅπως ὡς μεγίστην ἀρχὴν ἕξουσιν.", "st": "4.126"}, {"sp": "N", "t": "καίτοι πῶς οὐκ ἄτοπον τοὺς προεστῶτας τῶν Ἑλλήνων ἕνα μὲν ἄνδρα τοσούτων ἀνθρώπων καθιστάναι δεσπότην, ὧν οὐδὲ τὸν ἀριθμὸν ἐξευρεῖν ῥᾴδιόν ἐστι, τὰς δὲ μεγίστας τῶν πόλεων μηδ’ αὐτὰς αὑτῶν ἐᾶν εἶναι κυρίας, ἀλλ’ ἀναγκάζειν δουλεύειν ἢ ταῖς μεγίσταις συμφοραῖς περιβάλλειν;", "st": "4.127"}, {"sp": "N", "t": "ὃ δὲ πάντων δεινότατον, ὅταν τις ἴδῃ τοὺς τὴν ἡγεμονίαν ἔχειν ἀξιοῦντας ἐπὶ μὲν τοὺς Ἕλληνας καθ’ ἑκάστην τὴν ἡμέραν στρατευομένους, πρὸς δὲ τοὺς βαρβάρους εἰς ἅπαντα τὸν χρόνον συμμαχίαν πεποιημένους.", "st": "4.128"}, {"sp": "N", "t": "καὶ μηδεὶς ὑπολάβῃ με δυσκόλως ἔχειν, ὅτι τραχύτερον τούτων ἐμήσθην, προειπὼν ὡς περὶ διαλλαγῶν ποιήσομαι τοὺς λόγους· οὐ γὰρ ἵνα πρὸς τοὺς ἄλλους διαβάλω τὴν πόλιν τὴν Λακεδαιμονίων οὕτως εἴρηκα περὶ αὐτῶν, ἀλλ’ ἵν’ αὐτοὺς ἐκείνους παύσω, καθ’ ὅσον ὁ λόγος δύναται, τοιαύτην ἔχοντας τὴν γνώμην.", "st": "4.129"}, {"sp": "N", "t": "ἔστι δὲ οὐχ οἷόν τ’ ἀποτρέπειν τῶν ἁμαρτημάτων, οὐδ’ ἑτέρων πράξεων πείθειν ἐπιθυμεῖν, ἢν μή τις ἐρρωμένως ἐπιτιμήσῃ τοῖς παροῦσιν· χρὴ δὲ κατηγορεῖν μὲν ἡγεῖσθαι τοὺς ἐπὶ βλάβῃ τοιαῦτα λέγοντας, νουθετεῖν δὲ τοὺς ἐπ’ ὠφελείᾳ λοιδοροῦντας. τὸν γὰρ αὐτὸν λόγον οὐχ ὁμοίως ὑπολαμβάνειν δεῖ, μὴ μετὰ τῆς αὐτῆς διανοίας λεγόμενον.", "st": "4.130"}, {"sp": "N", "t": "ἐπεὶ καὶ τοῦτ’ ἔχομεν αὐτοῖς ἐπιτιμᾶν, ὅτι τῇ μὲν αὑτῶν πόλει τοὺς ὁμόρους εἱλωτεύειν ἀναγκάζουσι, τῷ δὲ κοινῷ τῷ τῶν συμμάχων οὐδὲν τοιοῦτον κατασκευάζουσιν, ἐξὸν αὐτοῖς τὰ πρὸς ἡμᾶς διαλυσαμένοις ἅπαντας τοὺς βαρβάρους περιοίκους ὅλης τῆς Ἑλλάδος καταστῆσαι.", "st": "4.131"}, {"sp": "N", "t": "καίτοι χρὴ τοὺς φύσει καὶ μὴ διὰ τύχην μέγα φρονοῦντας τοιούτοις ἔργοις ἐπιχειρεῖν πολὺ μᾶλλον ἢ τοὺς νησιώτας δασμολογεῖν, οὓς ἄξιόν ἐστιν ἐλεεῖν, ὁρῶντας τούτους μὲν διὰ σπανιότητα τῆς γῆς ὄρη γεωργεῖν ἀναγκαζομένους, τοὺς δ’ ἠπειρώτας δι’ ἀφθονίαν τῆς χώρας τὴν μὲν πλείστην αὐτῆς ἀργὸν περιορῶντας, ἐξ ἧς δὲ καρποῦνται τοσοῦτον πλοῦτον κεκτημένους.", "st": "4.132"}, {"sp": "N", "t": "ἡγοῦμαι δ’, εἴ τινες ἄλλοθεν ἐπελθόντες θεαταὶ γένοιντο τῶν παρόντων πραγμάτων, πολλὴν ἂν αὐτοὺς καταγνῶναι μανίαν ἀμφοτέρων ἡμῶν, οἵ τινες οὕτω περὶ μικρῶν κινδυνεύομεν, ἐξὸν ἀδεῶς πολλὰ κεκτῆσθαι, καὶ τὴν ἡμετέραν αὐτῶν χώραν διαφθείρομεν, ἀμελήσαντες τὴν Ἀσίαν καρποῦσθαι.", "st": "4.133"}, {"sp": "N", "t": "καὶ τῷ μὲν οὐδὲν προὐργιαίτερόν ἐστιν ἢ σκοπεῖν ἐξ ὧν μηδέποτε παυσόμεθα πρὸς ἀλλήλους πολεμοῦντες· ἡμεῖς δὲ τοσούτου δέομεν συγκρούειν τι τῶν ἐκείνου πραγμάτων ἢ ποιεῖν στασιάζειν, ὥστε καὶ τὰς διὰ τύχην αὐτῷ γεγενημένας ταραχὰς συνδιαλύειν ἐπιχειροῦμεν, οἵ τινες καὶ τοῖν στρατοπέδοιν τοῖν περὶ Κύπρον ἐῶμεν αὐτὸν τῷ μὲν χρῆσθαι τὸ δὲ πολιορκεῖν, ἀμφοτέροιν αὐτοῖν τῆς Ἑλλάδος ὄντοιν.", "st": "4.134"}, {"sp": "N", "t": "οἵ τε γὰρ ἀφεστῶτες πρὸς ἡμᾶς τ’ οἰκείως ἔχουσι καὶ Λακεδαιμονίοις σφᾶς αὐτοὺς ἐνδιδόασιν, τῶν τε μετὰ Τειριβάζου στρατευομένων καὶ τοῦ πεζοῦ τὸ χρησιμώτατον ἐκ τῶνδε τῶν τόπων ἤθροισται, καὶ τοῦ ναυτικοῦ τὸ πλεῖστον ἀπ’ Ἰωνίας συμπέπλευκεν, οἳ πολὺ ἂν ἥδιον κοινῇ τὴν Ἀσίαν ἐπόρθουν ἢ πρὸς ἀλλήλους ἕνεκα μικρῶν ἐκινδύνευον.", "st": "4.135"}, {"sp": "N", "t": "ὧν ἡμεῖς οὐδεμίαν ποιούμεθα πρόνοιαν, ἀλλὰ περὶ μὲν τῶν Κυκλάδων νήσων ἀμφισβητοῦμεν, τοσαύτας δὲ τὸ πλῆθος πόλεις καὶ τηλικαύτας τὸ μέγεθος δυνάμεις οὕτως εἰκῇ τῷ βαρβάρῳ παραδεδώκαμεν. τοιγαροῦν τὰ μὲν ἔχει, τὰ δὲ μέλλει, τοῖς δ’ ἐπιβουλεύει, δικαίως ἁπάντων ἡμῶν καταπεφρονηκώς.", "st": "4.136"}, {"sp": "N", "t": "διαπέπρακται γὰρ ὃ τῶν ἐκείνου προγόνων οὐδεὶς πώποτε· τήν τε γὰρ Ἀσίαν διωμολόγηται καὶ παρ’ ἡμῶν καὶ παρὰ Λακεδαιμονίων βασιλέως εἶναι, τάς τε πόλεις τὰς Ἑλληνίδας οὕτω κυρίως παρείληφεν, ὥστε τὰς μὲν αὐτῶν κατασκάπτειν, ἐν δὲ ταῖς ἀκροπόλεις ἐντειχίζειν. καὶ ταῦτα πάντα γέγονε διὰ τὴν ἡμετέραν ἄνοιαν, ἀλλ’ οὐ διὰ τὴν ἐκείνου δύναμιν.", "st": "4.137"}, {"sp": "N", "t": "καίτοι τινὲς θαυμάζουσι τὸ μέγεθος τῶν βασιλέως πραγμάτων, καί φασιν αὐτὸν εἶναι δυσπολέμητον, διεξιόντες ὡς πολλὰς τὰς μεταβολὰς τοῖς Ἕλλησι πεποίηκεν. ἐγὼ δ’ ἡγοῦμαι μὲν τοὺς ταῦτα λέγοντας οὐκ ἀποτρέπειν ἀλλ’ ἐπισπεύδειν τὴν στρατείαν· εἰ γὰρ ἡμῶν ὁμονοησάντων αὐτὸς ἐν ταραχαῖς ὢν χαλεπὸς ἔσται προσπολεμεῖν, ἦ που σφόδρα χρὴ δεδιέναι τὸν καιρὸν ἐκεῖνον, ὅταν τὰ μὲν τῶν βαρβάρων καταστῇ καὶ διὰ μιᾶς γένηται γνώμης, ἡμεῖς δὲ πρὸς ἀλλήλους ὥσπερ νῦν πολεμικῶς ἔχωμεν.", "st": "4.138"}, {"sp": "N", "t": "οὐ μὴν οὐδ’ εἰ συναγορεύουσι τοῖς ὑπ’ ἐμοῦ λεγομένοις, οὐδ’ ὣς ὀρθῶς περὶ τῆς ἐκείνου δυνάμεως γιγνώσκουσιν. εἰ μὲν γὰρ ἀπέφαινον αὐτὸν ἅμα τοῖν πολέοιν ἀμφοτέροιν πρότερόν ποτε περιγεγενημένον, εἰκότως ἂν ἡμᾶς καὶ νῦν ἐκφοβεῖν ἐπεχείρουν· εἰ δὲ τοῦτο μὲν μὴ γέγονεν, ἀντιπάλων δ’ ὄντων ἡμῶν καὶ Λακεδαιμονίων προσθέμενος τοῖς ἑτέροις ἐπικυδέστερα τὰ πράγματα θάτερ’ ἐποίησεν, οὐδέν ἐστι τοῦτο σημεῖον τῆς ἐκείνου ῥώμης. ἐν γὰρ τοῖς τοιούτοις καιροῖς πολλάκις μικραὶ δυνάμεις μεγάλας τὰς ῥοπὰς ἐποίησαν, ἐπεὶ καὶ περὶ Χίων ἔχοιμ’ ἂν τοῦτον τὸν λόγον εἰπεῖν, ὡς ὁποτέροις ἐκεῖνοι προσθέσθαι βουληθεῖεν, οὗτοι κατὰ θάλατταν κρείττους ἦσαν.", "st": "4.139"}, {"sp": "N", "t": "ἀλλὰ γὰρ οὐκ ἐκ τούτων δίκαιόν ἐστι σκοπεῖν τὴν βασιλέως δύναμιν, ἐξ ὧν μεθ’ ἑκατέρων γέγονεν, ἀλλ’ ἐξ ὧν αὐτὸς ὑπὲρ αὑτοῦ πεπολέμηκεν. καὶ πρῶτον μὲν ἀποστάσης Αἰγύπτου τί διαπέπρακται πρὸς τοὺς ἔχοντας αὐτήν; οὐκ ἐκεῖνος μὲν ἐπὶ τὸν πόλεμον τοῦτον κατέπεμψε τοὺς εὐδοκιμωτάτους Περσῶν, Ἀβροκόμαν καὶ Τιθραύστην καὶ Φαρνάβαζον, οὗτοι δὲ τρί’ ἔτη μείναντες, καὶ πλείω κακὰ παθόντες ἢ ποιήσαντες, τελευτῶντες οὕτως αἰσχρῶς ἀπηλλάγησαν, ὥστε τοὺς ἀφεστῶτας μηκέτι τὴν ἐλευθερίαν ἀγαπᾶν, ἀλλ’ ἤδη καὶ τῶν ὁμόρων ζητεῖν ἐπάρχειν;", "st": "4.140"}, {"sp": "N", "t": "μετὰ δὲ ταῦτ’ ἐπ’ Εὐαγόραν στρατεύσας, ὃς ἄρχει μὲν μιᾶς πόλεως, ἐν δὲ ταῖς συνθήκαις ἔκδοτός ἐστιν, οἰκῶν δὲ νῆσον κατὰ μὲν θάλατταν προδεδυστύχηκεν, ὑπὲρ δὲ τῆς χώρας τρισχιλίους ἔχει μόνον πελταστάς, ἀλλ’ ὅμως οὕτω ταπεινῆς δυνάμεως οὐ δύναται περιγενέσθαι βασιλεὺς πολεμῶν, ἀλλ’ ἤδη μὲν ἓξ ἔτη διατέτριφεν, εἰ δὲ δεῖ τὰ μέλλοντα τοῖς γεγενημένοις τεκμαίρεσθαι, πολὺ πλείων ἐλπίς ἐστιν ἕτερον ἀποστῆναι πρὶν ἐκεῖνον ἐκπολιορκηθῆναι· τοιαῦται βραδυτῆτες ἐν ταῖς πράξεσι ταῖς βασιλέως ἔνεισιν.", "st": "4.141"}, {"sp": "N", "t": "ἐν τῷ πολέμῳ τῷ περὶ Ῥόδον ἔχων μὲν τοὺς Λακεδαιμονίων συμμάχους εὔνους διὰ τὴν χαλεπότητα τῶν πολιτειῶν, χρώμενος δὲ ταῖς ὑπηρεσίαις ταῖς παρ’ ἡμῶν, στρατηγοῦντος δ’ αὐτῷ Κόνωνος, ὃς ἦν ἐπιμελέστατος μὲν τῶν στρατηγῶν, πιστότατος δὲ τοῖς Ἕλλησιν, ἐμπειρότατος δὲ τῶν πρὸς τὸν πόλεμον κινδύνων, τοιοῦτον λαβὼν συναγωνιστὴν τρία μὲν ἔτη περιεῖδε τὸ ναυτικὸν τὸ προκινδυνεῦον ὑπὲρ τῆς Ἀσίας ὑπὸ τριήρων ἑκατὸν μόνων πολιορκούμενον, πεντεκαίδεκα δὲ μηνῶν τοὺς στρατιώτας τὸν μισθὸν ἀπεστέρησεν, ὥστε τὸ μὲν ἐπ’ ἐκείνῳ πολλάκις ἂν διελύθησαν, διὰ δὲ τὸν ἐφεστῶτα καὶ τὴν συμμαχίαν τὴν περὶ Κόρινθον συστᾶσαν μόλις ναυμαχοῦντες ἐνίκησαν.", "st": "4.142"}, {"sp": "N", "t": "καὶ ταῦτ’ ἐστὶ τὰ βασιλικώτατα καὶ σεμνότατα τῶν ἐκείνῳ πεπραγμένων, καὶ περὶ ὧν οὐδέποτε παύονται λέγοντες οἱ βουλόμενοι τὰ τῶν βαρβάρων μεγάλα ποιεῖν. ὥστ’ οὐδεὶς ἂν ἔχοι τοῦτ’ εἰπεῖν, ὡς οὐ δικαίως χρῶμαι τοῖς παραδείγμασιν, οὐδ’ ὡς ἐπὶ μικροῖς διατρίβω τὰς μεγίστας τῶν πράξεων παραλείπων·", "st": "4.143"}, {"sp": "N", "t": "φεύγων γὰρ ταύτην τὴν αἰτίαν τὰ κάλλιστα τῶν ἔργων διῆλθον, οὐκ ἀμνημονῶν οὐδ’ ἐκείνων, ὅτι Δερκυλίδας μὲν χιλίους ἔχων ὁπλίτας τῆς Αἰολίδος ἐπῆρχε, Δράκων δὲ Ἀταρνέα καταλαβὼν καὶ τρισχιλίους πελταστὰς συλλέξας τὸ Μύσιον πεδίον ἀνάστατον ἐποίησε, Θίβρων δὲ ὀλίγῳ πλείους τούτων διαβιβάσας τὴν Λυδίαν ἅπασαν ἐπόρθησεν, Ἀγησίλαος δὲ τῷ Κυρείῳ στρατεύματι χρώμενος μικροῦ δεῖν τῆς ἐντὸς Ἅλυος χώρας ἐκράτησεν.", "st": "4.144"}, {"sp": "N", "t": "καὶ μὴν οὐδὲ τὴν στρατιὰν τὴν μετὰ τοῦ βασιλέως περιπολοῦσαν, οὐδὲ τὴν Περσῶν ἀνδρίαν ἄξιον φοβηθῆναι· καὶ γὰρ ἐκεῖνοι φανερῶς ἐπεδείχθησαν ὑπὸ τῶν Κύρῳ συναναβάντων οὐδὲν βελτίους ὄντες τῶν ἐπὶ θαλάττῃ. τὰς μὲν γὰρ ἄλλας μάχας ὅσας ἡττήθησαν ἐῶ, καὶ τίθημι στασιάζειν αὐτοὺς καὶ μὴ βούλεσθαι προθύμως πρὸς τὸν ἀδελφὸν τὸν βασιλέως διακινδυνεύειν.", "st": "4.145"}, {"sp": "N", "t": "ἀλλ’ ἐπειδὴ Κύρου τελευτήσαντος συνῆλθον ἅπαντες οἱ τὴν Ἀσίαν κατοικοῦντες, ἐν τούτοις τοῖς καιροῖς οὕτως αἰσχρῶς ἐπολέμησαν, ὥστε μηδένα λόγον ὑπολιπεῖν τοῖς εἰθισμένοις τὴν Περσῶν ἀνδρίαν ἐπαινεῖν. λαβόντες γὰρ ἑξακισχιλίους τῶν Ἑλλήνων οὐκ ἀριστίνδην ἐπειλεγμένους, ἀλλ’ οἳ διὰ φαυλότητα ἐν ταῖς αὑτῶν οὐχ οἷοί τ’ ἦσαν ζῆν, ἀπείρους μὲν τῆς χώρας ὄντας, ἐρήμους δὲ συμμάχων γεγενημένους, προδεδομένους δ’ ὑπὸ τῶν συναναβάντων, ἀπεστερημένους δὲ τοῦ στρατηγοῦ μεθ’ οὗ συνηκολούθησαν,", "st": "4.146"}, {"sp": "N", "t": "τοσοῦτον αὐτῶν ἥττους ἦσαν, ὥσθ’ ὁ βασιλεὺς ἀπορήσας τοῖς παροῦσι πράγμασι καὶ καταφρονήσας τῆς περὶ αὑτὸν δυνάμεως τοὺς ἄρχοντας τοὺς τῶν ἐπικούρων ὑποσπόνδους συλλαβεῖν ἐτόλμησεν, ὡς εἰ τοῦτο παρανομήσειε συνταράξων τὸ στρατόπεδον, καὶ μᾶλλον εἵλετο περὶ τοὺς θεοὺς ἐξαμαρτεῖν ἢ πρὸς ἐκείνους ἐκ τοῦ φανεροῦ διαγωνίσασθαι.", "st": "4.147"}, {"sp": "N", "t": "διαμαρτὼν δὲ τῆς ἐπιβουλῆς, καὶ τῶν στρατιωτῶν συμμεινάντων καὶ καλῶς ἐνεγκόντων τὴν συμφοράν, ἀπιοῦσιν αὐτοῖς Τισσαφέρνην καὶ τοὺς ἱππέας συνέπεμψεν, ὑφ’ ὧν ἐκεῖνοι παρὰ πᾶσαν ἐπιβουλευόμενοι τὴν ὁδὸν ὁμοίως διεπορεύθησαν ὡσπερανεὶ προπεμπόμενοι, μάλιστα μὲν φοβούμενοι τὴν ἀοίκητον τῆς χώρας, μέγιστον δὲ τῶν ἀγαθῶν νομίζοντες εἰ τῶν πολεμίων ὡς πλείστοις ἐντύχοιεν.", "st": "4.148"}, {"sp": "N", "t": "κεφάλαιον δὲ τῶν εἰρημένων· ἐκεῖνοι γὰρ οὐκ ἐπὶ λείαν ἐλθόντες οὐδὲ κώμην καταλαβόντες, ἀλλ’ ἐπ’ αὐτὸν τὸν βασιλέα στρατεύσαντες, ἀσφαλέστερον κατέβησαν τῶν περὶ φιλίας ὡς αὐτὸν πρεσβευόντων. ὥστε μοι δοκοῦσιν ἐν ἅπασι τοῖς τόποις σαφῶς ἐπιδεδεῖχθαι τὴν αὑτῶν μαλακίαν· καὶ γὰρ ἐν τῇ παραλίᾳ τῆς Ἀσίας πολλὰς μάχας ἥττηνται, καὶ διαβάντες εἰς τὴν Εὐρώπην δίκην ἔδοσαν (οἱ μὲν γὰρ αὐτῶν κακῶς ἀπώλοντο, οἱ δ’ αἰσχρῶς ἐσώθησαν), καὶ τελευτῶντες ὑπ’ αὐτοῖς τοῖς βασιλείοις καταγέλαστοι γεγόνασιν.", "st": "4.149"}, {"sp": "N", "t": "καὶ τούτων οὐδὲν ἀλόγως γέγονεν, ἀλλὰ πάντ’ εἰκότως ἀποβέβηκεν· οὐ γὰρ οἷόν τε τοὺς οὕτω τρεφομένους καὶ πολιτευομένους οὔτε τῆς ἄλλης ἀρετῆς μετέχειν οὔτ’ ἐν ταῖς μάχαις τρόπαιον ἱστάναι τῶν πολεμίων. πῶς γὰρ ἐν τοῖς ἐκείνων ἐπιτηδεύμασιν ἐγγενέσθαι δύναιτ’ ἂν ἢ στρατηγὸς δεινὸς ἢ στρατιώτης ἀγαθός, ὧν τὸ μὲν πλεῖστόν ἐστιν ὄχλος ἄτακτος καὶ κινδύνων ἄπειρος, πρὸς μὲν τὸν πόλεμον ἐκλελυμένος, πρὸς δὲ τὴν δουλείαν ἄμεινον τῶν παρ’ ἡμῖν οἰκετῶν πεπαιδευμένος,", "st": "4.150"}, {"sp": "N", "t": "οἱ δ’ ἐν ταῖς μεγίσταις δόξαις ὄντες αὐτῶν ὁμαλῶς μὲν οὐδὲ κοινῶς οὐδὲ πολιτικῶς οὐδεπώποτ’ ἐβίωσαν, ἅπαντα δὲ τὸν χρόνον διάγουσιν εἰς μὲν τοὺς ὑβρίζοντες τοῖς δὲ δουλεύοντες, ὡς ἂν ἄνθρωποι μάλιστα τὰς φύσεις διαφθαρεῖεν, καὶ τὰ μὲν σώματα διὰ τοὺς πλούτους τρυφῶντες, τὰς δὲ ψυχὰς διὰ τὰς μοναρχίας ταπεινὰς καὶ περιδεεῖς ἔχοντες, ἐξεταζόμενοι πρὸς αὐτοῖς τοῖς βασιλείοις καὶ προκαλινδούμενοι καὶ πάντα τρόπον μικρὸν φρονεῖν μελετῶντες, θνητὸν μὲν ἄνδρα προσκυνοῦντες καὶ δαίμονα προσαγορεύοντες, τῶν δὲ θεῶν μᾶλλον ἢ τῶν ἀνθρώπων ὀλιγωροῦντες. τοιγαροῦν οἱ καταβαίνοντες αὐτῶν ἐπὶ θάλατταν,", "st": "4.151"}, {"sp": "N", "t": "οὓς καλοῦσι σατράπας, οὐ καταισχύνουσι τὴν ἐκεῖ παίδευσιν, ἀλλ’ ἐν τοῖς ἤθεσι τοῖς αὐτοῖς διαμένουσι, πρὸς μὲν τοὺς φίλους ἀπίστως πρὸς δὲ τοὺς ἐχθροὺς ἀνάνδρως ἔχοντες, καὶ τὰ μὲν ταπεινῶς τὰ δ’ ὑπερηφάνως ζῶντες, τῶν μὲν συμμάχων καταφρονοῦντες τοὺς δὲ πολεμίους θεραπεύοντες.", "st": "4.152"}, {"sp": "N", "t": "τὴν μέν γε μετ’ Ἀγησιλάου στρατιὰν ὀκτὼ μῆνας ταῖς αὑτῶν δαπάναις διέθρεψαν, τοὺς δ’ ὑπὲρ αὑτῶν κινδυνεύοντας ἑτέρου τοσούτου χρόνου τὸν μισθὸν ἀπεστέρησαν· καὶ τοῖς μὲν Κισθήνην καταλαβοῦσιν ἑκατὸν τάλαντα διένειμαν, τοὺς δὲ μεθ’ αὑτῶν εἰς Κύπρον στρατευσαμένους μᾶλλον ἢ τοὺς αἰχμαλώτους ὕβριζον.", "st": "4.153"}, {"sp": "N", "t": "ὡς δ’ ἁπλῶς εἰπεῖν καὶ μὴ καθ’ ἓν ἕκαστον ἀλλ’ ὡς ἐπὶ τὸ πολύ, τίς ἢ τῶν πολεμησάντων αὐτοῖς οὐκ εὐδαιμονήσας ἀπῆλθεν, ἢ τῶν ὑπ’ ἐκείνοις γενομένων οὐκ αἰκισθεὶς τὸν βίον ἐτελεύτησεν; οὐ Κόνωνα μέν, ὃς ὑπὲρ τῆς Ἀσίας στρατηγήσας τὴν ἀρχὴν τὴν Λακεδαιμονίων κατέλυσεν, ἐπὶ θανάτῳ συλλαβεῖν ἐτόλμησαν, Θεμιστοκλέα δ’, ὃς ὑπὲρ τῆς Ἑλλάδος αὐτοὺς κατεναυμάχησε, τῶν μεγίστων δωρεῶν ἠξίωσαν;", "st": "4.154"}, {"sp": "N", "t": "καίτοι πῶς χρὴ τὴν τούτων φιλίαν ἀγαπᾶν, οἳ τοὺς μὲν εὐεργέτας τιμωροῦνται, τοὺς δὲ κακῶς ποιοῦντας οὕτως ἐπιφανῶς κολακεύουσιν; περὶ τίνας δ’ ἡμῶν οὐκ ἐξημαρτήκασιν; ποῖον δὲ χρόνον διαλελοίπασιν ἐπιβουλεύοντες τοῖς Ἕλλησιν; τί δ’ οὐκ ἐχθρὸν αὐτοῖς ἐστι τῶν παρ’ ἡμῖν, οἳ καὶ τὰ τῶν θεῶν ἕδη καὶ τοὺς νεὼς συλᾶν ἐν τῷ προτέρῳ πολέμῳ καὶ κατακάειν ἐτόλμησαν; διὸ καὶ τοὺς Ἴωνας ἄξιον ἐπαινεῖν,", "st": "4.155"}, {"sp": "N", "t": "ὅτι τῶν ἐμπρησθέντων ἱερῶν ἐπηράσαντο εἴ τινες κινήσειαν ἢ πάλιν εἰς τἀρχαῖα καταστῆσαι βουληθεῖεν, οὐκ ἀποροῦντες πόθεν ἐπισκευάσωσιν, ἀλλ’ ἵν’ ὑπόμνημα τοῖς ἐπιγιγνομένοις ᾖ τῆς τῶν βαρβάρων ἀσεβείας, καὶ μηδεὶς πιστεύῃ τοῖς τοιαῦτα εἰς τὰ τῶν θεῶν ἐξαμαρτεῖν τολμῶσιν, ἀλλὰ καὶ φυλάττωνται καὶ δεδίωσιν, ὁρῶντες αὐτοὺς οὐ μόνον τοῖς σώμασιν ἡμῶν ἀλλὰ καὶ τοῖς ἀναθήμασι πολεμήσαντας.", "st": "4.156"}, {"sp": "N", "t": "ἔχω δὲ καὶ περὶ τῶν πολιτῶν τῶν ἡμετέρων τοιαῦτα διελθεῖν. καὶ γὰρ οὗτοι πρὸς μὲν τοὺς ἄλλους, ὅσοις πεπολεμήκασιν, ἅμα διαλλάττονται καὶ τῆς ἔχθρας τῆς γεγενημένης ἐπιλανθάνονται, τοῖς δ’ ἠπειρώταις οὐδ’ ὅταν εὖ πάσχωσι χάριν ἴσασιν· οὕτως ἀείμνηστον τὴν ὀργὴν πρὸς αὐτοὺς ἔχουσιν. καὶ πολλῶν μὲν οἱ πατέρες ἡμῶν μηδισμοῦ θάνατον κατέγνωσαν, ἐν δὲ τοῖς συλλόγοις ἔτι καὶ νῦν ἀρὰς ποιοῦνται, πρὶν ἄλλο τι χρηματίζειν, εἴ τις ἐπικηρυκεύεται Πέρσαις τῶν πολιτῶν· Εὐμολπίδαι δὲ καὶ Κήρυκες ἐν τῇ τελετῇ τῶν μυστηρίων διὰ τὸ τούτων μῖσος καὶ τοῖς ἄλλοις βαρβάροις εἴργεσθαι τῶν ἱερῶν, ὥσπερ τοῖς ἀνδροφόνοις,", "st": "4.157"}, {"sp": "N", "t": "προαγορεύουσιν. οὕτω δὲ φύσει πολεμικῶς πρὸς αὐτοὺς ἔχομεν, ὥστε καὶ τῶν μύθων ἥδιστα συνδιατρίβομεν τοῖς Τρωικοῖς καὶ Περσικοῖς, δι’ ὧν ἔστι πυνθάνεσθαι τὰς ἐκείνων συμφοράς. εὕροι δ’ ἄν τις ἐκ μὲν τοῦ πολέμου τοῦ πρὸς τοὺς βαρβάρους ὕμνους πεποιημένους, ἐκ δὲ τοῦ πρὸς τοὺς Ἕλληνας θρήνους ἡμῖν γεγενημένους, καὶ τοὺς μὲν ἐν ταῖς ἑορταῖς ᾀδομένους, τῶν δ’ ἐπὶ ταῖς συμφοραῖς ἡμᾶς μεμνημένους.", "st": "4.158"}, {"sp": "N", "t": "οἶμαι δὲ καὶ τὴν Ὁμήρου ποίησιν μείζω λαβεῖν δόξαν, ὅτι καλῶς τοὺς πολεμήσαντας τοῖς βαρβάροις ἐνεκωμίασε, καὶ διὰ τοῦτο βουληθῆναι τοὺς προγόνους ἡμῶν ἔντιμον αὐτοῦ ποιῆσαι τὴν τέχνην ἔν τε τοῖς τῆς μουσικῆς ἄθλοις καὶ τῇ παιδεύσει τῶν νεωτέρων, ἳνα πολλάκις ἀκούοντες τῶν ἐπῶν ἐκμανθάνωμεν τὴν ἔχθραν τὴν ὑπάρχουσαν πρὸς αὐτούς, καὶ ζηλοῦντες τὰς ἀρετὰς τῶν στρατευσαμένων τῶν αὐτῶν ἔργων ἐκείνοις ἐπιθυμῶμεν.", "st": "4.159"}, {"sp": "N", "t": "ὥστε μοι δοκεῖ πολλὰ λίαν εἶναι τὰ παρακελευόμενα πολεμεῖν αὐτοῖς, μάλιστα δ’ ὁ παρὼν καιρός, ὃν οὐκ ἀφετέον· καὶ γὰρ αἰσχρὸν παρόντι μὲν μὴ χρῆσθαι, παρελθόντος δ’ αὐτοῦ μεμνῆσθαι. τί γὰρ ἂν καὶ βουληθεῖμεν ἡμῖν προσγενέσθαι, μέλλοντες βασιλεῖ πολεμεῖν, ἔξω τῶν νῦν ὑπαρχόντων;", "st": "4.160"}, {"sp": "N", "t": "οὐκ Αἴγυπτος μὲν αὐτοῦ καὶ Κύπρος ἀφέστηκε, Φοινίκη δὲ καὶ Συρία διὰ τὸν πόλεμον ἀνάστατοι γεγόνασι, Τύρος δ’, ἐφ’ ᾗ μέγ’ ἐφρόνησεν, ὑπὸ τῶν ἐχθρῶν τῶν ἐκείνου κατείληπται; τῶν δ’ ἐν Κιλικίᾳ πόλεων τὰς μὲν πλείστας οἱ μεθ’ ἡμῶν ὄντες ἔχουσι, τὰς δ’ οὐ χαλεπόν ἐστι κτήσασθαι. Λυκίας δ’ οὐδεὶς πώποτε Περσῶν ἐκράτησεν.", "st": "4.161"}, {"sp": "N", "t": "Ἑκατόμνως δ’ ὁ Καρίας ἐπίσταθμος τῇ μὲν ἀληθείᾳ πολὺν ἤδη χρόνον ἀφέστηκεν, ὁμολογήσει δ’ ὅταν ἡμεῖς βουληθῶμεν. ἀπὸ δὲ Κνίδου μέχρι Σινώπης Ἕλληνες τὴν Ἀσίαν παροικοῦσιν, οὓς οὐ δεῖ πείθειν ἀλλὰ μὴ κωλύειν πολεμεῖν. καίτοι τοιούτων ὁρμητηρίων ὑπαρξάντων, καὶ τοσούτου πολέμου τὴν Ἀσίαν περιστάντος, τί δεῖ τὰ συμβησόμενα λίαν ἀκριβῶς ἐξετάζειν; ὅπου γὰρ μικρῶν μερῶν ἥττους εἰσίν, οὐκ ἄδηλον ὡς ἂν διατεθεῖεν, εἰ πᾶσιν ἡμῖν πολεμεῖν ἀναγκασθεῖεν.", "st": "4.162"}, {"sp": "N", "t": "ἔχει δ’ οὕτως. ἐὰν μὲν ὁ βάρβαρος ἐρρωμενεστέρως κατάσχῃ τὰς πόλεις τὰς ἐπὶ θαλάττῃ, φρουρὰς μείζους ἐν αὐταῖς ἢ νῦν ἐγκαταστήσας, τάχ’ ἂν καὶ τῶν νήσων αἱ περὶ τὴν ἤπειρον, οἷον Ῥόδος καὶ Σάμος καὶ Χίος, ἐπὶ τὰς ἐκείνου τύχας ἀποκλίναιεν· ἢν δ’ ἡμεῖς αὐτὰς πρότεροι καταλάβωμεν, εἰκὸς τοὺς τὴν Λυδίαν καὶ Φρυγίαν καὶ τὴν ἄλλην τὴν ὑπερκειμένην χώραν οἰκοῦντας ἐπὶ τοῖς ἐντεῦθεν ὁρμωμένοις εἶναι.", "st": "4.163"}, {"sp": "N", "t": "διὸ δεῖ σπεύδειν καὶ μηδεμίαν ποιεῖσθαι διατριβήν, ἵνα μὴ πάθωμεν ὅπερ οἱ πατέρες ἡμῶν. ἐκεῖνοι γὰρ ὑστερίσαντες τῶν βαρβάρων καὶ προέμενοί τινας τῶν συμμάχων ἠναγκάσθησαν ὀλίγοι πρὸς πολλοὺς κινδυνεύειν, ἐξὸν αὐτοῖς προτέροις διαβᾶσιν εἰς τὴν ἤπειρον μετὰ πάσης τῆς τῶν Ἑλλήνων δυνάμεως ἐν μέρει τῶν ἐθνῶν ἕκαστον χειροῦσθαι.", "st": "4.164"}, {"sp": "N", "t": "δέδεικται γὰρ, ὅταν τις πολεμῇ πρὸς ἀνθρώπους ἐκ πολλῶν τόπων συλλεγομένους, ὅτι δεῖ μὴ περιμένειν ἕως ἂν ἐπιστῶσιν, ἀλλ’ ἔτι διεσπαρμένοις αὐτοῖς ἐπιχειρεῖν. ἐκεῖνοι μὲν οὖν προεξαμαρτόντες ἅπαντα ταῦτ’ ἐπηνωρθώσαντο, καταστάντες εἰς τοὺς μεγίστους ἀγῶνας· ἡμεῖς δ’ ἂν σωφρονῶμεν, ἐξ ἀρχῆς φυλαξόμεθα, καὶ πειρασόμεθα φθῆναι περὶ τὴν Λυδίαν καὶ τὴν Ἰωνίαν στρατόπεδον ἐγκαταστήσαντες,", "st": "4.165"}, {"sp": "N", "t": "εἰδότες ὅτι καὶ βασιλεὺς οὐχ ἑκόντων ἄρχει τῶν ἠπειρωτῶν, ἀλλὰ μείζω δύναμιν περὶ αὑτὸν ἑκάστων αὐτῶν ποιησάμενος· ἧς ἡμεῖς ὅταν κρείττω διαβιβάσωμεν, ὃ βουληθέντες ῥᾳδίως ἂν ποιήσαιμεν, ἀσφαλῶς ἅπασαν τὴν Ἀσίαν καρπωσόμεθα. πολὺ δὲ κάλλιον ἐκείνῳ περὶ τῆς βασιλείας πολεμεῖν, ἢ πρὸς ἡμᾶς αὐτοὺς περὶ τῆς ἡγεμονίας ἀμφισβητεῖν.", "st": "4.166"}, {"sp": "N", "t": "ἄξιον δ’ ἐπὶ τῆς νῦν ἡλικίας ποιήσασθαι τὴν στρατείαν, ἵν’ οἱ τῶν συμφορῶν κοινωνήσαντες, οὗτοι καὶ τῶν ἀγαθῶν ἀπολαύσωσι καὶ μὴ πάντα τὸν χρόνον δυστυχοῦντες διαγάγωσιν. ἱκανὸς γὰρ ὁ παρεληλυθώς, ἐν ᾧ τί τῶν δεινῶν οὐ γέγονεν; πολλῶν γὰρ κακῶν τῇ φύσει τῇ τῶν ἀνθρώπων ὑπαρχόντων αὐτοὶ πλείω τῶν ἀναγκαίων προσεξευρήκαμεν, πολέμους καὶ στάσεις ἡμῖν αὐτοῖς ἐμποιήσαντες,", "st": "4.167"}, {"sp": "N", "t": "ὥστε τοὺς μὲν ἐν ταῖς αὑτῶν ἀνόμως ἀπόλλυσθαι, τοὺς δ’ ἐπὶ ξένης μετὰ παίδων καὶ γυναικῶν ἀλᾶσθαι, πολλοὺς δὲ δι’ ἔνδειαν τῶν καθ’ ἡμέραν ἐπικουρεῖν ἀναγκαζομένους ὑπὲρ τῶν ἐχθρῶν τοῖς φίλοις μαχομένους ἀποθνήσκειν. ὑπὲρ ὧν οὐδεὶς πώποτ’ ἠγανάκτησεν, ἀλλ’ ἐπὶ μὲν ταῖς συμφοραῖς ταῖς ὑπὸ τῶν ποιητῶν συγκειμέναις δακρύειν ἀξιοῦσιν, ἀληθινὰ δὲ πάθη πολλὰ καὶ δεινὰ γιγνόμενα διὰ τὸν πόλεμον ἐφορῶντες τοσούτου δέουσιν ἐλεεῖν, ὥστε καὶ μᾶλλον χαίρουσιν ἐπὶ τοῖς ἀλλήλων κακοῖς ἢ τοῖς αὑτῶν ἰδίοις ἀγαθοῖς.", "st": "4.168"}, {"sp": "N", "t": "ἴσως δ’ ἂν καὶ τῆς ἐμῆς εὐηθείας πολλοὶ καταγελάσειαν, εἰ δυστυχίας ἀνδρῶν ὀδυροίμην ἐν τοῖς τοιούτοις καιροῖς, ἐν οἷς Ἰταλία μὲν ἀνάστατος γέγονε, Σικελία δὲ καταδεδούλωται, τοσαῦται δὲ πόλεις τοῖς βαρβάροις ἐκδέδονται, τὰ δὲ λοιπὰ μέρη τῶν Ἑλλήνων ἐν τοῖς μεγίστοις κινδύνοις ἐστίν.", "st": "4.169"}, {"sp": "N", "t": "θαυμάζω δὲ τῶν δυναστευόντων ἐν ταῖς πόλεσιν, εἰ προσήκειν αὑτοῖς ἡγοῦνται μέγα φρονεῖν, μηδὲν πώποθ’ ὑπὲρ τηλικούτων πραγμάτων μήτ’ εἰπεῖν μήτ’ ἐνθυμηθῆναι δυνηθέντες. ἐχρῆν γὰρ αὐτούς, εἴπερ ἦσαν ἄξιοι τῆς παρούσης δόξης, ἁπάντων ἀφεμένους τῶν ἄλλων περὶ τοῦ πολέμου τοῦ πρὸς τοὺς βαρβάρους εἰσηγεῖσθαι καὶ συμβουλεύειν.", "st": "4.170"}, {"sp": "N", "t": "τυχὸν μὲν γὰρ ἄν τι συνεπέραναν· εἰ δὲ καὶ προαπεῖπον, ἀλλ’ οὖν τούς γε λόγους ὥσπερ χρησμοὺς εἰς τὸν ἐπιόντα χρόνον ἂν κατέλιπον. νῦν δ’ οἱ μὲν ἐν ταῖς μεγίσταις δόξαις ὄντες ἐπὶ μικροῖς σπουδάζουσιν, ἡμῖν δὲ τοῖς τῶν πολιτικῶν ἐξεστηκόσι περὶ τηλικούτων πραγμάτων συμβουλεύειν παραλελοίπασιν.", "st": "4.171"}, {"sp": "N", "t": "οὐ μὴν ἀλλ’ ὅσῳ μικροψυχότεροι τυγχάνουσιν ὄντες οἱ προεστῶτες ἡμῶν, τοσούτῳ τοὺς ἄλλους ἐρρωμενεστέρως δεῖ σκοπεῖν ὅπως ἀπαλλαγησόμεθα τῆς παρούσης ἔχθρας. νῦν μὲν γὰρ μάτην ποιούμεθα τὰς περὶ τῆς εἰρήνης συνθήκας· οὐ γὰρ διαλυόμεθα τοὺς πολέμους ἀλλ’ ἀναβαλλόμεθα, καὶ περιμένομεν τοὺς καιροὺς ἐν οἷς ἀνήκεστόν τι κακὸν ἀλλήλους ἐργάσασθαι δυνησόμεθα.", "st": "4.172"}, {"sp": "N", "t": "δεῖ δὲ ταύτας τὰς ἐπιβουλὰς ἐκποδὼν ποιησαμένους ἐκείνοις τοῖς ἔργοις ἐπιχειρεῖν, ἐξ ὧν τάς τε πόλεις ἀσφαλέστερον οἰκήσομεν καὶ πιστότερον διακεισόμεθα πρὸς ἡμᾶς αὐτούς. ἔστι δ’ ἁπλοῦς καὶ ῥᾴδιος ὁ λόγος ὁ περὶ τούτων· οὔτε γὰρ εἰρήνην οἷόν τε βεβαίαν ἀγαγεῖν, ἢν μὴ κοινῇ τοῖς βαρβάροις πολεμήσωμεν, οὔθ’ ὁμονοῆσαι τοὺς Ἕλληνας, πρὶν ἂν καὶ τὰς ὠφελίας ἐκ τῶν αὐτῶν καὶ τοὺς κινδύνους πρὸς τοὺς αὐτοὺς ποιησώμεθα.", "st": "4.173"}, {"sp": "N", "t": "τούτων δὲ γενομένων, καὶ τῆς ἀπορίας τῆς περὶ τὸν βίον ἡμῶν ἀφαιρεθείσης, ἣ καὶ τὰς ἑταιρίας διαλύει καὶ τὰς συγγενείας εἰς ἔχθραν προάγει καὶ πάντας ἀνθρώπους εἰς πολέμους καὶ στάσεις καθίστησιν, οὐκ ἔστιν ὅπως οὐχ ὁμονοήσομεν καὶ τὰς εὐνοίας ἀληθινὰς πρὸς ἡμᾶς αὐτοὺς ἕξομεν. ὧν ἕνεκα περὶ παντὸς ποιητέον ὅπως ὡς τάχιστα τὸν ἐνθένδε πόλεμον εἰς τὴν ἤπειρον διοριοῦμεν, ὡς μόνον ἂν τοῦτ’ ἀγαθὸν ἀπολαύσαιμεν τῶν κινδύνων τῶν πρὸς ἡμᾶς αὐτούς, εἰ ταῖς ἐμπειρίαις ταῖς ἐκ τούτων γεγενημέναις πρὸς τὸν βάρβαρον καταχρήσασθαι δόξειεν ἡμῖν.", "st": "4.174"}, {"sp": "N", "t": "ἀλλὰ γὰρ ἴσως διὰ τὰς συνθήκας ἄξιον ἐπισχεῖν, ἀλλ’ οὐκ ἐπειχθῆναι καὶ θᾶττον ποιήσασθαι τὴν στρατείαν; δι’ ἃς αἱ μὲν ἠλευθερωμέναι τῶν πόλεων βασιλεῖ χάριν ἴσασιν, ὡς δι’ ἐκεῖνον τυχοῦσαι τῆς αὐτονομίας ταύτης, αἱ δ’ ἐκδεδομέναι τοῖς βαρβάροις μάλιστα μὲν Λακεδαιμονίοις ἐπικαλοῦσιν, ἔπειτα δὲ καὶ τοῖς ἄλλοις τοῖς μετασχοῦσι τῆς εἰρήνης, ὡς ὑπὸ τούτων δουλεύειν ἠναγκασμέναι. καίτοι πῶς οὐ χρὴ διαλύειν ταύτας τὰς ὁμολογίας, ἐξ ὧν τοιαύτη δόξα γέγονεν, ὡς ὁ μὲν βάρβαρος κήδεται τῆς Ἑλλάδος καὶ φύλαξ τῆς εἰρήνης ἐστίν, ἡμῶν δέ τινές εἰσιν οἱ λυμαινόμενοι καὶ κακῶς ποιοῦντες αὐτήν;", "st": "4.175"}, {"sp": "N", "t": "ὃ δὲ πάντων καταγελαστότατον, ὅτι τῶν γεγραμμένων ἐν ταῖς ὁμολογίαις τὰ χείριστα τυγχάνομεν διαφυλάττοντες. ἃ μὲν γὰρ αὐτονόμους ἀφίησι τάς τε νήσους καὶ τὰς πόλεις τὰς ἐπὶ τῆς Εὐρώπης, πάλαι λέλυται καὶ μάτην ἐν ταῖς στήλαις ἐστίν· ἃ δ’ αἰσχύνην ἡμῖν φέρει καὶ πολλοὺς τῶν συμμάχων ἐκδέδωκε, ταῦτα δὲ κατὰ χώραν μένει καὶ πάντες αὐτὰ κύρια ποιοῦμεν· ἃ χρῆν ἀναιρεῖν καὶ μηδὲ μίαν ἐᾶν ἡμέραν, νομίζοντας προστάγματα καὶ μὴ συνθήκας εἶναι. τίς γὰρ οὐκ οἶδεν ὅτι συνθῆκαι μέν εἰσιν, αἵ τινες ἂν ἴσως καὶ κοινῶς ἀμφοτέροις ἔχωσι, προστάγματα δὲ τὰ τοὺς ἑτέρους ἐλαττοῦντα παρὰ τὸ δίκαιον;", "st": "4.176"}, {"sp": "N", "t": "διὸ καὶ τῶν πρεσβευσάντων ταύτην τὴν εἰρήνην δικαίως ἂν κατηγοροῖμεν, ὅτι πεμφθέντες ὑπὸ τῶν Ἑλλήνων ὑπὲρ τῶν βαρβάρων ἐποιήσαντο τὰς συνθήκας. ἐχρῆν γὰρ αὐτούς, εἴτ’ ἐδόκει τὴν αὑτῶν ἔχειν ἑκάστους, εἴτε καὶ τῶν δοριαλώτων ἐπάρχειν, εἴτε τούτων κρατεῖν ὧν ὑπὸ τὴν εἰρήνην ἐτυγχάνομεν ἔχοντες, ἕν τι τούτων ὁρισαμένους καὶ κοινὸν τὸ δίκαιον ποιησαμένους, οὕτω συγγράφεσθαι περὶ αὐτῶν.", "st": "4.177"}, {"sp": "N", "t": "νῦν δὲ τῇ μὲν ἡμετέρᾳ πόλει καὶ τῇ Λακεδαιμονίων οὐδεμίαν τιμὴν ἀπένειμαν, τὸν δὲ βάρβαρον ἁπάσης τῆς Ἀσίας δεσπότην κατέστησαν, ὥσπερ ὑπὲρ ἐκείνου πολεμησάντων, ἡμῶν, ἢ τῆς μὲν Περσῶν ἀρχῆς πάλαι καθεστηκυίας ἡμῶν δ’ ἄρτι τὰς πόλεις κατοικούντων, ἀλλ’ οὐκ ἐκείνων μὲν νεωστὶ ταύτην τὴν ἐχόντων, ἡμῶν δὲ τὸν ἅπαντα χρόνον ἐν τοῖς Ἕλλησι δυναστευόντων.", "st": "4.178"}, {"sp": "N", "t": "οἶμαι δ’ ἐκείνως εἰπὼν μᾶλλον δηλώσειν τήν τε περὶ ἡμᾶς ἀτιμίαν γεγενημένην καὶ τὴν τοῦ βασιλέως πλεονεξίαν. τῆς γὰρ γῆς ἁπάσης τῆς ὑπὸ τῷ κόσμῳ κειμένης δίχα τετμημένης, καὶ τῆς μὲν Ἀσίας τῆς δ’ Εὐρώπης καλουμένης, τὴν ἡμίσειαν ἐκ τῶν συνθηκῶν εἴληφεν, ὥσπερ πρὸς τὸν Δία τὴν χώραν νεμόμενος, ἀλλ’ οὐ πρὸς ἀνθρώπους τὰς συνθήκας ποιούμενος.", "st": "4.179"}, {"sp": "N", "t": "καὶ ταύτας ἡμᾶς ἠνάγκασεν ἐν στήλαις λιθίναις ἀναγράψαντας ἐν τοῖς κοινοῖς τῶν ἱερῶν καταθεῖναι, πολὺ κάλλιον τρόπαιον τῶν ἐν ταῖς μάχαις γιγνομένων· τὰ μὲν γὰρ ὑπὲρ μικρῶν ἔργων καὶ μιᾶς τύχης ἐστίν, αὗται δ’ ὑπὲρ ἅπαντος τοῦ πολέμου καὶ καθ’ ὅλης τῆς Ἑλλάδος ἑστήκασιν.", "st": "4.180"}, {"sp": "N", "t": "ὑπὲρ ὧν ἄξιον ὀργίζεσθαι, καὶ σκοπεῖν ὅπως τῶν τε γεγενημένων δίκην ληψόμεθα καὶ τὰ μέλλοντα διορθωσόμεθα. καὶ γὰρ αἰσχρὸν ἰδίᾳ μὲν τοῖς βαρβάροις οἰκέταις ἀξιοῦν χρῆσθαι, δημοσίᾳ δὲ τοσούτους τῶν συμμάχων περιορᾶν αὐτοῖς δουλεύοντας, καὶ τοὺς μὲν περὶ τὰ Τρωικὰ γενομένους μιᾶς γυναικὸς ἁρπασθείσης οὕτως ἅπαντας συνοργισθῆναι τοῖς ἀδικηθεῖσιν, ὥστε μὴ πρότερον παύσασθαι πολεμοῦντας πρὶν τὴν πόλιν ἀνάστατον ἐποίησαν τοῦ τολμήσαντος ἐξαμαρτεῖν,", "st": "4.181"}, {"sp": "N", "t": "ἡμᾶς δ’ ὅλης τῆς Ἑλλάδος ὑβριζομένης μηδεμίαν ποιήσασθαι κοινὴν τιμωρίαν, ἐξὸν ἡμῖν εὐχῆς ἄξια διαπράξασθαι. μόνος γὰρ οὗτος ὁ πόλεμος εἰρήνης κρείττων ἐστί, θεωρίᾳ μὲν μᾶλλον ἢ στρατείᾳ προσεοικώς, ἀμφοτέροις δὲ συμφέρων, καὶ τοῖς ἡσυχίαν ἄγειν καὶ τοῖς πολεμεῖν ἐπιθυμοῦσιν. εἴη γὰρ ἂν τοῖς μὲν ἀδεῶς τὰ σφέτερ’ αὐτῶν καρποῦσθαι, τοῖς δ’ ἐκ τῶν ἀλλοτρίων μεγάλους πλούτους κατακτήσασθαι.", "st": "4.182"}, {"sp": "N", "t": "πολλαχῇ δ’ ἄν τις λογιζόμενος εὕροι ταύτας τὰς πράξεις μάλιστα λυσιτελούσας ἡμῖν. φέρε γάρ, πρὸς τίνας χρὴ πολεμεῖν τοὺς μηδεμιᾶς πλεονεξίας ἐπιθυμοῦντας ἀλλ’ αὐτὸ τὸ δίκαιον σκοποῦντας; οὐ πρὸς τοὺς καὶ πρότερον κακῶς τὴν Ἑλλάδα ποιήσαντας καὶ νῦν ἐπιβουλεύοντας καὶ πάντα τὸν χρόνον οὕτω πρὸς ἡμᾶς διακειμένους;", "st": "4.183"}, {"sp": "N", "t": "τίσι δὲ φθονεῖν εἰκός ἐστι τοὺς μὴ παντάπασιν ἀνάνδρως διακειμένους ἀλλὰ μετρίως τούτῳ τῷ πράγματι χρωμένους; οὐ τοῖς μείζους μὲν τὰς δυναστείας ἢ κατ’ ἀνθρώπους περιβεβλημένοις, ἐλάττονος δ’ ἀξίοις τῶν παρ’ ἡμῖν δυστυχούντων; ἐπὶ τίνας δὲ στρατεύειν προσήκει τοὺς ἅμα μὲν εὐσεβεῖν βουλομένους ἅμα δὲ τοῦ συμφέροντος ἐνθυμουμένους; οὐκ ἐπὶ τοὺς καὶ φύσει πολεμίους καὶ πατρικοὺς ἐχθρούς, καὶ πλεῖστα μὲν ἀγαθὰ κεκτημένους, ἥκιστα δ’ ὑπὲρ αὐτῶν ἀμύνεσθαι δυναμένους; οὐκοῦν ἐκεῖνοι πᾶσι τούτοις ἔνοχοι τυγχάνουσιν ὄντες.", "st": "4.184"}, {"sp": "N", "t": "καὶ μὴν οὐδὲ τὰς πόλεις λυπήσομεν στρατιώτας ἐξ αὐτῶν καταλέγοντες, ὃ νῦν ἐν τῷ πολέμῳ τῷ πρὸς ἀλλήλους ὀχληρότατόν ἐστιν αὐταῖς· πολὺ γὰρ οἶμαι σπανιωτέρους ἔσεσθαι τοὺς μένειν ἐθελήσοντας τῶν συνακολουθεῖν ἐπιθυμησόντων. τίς γὰρ οὕτως ἢ νέος ἢ παλαιὸς ῥᾴθυμός ἐστιν, ὅστις οὐ μετασχεῖν βουλήσεται ταύτης τῆς στρατιᾶς, τῆς ὑπ’ Ἀθηναίων μὲν καὶ Λακεδαιμονίων στρατηγουμένης, ὑπὲρ δὲ τῆς τῶν συμμάχων ἐλευθερίας ἀθροιζομένης, ὑπὸ δὲ τῆς Ἑλλάδος ἁπάσης ἐκπεμπομένης, ἐπὶ δὲ τὴν τῶν βαρβάρων τιμωρίαν πορευομένης;", "st": "4.185"}, {"sp": "N", "t": "φήμην δὲ καὶ μνήμην καὶ δόξαν πόσην τινὰ χρὴ νομίζειν ἢ ζῶντας ἕξειν ἢ τελευτήσαντας καταλείψειν τοὺς ἐν τοῖς τοιούτοις ἔργοις ἀριστεύσαντας; ὅπου γὰρ οἱ πρὸς Ἀλέξανδρον πολεμήσαντες καὶ μίαν πόλιν ἑλόντες τοιούτων ἐπαίνων ἠξιώθησαν, ποίων τινῶν χρὴ προσδοκᾶν ἐγκωμίων τεύξεσθαι τοὺς ὅλης τῆς Ἀσίας κρατήσαντας; τίς γὰρ ἢ τῶν ποιεῖν δυναμένων ἢ τῶν λέγειν ἐπισταμένων οὐ πονήσει καὶ φιλοσοφήσει βουλόμενος ἅμα τῆς θ’ αὑτοῦ διανοίας καὶ τῆς ἐκείνων ἀρετῆς μνημεῖον εἰς ἅπαντα τὸν χρόνον καταλιπεῖν;", "st": "4.186"}, {"sp": "N", "t": "οὐ τὴν αὐτὴν δὲ τυγχάνω γνώμην ἔχων ἔν τε τῷ παρόντι καὶ περὶ τὰς ἀρχὰς τοῦ λόγου. τότε μὲν γὰρ ᾤμην ἀξίως δυνήσεσθαι τῶν πραγμάτων εἰπεῖν· νῦν δ’ οὐκ ἐφικνοῦμαι τοῦ μεγέθους αὐτῶν, ἀλλὰ πολλά με διαπέφευγεν ὧν διενοήθην. αὐτοὺς οὖν χρὴ συνδιορᾶν ὅσης ἂν εὐδαιμονίας τύχοιμεν, εἰ τὸν μὲν πόλεμον τὸν νῦν ὄντα περὶ ἡμᾶς πρὸς τοὺς ἠπειρώτας ποιησαίμεθα, τὴν δ’ εὐδαιμονίαν τὴν ἐκ τῆς Ἀσίας εἰς τὴν Εὐρώπην διακομίσαιμεν, καὶ μὴ μόνον ἀκροατὰς γενομένους ἀπελθεῖν,", "st": "4.187"}, {"sp": "N", "t": "ἀλλὰ τοὺς μὲν πράττειν δυναμένους παρακαλοῦντας ἀλλήλους πειρᾶσθαι διαλλάττειν τήν τε πόλιν τὴν ἡμετέραν καὶ τὴν Λακεδαιμονίων, τοὺς δὲ τῶν λόγων ἀμφισβητοῦντας πρὸς μὲν τὴν παρακαταθήκην καὶ περὶ τῶν ἄλλων ὧν νῦν φλυαροῦσι παύεσθαι γράφοντας, πρὸς δὲ τοῦτον τὸν λόγον ποιεῖσθαι τὴν ἅμιλλαν, καὶ σκοπεῖν ὅπως ἄμεινον ἐμοῦ περὶ τῶν αὐτῶν πραγμάτων ἐροῦσιν,", "st": "4.188"}, {"sp": "N", "t": "ἐνθυμουμένους ὅτι τοῖς μεγάλ’ ὑπισχνουμένοις οὐ πρέπει περὶ μικρὰ διατρίβειν, οὐδὲ τοιαῦτα λέγειν ἐξ ὧν ὁ βίος μηδὲν ἐπιδώσει τῶν πεισθέντων, ἀλλ’ ὧν ἐπιτελεσθέντων αὐτοί τ’ ἀπαλλαγήσονται τῆς παρούσης ἀπορίας καὶ τοῖς ἄλλοις μεγάλων ἀγαθῶν αἴτιοι δόξουσιν εἶναι.", "st": "4.189"}, {"sp": "HDR", "t": "Φίλιππος", "st": "5"}, {"sp": "N", "t": "μὴ θαυμάσῃς, ὦ Φίλιππε, διότι τοῦ λόγου ποιήσομαι τὴν ἀρχὴν οὐ τοῦ πρὸς σὲ ῥηθησομένου καὶ νῦν δειχθήσεσθαι μέλλοντος, ἀλλὰ τοῦ περὶ Ἀμφιπόλεως γραφέντος. περὶ οὗ μικρὰ βούλομαι προειπεῖν, ἵνα δηλώσω καὶ σοὶ καὶ τοῖς ἄλλοις ὡς οὐ δι’ ἄνοιαν οὐδὲ διαψευσθεὶς τῆς ἀρρωστίας τῆς νῦν μοι παρούσης ἐπεθέμην γράφειν τὸν πρὸς σὲ λόγον, ἀλλ’ εἰκότως καὶ κατὰ μικρὸν ὑπαχθείς.", "st": "5.1"}, {"sp": "N", "t": "ὁρῶν γὰρ τὸν πόλεμον τὸν ἐνστάντα σοὶ καὶ τῇ πόλει περὶ Ἀμφιπόλεως πολλῶν κακῶν αἴτιον γιγνόμενον, ἐπεχείρησα λέγειν περί τε τῆς πόλεως ταύτης καὶ τῆς χώρας οὐδὲν τῶν αὐτῶν οὔτε τοῖς ὑπὸ τῶν σῶν ἑταίρων λεγομένοις οὔτε τοῖς ὑπὸ τῶν ῥητόρων τῶν παρ’ ἡμῖν, ἀλλ’ ὡς οἷόν τε πλεῖστον ἀφεστῶτα τῆς τούτων διανοίας.", "st": "5.2"}, {"sp": "N", "t": "οὗτοι μὲν γὰρ παρώξυνον ἐπὶ τὸν πόλεμον, συναγορεύοντες ταῖς ἐπιθυμίαις ὑμῶν· ἐγὼ δὲ περὶ μὲν τῶν ἀμφισβητουμένων οὐδὲν ἀπεφαινόμην, ὃν δ’ ὑπελάμβανον τῶν λόγων εἰρηνικώτατον εἶναι, περὶ τοῦτον διέτριβον, λέγων ὡς ἀμφότεροι διαμαρτάνετε τῶν πραγμάτων, καὶ σὺ μὲν πολεμεῖς ὑπὲρ τῶν ἡμῖν συμφερόντων, ἡ δὲ πόλις ὑπὲρ τῆς σῆς δυναστείας· λυσιτελεῖν γὰρ σοὶ μὲν ἡμᾶς ἔχειν τὴν χώραν ταύτην, τῇ δὲ πόλει μηδ’ ἐξ ἑνὸς τρόπου λαβεῖν αὐτήν.", "st": "5.3"}, {"sp": "N", "t": "καὶ περὶ τούτων οὕτως ἐδόκουν διεξιέναι τοῖς ἀκούουσιν, ὥστε μηδένα τὸν λόγον αὐτῶν μηδὲ τὴν λέξιν ἐπαινεῖν ὡς ἀκριβῶς καὶ καθαρῶς ἔχουσαν, ὅπερ εἰώθασί τινες ποιεῖν, ἀλλὰ τὴν ἀλήθειαν τῶν πραγμάτων θαυμάζειν, καὶ νομίζειν οὐδαμῶς ἂν ἄλλως παύσασθαι τῆς φιλονικίας ὑμᾶς,", "st": "5.4"}, {"sp": "N", "t": "πλὴν εἰ σὺ μὲν πεισθείης πλείονος ἀξίαν ἔσεσθαί σοι τὴν τῆς πόλεως φιλίαν ἢ τὰς προσόδους τὰς ἐξ Ἀμφιπόλεως γιγνομένας, ἡ δὲ πόλις δυνηθείη καταμαθεῖν ὡς χρὴ τὰς μὲν τοιαύτας φεύγειν ἀποικίας, αἵ τινες τετράκις ἢ πεντάκις ἀπολωλέκασι τοὺς ἐμπολιτευθέντας, ζητεῖν δ’ ἐκείνους τοὺς τόπους τοὺς πόρρω μὲν κειμένους τῶν ἄρχειν δυναμένων, ἐγγὺς δὲ τῶν δουλεύειν εἰθισμένων, εἰς οἷόν περ Λακεδαιμόνιοι Κυρηναίους ἀπῴκισαν·", "st": "5.5"}, {"sp": "N", "t": "πρὸς δὲ τούτοις, εἰ σὺ μὲν γνοίης ὅτι λόγῳ παραδοὺς τὴν χώραν ἡμῖν ταύτην αὐτὸς ἔργῳ κρατήσεις αὐτῆς, καὶ προσέτι τὴν εὔνοιαν τὴν ἡμετέραν κτήσει (τοσούτους γὰρ ὁμήρους λήψει παρ’ ἡμῶν τῆς φιλίας, ὅσους περ ἂν ἐποίκους εἰς τὴν σὴν δυναστείαν ἀποστείλωμεν), τὸ δὲ πλῆθος ἡμῶν εἴ τις διδάξειεν, ὡς ἂν λάβωμεν Ἀμφίπολιν, ἀναγκασθησόμεθα τὴν αὐτὴν εὔνοιαν ἔχειν τοῖς σοῖς πράγμασι διὰ τοὺς ἐνταῦθα κατοικοῦντας οἵαν περ εἴχομεν Ἀμαδόκῳ τῷ παλαιῷ διὰ τοὺς ἐν Χερρονήσῳ γεωργοῦντας.", "st": "5.6"}, {"sp": "N", "t": "τοιούτων δὲ πολλῶν λεγομένων ἤλπισαν ὅσοι περ ἤκουσαν, διαδοθέντος τοῦ λόγου διαλύσεσθαι τὸν πόλεμον ὑμᾶς καὶ γνωσιμαχήσαντας βουλεύσεσθαί τι κοινὸν ἀγαθὸν περὶ ὑμῶν αὐτῶν. εἰ μὲν οὖν ἀφρόνως ἢ καὶ νουνεχόντως ταῦτ’ ἐδόξαζον, δικαίως ἂν ἐκεῖνοι τὴν αἰτίαν ἔχοιεν· ὄντος δ’ οὖν ἐμοῦ περὶ τὴν πραγματείαν ταύτην ἔφθητε ποιησάμενοι τὴν εἰρήνην, πρὶν ἐξεργασθῆναι τὸν λόγον, σωφρονοῦντες· ὅπως γὰρ οὖν πεπρᾶχθαι κρεῖττον ἦν αὐτὴν ἢ συνέχεσθαι τοῖς κακοῖς τοῖς διὰ τὸν πόλεμον γιγνομένοις.", "st": "5.7"}, {"sp": "N", "t": "συνησθεὶς δὲ τοῖς περὶ τῆς εἰρήνης ψηφισθεῖσι, καὶ νομίσας οὐ μόνον ἡμῖν ἀλλὰ καὶ σοὶ καὶ τοῖς ἄλλοις Ἕλλησιν ἅπασι συνοίσειν, ἀποστῆσαι μὲν τὴν ἐμαυτοῦ διάνοιαν τῶν ἐχομένων οὐχ οἷός τ’ ἦν, ἀλλ’ οὕτω διεκείμην ὥστ’ εὐθὺς σκοπεῖσθαι πῶς ἂν τὰ πεπραγμένα παραμείνειεν ἡμῖν καὶ μὴ χρόνον ὀλίγον ἡ πόλις ἡμῶν διαλιποῦσα πάλιν ἑτέρων πολέμων ἐπιθυμήσειε·", "st": "5.8"}, {"sp": "N", "t": "διεξιὼν δὲ περὶ τούτων πρὸς ἐμαυτὸν εὕρισκον οὐδαμῶς ἂν ἄλλως αὐτὴν ἡσυχίαν ἄγουσαν, πλὴν εἰ δόξειε ταῖς πόλεσι ταῖς μεγίσταις διαλυσαμέναις τὰ πρὸς σφᾶς αὐτὰς εἰς τὴν Ἀσίαν τὸν πόλεμον ἐξενεγκεῖν, καὶ τὰς πλεονεξίας, ἃς νῦν παρὰ τῶν Ἑλλήνων ἀξιοῦσιν αὑταῖς γίγνεσθαι, ταύτας εἰ παρὰ τῶν βαρβάρων ποιήσασθαι βουληθεῖεν· ἅπερ ἐν τῷ πανηγυρικῷ λόγῳ τυγχάνω συμβεβουλευκώς.", "st": "5.9"}, {"sp": "N", "t": "ταῦτα δὲ διανοηθείς, καὶ νομίσας οὐδέποτ’ ἂν εὑρεθῆναι καλλίω ταύτης ὑπόθεσιν οὐδὲ κοινοτέραν οὐδὲ μᾶλλον ἅπασιν ἡμῖν συμφέρουσαν, ἐπήρθην πάλιν γράψαι περὶ αὐτῆς, οὐκ ἀγνοῶν οὐδὲν τῶν περὶ ἐμαυτόν, ἀλλ’ εἰδὼς μὲν τὸν λόγον τοῦτον οὐ τῆς ἡλικίας τῆς ἐμῆς δεόμενον, ἀλλ’ ἀνδρὸς ἀνθοῦσαν τὴν ἀκμὴν ἔχοντος καὶ τὴν φύσιν πολὺ τῶν ἄλλων διαφέροντος,", "st": "5.10"}, {"sp": "N", "t": "ὁρῶν δ’ ὅτι χαλεπόν ἐστι περὶ τὴν αὐτὴν ὑπόθεσιν δύο λόγους ἀνεκτῶς εἰπεῖν, ἄλλως τε κἂν ὁ πρότερον ἐκδοθεὶς οὕτως ᾖ γεγραμμένος, ὥστε καὶ τοὺς βασκαίνοντας ἡμᾶς μιμεῖσθαι καὶ θαυμάζειν αὐτὸν μᾶλλον τῶν καθ’ ὑπερβολὴν ἐπαινούντων.", "st": "5.11"}, {"sp": "N", "t": "ἀλλ’ ὅμως ἐγὼ ταύτας τὰς δυσχερείας ὑπεριδὼν οὕτως ἐπὶ γήρως γέγονα φιλότιμος, ὥστ’ ἠβουλήθην ἅμα τοῖς πρὸς σὲ λεγομένοις καὶ τοῖς μετ’ ἐμοῦ διατρίψασιν ὑποδεῖξαι καὶ ποιῆσαι φανερόν, ὅτι τὸ μὲν ταῖς πανηγύρεσιν ἐνοχλεῖν καὶ πρὸς ἅπαντας λέγειν τοὺς συντρέχοντας ἐν αὐταῖς πρὸς οὐδένα λέγειν ἐστίν, ἀλλ’ ὁμοίως οἱ τοιοῦτοι τῶν λόγων ἄκυροι τυγχάνουσιν ὄντες τοῖς νόμοις καὶ ταῖς πολιτείαις ταῖς ὑπὸ τῶν σοφιστῶν γεγραμμέναις,", "st": "5.12"}, {"sp": "N", "t": "δεῖ δὲ τοὺς βουλομένους μὴ μάτην φλυαρεῖν ἀλλὰ προὔργου τι ποιεῖν καὶ τοὺς οἰομένους ἀγαθόν τι κοινὸν εὑρηκέναι τοὺς μὲν ἄλλους ἐᾶν πανηγυρίζειν, αὐτοὺς δ’ ὧν εἰσηγοῦνται ποιήσασθαί τινα προστάτην τῶν καὶ λέγειν καὶ πράττειν δυναμένων καὶ δόξαν μεγάλην ἐχόντων, εἴπερ μέλλουσί τινες προσέξειν αὐτοῖς τὸν νοῦν.", "st": "5.13"}, {"sp": "N", "t": "ἅ περ ἐγὼ γνοὺς διαλεχθῆναι σοὶ προειλόμην,οὐ πρὸς χάριν ἐκλεξάμενος, — καίτοι πρὸ πολλοῦ ποιησαίμην ἄν σοι κεχαρισμένως εἰπεῖν, ἀλλ’ οὐκ ἐπὶ τούτῳ τὴν διάνοιαν ἔσχον. ἀλλὰ τοὺς μὲν ἄλλους ἑώρων τοὺς ἐνδόξους τῶν ἀνδρῶν ὑπὸ πόλεσι καὶ νόμοις οἰκοῦντας, καὶ οὐδὲν ἐξὸν αὐτοῖς ἄλλο πράττειν πλὴν τὸ προσταττόμενον, ἔτι δὲ πολὺ καταδεεστέρους ὄντας τῶν πραγμάτων τῶν ῥηθησομένων,", "st": "5.14"}, {"sp": "N", "t": "σοὶ δὲ μόνῳ πολλὴν ἐξουσίαν ὑπὸ τῆς τύχης δεδομένην καὶ πρέσβεις πέμπειν πρὸς οὕς τινας ἂν βουληθῇς, καὶ δέχεσθαι παρ’ ὧν ἄν σοι δοκῇ, καὶ λέγειν ὅ τι ἂν ἡγῇ συμφέρειν, πρὸς δὲ τούτοις καὶ πλοῦτον καὶ δύναμιν κεκτημένον ὅσην οὐδεὶς τῶν Ἑλλήνων, ἃ μόνα τῶν ὄντων καὶ πείθειν καὶ βιάζεσθαι πέφυκεν· ὧν οἶμαι καὶ τὰ ῥηθησόμενα προσδεήσεσθαι.", "st": "5.15"}, {"sp": "N", "t": "μέλλω γάρ σοι συμβουλεύειν προστῆναι τῆς τε τῶν Ἑλλήνων ὁμονοίας καὶ τῆς ἐπὶ τοὺς βαρβάρους στρατείας· ἔστι δὲ τὸ μὲν πείθειν πρὸς τοὺς Ἕλληνας συμφέρον, τὸ δὲ βιάζεσθαι πρὸς τοὺς βαρβάρους χρήσιμον. ἡ μὲν οὖν περιβολὴ παντὸς τοῦ λόγου τοιαύτη τίς ἐστιν.", "st": "5.16"}, {"sp": "N", "t": "οὐκ ὀκνήσω δὲ πρὸς σὲ κατειπεῖν ἐφ’ οἷς ἐλύπησάν τινές με τῶν πλησιασάντων· οἶμαι γὰρ ἔσεσθαί τι προὔργου. δηλώσαντος γάρ μου πρὸς αὐτοὺς ὅτι μέλλω σοι λόγον πέμπειν οὐκ ἐπίδειξιν ποιησόμενον οὐδ’ ἐγκωμιασόμενον τοὺς πολέμους τοὺς διὰ σοῦ γεγενημένους (ἕτεροι γὰρ τοῦτο ποιήσουσιν), ἀλλὰ πειρασόμενόν σε προτρέπειν ἐπὶ πράξεις οἰκειοτέρας καὶ καλλίους καὶ μᾶλλον συμφερούσας ὧν νῦν τυγχάνεις προῃρημένος,", "st": "5.17"}, {"sp": "N", "t": "οὕτως ἐξεπλάγησαν μὴ διὰ τὸ γῆρας ἐξεστηκὼς ὦ τοῦ φρονεῖν, ὥστ’ ἐτόλμησαν ἐπιπλῆξαί μοι, πρότερον οὐκ εἰωθότες τοῦτο ποιεῖν, λέγοντες ὡς ἀτόποις καὶ λίαν ἀνοήτοις ἐπιχειρῶ πράγμασιν, “ὅς τις Φιλίππῳ συμβουλεύσοντα λόγον μέλλεις πέμπειν, ὃς εἰ καὶ πρότερον ἐνόμιζεν αὑτὸν εἶναί τινος πρὸς τὸ φρονεῖν καταδεέστερον, νῦν διὰ τὸ μέγεθος τῶν συμβεβηκότων οὐκ ἔστιν ὅπως οὐκ οἴεται βέλτιον δύνασθαι βουλεύεσθαι τῶν ἄλλων.", "st": "5.18"}, {"sp": "N", "t": "ἔπειτα καὶ Μακεδόνων ἔχει περὶ αὑτὸν τοὺς σπουδαιοτάτους, οὓς εἰκός, εἰ καὶ περὶ τῶν ἄλλων ἀπείρως ἔχουσι, τό γε συμφέρον ἐκείνῳ μᾶλλον ἢ σὲ γιγνώσκειν. ἔτι δὲ καὶ τῶν Ἑλλήνων πολλοὺς ἂν ἴδοις ἐκεῖ κατοικοῦντας, οὐκ ἀδόξους ἄνδρας οὐδ’ ἀνοήτους, ἀλλ’ οἷς ἐκεῖνος ἀνακοινούμενος οὐκ ἐλάττω τὴν βασιλείαν πεποίηκεν ἀλλ’ εὐχῆς ἄξια διαπέπρακται.", "st": "5.19"}, {"sp": "N", "t": "τί γὰρ ἐλλέλοιπεν; οὐ Θετταλοὺς μὲν τοὺς πρότερον ἐνάρχοντας Μακεδονίας οὕτως οἰκείως πρὸς αὑτὸν διακεῖσθαι πεποίηκεν, ὥσθ’ ἑκάστους αὐτῶν μᾶλλον ἐκείνῳ πιστεύειν ἢ τοῖς συμπολιτευομένοις; τῶν δὲ πόλεων τῶν περὶ τὸν τόπον ἐκεῖνον τὰς μὲν ταῖς εὐεργεσίαις πρὸς τὴν αὑτοῦ συμμαχίαν προσῆκται, τὰς δὲ σφόδρα λυπούσας αὐτὸν ἀναστάτους πεποίηκεν;", "st": "5.20"}, {"sp": "N", "t": "Μάγνητας δὲ καὶ Περραιβοὺς καὶ Παίονας κατέστραπται, καὶ πάντας ὑπηκόους αὐτοὺς εἴληφεν; τοῦ δ’ Ἰλλυριῶν πλήθους πλὴν τῶν παρὰ τὸν Ἀδρίαν οἰκούντων ἐγκρατὴς καὶ κύριος γέγονεν; ἁπάσης δὲ τῆς Θρᾴκης οὓς ἠβουλήθη δεσπότας κατέστησεν; τὸν δὴ τοιαῦτα καὶ τηλικαῦτα διαπεπραγμένον οὐκ οἴει πολλὴν μωρίαν καταγνώσεσθαι τοῦ πέμψαντος τὸ βιβλίον, καὶ πολὺ διεψεῦσθαι νομιεῖν τῆς τε τῶν λόγων δυνάμεως καὶ τῆς αὑτοῦ διανοίας;”", "st": "5.21"}, {"sp": "N", "t": "ταῦτ’ ἀκούσας ὡς μὲν τὸ πρῶτον ἐξεπλάγην, καὶ πάλιν ὡς ἀναλαβὼν ἐμαυτὸν ἀντεῖπον πρὸς ἕκαστον τῶν ῥηθέντων, παραλείψω, μὴ καὶ δόξω τισὶ λίαν ἀγαπᾶν, εἰ χαριέντως αὐτοὺς ἠμυνάμην· λυπήσας δ’ οὖν μετρίως (ὡς ἐμαυτὸν ἔπειθον) τοὺς ἐπιπλῆξαί μοι τολμήσαντας, τελευτῶν ὑπεσχόμην μόνοις αὐτοῖς τὸν λόγον τῶν ἐν τῇ πόλει δείξειν, καὶ ποιήσειν οὐδὲν ἄλλο περὶ αὐτοῦ πλὴν ὅ τι ἂν ἐκείνοις δόξῃ.", "st": "5.22"}, {"sp": "N", "t": "τούτων ἀκούσαντες ἀπῆλθον, οὐκ οἶδ’ ὅπως τὴν διάνοιαν ἔχοντες. πλὴν οὐ πολλαῖς ἡμέραις ὕστερον ἐπιτελεσθέντος τοῦ λόγου καὶ δειχθέντος αὐτοῖς τοσοῦτον μετέπεσον, ὥστ’ ᾐσχύνοντο μὲν ἐφ’ οἷς ἐθρασύναντο, μετέμελε δ’ αὐτοῖς ἁπάντων τῶν εἰρημένων, ὡμολόγουν δὲ μηδενὸς πώποτε τοσοῦτον πράγματος διαμαρτεῖν, ἔσπευδον δὲ μᾶλλον ἢ ’γὼ πεμφθῆναί σοι τὸν λόγον τοῦτον, ἔλεγον δ’ ὡς ἐλπίζουσιν οὐ μόνον σὲ καὶ τὴν πόλιν ἕξειν μοι χάριν ὑπὲρ τῶν εἰρημένων, ἀλλὰ καὶ τοὺς Ἕλληνας ἅπαντας.", "st": "5.23"}, {"sp": "N", "t": "τούτου δ’ ἕνεκά σοι ταῦτα διῆλθον, ἵν’ ἄν τί σοι φανῇ τῶν ἐν ἀρχῇ λεγομένων ἢ μὴ πιστὸν ἢ μὴ δυνατὸν ἢ μὴ πρέπον σοι πράττειν, μὴ δυσχεράνας ἀποστῇς τῶν λοιπῶν, μηδὲ πάθῃς ταὐτὸ τοῖς ἐπιτηδείοις τοῖς ἐμοῖς, ἀλλ’ ἐπιμείνῃς ἡσυχάζουσαν ἔχων τὴν διάνοιαν, ἕως ἂν διὰ τέλους ἀκούσῃς ἁπάντων τῶν λεγομένων. οἶμαι γὰρ ἐρεῖν τι τῶν δεόντων καὶ τῶν σοὶ συμφερόντων.", "st": "5.24"}, {"sp": "N", "t": "καίτοι μ’ οὐ λέληθεν ὅσον διαφέρουσι τῶν λόγων εἰς τὸ πείθειν οἱ λεγόμενοι τῶν ἀναγιγνωσκομένων, οὐδ’ ὅτι πάντες ὑπειλήφασι τοὺς μὲν περὶ σπουδαίων πραγμάτων καὶ κατεπειγόντων ῥητορεύεσθαι, τοὺς δὲ πρὸς ἐπίδειξιν καὶ πρὸς ἐργολαβίαν γεγράφθαι.", "st": "5.25"}, {"sp": "N", "t": "καὶ ταῦτ’ οὐκ ἀλόγως ἐγνώκασιν· ἐπειδὰν γὰρ ὁ λόγος ἀποστερηθῇ τῆς τε δόξης τῆς τοῦ λέγοντος καὶ τῆς φωνῆς καὶ τῶν μεταβολῶν τῶν ἐν ταῖς ῥητορείαις γιγνομένων, ἔτι δὲ τῶν καιρῶν καὶ τῆς σπουδῆς τῆς περὶ τὴν πρᾶξιν, καὶ μηδὲν ᾖ τὸ συναγωνιζόμενον καὶ συμπεῖθον, ἀλλὰ τῶν μὲν προειρημένων ἁπάντων ἔρημος γένηται καὶ γυμνός, ἀναγιγνώσκῃ δέ τις αὐτὸν ἀπιθάνως καὶ μηδὲν ἦθος ἐνσημαινόμενος ἀλλ’ ὥσπερ ἀπαριθμῶν,", "st": "5.26"}, {"sp": "N", "t": "εἰκότως, οἶμαι, φαῦλος εἶναι δοκεῖ τοῖς ἀκούουσιν, ἅπερ καὶ τὸν νῦν ἐπιδεικνύμενον μάλιστ’ ἂν βλάψειε καὶ φαυλότερον· φαίνεσθαι ποιήσειεν· οὐδὲ γὰρ ταῖς περὶ τὴν λέξιν εὐρυθμίαις καὶ ποικιλίαις κεκοσμήκαμεν αὐτόν, αἷς αὐτός τε νεώτερος ὢν ἐχρώμην, καὶ τοῖς ἄλλοις ὑπέδειξα δι’ ὧν τοὺς λόγους ἡδίους ἂν ἅμα καὶ πιστοτέρους ποιοῖεν.", "st": "5.27"}, {"sp": "N", "t": "ὧν οὐδὲν ἔτι δύναμαι διὰ τὴν ἡλικίαν, ἀλλ’ ἀπόχρη μοι τοσοῦτον, ἢν αὐτὰς τὰς πράξεις ἁπλῶς δυνηθῶ διελθεῖν. ἡγοῦμαι δὲ καὶ σοὶ προσήκειν ἁπάντων τῶν ἄλλων ἀμελήσαντι ταύταις μόναις προσέχειν τὸν νοῦν. οὕτω δ’ ἂν ἀκριβέστατα καὶ κάλλιστα θεωρήσειας εἴ τι τυγχάνομεν λέγοντες,", "st": "5.28"}, {"sp": "N", "t": "ἢν τὰς μὲν δυσχερείας τὰς περὶ τοὺς σοφιστὰς καὶ τοὺς ἀναγιγνωσκομένους τῶν λόγων ἀφέλῃς, ἀναλαμβάνων δ’ ἕκαστον αὐτῶν εἰς τὴν διάνοιαν ἐξετάζῃς, μὴ πάρεργον ποιούμενος μηδὲ μετὰ ῥᾳθυμίας, ἀλλὰ μετὰ λογισμοῦ καὶ φιλοσοφίας, ἧς καὶ σὲ μετεσχηκέναι φασίν. μετὰ γὰρ τούτων σκοπούμενος μᾶλλον ἢ μετὰ τῆς τῶν πολλῶν δόξης ἄμεινον ἂν βουλεύσαιο περὶ αὐτῶν.", "st": "5.29"}, {"sp": "N", "t": "ἃ μὲν οὖν ἐβουλόμην σοι προειρῆσθαι, ταῦτ’ ἐστίν. περὶ δ’ αὐτῶν τῶν πραγμάτων ἤδη ποιήσομαι τοὺς λόγους. φημὶ γὰρ χρῆναί σε τῶν μὲν ἰδίων μηδενὸς ἀμελῆσαι, πειραθῆναι δὲ διαλλάξαι τήν τε πόλιν τὴν Ἀργείων καὶ τὴν Λακεδαιμονίων καὶ τὴν Θηβαίων καὶ τὴν ἡμετέραν. ἢν γὰρ ταύτας συστῆσαι δυνηθῇς, οὐ χαλεπῶς καὶ τὰς ἄλλας ὁμονοεῖν ποιήσεις·", "st": "5.30"}, {"sp": "N", "t": "ἅπασαι γάρ εἰσιν ὑπὸ ταῖς εἰρημέναις, καὶ καταφεύγουσιν, ὅταν φοβηθῶσιν, ἐφ’ ἣν ἂν τύχωσι τούτων, καὶ τὰς βοηθείας ἐντεῦθεν λαμβάνουσιν. ὥστ’ ἐὰν τέτταρας μόνον πόλεις εὖ φρονεῖν πείσῃς, καὶ τὰς ἄλλας πολλῶν κακῶν ἀπαλλάξεις.", "st": "5.31"}, {"sp": "N", "t": "γνοίης δ’ ἂν ὡς οὐδεμιᾶς σοι προσήκει τούτων ὀλιγωρεῖν, ἢν ἀνενέγκῃς αὐτῶν τὰς πράξεις ἐπὶ τοὺς σοὺς προγόνους· εὑρήσεις γὰρ ἑκάστῃ πολλὴν φιλίαν πρὸς ὑμᾶς καὶ μεγάλας εὐεργεσίας ὑπαρχούσας. Ἄργος μὲν γάρ ἐστί σοι πατρίς, ἧς δίκαιον τοσαύτην σε ποιεῖσθαι πρόνοιαν ὅσην περ τῶν γονέων τῶν σαυτοῦ· Θηβαῖοι δὲ τὸν ἀρχηγὸν τοῦ γένους ὑμῶν τιμῶσι καὶ ταῖς προσόδοις καὶ ταῖς θυσίαις μᾶλλον ἢ τοὺς θεοὺς τοὺς ἄλλους·", "st": "5.32"}, {"sp": "N", "t": "Λακεδαιμόνιοι δὲ τοῖς ἀπ’ ἐκείνου γεγονόσι καὶ τὴν βασιλείαν καὶ τὴν ἡγεμονίαν εἰς ἅπαντα τὸν χρόνον δεδώκασι· τὴν δὲ πόλιν τὴν ἡμετέραν φασίν, οἷς περὶ τῶν παλαιῶν πιστεύομεν, Ἡρακλεῖ μὲν συναιτίαν γενέσθαι τῆς ἀθανασίας (ὃν δὲ τρόπον, σοὶ μὲν αὖθις πυθέσθαι ῥᾴδιον, ἐμοὶ δὲ νῦν εἰπεῖν οὐ καιρός), τοῖς δὲ παισὶ τοῖς ἐκείνου τῆς σωτηρίας.", "st": "5.33"}, {"sp": "N", "t": "μόνη γὰρ ὑποστᾶσα τοὺς μεγίστους κινδύνους πρὸς τὴν Εὐρυσθέως δύναμιν ἐκεῖνόν τε τῆς ὕβρεως ἔπαυσε, καὶ τοὺς παῖδας τῶν φόβων τῶν ἀεὶ παραγιγνομένων αὐτοῖς ἀπήλλαξεν. ὑπὲρ ὧν οὐ μόνον τοὺς τότε σωθέντας δίκαιον ἦν ἡμῖν χάριν ἔχειν, ἀλλὰ καὶ τοὺς νῦν ὄντας· διὰ γὰρ ἡμᾶς καὶ ζῶσι καὶ τῶν ὑπαρχόντων ἀγαθῶν ἀπολαύουσι· μὴ γὰρ σωθέντων ἐκείνων οὐδὲ γενέσθαι τὸ παράπαν ὑπῆρχεν αὐτοῖς.", "st": "5.34"}, {"sp": "N", "t": "τοιούτων οὖν ἁπασῶν τῶν πόλεων γεγενημένων ἔδει μὲν μηδέποτέ σοι μηδὲ πρὸς μίαν αὐτῶν γενέσθαι διαφοράν· ἀλλὰ γὰρ ἅπαντες πλείω πεφύκαμεν ἐξαμαρτάνειν ἢ κατορθοῦν. ὥστε τὰ μὲν πρότερον γεγενημένα κοινὰ θεῖναι δίκαιόν ἐστιν· εἰς δὲ τὸν ἐπίλοιπον χρόνον φυλακτέον ὅπως μηδὲν συμβήσεταί σοι τοιοῦτον, καὶ σκεπτέον τί ἂν ἀγαθὸν αὐτὰς ἐργασάμενος φανείης ἄξια καὶ σαυτοῦ καὶ τῶν ἐκείναις πεπραγμένων πεποιηκώς.", "st": "5.35"}, {"sp": "N", "t": "ἔχεις δὲ καιρόν· ἀποδιδόντα γάρ σε χάριν ὧν ὤφειλες ὑπολήψονται διὰ τὸ πλῆθος τοῦ χρόνου τοῦ μεταξὺ προϋπάρχειν τῶν εὐεργεσιῶν. καλὸν δ’ ἐστὶ δοκεῖν μὲν τὰς μεγίστας τῶν πόλεων εὖ ποιεῖν μηδὲν δ’ ἧττον ἑαυτὸν ἢ ’κείνας ὠφελεῖν. χωρὶς δὲ τούτων,", "st": "5.36"}, {"sp": "N", "t": "εἰ πρός τινας αὐτῶν ἀηδές τί σοι συμβέβηκεν, ἅπαντα ταῦτα διαλύσεις· αἱ γὰρ ἐν τοῖς παροῦσι καιροῖς εὐεργεσίαι λήθην ἐμποιήσουσι τῶν πρότερον ὑμῖν εἰς ἀλλήλους πεπλημμελημένων. ἀλλὰ μὴν κἀκεῖνο φανερόν, ὅτι πάντες ἄνθρωποι τούτων πλείστην μνείαν ἔχουσιν, ὧν ἂν ἐν ταῖς συμφοραῖς εὖ πάθωσιν.", "st": "5.37"}, {"sp": "N", "t": "ὁρᾷς δ’ ὡς τεταλαιπώρηνται διὰ τὸν πόλεμον, καὶ ὡς παραπλησίως ἔχουσι τοῖς ἰδίᾳ μαχομένοις. καὶ γὰρ ἐκείνους αὐξομένης μὲν τῆς ὀργῆς οὐδεὶς ἂν διαλλάξειεν· ἐπὴν δὲ κακῶς ἀλλήλους διαθῶσιν, οὐδενὸς διαλύοντος αὐτοὶ διέστησαν. ὅπερ οἶμαι καὶ ταύτας ποιήσειν, ἢν μὴ σὺ πρότερον αὐτῶν ἐπιμεληθῇς.", "st": "5.38"}, {"sp": "N", "t": "τάχ’ οὖν ἄν τις ἐνστῆναι τοῖς εἰρημένοις τολμήσειε, λέγων ὡς ἐπιχειρῶ σε πείθειν ἀδυνάτοις ἐπιτίθεσθαι πράγμασιν· οὔτε γὰρ Ἀργείους φίλους ἄν ποτε γενέσθαι Λακεδαιμονίοις οὔτε Λακεδαιμονίους Θηβαίοις, οὔθ’ ὅλως τοὺς εἰθισμένους ἅπαντα τὸν χρόνον πλεονεκτεῖν οὐδέποτ’ ἂν ἰσομοιρῆσαι πρὸς ἀλλήλους.", "st": "5.39"}, {"sp": "N", "t": "ἐγὼ δ’, ὅτε μὲν ἡ πόλις ἡμῶν ἐν τοῖς Ἕλλησιν ἐδυνάστευε καὶ πάλιν ἡ Λακεδαιμονίων, οὐδὲν ἂν ἡγοῦμαι περανθῆναι τούτων· ῥᾳδίως γὰρ ἂν ἑκατέραν ἐμποδὼν γενέσθαι τοῖς πραττομένοις· νῦν δ’ οὐχ ὁμοίως ἔγνωκα περὶ αὐτῶν. οἶδα γὰρ ἁπάσας ὡμαλισμένας ὑπὸ τῶν συμφορῶν, ὥσθ’ ἡγοῦμαι πολὺ μᾶλλον αὐτὰς αἱρήσεσθαι τὰς ἐκ τῆς ὁμονοίας ὠφελείας ἢ τὰς ἐκ τῶν τότε πραττομένων πλεονεξίας.", "st": "5.40"}, {"sp": "N", "t": "ἔπειτα τῶν μὲν ἄλλων ὁμολογῶ μηδέν’ ἂν δυνηθῆναι διαλλάξαι τὰς πόλεις ταύτας, σοὶ δ’ οὐδὲν τῶν τοιούτων ἐστὶ χαλεπόν. ὁρῶ γάρ σε τῶν τοῖς ἄλλοις ἀνελπίστων δοκούντων εἶναι καὶ παραδόξων πολλὰ διαπεπραγμένον, ὥστ’ οὐδὲν ἄτοπον εἰ καὶ ταῦτα μόνος συστῆσαι δυνηθείης. χρὴ δὲ τοὺς μέγα φρονοῦντας καὶ τοὺς διαφέροντας μὴ τοῖς τοιούτοις ἐπιχειρεῖν ἃ καὶ τῶν τυχόντων ἄν τις καταπράξειεν, ἀλλ’ ἐκείνοις οἷς μηδεὶς ἂν ἄλλος ἐπιχειρήσειε πλὴν τῶν ὁμοίαν σοὶ καὶ τὴν φύσιν καὶ τὴν δύναμιν ἐχόντων.", "st": "5.41"}, {"sp": "N", "t": "θαυμάζω δὲ τῶν ἡγουμένων ἀδύνατον εἶναι πραχθῆναί τι τούτων, εἰ μήτ’ αὐτοὶ τυγχάνουσιν εἰδότες μήθ’ ἑτέρων ἀκηκόασιν ὅτι πολλοὶ δὴ πόλεμοι καὶ δεινοὶ γεγόνασιν, οὓς οἱ διαλυσάμενοι μεγάλων ἀγαθῶν ἀλλήλοις αἴτιοι κατέστησαν. τίς γὰρ ἂν ὑπερβολὴ γένοιτο τῆς ἔχθρας τῆς πρὸς Ξέρξην τοῖς Ἕλλησι γενομένης; οὗ τὴν φιλίαν ἅπαντες ἴσασιν ἡμᾶς τε καὶ Λακεδαιμονίους μᾶλλον ἀγαπήσαντας ἢ τῶν συγκατασκευασάντων ἑκατέροις ἡμῶν τὴν ἀρχήν.", "st": "5.42"}, {"sp": "N", "t": "καὶ τί δεῖ λέγειν τὰ παλαιὰ καὶ τὰ πρὸς τοὺς βαρβάρους; ἀλλ’ εἴ τις ἀθρήσειε καὶ σκέψαιτο τὰς τῶν Ἑλλήνων συμφοράς, οὐδὲν ἂν μέρος οὖσαι φανεῖεν τῶν διὰ Θηβαίους καὶ Λακεδαιμονίους ἡμῖν γεγενημένων. ἀλλ’ οὐδὲν ἧττον Λακεδαιμονίων τε στρατευσάντων ἐπὶ Θηβαίους, καὶ βουλομένων λυμήνασθαι τὴν Βοιωτίαν καὶ διοικίσαι τὰς πόλεις, βοηθήσαντες ἡμεῖς ἐμποδὼν ἐγενόμεθα ταῖς ἐκείνων ἐπιθυμίαις·", "st": "5.43"}, {"sp": "N", "t": "καὶ πάλιν μεταπεσούσης τῆς τύχης, καὶ Θηβαίων καὶ Πελοποννησίων ἁπάντων ἐπιχειρησάντων ἀνάστατον ποιῆσαι τὴν Σπάρτην, ἡμεῖς καὶ πρὸς ἐκείνους μόνοι τῶν Ἑλλήνων ποιησάμενοι συμμαχίαν συναίτιοι τῆς σωτηρίας αὐτοῖς κατέστημεν.", "st": "5.44"}, {"sp": "N", "t": "πολλῆς οὖν ἀνοίας ἂν εἴη μεστός, εἴ τις ὁρῶν τηλικαύτας μεταβολὰς γιγνομένας, καὶ τὰς πόλεις μήτ’ ἔχθρας μήθ’ ὅρκων μήτ’ ἄλλου μηδενὸς φροντιζούσας, πλὴν ὅ τι ἂν ὑπολάβωσιν ὠφέλιμον αὑταῖς εἶναι, τοῦτο δὲ στεργούσας μόνον καὶ πᾶσαν τὴν σπουδὴν περὶ τούτου ποιουμένας, μὴ καὶ νῦν νομίζοι τὴν αὐτὴν γνώμην ἕξειν αὐτάς, ἄλλως τε καὶ σοῦ μὲν ἐπιστατοῦντος ταῖς διαλλαγαῖς, τοῦ δὲ συμφέροντος πείθοντος, τῶν δὲ παρόντων κακῶν ἀναγκαζόντων. ἐγὼ μὲν γὰρ οἶμαι τούτων σοι συναγωνιζομένων ἅπαντα γενήσεσθαι κατὰ τρόπον.", "st": "5.45"}, {"sp": "N", "t": "ἡγοῦμαι δ’ οὕτως ἄν σε μάλιστα καταμαθεῖν εἴτ’ εἰρηνικῶς εἴτε πολεμικῶς αἱ πόλεις αὗται πρὸς ἀλλήλας ἔχουσιν, εἰ διεξέλθοιμεν μήτε παντάπασιν ἁπλῶς μήτε λίαν ἀκριβῶς τὰ μέγιστα τῶν παρόντων αὐταῖς. καὶ πρῶτον μὲν σκεψώμεθα τὰ Λακεδαιμονίων.", "st": "5.46"}, {"sp": "N", "t": "οὗτοι γὰρ ἄρχοντες τῶν Ἑλλήνων (οὐ πολὺς χρόνος ἐξ οὗ) καὶ κατὰ γῆν καὶ κατὰ θάλατταν, εἰς τοσαύτην μεταβολὴν ἦλθον, ἐπειδὴ τὴν μάχην ἡττήθησαν τὴν ἐν Λεύκτροις, ὥστε ἀπεστερήθησαν μὲν τῆς ἐν τοῖς Ἕλλησι δυναστείας, τοιούτους δ’ ἄνδρας ἀπώλεσαν σφῶν αὐτῶν, οἳ προῃροῦντο τεθνάναι μᾶλλον ἢ ζῆν ἡττηθέντες ὧν πρότερον ἐδέσποζον.", "st": "5.47"}, {"sp": "N", "t": "πρὸς δὲ τούτοις ἐπεῖδον Πελοποννησίους ἅπαντας τοὺς πρότερον μεθ’ αὑτῶν ἐπὶ τοὺς ἄλλους ἀκολουθοῦντας, τούτους μετὰ Θηβαίων εἰς τὴν αὑτῶν εἰσβαλόντας, πρὸς οὓς ἠναγκάσθησαν διακινδυνεύειν οὐκ ἐν τῇ χώρᾳ περὶ τῶν καρπῶν, ἀλλ’ ἐν μέσῃ τῇ πόλει πρὸς αὐτοῖς τοῖς ἀρχείοις περὶ παίδων καὶ γυναικῶν, τοιοῦτον κίνδυνον ὃν μὴ κατορθώσαντες μὲν εὐθὺς ἀπώλλυντο,", "st": "5.48"}, {"sp": "N", "t": "νικήσαντες δ’ οὐδὲν μᾶλλον ἀπηλλαγμένοι τῶν κακῶν εἰσιν, ἀλλὰ πολεμοῦνται μὲν ὑπὸ τῶν τὴν χώραν αὐτῶν περιοικούντων, ἀπιστοῦνται δ’ ὑφ’ ἁπάντων Πελοποννησίων, μισοῦνται δ’ ὑπὸ τοῦ πλήθους τῶν Ἑλλήνων, ἄγονται δὲ καὶ φέρονται καὶ τῆς νυκτὸς καὶ τῆς ἡμέρας ὑπὸ τῶν οἰκετῶν τῶν σφετέρων αὐτῶν, οὐδένα δὲ χρόνον διαλείπουσιν ἢ στρατεύοντες ἐπί τινας ἢ μαχόμενοι πρός τινας ἢ βοηθοῦντες τοῖς ἀπολλυμένοις αὑτῶν.", "st": "5.49"}, {"sp": "N", "t": "τὸ δὲ μέγιστον τῶν κακῶν· δεδιότες γὰρ διατελοῦσι μὴ Θηβαῖοι διαλυσάμενοι τὰ πρὸς Φωκέας πάλιν ἐπανελθόντες μείζοσιν αὐτοὺς συμφοραῖς περιβάλωσι τῶν πρότερον γεγενημένων. καίτοι πῶς οὐ χρὴ νομίζειν τοὺς οὕτω διακειμένους ἀσμένους ἂν ἰδεῖν ἐπιστατοῦντα τῆς εἰρήνης ἀξιόχρεων ἄνδρα καὶ δυνάμενον διαλῦσαι τοὺς ἐνεστῶτας πολέμους αὐτοῖς;", "st": "5.50"}, {"sp": "N", "t": "Ἀργείους τοίνυν ἴδοις ἂν τὰ μὲν παραπλησίως τοῖς εἰρημένοις πράττοντας, τὰ δὲ χεῖρον τούτων ἔχοντας· πολεμοῦσι μὲν γὰρ ἐξ οὗ περ τὴν πόλιν οἰκοῦσι πρὸς τοὺς ὁμόρους, ὥσπερ Λακεδαιμόνιοι, τοσοῦτον δὲ διαφέρουσιν ὅσον ἐκεῖνοι μὲν πρὸς ἥττους αὑτῶν, οὗτοι δὲ πρὸς κρείττους· ὃ πάντες ἂν ὁμολογήσειαν μέγιστον εἶναι τῶν κακῶν. οὕτω δὲ τὰ περὶ τὸν πόλεμον ἀτυχοῦσιν, ὥστ’ ὀλίγου δεῖν καθ’ ἕκαστον τὸν ἐνιαυτὸν τεμνομένην καὶ πορθουμένην τὴν αὑτῶν χώραν περιορῶσιν.", "st": "5.51"}, {"sp": "N", "t": "ὃ δὲ πάντων δεινότατον· ὅταν γὰρ οἱ πολέμιοι διαλίπωσι κακῶς αὐτοὺς ποιοῦντες, αὐτοὶ τοὺς ἐνδοξοτάτους καὶ πλουσιωτάτους τῶν πολιτῶν ἀπολλύουσι, καὶ ταῦτα δρῶντες οὕτω χαίρουσιν ὡς οὐδένες ἄλλοι τοὺς πολεμίους ἀποκτείνοντες. αἴτιον δ’ ἐστὶ τοῦ ταραχωδῶς αὐτοὺς ζῆν οὕτως οὐδὲν ἄλλο πλὴν ὁ πόλεμος· ὃν ἢν διαλύσῃς, οὐ μόνον αὐτοὺς τούτων ἀπαλλάξεις, ἀλλὰ καὶ περὶ τῶν ἄλλων ἄμεινον βουλεύεσθαι ποιήσεις.", "st": "5.52"}, {"sp": "N", "t": "ἀλλὰ μὴν τὰ περὶ Θηβαίους οὐδὲ σὲ λέληθεν. καλλίστην γὰρ μάχην νικήσαντες, καὶ δόξαν ἐξ αὐτῆς μεγίστην λαβόντες, διὰ τὸ μὴ καλῶς χρῆσθαι ταῖς εὐτυχίαις οὐδὲν βέλτιον πράττουσι τῶν ἡττηθέντων καὶ δυστυχησάντων. οὐ γὰρ ἔφθασαν τῶν ἐχθρῶν κρατήσαντες, καὶ πάντων ἠνώχλουν μὲν ταῖς πόλεσι ταῖς ἐν Πελοποννήσῳ, Θετταλίαν δ’ ἐτόλμων καταδουλοῦσθαι, Μεγαρεῦσι δ’ ὁμόροις οὖσιν ἠπείλουν, τὴν δ’ ἡμετέραν πόλιν μέρος τι τῆς χώρας ἀπεστέρουν, Εὔβοιαν δ’ ἐπόρθουν, εἰς Βυζάντιον δὲ τριήρεις ἐξέπεμπον ὡς καὶ γῆς καὶ θαλάττης ἄρξοντες.", "st": "5.53"}, {"sp": "N", "t": "τελευτῶντες δὲ πρὸς Φωκέας πόλεμον ἐξήνεγκαν ὡς τῶν τε πόλεων ἐν ὀλίγῳ χρόνῳ κρατήσοντες, τόν τε τόπον ἅπαντα τὸν περιέχοντα κατασχήσοντες, τῶν τε χρημάτων τῶν ἐν Δελφοῖς περιγενησόμενοι ταῖς ἐκ τῶν ἰδίων δαπάναις. ὧν οὐδὲν αὐτοῖς ἀποβέβηκεν, ἀλλ’ ἀντὶ μὲν τοῦ λαβεῖν τὰς Φωκέων πόλεις τὰς αὑτῶν ἀπολωλέκασιν, εἰσβάλλοντες δ’ εἰς τὴν τῶν πολεμίων ἐλάττω κακὰ ποιοῦσιν ἐκείνους ἢ πάσχουσιν ἀπιόντες εἰς τὴν αὑτῶν·", "st": "5.54"}, {"sp": "N", "t": "ἐν μὲν γὰρ τῇ Φωκίδι τῶν μισθοφόρων τινὰς ἀποκτείνουσιν, οἷς λυσιτελεῖ τεθνάναι μᾶλλον ἢ ζῆν, ἀναχωροῦντες δὲ τοὺς ἐνδοξοτάτους αὑτῶν καὶ μάλιστα τολμῶντας ὑπὲρ τῆς πατρίδος ἀποθνήσκειν ἀπολλύουσιν. εἰς τοῦτο δ’ αὐτῶν περιέστηκε τὰ πράγματα, ὥστ’ ἐλπίσαντες ἅπαντας τοὺς Ἕλληνας ὑφ’ αὑτοῖς ἔσεσθαι νῦν ἐν σοὶ τὰς ἐλπίδας ἔχουσι τῆς αὑτῶν σωτηρίας. ὥστ’ οἶμαι καὶ τούτους ταχέως ποιήσειν ὅ τι ἂν σὺ κελεύῃς καὶ συμβουλεύῃς.", "st": "5.55"}, {"sp": "N", "t": "λοιπὸν δ’ ἂν ἦν ἡμῖν ἔτι περὶ τῆς πόλεως διαλεχθῆναι τῆς ἡμετέρας, εἰ μὴ προτέρα τῶν ἄλλων εὖ φρονήσασα τὴν εἰρήνην ἐπεποίητο. νῦν δ’ αὐτὴν οἶμαι καὶ συναγωνιεῖσθαι τοῖς ὑπὸ σοῦ πραττομένοις, ἄλλως τε κἂν δυνηθῇ συνιδεῖν ὅτι ταῦτα διοικεῖς πρὸ τῆς ἐπὶ τὸν βάρβαρον στρατείας.", "st": "5.56"}, {"sp": "N", "t": "ὡς μὲν οὖν οὐκ ἀδύνατόν ἐστί σοι συστῆσαι τὰς πόλεις ταύτας, ἐκ τῶν εἰρημένων ἡγοῦμαί σοι γεγενῆσθαι φανερόν· ἔτι τοίνυν ὡς καὶ ῥᾳδίως ταῦτα πράξεις, ἐκ πολλῶν παραδειγμάτων οἶμαί σε γνῶναι ποιήσειν. ἢν γὰρ φανῶσιν ἕτεροί τινες τῶν προγεγενημένων μὴ καλλίοσι μὲν μηδ’ ὁσιωτέροις ὧν ἡμεῖς συμβεβουλεύκαμεν ἐπιχειρήσαντες, μείζω δὲ καὶ δυσκολώτερα τούτων ἐπιτελέσαντες, τί λοιπὸν ἔσται τοῖς ἀντιλέγουσιν ὡς οὐ θᾶττον σὺ τὰ ῥᾴω πράξεις ἢ ’κεῖνοι τὰ χαλεπώτερα;", "st": "5.57"}, {"sp": "N", "t": "σκέψαι δὲ πρῶτον τὰ περὶ Ἀλκιβιάδην. ἐκεῖνος γὰρ φυγὼν παρ’ ἡμῶν, καὶ τοὺς ἄλλους ὁρῶν τοὺς πρὸ αὑτοῦ ταύτῃ συμφορᾷ κεχρημένους ἐπτηχότας διὰ τὸ μέγεθος τὸ τῆς πόλεως, οὐ τὴν αὐτὴν γνώμην ἔσχεν ἐκείνοις, ἀλλ’ οἰηθεὶς πειρατέον εἶναι βίᾳ κατελθεῖν προείλετο πολεμεῖν πρὸς αὐτήν.", "st": "5.58"}, {"sp": "N", "t": "καθ’ ἕκαστον μὲν οὖν τῶν τότε γενομένων εἴ τις λέγειν ἐπιχειρήσειεν, οὔτ’ ἂν διελθεῖν ἀκριβῶς δύναιτο, πρός τε τὸ παρὸν ἴσως ἂν ἐνοχλήσειεν· εἰς τοσαύτην δὲ ταραχὴν κατέστησεν οὐ μόνον τὴν πόλιν ἀλλὰ καὶ Λακεδαιμονίους καὶ τοὺς ἄλλους Ἕλληνας, ὥσθ’ ἡμᾶς μὲν παθεῖν ἃ πάντες ἴσασι, τοὺς δ’ ἄλλους τηλικούτοις κακοῖς περιπεσεῖν,", "st": "5.59"}, {"sp": "N", "t": "ὥστε μηδέπω νῦν ἐξιτήλους εἶναι τὰς συμφορὰς τὰς δι’ ἐκεῖνον τὸν πόλεμον ἐν ταῖς πόλεσιν ἐγγεγενημένας, Λακεδαιμονίους δὲ τοὺς τότε δόξαντας εὐτυχεῖν εἰς τὰς νῦν ἀτυχίας δι’ Ἀλκιβιάδην καθεστάναι·", "st": "5.60"}, {"sp": "N", "t": "πεισθέντες γὰρ ὑπ’ αὐτοῦ τῆς κατὰ θάλατταν δυνάμεως ἐπιθυμῆσαι καὶ τὴν κατὰ γῆν ἡγεμονίαν ἀπώλεσαν, ὥστ’ εἴ τις φαίη τότε τὴν ἀρχὴν αὐτοῖς γενέσθαι τῶν παρόντων κακῶν, ὅτε τὴν ἀρχὴν τῆς θαλάττης ἐλάμβανον, οὐκ ἂν ἐξελεγχθείη ψευδόμενος. ἐκεῖνος μὲν οὖν τηλικούτων αἴτιος γενόμενος κατῆλθεν εἰς τὴν πόλιν, μεγάλης μὲν δόξης τυχών, οὐ μὴν ἐπαινούμενος ὑφ’ ἁπάντων. Κόνων δ’ οὐ πολλοῖς ἔτεσιν ὕστερον ἀντίστροφα τούτων ἔπραξεν.", "st": "5.61"}, {"sp": "N", "t": "ἀτυχήσας γὰρ ἐν τῇ ναυμαχίᾳ τῇ περὶ Ἑλλήσποντον οὐ δι’ αὑτὸν ἀλλὰ διὰ τοὺς συνάρχοντας, οἴκαδε μὲν ἀφικέσθαι κατῃσχύνθη, πλεύσας δ’ εἰς Κύπρον χρόνον μέν τινα περὶ τὴν τῶν ἰδίων ἐπιμέλειαν διέτριβεν, αἰσθόμενος δ’ Ἀγησίλαον μετὰ πολλῆς δυνάμεως εἰς τὴν Ἀσίαν διαβεβηκότα καὶ πορθοῦντα τὴν χώραν οὕτω μέγ’ ἐφρόνησεν,", "st": "5.62"}, {"sp": "N", "t": "ὥστ’ ἀφορμήν οὐδεμίαν ἄλλην ἔχων πλὴν τὸ σῶμα καὶ τὴν διάνοιαν ἤλπισε Λακεδαιμονίους καταπολεμήσειν ἄρχοντας τῶν Ἑλλήνων καὶ κατὰ γῆν καὶ κατὰ θάλατταν, καὶ ταῦτα πέμπων ὡς τοὺς βασιλέως στρατηγοὺς ὑπισχνεῖτο ποιήσειν. καὶ τί δεῖ τὰ πλείω λέγειν; συστάντος γὰρ αὐτῷ ναυτικοῦ περὶ Ῥόδον καὶ νικήσας τῇ ναυμαχίᾳ Λακεδαιμονίους μὲν ἐξέβαλεν ἐκ τῆς ἀρχῆς,", "st": "5.63"}, {"sp": "N", "t": "τοὺς δ’ Ἕλληνας ἠλευθέρωσεν, οὐ μόνον δὲ τὰ τείχη τῆς πατρίδος ἀνώρθωσεν, ἀλλὰ καὶ τὴν πόλιν εἰς τὴν αὐτὴν δόξαν προήγαγεν ἐξ ἧσπερ ἐξέπεσεν. καίτοι τίς ἂν προσεδόκησεν ὑπ’ ἀνδρὸς οὕτω ταπεινῶς πράξαντος ἀναστραφήσεσθαι τὰ τῆς Ἑλλάδος πράγματα, καὶ τὰς μὲν ἀτιμωθήσεσθαι τὰς δ’ ἐπιπολάσειν τῶν Ἑλληνίδων πόλεων;", "st": "5.64"}, {"sp": "N", "t": "Διονύσιος τοίνυν (βούλομαι γὰρ ἐκ πολλῶν σε πεισθῆναι ῥᾳδίαν εἶναι τὴν πρᾶξιν, ἐφ’ ἥν σε τυγχάνω παρακαλῶν) πολλοστὸς ὢν Συρακοσίων καὶ τῷ γένει καὶ τῇ δόξῃ καὶ τοῖς ἄλλοις ἅπασιν, ἐπιθυμήσας μοναρχίας ἀλόγως καὶ μανικῶς, καὶ τολμήσας ἅπαντα πράττειν τὰ φέροντα πρὸς τὴν δύναμιν ταύτην, κατέσχε μὲν Συρακούσας, ἁπάσας δὲ τὰς ἐν Σικελίᾳ πόλεις, ὅσαι περ ἦσαν Ἑλληνίδες, κατεστρέψατο, τηλικαύτην δὲ δύναμιν περιεβάλετο καὶ πεζὴν καὶ ναυτικήν, ὅσην οὐδεὶς ἀνὴρ τῶν πρὸ ἐκείνου γενομένων.", "st": "5.65"}, {"sp": "N", "t": "ἔτι τοίνυν Κῦρος (ἵνα μνησθῶμεν καὶ περὶ τῶν βαρβάρων) ἐκτεθεὶς μὲν ὑπὸ τῆς μητρὸς εἰς τὴν ὁδόν, ἀναιρεθεὶς δ’ ὑπὸ Περσίδος γυναικός, εἰς τοσαύτην ἦλθε μεταβολὴν ὥσθ’ ἁπάσης τῆς Ἀσίας γενέσθαι δεσπότης.", "st": "5.66"}, {"sp": "N", "t": "ὅπου δ’ Ἀλκιβιάδης μὲν φυγὰς ὤν, Κόνων δὲ δεδυστυχηκώς, Διονύσιος δ’ οὐκ ἔνδοξος ὤν, Κῦρος δ’ οὕτως οἰκτρᾶς αὐτῷ τῆς ἐξ ἀρχῆς γενέσεως ὑπαρξάσης, εἰς τοσοῦτον προῆλθον καὶ τηλικαῦτα διεπράξαντο, πῶς οὐ σέ γε χρὴ προσδοκᾶν τὸν ἐκ τοιούτων μὲν γεγονότα, Μακεδονίας δὲ βασιλεύοντα, τοσούτων δὲ κύριον ὄντα, ῥᾳδίως τὰ προειρημένα συστήσειν;", "st": "5.67"}, {"sp": "N", "t": "σκέψαι δ’ ὡς ἄξιόν ἐστι τοῖς τοιούτοις τῶν ἔργων μάλιστ’ ἐπιχειρεῖν, ἐν οἷς κατορθώσας μὲν ἐνάμιλλον τὴν σαυτοῦ δόξαν καταστήσεις τοῖς πρωτεύσασι, διαμαρτὼν δὲ τῆς προσδοκίας ἀλλ’ οὖν τήν γ’ εὔνοιαν κτήσει τὴν παρὰ τῶν Ἑλλήνων, ἣν πολὺ κάλλιόν ἐστι λαβεῖν ἢ πολλὰς πόλεις τῶν Ἑλληνίδων κατὰ κράτος ἑλεῖν· τὰ μὲν γὰρ τοιαῦτα τῶν ἔργων φθόνον ἔχει καὶ δυσμένειαν καὶ πολλὰς βλασφημίας, οἷς δ’ ἡμεῖς συμβεβουλεύκαμεν οὐδὲν πρόσεστι τούτων. ἀλλ’ εἴ τις θεῶν αἵρεσίν σοι δοίη μετὰ ποίας ἂν ἐπιμελείας καὶ διατριβῆς εὔξαιο τὸν βίον διαγαγεῖν, οὐδεμίαν ἕλοι’ ἄν, εἴπερ ἐμοὶ συμβούλῳ χρῷο, μᾶλλον ἢ ταύτην.", "st": "5.68"}, {"sp": "N", "t": "οὐ γὰρ μόνον ὑπὸ τῶν ἄλλων ἔσει ζηλωτός, ἀλλὰ καὶ σὺ σαυτὸν μακαριεῖς. τίς γὰρ ἂν ὑπερβολὴ γένοιτο τῆς τοιαύτης εὐδαιμονίας, ὅταν πρέσβεις μὲν ἥκωσιν ἐκ τῶν μεγίστων πόλεων οἱ μάλιστ’ εὐδοκιμοῦντες εἰς τὴν σὴν δυναστείαν, μετὰ δὲ τούτων βουλεύῃ περὶ τῆς κοινῆς σωτηρίας, περὶ ἧς οὐδεὶς ἄλλος φανήσεται τοιαύτην πρόνοιαν πεποιημένος,", "st": "5.69"}, {"sp": "N", "t": "αἰσθάνῃ δὲ τὴν Ἑλλάδα πᾶσαν ὀρθὴν οὖσαν ἐφ’ οἷς σὺ τυγχάνεις εἰσηγούμενος, μηδεὶς δ’ ὀλιγώρως ἔχῃ τῶν παρὰ σοὶ βραβευομένων, ἀλλ’ οἱ μὲν πυνθάνωνται περὶ αὐτῶν ἐν οἷς ἐστίν, οἱ δ’ εὔχωνταί σε μὴ διαμαρτεῖν ὧν ἐπεθύμησας, οἱ δὲ δεδίωσι μὴ πρότερόν τι πάθῃς πρὶν τέλος ἐπιθεῖναι τοῖς πραττομένοις;", "st": "5.70"}, {"sp": "N", "t": "ὧν γιγνομένων πῶς οὐκ ἂν εἰκότως μέγα φρονοίης; πῶς δ’ οὐκ ἂν περιχαρὴς ὢν τὸν βίον διατελοίης, τηλικούτων εἰδὼς σαυτὸν πραγμάτων ἐπιστάτην γεγενημένον; τίς δ’ οὐκ ἂν τῶν καὶ μετρίως λογιζομένων ταύτας ἄν σοι παραινέσειε μάλιστα προαιρεῖσθαι τῶν πράξεων, τὰς ἀμφότερα φέρειν ἅμα δυναμένας, ὥσπερ καρπούς, ἡδονάς θ’ ὑπερβαλλούσας καὶ τιμὰς ἀνεξαλείπτους;", "st": "5.71"}, {"sp": "N", "t": "ἀπέχρη δ’ ἂν ἤδη μοι τὰ προειρημένα περὶ τούτων, εἰ μὴ παραλελοιπὼς ἦν τινα λόγον, οὐκ ἀμνημονήσας ἀλλ’ ὀκνήσας εἰπεῖν, ὃν ἤδη μοι δοκῶ δηλώσειν· οἶμαι γὰρ σοί τε συμφέρειν ἀκοῦσαι περὶ αὐτῶν, ἐμοί τε προσήκειν μετὰ παρρησίας (ὥσπερ εἴθισμαι) ποιεῖσθαι τοὺς λόγους.", "st": "5.72"}, {"sp": "N", "t": "αἰσθάνομαι γάρ σε διαβαλλόμενον ὑπὸ τῶν σοὶ μὲν φθονούντων, τὰς δὲ πόλεις τὰς αὑτῶν εἰθισμένων εἰς ταραχὰς καθιστάναι, καὶ τὴν εἰρήνην τὴν τοῖς ἄλλοις κοινὴν πόλεμον τοῖς αὑτῶν ἰδίοις εἶναι νομιζόντων, οἳ πάντων τῶν ἄλλων ἀμελήσαντες περὶ τῆς σῆς δυνάμεως λέγουσιν, ὡς οὐχ ὑπὲρ τῆς Ἑλλάδος ἀλλ’ ἐπὶ ταύτην αὐξάνεται, καὶ σὺ πολὺν χρόνον ἤδη πᾶσιν ἡμῖν ἐπιβουλεύεις,", "st": "5.73"}, {"sp": "N", "t": "καὶ λόγῳ μὲν μέλλεις Μεσσηνίοις βοηθεῖν, ἐὰν τὰ περὶ Φωκεῖς διοικήσῃς, ἔργῳ δ’ ὑπὸ σαυτῷ ποιεῖσθαι Πελοπόννησον· ὑπάρχουσι δέ σοι Θετταλοὶ μὲν καὶ Θηβαῖοι καὶ πάντες οἱ τῆς Ἀμφικτυονίας μετέχοντες ἕτοιμοι συνακολουθεῖν, Ἀργεῖοι δὲ καὶ Μεσσήνιοι καὶ Μεγαλοπολῖται καὶ τῶν ἄλλων πολλοὶ συμπολεμεῖν καὶ ποιεῖν ἀναστάτους Λακεδαιμονίους· ἢν δὲ ταῦτα πράξῃς, ὡς καὶ τῶν ἄλλων Ἑλλήνων ῥᾳδίως κρατήσεις.", "st": "5.74"}, {"sp": "N", "t": "ταῦτα φλυαροῦντες καὶ φάσκοντες ἀκριβῶς εἰδέναι, καὶ ταχέως ἅπαντα τῷ λόγῳ καταστρεφόμενοι, πολλοὺς πείθουσι, καὶ μάλιστα μὲν τοὺς τῶν αὐτῶν κακῶν ἐπιθυμοῦντας ὧν περ οἱ λογοποιοῦντες, ἔπειτα καὶ τοὺς οὐδενὶ λογισμῷ χρωμένους ὑπὲρ τῶν κοινῶν, ἀλλὰ παντάπασιν ἀναισθήτως διακειμένους καὶ πολλὴν χάριν ἔχοντας τοῖς ὑπὲρ αὐτῶν φοβεῖσθαι καὶ δεδιέναι προσποιουμένοις, ἔτι δὲ τοὺς οὐκ ἀποδοκιμάζοντας τὸ δοκεῖν ἐπιβουλεύειν σε τοῖς Ἕλλησιν, ἀλλὰ τὴν αἰτίαν ταύτην ἀξίαν ἐπιθυμίας εἶναι νομίζοντας.", "st": "5.75"}, {"sp": "N", "t": "οἳ τοσοῦτον ἀφεστᾶσι τοῦ νοῦν ἔχειν, ὥστ’ οὐκ ἴσασιν ὅτι τοῖς αὐτοῖς ἄν τις λόγοις χρώμενος τοὺς μὲν βλάψειε τοὺς δ’ ὠφελήσειεν. οἷον καὶ νῦν, εἰ μέν τις φαίη τὸν τῆς Ἀσίας βασιλέα τοῖς Ἕλλησιν ἐπιβουλεύειν καὶ παρεσκευάσθαι στρατεύειν ἐφ’ ἡμᾶς, οὐδὲν ἂν λέγοι περὶ αὐτοῦ φλαῦρον, ἀλλ’ ἀνδρωδέστερον αὐτὸν καὶ πλέονος ἄξιον δοκεῖν εἶναι ποιήσειεν· εἰ δὲ τῶν ἀφ’ Ἡρακλέους τινὶ πεφυκότων, ὃς ἁπάσης κατέστη τῆς Ἑλλάδος εὐεργέτης, ἐπιφέροι τὴν αἰτίαν ταύτην, εἰς τὴν μεγίστην αἰσχύνην ἂν αὐτὸν καταστήσειεν.", "st": "5.76"}, {"sp": "N", "t": "τίς γὰρ οὐκ ἂν ἀγανακτήσειε καὶ μισήσειεν, εἰ φαίνοιτο τούτοις ἐπιβουλεύων ὑπὲρ ὧν ὁ πρόγονος αὐτοῦ προείλετο κινδυνεύειν, καὶ τὴν μὲν εὔνοιαν, ἣν ἐκεῖνος κατέλιπε τοῖς ἐξ ἑαυτοῦ γεγενημένοις, μὴ πειρῷτο διαφυλάττειν, ἀμελήσας δὲ τούτων ἐπονειδίστων ἐπιθυμοίη καὶ πονηρῶν πραγμάτων;", "st": "5.77"}, {"sp": "N", "t": "ὧν ἐνθυμούμενον χρὴ μὴ περιορᾶν τοιαύτην φήμην σαυτῷ περιφυομένην, ἣν οἱ μὲν ἐχθροὶ περιθεῖναί σοι ζητοῦσι, τῶν δὲ φίλων οὐδεὶς ὅστις οὐκ ἂν ἀντειπεῖν ὑπὲρ σοῦ τολμήσειεν. καίτοι περὶ τῶν σοι συμφερόντων ἐν ταῖς τούτων ἀμφοτέρων γνώμαις μάλιστ’ ἂν κατίδοις τὴν ἀλήθειαν.", "st": "5.78"}, {"sp": "N", "t": "ἴσως οὖν ὑπολαμβάνεις μικροψυχίαν εἶναι τὸ τῶν βλασφημούντων καὶ φλυαρούντων καὶ τῶν πειθομένων τούτοις φροντίζειν, ἄλλως θ’ ὅταν καὶ μηδὲν σαυτῷ συνειδῇς ἐξαμαρτάνων. χρὴ δὲ μὴ καταφρονεῖν τοῦ πλήθους, μηδὲ παρὰ μικρὸν ἡγεῖσθαι τὸ παρὰ πᾶσιν εὐδοκιμεῖν, ἀλλὰ τότε νομίζειν καλὴν ἔχειν καὶ μεγάλην τὴν δόξαν καὶ πρέπουσαν σοὶ καὶ τοῖς προγόνοις καὶ τοῖς ὑφ’ ὑμῶν πεπραγμένοις,", "st": "5.79"}, {"sp": "N", "t": "ὅταν οὕτω διαθῇς τοὺς Ἕλληνας, ὥσπερ ὁρᾷς Λακεδαιμονίους τε πρὸς τοὺς ἑαυτῶν βασιλέας ἔχοντας τούς θ’ ἑταίρους τοὺς σοὺς πρὸς σὲ διακειμένους. ἔστι δ’ οὐ χαλεπὸν τυχεῖν τούτων, ἢν ἐθελήσῃς κοινὸς ἅπασι γενέσθαι, καὶ παύσῃ ταῖς μὲν τῶν πόλεων οἰκείως ἔχων, πρὸς δὲ τὰς ἀλλοτρίως διακείμενος, ἔτι δ’ ἢν τὰ τοιαῦτα προαιρῇ πράττειν, ἐξ ὧν τοῖς μὲν Ἕλλησιν ἔσει πιστός, τοῖς δὲ βαρβάροις φοβερός.", "st": "5.80"}, {"sp": "N", "t": "καὶ μὴ θαυμάσῃς, ἅ περ ἐπέστειλα καὶ πρὸς Διονύσιον τὴν τυραννίδα κτησάμενον, εἰ μήτε στρατηγὸς ὢν μήτε ῥήτωρ μήτ’ ἄλλως δυνάστης θρασύτερόν σοι διείλεγμαι τῶν ἄλλων. ἐγὼ γὰρ πρὸς μὲν τὸ πολιτεύεσθαι πάντων ἀφυέστατος ἐγενόμην τῶν πολιτῶν (οὔτε γὰρ φωνὴν ἔσχον ἱκανὴν οὔτε τόλμαν δυναμένην ὄχλῳ χρῆσθαι καὶ μολύνεσθαι καὶ λοιδορεῖσθαι τοῖς ἐπὶ τοῦ βήματος κυλινδουμένοις),", "st": "5.81"}, {"sp": "N", "t": "τοῦ δὲ φρονεῖν εὖ καὶ πεπαιδεῦσθαι καλῶς, εἰ καί τις ἀγροικότερον εἶναι φήσει τὸ ῥηθέν, ἀμφισβητῶ, καὶ θείην ἂν ἐμαυτὸν οὐκ ἐν τοῖς ἀπολελειμμένοις ἀλλ’ ἐν τοῖς προέχουσι τῶν ἄλλων. διό περ ἐπιχειρῶ συμβουλεύειν τὸν τρόπον τοῦτον, ὃν ἐγὼ πέφυκα καὶ δύναμαι, καὶ τῇ πόλει καὶ τοῖς Ἕλλησι καὶ τῶν ἀνδρῶν τοῖς ἐνδοξοτάτοις.", "st": "5.82"}, {"sp": "N", "t": "περὶ μὲν οὖν τῶν ἐμῶν καὶ ὧν σοι πρακτέον ἐστὶ πρὸς τοὺς Ἕλληνας, σχεδὸν ἀκήκοας· περὶ δὲ τῆς στρατείας τῆς εἰς τὴν Ἀσίαν ταῖς μὲν πόλεσιν, ἃς ἔφην χρῆναί σε διαλλάττειν, τότε συμβουλεύσομεν ὡς χρὴ πολεμεῖν πρὸς τοὺς βαρβάρους, ὅταν ἴδωμεν αὐτὰς ὁμονοούσας, πρὸς σὲ δὲ νῦν ποιήσομαι τοὺς λόγους, οὐ τὴν αὐτὴν ἔχων διάνοιαν καὶ κατ’ ἐκείνην τὴν ἡλικίαν, ὅτ’ ἔγραφον περὶ τὴν αὐτὴν ὑπόθεσιν ταύτην.", "st": "5.83"}, {"sp": "N", "t": "τότε μὲν γὰρ παρεκελευόμην τοῖς ἀκουσομένοις καταγελᾶν μου καὶ καταφρονεῖν, ἢν μὴ καὶ τῶν πραγμάτων καὶ τῆς δόξης τῆς ἐμαυτοῦ καὶ τοῦ χρόνου τοῦ περὶ τὸν λόγον διατριφθέντος ἀξίως φαίνωμαι διεξιών· νῦν δὲ φοβοῦμαι μὴ πάντων τῶν προειρημένων πολὺ καταδεέστερον τύχω διαλεχθείς. καὶ γὰρ πρὸς τοῖς ἄλλοις ὁ λόγος ὁ πανηγυρικός, ὁ τοὺς ἄλλους τοὺς περὶ τὴν φιλοσοφίαν διατρίβοντας εὐπορωτέρους ποιήσας, ἐμοὶ πολλὴν ἀπορίαν παρέσχηκεν· οὔτε γὰρ ταὐτὰ βούλομαι λέγειν τοῖς ἐν ἐκείνῳ γεγραμμένοις, οὔτ’ ἔτι καινὰ δύναμαι ζητεῖν.", "st": "5.84"}, {"sp": "N", "t": "οὐ μὴν ἀποστατέον ἐστίν, ἀλλὰ λεκτέον περὶ ὧν ὑπεθέμην, ὅ τι ἂν ὑποπέσῃ καὶ συμφέρῃ πρὸς τὸ πεῖσαί σε ταῦτα πράττειν. καὶ γὰρ ἢν ἐλλίπω τι καὶ μὴ δυνηθῶ τὸν αὐτὸν τρόπον γράψαι τοῖς πρότερον ἐκδεδομένοις, ἀλλ’ οὖν ὑπογράψειν γ’ οἶμαι χαριέντως τοῖς ἐξεργάζεσθαι καὶ διαπονεῖν δυναμένοις.", "st": "5.85"}, {"sp": "N", "t": "τὴν μὲν οὖν ἀρχὴν τοῦ λόγου τοῦ σύμπαντος οἶμαι πεποιῆσθαι ταύτην, ἥν περ προσήκει τοὺς ἐπὶ τὴν Ἀσίαν πείθοντας στρατεύειν. δεῖ γὰρ μηδὲν πρότερον πράττειν, πρὶν ἂν λάβῃ τις τοὺς Ἕλληνας δυοῖν θάτερον, ἢ συναγωνιζομένους ἢ πολλὴν εὔνοιαν ἔχοντας τοῖς πραττομένοις. ὧν Ἀγησίλαος ὁ δόξας εἶναι Λακεδαιμονίων φρονιμώτατος ὠλιγώρησεν,", "st": "5.86"}, {"sp": "N", "t": "οὐ διὰ κακίαν, ἀλλὰ διὰ φιλοτιμίαν. ἔσχε γὰρ διττὰς ἐπιθυμίας, καλὰς μὲν ἀμφοτέρας, οὐ συμφωνούσας δ’ ἀλλήλαις οὐδ’ ἅμα πράττεσθαι δυναμένας. προῃρεῖτο γὰρ βασιλεῖ τε πολεμεῖν, καὶ τοὺς ἑταίρους εἰς τὰς πόλεις τὰς αὑτῶν καταγαγεῖν καὶ κυρίους ποιῆσαι τῶν πραγμάτων. συνέβαινεν οὖν ἐκ μὲν τῆς πραγματείας τῆς ὑπὲρ τῶν ἑταίρων ἐν κακοῖς καὶ κινδύνοις εἶναι τοὺς Ἕλληνας, διὰ δὲ τὴν ταραχὴν τὴν ἐνθάδε γιγνομένην μὴ σχολὴν ἄγειν μηδὲ δύνασθαι πολεμεῖν τοῖς βαρβάροις.", "st": "5.87"}, {"sp": "N", "t": "ὥστ’ ἐκ τῶν ἀγνοηθέντων κατ’ ἐκεῖνον τὸν χρόνον ῥᾴδιον καταμαθεῖν ὅτι δεῖ τοὺς ὀρθῶς βουλευομένους μὴ πρότερον ἐκφέρειν πρὸς βασιλέα πόλεμον, πρὶν ἂν διαλλάξῃ τις τοὺς Ἕλληνας καὶ παύσῃ τῆς μανίας τῆς νῦν αὐτοῖς ἐνεστώσης· ἅ περ καὶ σοὶ συμβεβουλευκότες τυγχάνομεν.", "st": "5.88"}, {"sp": "N", "t": "περὶ μὲν οὖν τούτων οὐδεὶς ἂν ἀντειπεῖν τῶν εὖ φρονούντων τολμήσειεν· οἶμαι δὲ τῶν μὲν ἄλλων εἴ τισι δόξειε περὶ τῆς στρατείας τῆς εἰς τὴν Ἀσίαν συμβουλεύειν, ἐπὶ ταύτην ἂν ἐπιπεσεῖν τὴν παράκλησιν, λέγοντας ὡς ὅσοι περ ἐπεχείρησαν πρὸς τὸν βασιλέα πολεμεῖν, ἅπασι συνέπεσεν ἐξ ἀδόξων μὲν γενέσθαι λαμπροῖς, ἐκ πενήτων δὲ πλουσίοις, ἐκ ταπεινῶν δὲ πολλῆς χώρας καὶ πόλεων δεσπόταις.", "st": "5.89"}, {"sp": "N", "t": "ἐγὼ δ’ οὐκ ἐκ τῶν τοιούτων μέλλω σε παρακαλεῖν, ἀλλ’ ἐκ τῶν ἠτυχηκέναι δοξάντων, λέγω δ’ ἐκ τῶν μετὰ Κύρου καὶ Κλεάρχου συστρατευσαμένων. ἐκείνους γὰρ ὁμολογεῖται νικῆσαι μὲν μαχομένους ἅπασαν τὴν βασιλέως δύναμιν τοσοῦτον, ὅσον περ ἂν εἰ ταῖς γυναιξὶν αὐτῶν συνέβαλον, ἤδη δ’ ἐγκρατεῖς δοκοῦντας εἶναι τῶν πραγμάτων διὰ τὴν Κύρου προπέτειαν ἀτυχῆσαι· περιχαρῆ γὰρ αὐτὸν ὄντα καὶ διώκοντα πολὺ πρὸ τῶν ἄλλων, ἐν μέσοις γενόμενον τοῖς πολεμίοις ἀποθανεῖν.", "st": "5.90"}, {"sp": "N", "t": "ἀλλ’ ὅμως τηλικαύτης συμφορᾶς συμπεσούσης οὕτω σφόδρα κατεφρόνησεν ὁ βασιλεὺς τῆς περὶ αὑτὸν δυνάμεως, ὥστε προκαλεσάμενος Κλέαρχον καὶ τοὺς ἄλλους ἡγεμόνας εἰς λόγον ἐλθεῖν, καὶ τούτοις μὲν ὑπισχνούμενος μεγάλας δωρεὰς δώσειν, τοῖς δ’ ἄλλοις στρατιώταις ἐντελῆ τὸν μισθὸν ἀποδοὺς ἀποπέμψειν, τοιαύταις ἐλπίσιν ὑπαγαγόμενος, καὶ πίστεις δοὺς τῶν ἐκεῖ νομιζομένων τὰς μεγίστας, συλλαβὼν αὐτοὺς ἀπέκτεινε, καὶ μᾶλλον εἵλετο περὶ τοὺς θεοὺς ἐξαμαρτεῖν ἢ τοῖς στρατιώταις οὕτως ἐρήμοις οὖσι συμβαλεῖν.", "st": "5.91"}, {"sp": "N", "t": "ὥστε τίς ἂν γένοιτο παράκλησις ταύτης καλλίων καὶ πιστοτέρα; φαίνονται γὰρ κἀκεῖνοι κρατήσαντες ἂν τῶν βασιλέως πραγμάτων, εἰ μὴ διὰ Κῦρον. σοὶ δὲ τήν τ’ ἀτυχίαν τὴν τότε γεγενημένην οὐ χαλεπὸν φυλάξασθαι, τοῦ τε στρατοπέδου τοῦ κρατήσαντος τὴν ἐκείνου δύναμιν ῥᾴδιον πολὺ κρεῖττον κατασκευάσασθαι. καίτοι τούτων ἀμφοτέρων ὑπαρξάντων πῶς οὐ χρὴ θαρρεῖν ποιούμενον τὴν στρατείαν ταύτην;", "st": "5.92"}, {"sp": "N", "t": "καὶ μηδεὶς ὑπολάβῃ με βούλεσθαι λαθεῖν, ὅτι τούτων ἔνια πέφρακα τὸν αὐτὸν τρόπον ὅν περ πρότερον. ἐπιστὰς γὰρ ἐπὶ τὰς αὐτὰς διανοίας εἱλόμην μὴ πονεῖν γλιχόμενος τὰ δεδηλωμένα καλῶς ἑτέρως εἰπεῖν· καὶ γὰρ εἰ μὲν ἐπίδειξιν ἐποιούμην, ἐπειρώμην ἂν ἅπαντα τὰ τοιαῦτα διαφεύγειν,", "st": "5.93"}, {"sp": "N", "t": "σοὶ δὲ συμβουλεύων μωρὸς ἂν ἦν, εἰ περὶ τὴν λέξιν πλείω χρόνον διέτριβον ἢ περὶ τὰς πράξεις, ἔτι δ’ εἰ τοὺς ἄλλους ὁρῶν τοῖς ἐμοῖς χρωμένους αὐτὸς μόνος ἀπειχόμην τῶν ὑπ’ ἐμοῦ πρότερον εἰρημένων. τοῖς μὲν οὖν οἰκείοις τυχὸν ἂν χρησαίμην, ἤν που σφόδρα κατεπείγῃ καὶ πρέπῃ, τῶν δ’ ἀλλοτρίων οὐδὲν ἂν προσδεξαίμην, ὥσπερ οὐδ’ ἐν τῷ παρελθόντι χρόνῳ.", "st": "5.94"}, {"sp": "N", "t": "ταῦτα μὲν οὖν οὕτως· δοκεῖ δέ μοι μετὰ ταῦτα περὶ τῆς παρασκευῆς διαλεκτέον εἶναι τῆς τε σοὶ γενησομένης καὶ τῆς ἐκείνοις ὑπαρξάσης. τὸ μὲν τοίνυν μέγιστον, σὺ μὲν τοὺς Ἕλληνας εὔνους ἕξεις, ἤν περ ἐθελήσῃς ἐμμεῖναι τοῖς περὶ τούτων εἰρημένοις, ἐκεῖνοι δὲ διὰ τὰς δεκαδαρχίας τὰς ἐπὶ Λακεδαιμονίων ὡς οἷόν τε δυσμενεστάτους. ἡγοῦντο γὰρ Κύρου μὲν καὶ Κλεάρχου κατορθωσάντων μᾶλλον ἔτι δουλεύσειν, βασιλέως δὲ κρατήσαντος ἀπαλλαγήσεσθαι τῶν κακῶν τῶν παρόντων· ὅ περ καὶ συνέπεσεν αὐτοῖς.", "st": "5.95"}, {"sp": "N", "t": "καὶ μὴν καὶ στρατιώτας σὺ μὲν ἐξ ἑτοίμου λήψει τοσούτους ὅσους ἂν βουληθῇς· οὕτω γὰρ ἔχει τὰ τῆς Ἑλλάδος, ὥστε ῥᾷον εἶναι συστῆσαι στρατόπεδον μεῖζον καὶ κρεῖττον ἐκ τῶν πλανωμένων ἢ τῶν πολιτευομένων· ἐν ἐκείνοις δὲ τοῖς χρόνοις οὐκ ἦν ξενικὸν οὐδέν, ὥστ’ ἀναγκαζόμενοι ξενολογεῖν ἐκ τῶν πόλεων πλέον ἀνήλισκον εἰς τὰς διδομένας τοῖς συλλέγουσι δωρεὰς ἢ τὴν εἰς τοὺς στρατιώτας μισθοφοράν.", "st": "5.96"}, {"sp": "N", "t": "καὶ μὴν εἰ βουληθεῖμεν ἐξετάσαι καὶ παραβαλεῖν σέ τε τὸν νῦν ἡγησόμενον τῆς στρατείας καὶ βουλευσόμενον περὶ ἁπάντων καὶ Κλέαρχον τὸν ἐπιστατήσαντα τῶν τότε πραγμάτων, εὑρήσομεν ἐκεῖνον μὲν οὐδεμιᾶς πώποτε δυνάμεως πρότερον οὔτε ναυτικῆς οὔτε πεζῆς καταστάντα κύριον, ἀλλ’ ἐκ τῆς ἀτυχίας τῆς συμβάσης αὐτῷ περὶ τὴν ἤπειρον ὀνομαστὸν γενόμενον,", "st": "5.97"}, {"sp": "N", "t": "σὲ δὲ τοσαῦτα καὶ τηλικαῦτα τὸ μέγεθος διαπεπραγμένον· περὶ ὧν εἰ μὲν πρὸς ἑτέρους τὸν λόγον ἐποιούμην, καλῶς ἂν εἶχε διελθεῖν, πρὸς σὲ δὲ διαλεγόμενος, εἰ τὰς σὰς πράξεις σοι διεξιοίην, δικαίως ἂν ἀνόητος ἅμα καὶ περίεργος εἶναι δοκοίην.", "st": "5.98"}, {"sp": "N", "t": "ἄξιον δὲ μνησθῆναι καὶ τῶν βασιλέων ἀμφοτέρων, ἐφ’ ὃν σοί τε συμβουλεύω στρατεύειν καὶ πρὸς ὃν Κλέαρχος ἐπολέμησεν, ἵν’ ἑκατέρου τὴν γνώμην καὶ τὴν δύναμιν εἰδῇς. ὁ μὲν τοίνυν τούτου πατὴρ τὴν πόλιν τὴν ἡμετέραν καὶ πάλιν τὴν Λακεδαιμονίων κατεπολέμησεν, οὗτος δ’ οὐδενὸς πώποτε τῶν στρατευμάτων τῶν τὴν χώραν αὐτοῦ λυμαινομένων ἐπεκράτησεν.", "st": "5.99"}, {"sp": "N", "t": "ἔπειθ’ ὁ μὲν τὴν Ἀσίαν ἅπασαν παρὰ τῶν Ἑλλήνων ἐν ταῖς συνθήκαις ἐξέλαβεν, οὗτος δὲ τοσούτου δεῖ τῶν ἄλλων ἄρχειν, ὥστ’ οὐδὲ τῶν ἐκδοθεισῶν αὐτῷ πόλεων ἐγκρατής ἐστιν. ὥστ’ οὐδεὶς ὅστις οὐκ ἂν ἀπορήσειε, πότερα χρὴ νομίζειν τοῦτον αὐτῶν ἀφεστάναι δι’ ἀνανδρίαν, ἢ ’κείνας ὑπερεωρακέναι καὶ καταπεφρονηκέναι τῆς βαρβαρικῆς δυναστείας.", "st": "5.100"}, {"sp": "N", "t": "τὰ τοίνυν περὶ τὴν χώραν ὡς διάκειται, τίς οὐκ ἂν ἀκούσας παροξυνθείη πολεμεῖν πρὸς αὐτόν; Αἴγυπτος γὰρ ἀφειστήκει μὲν καὶ κατ’ ἐκεῖνον τὸν χρόνον, οὐ μὴν ἀλλ’ ἐφοβοῦντο μή ποτε βασιλεὺς αὐτὸς ποιησάμενος στρατείαν κρατήσειε καὶ τῆς διὰ τὸν ποταμὸν δυσχωρίας καὶ τῆς ἄλλης παρασκευῆς ἁπάσης· νῦν δ’ οὗτος ἀπήλλαξεν αὐτοὺς τοῦ δέους τούτου. συμπαρασκευασάμενος γὰρ δύναμιν ὅσην οἷός τ’ ἦν πλείστην, καὶ στρατεύσας ἐπ’ αὐτούς, ἀπῆλθεν ἐκεῖθεν οὐ μόνον ἡττηθείς, ἀλλὰ καὶ καταγελασθεὶς καὶ δόξας οὔτε βασιλεύειν οὔτε στρατηγεῖν ἄξιος εἶναι.", "st": "5.101"}, {"sp": "N", "t": "τὰ τοίνυν περὶ Κύπρον καὶ Φοινίκην καὶ Κιλικίαν καὶ τὸν τόπον ἐκεῖνον, ὅθεν ἐχρῶντο ναυτικῷ, τότε μὲν ἦν βασιλέως, νῦν δὲ τὰ μὲν ἀφέστηκε, τὰ δ’ ἐν πολέμῳ καὶ κακοῖς τοσούτοις ἐστίν, ὥστ’ ἐκείνῳ μὲν μηδὲν εἶναι τούτων τῶν ἐθνῶν χρήσιμον, σοὶ δ’, ἢν πολεμεῖν πρὸς αὐτὸν βουληθῇς, συμφόρως ἕξειν.", "st": "5.102"}, {"sp": "N", "t": "καὶ μὴν Ἰδριέα γε τὸν εὐπορώτατον τῶν νῦν περὶ τὴν ἤπειρον προσήκει δυσμενέστερον εἶναι τοῖς βασιλέως πράγμασι τῶν πολεμούντων· ἢ πάντων γ’ ἂν εἴη σχετλιώτατος, εἰ μὴ βούλοιτο καταλελύσθαι ταύτην τὴν ἀρχήν, τὴν αἰκισαμένην μὲν τὸν ἀδελφόν, πολεμήσασαν δὲ πρὸς αὐτόν, ἅπαντα δὲ τὸν χρόνον ἐπιβουλεύουσαν καὶ βουλομένην τοῦ τε σώματος αὐτοῦ καὶ τῶν χρημάτων ἁπάντων γενέσθαι κυρίαν.", "st": "5.103"}, {"sp": "N", "t": "ὑπὲρ ὧν δεδιὼς νῦν μὲν ἀναγκάζεται θεραπεύειν αὐτὸν καὶ χρήματα πολλὰ καθ’ ἕκαστον τὸν ἐνιαυτὸν ἀναπέμπειν· εἰ δὲ σὺ διαβαίης εἰς τὴν ἤπειρον, ἐκεῖνός τ’ ἂν ἄσμενος ἴδοι βοηθὸν ἥκειν αὑτῷ σε νομίζων, τῶν τ’ ἄλλων σατραπῶν πολλοὺς ἀποστήσεις, ἢν ὑπόσχῃ τὴν ἐλευθερίαν αὐτοῖς, καὶ τοὔνομα τοῦτο διασπείρῃς εἰς τὴν Ἀσίαν, ὅ περ εἰς τοὺς Ἕλληνας εἰσπεσὸν καὶ τὴν ἡμετέραν καὶ τὴν Λακεδαιμονίων ἀρχὴν κατέλυσεν.", "st": "5.104"}, {"sp": "N", "t": "ἔτι δ’ ἂν πλείω λέγειν ἐπεχείρουν, ὃν τρόπον πολεμῶν τάχιστ’ ἂν περιγένοιο τῆς τοῦ βασιλέως δυνάμεως· νῦν δὲ φοβοῦμαι μή τινες ἐπιτιμήσωσιν ἡμῖν, εἰ μηδὲν πώποτε μεταχειρισάμενος τῶν στρατηγικῶν νῦν τολμῴην σοὶ παραινεῖν τῷ πλεῖστα καὶ μέγιστα διαπεπραγμένῳ κατὰ πόλεμον. ὥστε περὶ μὲν τούτων οὐδὲν οἶμαι δεῖν πλείω λέγειν. περὶ δὲ τῶν ἄλλων, ἡγοῦμαι τόν τε πατέρα σου καὶ τὸν κτησάμενον τὴν βασιλείαν καὶ τὸν τοῦ γένους ἀρχηγόν, εἰ τῷ μὲν εἴη θέμις, οἱ δὲ δύναμιν λάβοιεν, τῶν αὐτῶν ἂν τούτων γενέσθαι συμβούλους ὧν περ ἐγώ.", "st": "5.105"}, {"sp": "N", "t": "χρῶμαι δὲ τεκμηρίοις ἐξ ὧν διαπεπραγμένοι τυγχάνουσιν. ὅ τε γὰρ πατήρ σου πρὸς τὰς πόλεις ταύτας, αἷς σοὶ παραινῶ προσέχειν τὸν νοῦν, πρὸς ἁπάσας οἰκείως εἶχεν· ὅ τε κτησάμενος τὴν ἀρχήν, μεῖζον φρονήσας τῶν αὑτοῦ πολιτῶν καὶ μοναρχίας ἐπιθυμήσας, οὐχ ὁμοίως ἐβουλεύσατο τοῖς πρὸς τὰς τοιαύτας φιλοτιμίας ὁρμωμένοις.", "st": "5.106"}, {"sp": "N", "t": "οἱ μὲν γὰρ ἐν ταῖς αὑτῶν πόλεσι στάσεις καὶ ταραχὰς καὶ σφαγὰς ἐμποιοῦντες ἐκτῶντο τὴν τιμὴν ταύτην, ὁ δὲ τὸν μὲν τόπον τὸν Ἑλληνικὸν ὅλως εἴασε, τὴν δ’ ἐν Μακεδονίᾳ βασιλείαν κατασχεῖν ἐπεθύμησεν· ἠπίστατο γὰρ τοὺς μὲν Ἕλληνας οὐκ εἰθισμένους ὑπομένειν τὰς μοναρχίας, τοὺς δ’ ἄλλους οὐ δυναμένους ἄνευ τῆς τοιαύτης δυναστείας διοικεῖν τὸν βίον τὸν σφέτερον αὐτῶν.", "st": "5.107"}, {"sp": "N", "t": "καὶ γάρ τοι συνέβη διὰ τὸ γνῶναι περὶ τούτων αὐτὸν ἰδίως καὶ τὴν βασιλείαν γεγενῆσθαι πολὺ τῶν ἄλλων ἐξηλλαγμένην· μόνους γὰρ Ἑλλήνων οὐχ ὁμοφύλου γένους ἄρχειν ἀξιώσας μόνος καὶ διαφυγεῖν ἠδυνήθη τοὺς κινδύνους τοὺς περὶ τὰς μοναρχίας γιγνομένους. τοὺς μὲν γὰρ ἐν τοῖς Ἕλλησι τοιοῦτόν τι διαπεπραγμένους εὕροιμεν ἂν οὐ μόνον αὐτοὺς διεφθαρμένους, ἀλλὰ καὶ τὸ γένος αὐτῶν ἐξ ἀνθρώπων ἠφανισμένον, ἐκεῖνον δ’ αὐτόν τ’ ἐν εὐδαιμονίᾳ τὸν βίον διαγαγόντα, τῷ τε γένει καταλιπόντα τὰς αὐτὰς τιμὰς ἅσπερ αὐτὸς εἶχεν.", "st": "5.108"}, {"sp": "N", "t": "περὶ τοίνυν Ἡρακλέους, οἱ μὲν ἄλλοι τὴν ἀνδρίαν ὑμνοῦντες αὐτοῦ καὶ τοὺς ἄθλους ἀπαριθμοῦντες διατελοῦσι, περὶ δὲ τῶν ἄλλων· τῶν τῇ ψυχῇ προσόντων ἀγαθῶν οὐδεὶς οὔτε τῶν ποιητῶν οὔτε τῶν λογοποιῶν οὐδεμίαν φανήσεται μνείαν πεποιημένος. ἐγὼ δ’ ὁρῶμεν τόπον ἴδιον καὶ παντάπασιν ἀδιεξέργαστον, οὐ μικρὸν οὐδὲ κενόν, ἀλλὰ πολλῶν μὲν ἐπαίνων καὶ καλῶν πράξεων γέμοντα, ποθοῦντα δὲ τὸν ἀξίως ἂν δυνηθέντα διαλεχθῆναι περὶ αὐτῶν·", "st": "5.109"}, {"sp": "N", "t": "ἐφ’ ὃν εἰ μὲν νεώτερος ὢν ἐπέστην, ῥᾳδίως ἂν ἐπέδειξα τὸν πρόγονον ὑμῶν καὶ τῇ φρονήσει καὶ τῇ φιλοτιμίᾳ καὶ τῇ δικαιοσύνῃ πλέον διενεγκόντα πάντων τῶν προγεγενημένων ἢ τῇ ῥώμῃ τῇ τοῦ σώματος· νῦν δ’ ἐπελθὼν ἐπ’ αὐτόν, καὶ κατιδὼν τὸ πλῆθος τῶν ἐνόντων εἰπεῖν, τήν τε δύναμιν τὴν παροῦσάν μοι κατεμεμψάμην καὶ τὸν λόγον ᾐσθόμην διπλάσιον ἂν γενόμενον τοῦ νῦν ἀναγιγνωσκομένου. τῶν μὲν οὖν ἄλλων ἀπέστην διὰ τὰς αἰτίας ταύτας, μίαν δὲ πρᾶξιν ἐξ αὐτῶν ἔλαβον, ἥ περ ἦν προσήκουσα μὲν καὶ πρέπουσα τοῖς προειρημένοις, τὸν δὲ καιρὸν ἔχουσα μάλιστα σύμμετρον τοῖς νῦν λεγομένοις.", "st": "5.110"}, {"sp": "N", "t": "ἐκεῖνος γὰρ ὁρῶν τὴν Ἑλλάδα πολέμων καὶ στάσεων καὶ πολλῶν ἄλλων κακῶν μεστὴν οὖσαν, παύσας ταῦτα καὶ διαλλάξας τὰς πόλεις πρὸς ἀλλήλας ὑπέδειξε τοῖς ἐπιγιγνομένοις, μεθ’ ὧν χρὴ καὶ πρὸς οὓς δεῖ τοὺς πολέμους ἐκφέρειν. ποιησάμενος γὰρ στρατείαν ἐπὶ Τροίαν, ἥ περ εἶχε τότε μεγίστην δύναμιν τῶν περὶ τὴν Ἀσίαν, τοσοῦτον διήνεγκε τῇ στρατηγίᾳ τῶν πρὸς τὴν αὐτὴν ταύτην ὕστερον πολεμησάντων,", "st": "5.111"}, {"sp": "N", "t": "ὅσον οἱ μὲν μετὰ τῆς τῶν Ἑλλήνων δυνάμεως ἐν ἔτεσι δέκα μόλις αὐτὴν ἐξεπολιόρκησαν, ὁ δ’ ἐν ἡμέραις ἐλάττοσιν ἢ τοσαύταις καὶ μετ’ ὀλίγων στρατεύσας ῥᾳδίως αὐτὴν κατὰ κράτος εἷλεν. καὶ μετὰ ταῦτα τοὺς βασιλέας τῶν ἐθνῶν τῶν ἐφ’ ἑκατέρας τῆς ἠπείρου τὴν παραλίαν κατοικούντων ἅπαντας ἀπέκτεινεν· οὓς οὐδέποτ’ ἂν διέφθειρεν, εἰ μὴ καὶ τῆς δυνάμεως αὐτῶν ἐκράτησεν. ταῦτα δὲ πράξας τὰς στήλας τὰς Ἡρακλέους καλουμένας ἐποιήσατο, τροπαῖον μὲν τῶν βαρβάρων, μνημεῖον δὲ τῆς ἀρετῆς τῆς αὑτοῦ καὶ τῶν κινδύνων, ὅρους δὲ τῆς τῶν Ἑλλήνων χώρας.", "st": "5.112"}, {"sp": "N", "t": "τούτου δ’ ἕνεκά σοι περὶ τούτων διῆλθον, ἵνα γνῷς ὅτι σε τυγχάνω τῷ λόγῳ παρακαλῶν ἐπὶ τοιαύτας πράξεις, ἃς ἐπὶ τῶν ἔργων οἱ πρόγονοί σου φαίνονται καλλίστας προκρίναντες. ἅπαντας μὲν οὖν χρὴ τοὺς νοῦν ἔχοντας τὸν κράτιστον ὑποστησαμένους πειρᾶσθαι γίγνεσθαι τοιούτους, μάλιστα δὲ σοὶ προσήκει. τὸ γὰρ μὴ δεῖν ἀλλοτρίοις χρῆσθαι παραδείγμασιν, ἀλλ’ οἰκεῖον ὑπάρχειν, πῶς οὐκ εἰκὸς ὑπ’ αὐτοῦ σε παροξύνεσθαι, καὶ φιλονικεῖν ὅπως τῷ προγόνῳ σαυτὸν ὅμοιον παρασκευάσεις;", "st": "5.113"}, {"sp": "N", "t": "λέγω δ’ οὐχ ὡς δυνησόμενον ἁπάσας σε μιμήσασθαι τὰς Ἡρακλέους πράξεις (οὐδὲ γὰρ ἂν τῶν θεῶν ἔνιοι δυνηθεῖεν)· ἀλλὰ κατά γε τὸ τῆς ψυχῆς ἦθος καὶ τὴν φιλανθρωπίαν καὶ τὴν εὔνοιαν, ἣν εἶχεν εἰς τοὺς Ἕλληνας, δύναι’ ἂν ὁμοιωθῆναι τοῖς ἐκείνου βουλήμασιν. ἔστι δέ σοι πεισθέντι τοῖς ὑπ’ ἐμοῦ λεγομένοις τυχεῖν δόξης,", "st": "5.114"}, {"sp": "N", "t": "οἵας ἂν αὐτὸς βουληθῇς· ῥᾴδιον γάρ ἐστιν ἐκ τῶν παρόντων κτήσασθαι τὴν καλλίστην, ἢ ἐξ ὧν παρέλαβες ἐπὶ τὴν νῦν ὑπάρχουσαν προελθεῖν. σκέψαι δ’ ὅτι σε τυγχάνω παρακαλῶν, ἐξ ὧν ποιήσει τὰς στρατείας οὐ μετὰ τῶν βαρβάρων ἐφ’ οὓς οὐ δίκαιόν ἐστιν, ἀλλὰ μετὰ τῶν Ἑλλήνων ἐπὶ τούτους πρὸς οὓς προσήκει τοὺς ἀφ’ Ἡρακλέους γεγονότας πολεμεῖν.", "st": "5.115"}, {"sp": "N", "t": "καὶ μὴ θαυμάσῃς, εἰ διὰ παντός σε τοῦ λόγου πειρῶμαι προτρέπειν ἐπί τε τὰς εὐεργεσίας τὰς τῶν Ἑλλήνων καὶ πραότητα καὶ φιλανθρωπίαν· ὁρῶ γὰρ τὰς μὲν χαλεπότητας λυπηρὰς οὔσας καὶ τοῖς ἔχουσι καὶ τοῖς ἐντυγχάνουσι, τὰς δὲ πραότητας οὐ μόνον ἐπὶ τῶν ἀνθρώπων καὶ τῶν ἄλλων ζώων ἁπάντων εὐδοκιμούσας,", "st": "5.116"}, {"sp": "N", "t": "ἀλλὰ καὶ τῶν θεῶν τοὺς μὲν τῶν ἀγαθῶν αἰτίους ἡμῖν ὄντας Ὀλυμπίους προσαγορευομένους, τοὺς δ’ ἐπὶ ταῖς συμφοραῖς καὶ ταῖς τιμωρίαις τεταγμένους δυσχερεστέρας τὰς ἐπωνυμίας ἔχοντας, καὶ τῶν μὲν καὶ τοὺς ἰδιώτας καὶ τὰς πόλεις καὶ νεὼς καὶ βωμοὺς ἱδρυμένους, τοὺς δ’ οὔτ’ ἐν ταῖς εὐχαῖς οὔτ’ ἐν ταῖς θυσίαις τιμωμένους, ἀλλ’ ἀποπομπὰς αὐτῶν ἡμᾶς ποιουμένους.", "st": "5.117"}, {"sp": "N", "t": "ὧν ἐνθυμούμενον ἐθίζειν σαυτὸν χρή, καὶ μελετᾶν ὅπως ἔτι μᾶλλον ἢ νῦν τοιαύτην ἅπαντες περὶ σοῦ τὴν γνώμην ἕξουσιν. χρὴ δὲ τοὺς μείζονος δόξης τῶν ἄλλων ἐπιθυμοῦντας περιβάλλεσθαι μὲν τῇ διανοίᾳ τὰς πράξεις δυνατὰς μέν, εὐχῇ δ’ ὁμοίας, ἐξεργάζεσθαι δὲ ζητεῖν αὐτὰς ὅπως ἂν οἱ καιροὶ παραδιδῶσιν.", "st": "5.118"}, {"sp": "N", "t": "ἐκ πολλῶν δ’ ἂν κατανοήσειας ὅτι δεῖ τοῦτον τὸν τρόπον πράττειν, μάλιστα δ’ ἐκ τῶν Ἰάσονι συμβάντων. ἐκεῖνος γὰρ οὐδὲν τοιοῦτον οἷον σὺ κατεργασάμενος μεγίστης δόξης ἔτυχεν, οὐκ ἐξ ὧν ἔπραξεν, ἀλλ’ ἐξ ὧν ἔφησεν· ἐποιεῖτο γὰρ τοὺς λόγους ὡς εἰς τὴν ἤπειρον διαβησόμενος καὶ βασιλεῖ πολεμήσων.", "st": "5.119"}, {"sp": "N", "t": "ὅπου δ’ Ἰάσων λόγῳ μόνον χρησάμενος οὕτως αὑτὸν ηὔξησεν, ποίαν τινὰ χρὴ προσδοκᾶν περὶ σοῦ γνώμην αὐτοὺς ἕξειν, ἢν ἔργῳ ταῦτα πράξῃς, καὶ μάλιστα μὲν πειραθῇς ὅλην τὴν βασιλείαν ἑλεῖν, εἰ δὲ μή, χώραν ὅτι πλείστην ἀφορίσασθαι καὶ διαλαβεῖν τὴν Ἀσίαν, ὡς λέγουσί τινες, ἀπὸ Κιλικίας μέχρι Σινώπης, πρὸς δὲ τούτοις κτίσαι πόλεις ἐπὶ τούτῳ τῷ τόπῳ, καὶ κατοικίσαι τοὺς νῦν πλανωμένους δι’ ἔνδειαν τῶν καθ’ ἡμέραν καὶ λυμαινομένους οἷς ἂν ἐντύχωσιν.", "st": "5.120"}, {"sp": "N", "t": "οὓς εἰ μὴ παύσομεν ἀθροιζομένους βίον αὐτοῖς ἱκανὸν πορίσαντες, λήσουσιν ἡμᾶς τοσοῦτοι γενόμενοι τὸ πλῆθος, ὥστε μηδὲν ἧττον αὐτοὺς εἶναι φοβεροὺς τοῖς Ἕλλησιν ἢ τοῖς βαρβάροις· ὧν οὐδεμίαν ποιούμεθα πρόνοιαν, ἀλλ’ ἀγνοοῦμεν κοινὸν φόβον καὶ κίνδυνον ἅπασιν ἡμῖν αὐξανόμενον.", "st": "5.121"}, {"sp": "N", "t": "ἔστιν οὖν ἀνδρὸς μέγα φρονοῦντος καὶ φιλέλληνος καὶ πορρωτέρω τῶν ἄλλων τῇ διανοίᾳ καθορῶντος, ἀποχρησάμενον τοῖς τοιούτοις πρὸς τοὺς βαρβάρους, καὶ χώραν ἀποτεμόμενον τοσαύτην ὅσην ὀλίγῳ πρότερον εἰρήκαμεν, ἀπαλλάξαι τε τοὺς ξενιτευομένους τῶν κακῶν ὧν αὐτοί τ’ ἔχουσι καὶ τοῖς ἄλλοις παρέχουσι, καὶ πόλεις ἐξ αὐτῶν συστῆσαι, καὶ ταύταις ὁρίσαι τὴν Ἑλλάδα καὶ προβαλέσθαι πρὸ ἁπάντων ἡμῶν.", "st": "5.122"}, {"sp": "N", "t": "ταῦτα γὰρ πράξας οὐ μόνον ἐκείνους εὐδαίμονας ποιήσεις, ἀλλὰ καὶ πάντας ἡμᾶς εἰς ἀσφάλειαν καταστήσεις. ἢν δ’ οὖν τούτων διαμάρτῃς, ἀλλ’ ἐκεῖνό γε ῥᾳδίως ποιήσεις, τὰς πόλεις τὰς τὴν Ἀσίαν κατοικούσας ἐλευθερώσεις. ὅ τι δ’ ἂν τούτων πρᾶξαι δυνηθῇς ἢ καὶ μόνον ἐπιχειρήσῃς, οὐκ ἔσθ’ ὅπως οὐ μᾶλλον τῶν ἄλλων εὐδοκιμήσεις, καὶ δικαίως, ἤν περ αὐτός τ’ ἐπὶ ταῦθ’ ὁρμήσῃς καὶ τοὺς Ἕλληνας προτρέψῃς·", "st": "5.123"}, {"sp": "N", "t": "ἐπεὶ νῦν γε τίς οὐκ ἂν εἰκότως τὰ συμβεβηκότα θαυμάσειε καὶ καταφρονήσειεν ἡμῶν, ὅπου παρὰ μὲν τοῖς βαρβάροις, οὓς ὑπειλήφαμεν μαλακοὺς εἶναι καὶ πολέμων ἀπείρους καὶ διεφθαρμένους ὑπὸ τῆς τρυφῆς, ἄνδρες ἐγγεγόνασιν οἳ τῆς Ἑλλάδος ἄρχειν ἠξίωσαν, τῶν δ’ Ἑλλήνων οὐδεὶς τοσοῦτον πεφρόνηκεν ὥστ’ ἐπιχειρῆσαι τῆς Ἀσίας ἡμᾶς ποιῆσαι κυρίους,", "st": "5.124"}, {"sp": "N", "t": "ἀλλὰ τοσοῦτον αὐτῶν ἀπολελειμμένοι τυγχάνομεν, ὥστ’ ἐκεῖνοι μὲν οὐκ ὤκνησαν οὐδὲ προϋπάρξαι τῆς ἔχθρας τῆς πρὸς τοὺς Ἕλληνας, ἡμεῖς δ’ οὐδ’ ὑπὲρ ὧν κακῶς ἐπάθομεν ἀμύνεσθαι τολμῶμεν αὐτούς, ἀλλ’ ὁμολογούντων ἐκείνων ἐν ἅπασι τοῖς πολέμοις μήτε στρατιώτας ἔχειν μήτε στρατηγοὺς μήτ’ ἄλλο μηδὲν τῶν εἰς τοὺς κινδύνους χρησίμων,", "st": "5.125"}, {"sp": "N", "t": "ἀλλὰ ταῦτα πάντα παρ’ ἡμῶν μεταπεμπομένων, εἰς τοῦθ’ ἥκομεν ἐπιθυμίας τοῦ κακῶς ἡμᾶς αὐτοὺς ποιεῖν, ὥστ’ ἐξὸν ἡμῖν τἀκείνων ἀδεῶς ἔχειν πρὸς ἡμᾶς τ’ αὐτοὺς περὶ μικρῶν πολεμοῦμεν, καὶ τοὺς ἀφισταμένους τῆς ἀρχῆς τῆς βασιλέως συγκαταστρεφόμεθα, καὶ λελήθαμεν ἡμᾶς αὐτοὺς ἐνίοτε μετὰ τῶν πατρικῶν ἐχθρῶν τοὺς τῆς αὐτῆς συγγενείας μετέχοντας ἀπολλύναι ζητοῦντες.", "st": "5.126"}, {"sp": "N", "t": "διὸ καὶ σοὶ νομίζω συμφέρειν οὕτως ἀνάνδρως διακειμένων τῶν ἄλλων προστῆναι τοῦ πολέμου τοῦ πρὸς ἐκεῖνον. προσήκει δὲ τοῖς μὲν ἄλλοις τοῖς ἀφ’ Ἡρακλέους πεφυκόσι καὶ τοῖς ἐν πολιτείᾳ καὶ νόμοις ἐνδεδεμένοις ἐκείνην τὴν πόλιν στέργειν, ἐν ᾗ τυγχάνουσι κατοικοῦντες, σὲ δ’ ὥσπερ ἄφετον γεγενημένον ἅπασαν τὴν Ἑλλάδα πατρίδα νομίζειν, ὥσπερ ὁ γεννήσας ὑμᾶς, καὶ κινδυνεύειν ὑπὲρ αὐτῆς ὁμοίως ὥσπερ ὑπὲρ ὧν μάλιστα σπουδάζεις.", "st": "5.127"}, {"sp": "N", "t": "ἴσως δ’ ἄν τινες ἐπιτιμῆσαί μοι τολμήσειαν τῶν οὐδὲν ἄλλο δυναμένων ἢ τοῦτο ποιεῖν, ὅτι σὲ προειλόμην παρακαλεῖν ἐπί τε τὴν στρατείαν τὴν ἐπὶ τοὺς βαρβάρους καὶ τὴν ἐπιμέλειαν τὴν τῶν Ἑλλήνων, παραλιπὼν τὴν ἐμαυτοῦ πόλιν.", "st": "5.128"}, {"sp": "N", "t": "ἐγὼ δ’ εἰ μὲν πρὸς ἄλλους τινὰς πρότερον ἐπεχείρουν διαλέγεσθαι περὶ τούτων ἢ πρὸς τὴν πατρίδα τὴν αὑτοῦ τὴν τρὶς τοὺς Ἕλληνας ἐλευθερώσασαν, δὶς μὲν ἀπὸ τῶν βαρβάρων, ἅπαξ δ’ ἀπὸ τῆς Λακεδαιμονίων ἀρχῆς, ὡμολόγουν ἂν πλημμελεῖν· νῦν δ’ ἐκείνην μὲν φανήσομαι πρώτην ἐπὶ ταῦτα προτρέπων ὡς ἠδυνάμην μετὰ πλείστης σπουδῆς, αἰσθανόμενος δ’ ἔλαττον αὐτὴν φροντίζουσαν τῶν ὑπ’ ἐμοῦ λεγομένων ἢ τῶν ἐπὶ τοῦ βήματος μαινομένων ἐκείνην μὲν εἴασα, τῆς δὲ πραγματείας οὐκ ἀπέστην.", "st": "5.129"}, {"sp": "N", "t": "διὸ δικαίως ἄν με πάντες ἐπαινοῖεν ὅτι, τῇ δυνάμει ταύτῃ χρώμενος ἣν ἔχων τυγχάνω, διατετέλεκα πάντα τὸν χρόνον πολεμῶν μὲν τοῖς βαρβάροις, κατηγορῶν δὲ τῶν μὴ τὴν αὐτὴν ἐμοὶ γνώμην ἐχόντων, προτρέπειν δ’ ἐπιχειρῶν οὓς ἂν ἐλπίσω μάλιστα δυνήσεσθαι τοὺς μὲν Ἕλληνας ἀγαθόν τι ποιῆσαι, τοὺς δὲ βαρβάρους ἀφελέσθαι τὴν ὑπάρχουσαν εὐδαιμονίαν.", "st": "5.130"}, {"sp": "N", "t": "διόπερ καὶ νῦν πρὸς σὲ ποιοῦμαι τοὺς λόγους, οὐκ ἀγνοῶν ὅτι τούτοις ὑπ’ ἐμοῦ μὲν λεγομένοις πολλοὶ φθονήσουσι, τοῖς δ’ αὐτοῖς τούτοις ὑπὸ σοῦ πραττομένοις ἅπαντες συνησθήσονται. τῶν μὲν γὰρ εἰρημένων οὐδεὶς κεκοινώνηκε, τῶν δ’ ὠφελιῶν τῶν κατεργασθησομένων οὐκ ἔστιν ὅστις οὐκ οἰήσεται μεθέξειν.", "st": "5.131"}, {"sp": "N", "t": "σκέψαι δ’ ὡς αἰσχρὸν περιορᾶν τὴν Ἀσίαν ἄμεινον πράττουσαν τῆς Εὐρώπης καὶ τοὺς βαρβάρους εὐπορωτέρους τῶν Ἑλλήνων ὄντας, ἔτι δὲ τοὺς μὲν ἀπὸ Κύρου τὴν ἀρχὴν ἔχοντας, ὃν ἡ μήτηρ εἰς τὴν ὁδὸν ἐξέβαλε, βασιλέας μεγάλους προσαγορευομένους, τοὺς δ’ ἀφ’ Ἡρακλέους πεφυκότας, ὃν ὁ γεννήσας διὰ τὴν ἀρετὴν εἰς θεοὺς ἀνήγαγε, ταπεινοτέροις ὀνόμασιν ἢ ’κείνους προσαγορευομένους. ὧν οὐδὲν ἐατέον οὕτως ἔχειν, ἀλλ’ ἀναστρεπτέον καὶ μεταστατέον ἅπαντα ταῦτ’ ἐστίν.", "st": "5.132"}, {"sp": "N", "t": "εὖ δ’ ἴσθι μηδὲν ἄν με τούτων ἐπιχειρήσαντά σε πείθειν, εἰ δυναστείαν μόνον καὶ πλοῦτον ἑώρων ἐξ αὐτῶν γενησόμενον· ἡγοῦμαι γὰρ τά γε τοιαῦτα καὶ νῦν σοι πλείω τῶν ἱκανῶν ὑπάρχειν, καὶ πολλὴν ἀπληστίαν ἔχειν ὅς τις προαιρεῖται κινδυνεύειν ὥστ’ ἤ ταῦτα λαβεῖν ἢ στερηθῆναι τῆς ψυχῆς.", "st": "5.133"}, {"sp": "N", "t": "ἀλλὰ γὰρ οὐ πρὸς τὰς τούτων κτήσεις ἀποβλέψας ποιοῦμαι τοὺς λόγους, ἀλλ’ οἰόμενος ἐκ τούτων μεγίστην σοι καὶ καλλίστην γενήσεσθαι δόξαν. ἐνθυμοῦ δ’ ὅτι τὸ μὲν σῶμα θνητὸν ἅπαντες ἔχομεν, κατὰ δὲ τὴν εὔνοιαν καὶ τοὺς ἐπαίνους καὶ τὴν φήμην καὶ τὴν μνήμην τὴν τῷ χρόνῳ συμπαρακολουθοῦσαν ἀθανασίας μεταλαμβάνομεν, ἧς ἄξιον ὀρεγομένους καθ’ ὅσον οἷοί τ’ ἐσμὲν ὁτιοῦν πάσχειν.", "st": "5.134"}, {"sp": "N", "t": "ἴδοις δ’ ἂν καὶ τῶν ἰδιωτῶν τοὺς ἐπιεικεστάτους ὑπὲρ ἄλλου μὲν οὐδενὸς ἂν τὸ ζῆν ἀντικαταλλαξαμένους, ὑπὲρ δὲ τοῦ τυχεῖν καλῆς δόξης ἀποθνήσκειν ἐν τοῖς πολέμοις ἐθέλοντας, ὅλως δὲ τοὺς μὲν τιμῆς ἐπιθυμοῦντας ἀεὶ μείζονος ἧς ἔχουσιν ὑπὸ πάντων ἐπαινουμένους, τοὺς δὲ πρὸς ἄλλο τι τῶν ὄντων ἀπλήστως διακειμένους ἀκρατεστέρους καὶ φαυλοτέρους εἶναι δοκοῦντας.", "st": "5.135"}, {"sp": "N", "t": "τὸ δὲ μέγιστον τῶν εἰρημένων, ὅτι συμβαίνει τοῦ μὲν πλούτου καὶ τῶν δυναστειῶν πολλάκις τοὺς ἐχθροὺς κυρίους γίγνεσθαι, τῆς δ’ εὐνοίας τῆς παρὰ τῶν πολιτῶν καὶ τῶν ἄλλων τῶν προειρημένων μηδένας ἄλλους καταλείπεσθαι κληρονόμους πλὴν τοὺς ἐξ ἡμῶν γεγονότας. ὥστ’ ᾐσχυνόμην ἄν, εἰ μὴ τούτων ἕνεκα συνεβούλευον καὶ τὴν στρατείαν ποιεῖσθαι ταύτην καὶ πολεμεῖν καὶ κινδυνεύειν.", "st": "5.136"}, {"sp": "N", "t": "οὕτω δ’ ἄριστα βουλεύσει περὶ τούτων, ἢν ὑπολάβῃς μὴ μόνον τὸν λόγον τοῦτόν σε παρακαλεῖν, ἀλλὰ καὶ τοὺς προγόνους καὶ τὴν τῶν βαρβάρων ἀνανδρίαν καὶ τοὺς ὀνομαστοτάτους γενομένους καὶ δόξαντας ἡμιθέους εἶναι διὰ τὴν στρατείαν τὴν ἐπ’ ἐκείνους, μάλιστα δὲ πάντων τὸν καιρόν, ἐν ᾧ σὺ μὲν τυγχάνεις τοσαύτην δύναμιν κεκτημένος ὅσην οὐδεὶς τῶν τὴν Εὐρώπην κατοικησάντων, πρὸς ὃν δὲ πολεμήσεις, οὕτω σφόδρα μεμισημένος καὶ καταπεφρονημένος ὑφ’ ἁπάντων ὡς οὐδεὶς πώποτε τῶν βασιλευσάντων.", "st": "5.137"}, {"sp": "N", "t": "πρὸ πολλοῦ δ’ ἂν ἐποιησάμην οἷόν τ’ εἶναι συνερᾶσαι τοὺς λόγους ἅπαντας τοὺς ὑπ’ ἐμοῦ περὶ τούτων εἰρημένους· μᾶλλον γὰρ ἂν ἄξιος οὗτος ἔδοξεν εἶναι τῆς ὑποθέσεως. οὐ μὴν ἀλλὰ σέ γε χρὴ σκοπεῖν ἐξ ἁπάντων τὰ συντείνοντα καὶ προτρέποντα πρὸς τὸν πόλεμον τοῦτον· οὕτω γὰρ ἂν ἄριστα βουλεύσαιο περὶ αὐτῶν.", "st": "5.138"}, {"sp": "N", "t": "οὐκ ἀγνοῶ δ’ ὅτι πολλοὶ τῶν Ἑλλήνων τὴν βασιλέως δύναμιν ἄμαχον εἶναι νομίζουσιν· ὧν ἄξιον θαυμάζειν, εἰ τὴν ὑπ’ ἀνθρώπου βαρβάρου καὶ κακῶς τεθραμμένου κατασταθεῖσαν καὶ συναχθεῖσαν ἐπὶ δουλείᾳ, ταύτην ὑπ’ ἀνδρὸς Ἕλληνος καὶ περὶ τοὺς πολέμους πολλὴν ἐμπειρίαν ἔχοντος μὴ νομίζουσιν ἂν ἐπ’ ἐλευθερίᾳ διαλυθῆναι, καὶ ταῦτ’ εἰδότες ὅτι συστῆσαι μέν ἐστιν ἅπαντα χαλεπόν, διαστῆσαι δὲ ῥᾴδιον.", "st": "5.139"}, {"sp": "N", "t": "ἐνθυμοῦ δ’ ὅτι μάλιστα τούτους τιμῶσιν ἅπαντες καὶ θαυμάζουσιν, οἵτινες ἀμφότερα δύνανται, καὶ πολιτεύεσθαι καὶ στρατηγεῖν. ὅταν οὖν ὁρᾷς τοὺς ἐν μιᾷ πόλει ταύτην ἔχοντας τὴν φύσιν εὐδοκιμοῦντας, ποίους τινὰς χρὴ προσδοκᾶν τοὺς ἐπαίνους ἔσεσθαι τοὺς περὶ σοῦ ῥηθησομένους, ὅταν φαίνῃ ταῖς μὲν εὐεργεσίαις ἐν ἅπασι τοῖς Ἕλλησι πεπολιτευμένος, ταῖς δὲ στρατηγίαις τοὺς βαρβάρους κατεστραμμένος;", "st": "5.140"}, {"sp": "N", "t": "ἐγὼ μὲν γὰρ ἡγοῦμαι ταῦτα πέρας ἕξειν· οὐδένα γὰρ ἄλλον ποτὲ δυνήσεσθαι μείζω πρᾶξαι τούτων· οὔτε γὰρ ἐν τοῖς Ἕλλησι γενήσεσθαι τηλικοῦτον ἔργον, ὅσον ἐστὶ τὸ πάντας ἡμᾶς ἐκ τοσούτων πολέμων ἐπὶ τὴν ὁμόνοιαν προαγαγεῖν, οὔτε τοῖς βαρβάροις εἰκός ἐστι συστῆναι τηλικαύτην δύναμιν, ἢν τὴν νῦν ὑπάρχουσαν καταλύσῃς.", "st": "5.141"}, {"sp": "N", "t": "ὥστε τῶν μὲν ἐπιγιγνομένων οὐδ’ ἤν τις τῶν ἄλλων διενέγκῃ τὴν φύσιν, οὐδὲν ἕξει ποιῆσαι τοιοῦτον. ἀλλὰ μὴν τῶν γε προγεγενημένων ἔχω μὲν ὑπερβαλεῖν τὰς πράξεις τοῖς ἤδη διὰ σοῦ κατειργασμένοις, οὐ γλίσχρως, ἀλλ’ ἀληθινῶς· ὅστις γὰρ ἔθνη τοσαῦτα τυγχάνεις κατεστραμμένος ὅσας οὐδεὶς πώποτε τῶν Ἑλλήνων πόλεις εἷλε, πῶς οὐκ ἂν πρὸς ἕκαστον αὐτῶν ἀντιπαραβάλλων ῥᾳδίως ἂν ἐπέδειξα μείζω σε κἀκείνων διαπεπραγμένον;", "st": "5.142"}, {"sp": "N", "t": "ἀλλὰ γὰρ εἱλόμην ἀποσχέσθαι τῆς τοιαύτης ἰδέας δι’ ἀμφότερα, διά τε τοὺς οὐκ εὐκαίρως αὐτῇ χρωμένους, καὶ διὰ τὸ μὴ βούλεσθαι ταπεινοτέρους ποιεῖν τῶν νῦν ὄντων τοὺς ἡμιθέους εἶναι νομιζομένους.", "st": "5.143"}, {"sp": "N", "t": "ἐνθυμοῦ δ’, ἵνα τι καὶ τῶν ἀρχαίων εἴπωμεν, ὅτι τὸν Ταντάλου πλοῦτον καὶ τὴν Πέλοπος ἀρχὴν καὶ τὴν Εὐρυσθέως δύναμιν οὐδεὶς ἂν οὔτε λόγων εὑρετὴς οὔτε ποιητὴς ἐπαινέσειεν, ἀλλὰ μετά γε τὴν Ἡρακλέους ὑπερβολὴν καὶ τὴν Θησέως ἀρετὴν τοὺς ἐπὶ Τροίαν στρατευσαμένους καὶ τοὺς ἐκείνοις ὁμοίους γενομένους ἅπαντες ἂν εὐλογήσειαν.", "st": "5.144"}, {"sp": "N", "t": "καίτοι τοὺς ὀνομαστοτάτους καὶ τοὺς ἀρίστους αὐτῶν ἴσμεν ἐν μικροῖς πολιχνίοις καὶ νησυδρίοις τὰς ἀρχὰς κατασχόντας. ἀλλ’ ὅμως ἰσόθεον καὶ παρὰ πᾶσιν ὀνομαστὴν τὴν αὑτῶν δόξαν κατέλιπον· ἅπαντες γὰρ φιλοῦσιν οὐ τοὺς σφίσιν αὐτοῖς μεγίστην δυναστείαν κτησαμένους, ἀλλὰ τοὺς τοῖς Ἕλλησι πλείστων ἀγαθῶν αἰτίους γεγενημένους.", "st": "5.145"}, {"sp": "N", "t": "οὐ μόνον δ’ ἐπὶ τούτων αὐτοὺς ὄψει τὴν γνώμην ταύτην ἔχοντας, ἀλλ’ ἐπὶ πάντων ὁμοίως· ἐπεὶ καὶ τὴν πόλιν ἡμῶν οὐδεὶς ἂν ἐπαινέσειεν, οὔθ’ ὅτι τῆς θαλάττης ἦρξεν οὔθ’ ὅτι τοσοῦτον πλῆθος χρημάτων εἰσπράξασα τοὺς συμμάχους εἰς τὴν ἀκρόπολιν ἀνήνεγκεν, ἀλλὰ μὴν οὐδ’ ὅτι πολλῶν πόλεων ἐξουσίαν ἔλαβε, τὰς μὲν ἀναστάτους ποιῆσαι, τὰς δ’ αὐξῆσαι, τὰς δ’ ὅπως ἐβουλήθη διοικῆσαι·", "st": "5.146"}, {"sp": "N", "t": "πάντα γὰρ ταῦτα παρῆν αὐτῇ πράττειν· ἀλλ’ ἐκ τούτων μὲν πολλαὶ κατηγορίαι κατ’ αὐτῆς γεγόνασιν, ἐκ δὲ τῆς Μαραθῶνι μάχης καὶ τῆς ἐν Σαλαμῖνι ναυμαχίας, καὶ μάλισθ’ ὅτι τὴν αὑτῶν ἐξέλιπον ὑπὲρ τῆς τῶν Ἑλλήνων σωτηρίας, ἅπαντες αὐτὴν ἐγκωμιάζουσιν.", "st": "5.147"}, {"sp": "N", "t": "τὴν αὐτὴν δὲ γνώμην καὶ περὶ Δακεδαιμονίων ἔχουσιν· καὶ γὰρ ἐκείνων μᾶλλον ἄγανται τὴν ἧτταν τὴν ἐν Θερμοπύλαις ἢ τὰς ἄλλας νίκας, καὶ τὸ τρόπαιον τὸ μὲν κατ’ ἐκείνων ὑπὸ τῶν βαρβάρων σταθὲν ἀγαπῶσι καὶ θεωροῦσι, τὰ δ’ ὑπὸ Δακεδαιμονίων κατὰ τῶν ἄλλων οὐκ ἐπαινοῦσιν ἀλλ’ ἀηδῶς ὁρῶσιν· ἡγοῦνται γὰρ τὸ μὲν ἀρετῆς εἶναι σημεῖον, τὰ δὲ πλεονεξίας.", "st": "5.148"}, {"sp": "N", "t": "ταῦτ’ οὖν ἐξετάσας ἅπαντα καὶ διελθὼν πρὸς αὑτόν, ἢν μέν τι τῶν εἰρημένων ᾖ μαλακώτερον ἢ καταδεέστερον, αἰτιῶ τὴν ἡλικίαν τὴν ἐμήν, ᾗ δικαίως ἂν ἅπαντες συγγνώμην ἔχοιεν· ἢν δ’ ὅμοια τοῖς πρότερον διαδεδομένοις, νομίζειν αὐτὰ χρὴ μὴ τὸ γῆρας τοὐμὸν εὑρεῖν ἀλλὰ τὸ δαιμόνιον ὑποβαλεῖν, οὐκ ἐμοῦ φροντίζον, ἀλλὰ τῆς Ἑλλάδος κηδόμενον, καὶ βουλόμενον ταύτην τε τῶν κακῶν ἀπαλλάξαι τῶν παρόντων καὶ σοὶ πολὺ μείζω περιθεῖναι δόξαν τῆς νῦν ὑπαρχούσης.", "st": "5.149"}, {"sp": "N", "t": "οἶμαι δέ σ’ οὐκ ἀγνοεῖν ὃν τρόπον οἱ θεοὶ τὰ τῶν ἀνθρώπων διοικοῦσιν. οὐ γὰρ αὐτόχειρες οὔτε τῶν ἀγαθῶν οὔτε τῶν κακῶν γίγνονται τῶν συμβαινόντων αὐτοῖς, ἀλλ’ ἑκάστοις τοιαύτην ἔννοιαν ἐμποιοῦσιν,", "st": "5.150"}, {"sp": "N", "t": "ὥστε δι’ ἀλλήλων ἡμῖν ἑκάτερα παραγίγνεσθαι τούτων. οἷον ἴσως καὶ νῦν τοὺς μὲν λόγους ἡμῖν ἀπένειμαν, ἐπὶ δὲ τὰς πράξεις σὲ τάττουσι, νομίζοντες τούτων μὲν σὲ κάλλιστ’ ἂν ἐπιστατῆσαι, τὸν δὲ λόγον τὸν ἐμὸν ἥκιστ’ ἂν ὀχληρὸν γενέσθαι τοῖς ἀκούουσιν. ἡγοῦμαι δὲ καὶ τὰ πεπραγμένα πρότερον οὐκ ἄν ποτέ σοι γενέσθαι τηλικαῦτα τὸ μέγεθος, εἰ μή τις θεῶν αὐτὰ συγκατώρθωσεν,", "st": "5.151"}, {"sp": "N", "t": "οὐχ ἵνα τοῖς βαρβάροις μόνον τοῖς ἐπὶ τῆς Εὐρώπης κατοικοῦσι πολεμῶν διατελῇς, ἀλλ’ ὅπως ἂν ἐν τούτοις γυμνασθεὶς καὶ λαβὼν ἐμπειρίαν καὶ γνωσθεὶς οἷος εἶ τούτων ἐπιθυμήσῃς ὧν ἐγὼ τυγχάνω συμβεβουλευκώς. αἰσχρὸν οὖν ἐστι καλῶς τῆς τύχης ἡγουμένης ἀπολειφθῆναι, καὶ μὴ παρασχεῖν σαυτὸν εἰς ὃ βούλεταί σε προαγαγεῖν.", "st": "5.152"}, {"sp": "N", "t": "νομίζω δὲ χρῆναί σε πάντας μὲν τιμᾶν τοὺς περὶ τῶν σοι πεπραγμένων ἀγαθόν τι λέγοντας, κάλλιστα μέντοι νομίζειν ἐκείνους ἐγκωμιάζειν, τοὺς μειζόνων ἔργων ἢ τηλικούτων τὴν σὴν φύσιν ἀξιοῦντας, καὶ τοὺς μὴ μόνον ἐν τῷ παρόντι κεχαρισμένως διειλεγμένους, ἀλλ’ οἵ τινες ἂν τοὺς ἐπιγιγνομένους οὕτω ποιήσωσι τὰς σὰς πράξεις θαυμάζειν ὡς οὐδενὸς ἄλλου τῶν προγεγενημένων. πολλὰ δὲ βουλόμενος τοιαῦτα λέγειν οὐ δύναμαι· τὴν δ’ αἰτίαν δι’ ἥν, πλεονάκις τοῦ δέοντος εἴρηκα.", "st": "5.153"}, {"sp": "N", "t": "λοιπὸν οὖν ἐστι τὰ προειρημένα συναγαγεῖν, ἵν’ ὡς ἐν ἐλαχίστοις κατίδοις τὸ κεφάλαιον τῶν συμβεβουλευμένων. φημὶ γὰρ χρῆναί σε τοὺς μὲν Ἕλληνας εὐεργετεῖν, Μακεδόνων δὲ βασιλεύειν, τῶν δὲ βαρβάρων ὡς πλείστων ἄρχειν. ἢν γὰρ ταῦτα πράττῃς, ἅπαντές σοι χάριν ἕξουσιν, οἱ μὲν Ἕλληνες ὑπὲρ ὧν εὖ πάσχουσι, Μακεδόνες δ’ ἢν βασιλικῶς ἀλλὰ μὴ τυραννικῶς αὐτῶν ἐπιστατῇς, τὸ δὲ τῶν ἄλλων γένος, ἢν διὰ σὲ βαρβαρικῆς δεσποτείας ἀπαλλαγέντες Ἑλληνικῆς ἐπιμελείας τύχωσι.", "st": "5.154"}, {"sp": "N", "t": "ταῦθ’ ὅπως μὲν γέγραπται τοῖς καιροῖς καὶ ταῖς ἀκριβείαις, παρ’ ὑμῶν τῶν ἀκουόντων πυνθάνεσθαι δίκαιόν ἐστιν· ὅτι μέντοι βελτίω τούτων καὶ μᾶλλον ἁρμόττοντα τοῖς ὑπάρχουσιν οὐδεὶς ἄν σοι συμβουλεύσειεν, σαφῶς εἰδέναι νομίζω.", "st": "5.155"}, {"sp": "HDR", "t": "Ἀρχίδαμος", "st": "6"}, {"sp": "N", "t": "ἴσως τινὲς ὑμῶν θαυμάζουσιν ὅτι τὸν ἄλλον χρόνον ἐμμεμενηκὼς τοῖς τῆς πόλεως νομίμοις ὡς οὐκ οἶδ’ εἴ τις ἄλλος τῶν ἡλικιωτῶν, τοσαύτην πεποίημαι τὴν μεταβολὴν ὥστε περὶ ὧν ὀκνοῦσιν οἱ πρεσβύτεροι λέγειν, περὶ τούτων νεώτερος ὢν παρελήλυθα συμβουλεύσων.", "st": "6.1"}, {"sp": "N", "t": "ἐγὼ δ’, εἰ μέν τις τῶν εἰθισμένων ἐν ὑμῖν ἀγορεύειν ἀξίως ἦν τῆς πόλεως εἰρηκώς, πολλὴν ἂν ἡσυχίαν ἦγον· νῦν δ’ ὁρῶν τοὺς μὲν συναγορεύοντας οἷς οἱ πολέμιοι προστάττουσι, τοὺς δ’ οὐκ ἐρρωμένως ἐναντιουμένους, τοὺς δὲ παντάπασιν ἀποσεσιωπηκότας, ἀνέστην ἀποφανούμενος ἃ γιγνώσκω περὶ τούτων, αἰσχρὸν νομίσας, εἰ τὴν ἰδίαν τοῦ βίου τάξιν διαφυλάττων περιόψομαι τὴν πόλιν ἀνάξια ψηφισαμένην ἑαυτῆς.", "st": "6.2"}, {"sp": "N", "t": "ἡγοῦμαι δ’, εἰ καὶ περὶ τῶν ἄλλων πρέπει τοὺς τηλικούτους σιωπᾶν, περί γε τοῦ πολεμεῖν ἢ μὴ προσήκειν τούτους μάλιστα συμβουλεύειν, οἵπερ καὶ τῶν κινδύνων πλεῖστον μέρος μεθέξουσιν, ἄλλως τε δὴ καὶ τοῦ γνῶναί τι τῶν δεόντων ἐν κοινῷ καθεστῶτος ἡμῖν.", "st": "6.3"}, {"sp": "N", "t": "εἰ μὲν γὰρ ἦν δεδειγμένον, ὥστε τοὺς μὲν πρεσβυτέρους περὶ ἁπάντων εἰδέναι τὸ βέλτιστον, τοὺς δὲ νεωτέρους μηδὲ περὶ ἑνὸς ὀρθῶς γιγνώσκειν, καλῶς ἂν εἶχεν ἀπείργειν ἡμᾶς τοῦ συμβουλεύειν· ἐπειδὴ δ’ οὐ τῷ πλήθει τῶν ἐτῶν πρὸς τὸ φρονεῖν εὖ διαφέρομεν ἀλλήλων, ἀλλὰ τῇ φύσει καὶ ταῖς ἐπιμελείαις, πῶς οὐκ ἀμφοτέρων χρὴ τῶν ἡλικιῶν πεῖραν λαμβάνειν, ἵν’ ἐξ ἁπάντων ὑμῖν ἐξῇ τῶν ῥηθέντων ἑλέσθαι τὰ συμφορώτατα;", "st": "6.4"}, {"sp": "N", "t": "θαυμάζω δ’ ὅσοι τριήρων μὲν ἡγεῖσθαι καὶ στρατοπέδων ἄρχειν ἀξιοῦσιν ἡμᾶς, ὑπὲρ ὧν μὴ καλῶς βουλευσάμενοι πολλαῖς ἂν συμφοραῖς καὶ μεγάλαις τὴν πόλιν περιβάλοιμεν, εἰπεῖν δ’ ἃ γιγνώσκομεν περὶ ὧν ὑμεῖς μέλλετε κρίνειν οὐκ οἴονται δεῖν ἡμᾶς, ἐν οἷς κατορθώσαντες μὲν ἅπαντας ὑμᾶς ὠφελήσομεν, διαμαρτόντες δὲ τῆς ὑμετέρας γνώμης αὐτοὶ μὲν ἴσως φαυλότεροι δόξομεν εἶναι, τὸ δὲ κοινὸν οὐδὲν ἂν ζημιώσαιμεν.", "st": "6.5"}, {"sp": "N", "t": "οὐ μὴν ὡς ἐπιθυμῶν τοῦ λέγειν, οὐδ’ ὡς ἄλλως πως παρεσκευασμένος ζῆν ἢ τὸν παρελθόντα χρόνον, οὕτως εἴρηκα περὶ τούτων, ἀλλὰ βουλόμενος ὑμᾶς προτρέψαι μηδεμίαν ἀποδοκιμάζειν τῶν ἡλικιῶν, ἀλλ’ ἐν ἁπάσαις ζητεῖν εἴ τίς τι δύναται περὶ τῶν παρόντων πραγμάτων εἰπεῖν ἀγαθόν·", "st": "6.6"}, {"sp": "N", "t": "ὡς ἐξ οὗ τὴν πόλιν οἰκοῦμεν, οὐδεὶς οὔτε κίνδυνος οὔτε πόλεμος περὶ τοσούτων τὸ μέγεθος ἡμῖν γέγονε, περὶ ὅσων νυνὶ βουλευσόμενοι συνεληλύθαμεν. πρότερον μὲν γὰρ ὑπὲρ τοῦ τῶν ἄλλων ἄρχειν ἠγωνιζόμεθα, νῦν δ’ ὑπὲρ τοῦ μὴ ποιεῖν αὐτοὶ τὸ προσταττόμενον· ὃ σημεῖον ἐλευθερίας ἐστίν, ὑπὲρ ἧς οὐδὲν ὅ τι τῶν δεινῶν οὐχ ὑπομενετέον, οὐ μόνον ἡμῖν, ἀλλὰ καὶ τοῖς ἄλλοις τοῖς μὴ λίαν ἀνάνδρως διακειμένοις ἀλλὰ καὶ κατὰ μικρὸν ἀρετῆς ἀντιποιουμένοις.", "st": "6.7"}, {"sp": "N", "t": "ἐγὼ μὲν οὖν, εἰ δεῖ τοὐμὸν ἴδιον εἰπεῖν, ἑλοίμην ἂν ἀποθανεῖν ἤδη μὴ ποιήσας τὸ προσταττόμενον μᾶλλον ἢ πολλαπλάσιον χρόνον ζῆν τοῦ τεταγμένου ψηφισάμενος ἃ Θηβαῖοι κελεύουσιν· αἰσχυνοίμην γὰρ ἄν, εἰ γεγονὼς μὲν ἀφ’ Ἡρακλέους, τοῦ δὲ πατρὸς βασιλεύοντος, αὐτὸς δ’ ἐπίδοξος ὢν τυχεῖν τῆς τιμῆς ταύτης, περιίδοιμι, καθ’ ὅσον ἐστὶν ἐπ’ ἐμοί, τὴν χώραν ἣν ἡμῖν οἱ πατέρες κατέλιπον, ταύτην τοὺς οἰκέτας τοὺς ἡμετέρους ἔχοντας.", "st": "6.8"}, {"sp": "N", "t": "ἀξιῶ δὲ καὶ ὑμᾶς τὴν αὐτὴν ἐμοὶ γνώμην ἔχειν, ἐνθυμηθέντας ὅτι μέχρι μὲν ταυτησὶ τῆς ἡμέρας δεδυστυχηκέναι δοκοῦμεν ἐν τῇ μάχῃ τῇ πρὸς Θηβαίους, καὶ τοῖς μὲν σώμασι κρατηθῆναι διὰ τὸν οὐκ ὀρθῶς ἡγησάμενον, τὰς δὲ ψυχὰς ἔτι καὶ νῦν ἀηττήτους ἔχειν,", "st": "6.9"}, {"sp": "N", "t": "εἰ δὲ φοβηθέντες τοὺς ἐπιόντας κινδύνους προησόμεθά τι τῶν ἡμετέρων αὐτῶν, βεβαιώσομεν τὰς Θηβαίων ἀλαζονείας καὶ πολὺ σεμνότερον τρόπαιον τοῦ περὶ Λεῦκτρα καὶ φανερώτερον στήσομεν καθ’ ἡμῶν αὐτῶν· τὸ μὲν γὰρ ἀτυχίας, τὸ δὲ τῆς ἡμετέρας διανοίας ἔσται γεγενημένον. μηδεὶς οὖν ὑμᾶς πείσῃ τοιαύταις αἰσχύναις τὴν πόλιν περιβαλεῖν.", "st": "6.10"}, {"sp": "N", "t": "καίτοι λίαν προθύμως οἱ σύμμαχοι συμβεβουλεύκασιν ὑμῖν ὡς χρὴ Μεσσήνην ἀφέντας ποιήσασθαι τὴν εἰρήνην. οἷς ὑμεῖς δικαίως ἂν ὀργίζοισθε πολὺ μᾶλλον ἢ τοῖς ἐξ ἀρχῆς ἀποστᾶσιν ἡμῶν. ἐκεῖνοι μὲν γὰρ ἀφέμενοι τῆς ἡμετέρας φιλίας τὰς αὑτῶν πόλεις ἀπώλεσαν, εἰς στάσεις καὶ σφαγὰς καὶ πολιτείας πονηρὰς ἐμβαλόντες, οὗτοι δ’ ἡμᾶς ἥκουσι κακῶς ποιήσοντες·", "st": "6.11"}, {"sp": "N", "t": "τὴν γὰρ δόξαν, ἣν ἡμῖν οἱ πρόγονοι μετὰ πολλῶν κινδύνων ἐν ἑπτακοσίοις ἔτεσι κτησάμενοι κατέλιπον, ταύτην ἐν ὀλίγῳ χρόνῳ πείθουσιν ἡμᾶς ἀποβαλεῖν, ἧς οὔτ’ ἀπρεπεστέραν τῇ Λακεδαίμονι συμφορὰν οὔτε δεινοτέραν οὐδέποτ’ ἂν εὑρεῖν ἠδυνήθησαν.", "st": "6.12"}, {"sp": "N", "t": "εἰς τοῦτο δ’ ἥκουσι πλεονεξίας καὶ τοσαύτην ἡμῶν κατεγνώκασιν ἀνανδρίαν, ὥστε πολλάκις ἡμᾶς ἀξιώσαντες ὑπὲρ τῆς αὑτῶν πολεμεῖν, ὑπὲρ Μεσσήνης οὐκ οἴονται δεῖν κινδυνεύειν, ἀλλ’ ἵν’ αὐτοὶ τὴν σφετέραν αὐτῶν ἀσφαλῶς καρπῶνται, πειρῶνται διδάσκειν ἡμᾶς ὡς χρὴ τοῖς ἐχθροῖς τῆς ἡμετέρας παραχωρῆσαι, καὶ πρὸς τοῖς ἄλλοις ἐπαπειλοῦσιν ὡς εἰ μὴ ταῦτα συγχωρήσομεν ποιησόμενοι τὴν εἰρήνην κατὰ σφᾶς αὐτούς.", "st": "6.13"}, {"sp": "N", "t": "ἐγὼ δ’ οὐ τοσούτῳ χαλεπώτερον ἡγοῦμαι τὸν κίνδυνον ἡμῖν ἔσεσθαι τὸν ἄνευ τούτων, ὅσῳ καλλίω καὶ λαμπρότερον καὶ παρὰ πᾶσιν ἀνθρώποις ὀνομαστότερον· τὸ γὰρ μὴ δι’ ἑτέρων ἀλλὰ δι’ ἡμῶν αὐτῶν πειρᾶσθαι σώζεσθαι καὶ περιγενέσθαι τῶν ἐχθρῶν ὁμολογούμενον τοῖς ἄλλοις τοῖς τῆς πόλεως ἔργοις ἐστίν.", "st": "6.14"}, {"sp": "N", "t": "οὐδὲ πώποτε δὲ λόγους ἀγαπήσας, ἀλλ’ ἀεὶ νομίζων τοὺς περὶ τοῦτο διατρίβοντας ἀργοτέρους εἶναι πρὸς τὰς πράξεις, νῦν οὐδὲν ἂν περὶ πλείονος ποιησαίμην ἢ δυνηθῆναι περὶ τῶν προκειμένων ὡς βούλομαι διελθεῖν· ἐν γὰρ τῷ παρόντι διὰ τούτων ἐλπίζω μεγίστων ἀγαθῶν αἴτιος ἂν γενέσθαι τῇ πόλει.", "st": "6.15"}, {"sp": "N", "t": "πρῶτον μὲν οὖν οἶμαι δεῖν διαλεχθῆναι πρὸς ὑμᾶς ὃν τρόπον ἐκτησάμεθα Μεσσήνην καὶ δι’ ἃς αἰτίας ἐν Πελοποννήσῳ κατῳκήσατε Δωριεῖς τὸ παλαιὸν ὄντες. διὰ τοῦτο δὲ προλήψομαι πορρωτέρωθεν, ἵν’ ἐπίστησθε ὅτι ταύτην ὑμᾶς τὴν χώραν ἐπιχειροῦσιν ἀποστερεῖν, ἣν ὑμεῖς οὐδὲν ἧττον ἢ τὴν ἄλλην Λακεδαίμονα κέκτησθε δικαίως.", "st": "6.16"}, {"sp": "N", "t": "ἐπειδὴ γὰρ Ἡρακλῆς μετήλλαξε τὸν βίον θεὸς ἐκ θνητοῦ γενόμενος, κατὰ μὲν ἀρχὰς οἱ παῖδες αὐτοῦ διὰ τὴν τῶν ἐχθρῶν δύναμιν ἐν πολλοῖς πλάνοις καὶ κινδύνοις ἦσαν, τελευτήσαντος δ’ Εὐρυσθέως κατῴκησαν ἐν Δωριεῦσιν. ἐπὶ δὲ τρίτης γενεᾶς ἀφίκοντο εἰς Δελφούς, χρήσασθαι τῷ μαντείῳ περί τινων βουληθέντες. ὁ δὲ θεὸς περὶ μὲν ὧν ἐπηρώτησαν οὐκ ἀνεῖλεν, ἐκέλευσε δ’ αὐτοὺς ἐπὶ τὴν πατρῴαν ἰέναι χώραν.", "st": "6.17"}, {"sp": "N", "t": "σκοπούμενοι δὲ τὴν μαντείαν, εὕρισκον Ἄργος μὲν κατ’ ἀγχιστείαν αὑτῶν γιγνόμενον (Εὐρυσθέως γὰρ ἀποθανόντος μόνοι Περσειδῶν ἦσαν καταλελειμμένοι), Λακεδαίμονα δὲ κατὰ δόσιν (ἐκβληθεὶς γὰρ Τυνδάρεως ἐκ τῆς ἀρχῆς, ἐπειδὴ Κάστωρ καὶ Πολυδεύκης ἐξ ἀνθρώπων ἠφανίσθησαν, καταγαγόντος αὐτὸν Ἡρακλέους δίδωσιν αὐτῷ τὴν χώραν διά τε τὴν εὐεργεσίαν ταύτην καὶ διὰ τὴν συγγένειαν τὴν πρὸς τοὺς παῖδας),", "st": "6.18"}, {"sp": "N", "t": "Μεσσήνην δὲ δοριάλωτον ληφθεῖσαν (συληθεὶς γὰρ Ἡρακλῆς τὰς βοῦς τὰς ἐκ τῆς Ἐρυθείας ὑπὸ Νηλέως καὶ τῶν παίδων, πλὴν ὑπὸ Νέστορος, λαβὼν αὐτὴν αἰχμάλωτον τοὺς μὲν ἀδικήσαντας ἀπέκτεινεν, Νέστορι δὲ παρακατατίθεται τὴν πόλιν, νομίσας αὐτὸν εὖ φρονεῖν ὅτι νεώτατος ὢν οὐ συνεξήμαρτε τοῖς ἀδελφοῖς).", "st": "6.19"}, {"sp": "N", "t": "ὑπολαβόντες δ’ οὕτως ἔχειν τὴν μαντείαν, καὶ τοὺς προγόνους τοὺς ὑμετέρους παραλαβόντες καὶ στρατόπεδον συστησάμενοι, τὴν μὲν ἰδίαν χώραν εἰς τὸ κοινὸν τοῖς συνακολουθήσασιν ἔδοσαν, τὴν δὲ βασιλείαν ἐξαίρετον αὐτοὶ παρ’ ἐκείνων ἔλαβον, ἐπὶ δὲ τούτοις πίστεις ἀλλήλοις δόντες ἐποιοῦντο τὴν στρατείαν.", "st": "6.20"}, {"sp": "N", "t": "τοὺς μὲν οὖν κινδύνους τοὺς ἐν τῇ πορείᾳ γενομένους καὶ τὰς ἄλλας πράξεις τὰς οὐδὲν πρὸς τὸ παρὸν φερούσας τί δεῖ λέγοντα διατρίβειν; πολέμῳ δὲ κρατήσαντες τοὺς ἐν τοῖς τόποις τοῖς εἰρημένοις κατοικοῦντας τριχῇ διείλοντο τὰς βασιλείας. ὑμεῖς μὲν οὖν μέχρι ταυτησὶ τῆς ἡμέρας ἐμμένετε ταῖς συνθήκαις καὶ τοῖς ὅρκοις, οὓς ἐποιήσασθε πρὸς τοὺς προγόνους τοὺς ἡμετέρους·", "st": "6.21"}, {"sp": "N", "t": "διὸ καὶ τὸν παρελθόντα χρόνον ἄμεινον τῶν ἄλλων ἐφέρεσθε, καὶ τὸν ἐπιόντα προσδοκᾶν χρὴ τοιούτους ὄντας βέλτιον ἢ νῦν πράξειν. Μεσσήνιοι δ’ εἰς τοῦτ’ ἀσεβείας ἦλθον, ὥστ’ ἐπιβουλεύσαντες ἀπέκτειναν Κρεσφόντην, τὸν οἰκιστὴν μὲν τῆς πόλεως, κύριον δὲ τῆς χώρας, ἔκγονον δ’ Ἡρακλέους, αὐτῶν δ’ ἡγεμόνα γεγενημένον.", "st": "6.22"}, {"sp": "N", "t": "διαφυγόντες δ’ οἱ παῖδες αὐτοῦ τοὺς κινδύνους ἱκέται κατέστησαν ταυτησὶ τῆς πόλεως, ἀξιοῦντες βοηθεῖν τῷ τεθνεῶτι καὶ τὴν χώραν διδόντες ἡμῖν. ἐπερόμενοι δὲ τὸν θεόν, κἀκείνου προστάξαντος δέχεσθαι ταῦτα καὶ τιμωρεῖν τοῖς ἠδικημένοις, ἐκπολιορκήσαντες Μεσσηνίους οὕτως ἐκτήσασθε τὴν χώραν.", "st": "6.23"}, {"sp": "N", "t": "περὶ μὲν οὖν τῶν ἐξ ἀρχῆς ὑπαρξάντων ἡμῖν ἀκριβῶς μὲν οὐ διῆλθον (ὁ γὰρ παρὼν καιρὸς οὐκ ἐᾷ μυθολογεῖν, ἀλλ’ ἀναγκαῖον ἦν συντομώτερον ἢ σαφέστερον διαλεχθῆναι περὶ αὐτῶν), οὐ μὴν ἀλλὰ καὶ διὰ τούτων οἶμαι πᾶσι φανερὸν εἶναι διότι τὴν ὁμολογουμένην ἡμετέραν εἶναι χώραν οὐδὲν διαφερόντως κεκτημένοι τυγχάνομεν ἢ τὴν ἀμφισβητουμένην. ταύτην τε γὰρ οἰκοῦμεν δόντων μὲν Ἡρακλειδῶν, ἀνελόντος δὲ τοῦ θεοῦ, πολέμῳ δὲ κρατήσαντες τοὺς ἔχοντας· ἐκείνην τ’ ἐλάβομεν παρὰ τῶν αὐτῶν καὶ τὸν αὐτὸν τρόπον καὶ ταῖς μαντείαις χρησάμενοι ταῖς αὐταῖς.", "st": "6.24"}, {"sp": "N", "t": "εἰ μὲν οὖν οὕτως ἔχομεν ὥστε μηδὲ περὶ ἑνὸς ἀντιλέγειν, μηδ’ ἐὰν αὐτὴν τὴν Σπάρτην ἐκλιπεῖν προστάττωσιν ἡμῖν, περίεργόν ἐστιν ὑπὲρ Μεσσήνης σπουδάζειν· εἰ δὲ μηδεὶς ἂν ὑμῶν ἀξιώσειε ζῆν ἀποστερούμενος τῆς πατρίδος, προσήκει καὶ περὶ ἐκείνης τὴν αὐτὴν ὑμᾶς γνώμην ἔχειν. τὰ γὰρ αὐτὰ δικαιώματα καὶ τοὺς αὐτοὺς λόγους περὶ ἀμφοτέρων αὐτῶν ἔχομεν εἰπεῖν.", "st": "6.25"}, {"sp": "N", "t": "ἀλλὰ μὴν οὐδ’ ἐκεῖν’ ὑμᾶς λέληθεν, ὅτι τὰς κτήσεις καὶ τὰς ἰδίας καὶ τὰς κοινάς, ἂν ἐπιγένηται πολὺς χρόνος, κυρίας καὶ πατρῴας ἅπαντες εἶναι νομίζουσιν. ἡμεῖς τοίνυν Μεσσήνην εἵλομεν πρὶν Πέρσας λαβεῖν τὴν βασιλείαν καὶ κρατῆσαι τῆς ἠπείρου, καὶ πρὶν οἰκισθῆναί τινας τῶν πόλεων τῶν Ἑλληνίδων.", "st": "6.26"}, {"sp": "N", "t": "καὶ τούτων ἡμῖν ὑπαρχόντων τῷ μὲν βαρβάρῳ τὴν Ἀσίαν ὡς πατρῴαν οὖσαν ἀποδιδόασιν, ὃς οὔπω διακόσι’ ἔτη κατέσχηκε τὴν ἀρχήν, ἡμᾶς δὲ Μεσσήνην ἀποστεροῦσιν, οἳ πλέον διπλάσιον χρόνον ἢ τοσοῦτον τυγχάνομεν ἔχοντες αὐτήν· καὶ Θεσπιὰς μὲν καὶ Πλαταιὰς ἐχθὲς καὶ πρώην ἀναστάτους πεποιήκασι, ταύτην δὲ διὰ τετρακοσίων ἐτῶν μέλλουσι κατοικίζειν, ἀμφότερα παρὰ τοὺς ὅρκους καὶ τὰς συνθήκας πράττοντες.", "st": "6.27"}, {"sp": "N", "t": "καὶ εἰ μὲν τοὺς ὡς ἀληθῶς Μεσσηνίους κατῆγον, ἠδίκουν μὲν ἄν, ὅμως δ’ εὐλογωτέρως ἂν εἰς ἡμᾶς ἐξημάρτανον· νῦν δὲ τοὺς Εἵλωτας ὁμόρους ἡμῖν παρακατοικίζουσιν, ὥστε μὴ τοῦτ’ εἶναι χαλεπώτατον, εἰ τῆς χώρας στερησόμεθα παρὰ τὸ ἀλλ’ εἰ τοὺς δούλους τοὺς ἡμετέρους ἐποψόμεθα κυρίους αὐτῆς ὄντας.", "st": "6.28"}, {"sp": "N", "t": "ἔτι τοίνυν ἐκ τῶν ἐχομένων γνώσεσθε σαφέστερον ὅτι καὶ νῦν δεινὰ πάσχομεν καὶ τότε Μεσσήνην εἴχομεν δικαίως. πολλῶν γὰρ κινδύνων ἡμῖν γεγενημένων ἤδη ποτὲ ποιήσασθαι τὴν εἰρήνην ἠναγκάσθημεν πολὺ χεῖρον πράττοντες τῶν πολεμίων· ἀλλ’ ὅμως ἐν τοιούτοις καιροῖς γιγνομένων τῶν συνθηκῶν,", "st": "6.29"}, {"sp": "N", "t": "ἐν οἷς οὐχ οἷόν τ’ ἦν πλεονεκτεῖν, περὶ μὲν ἄλλων τινῶν ἀμφισβητήσεις ἐγίγνοντο, περὶ δὲ Μεσσήνης οὔτε βασιλεὺς οὔθ’ ἡ τῶν Ἀθηναίων πόλις οὐδὲ πώποθ’ ἡμῖν ἐνεκάλεσεν ὡς ἀδίκως κεκτημένοις αὐτήν. καίτοι πῶς ἂν περὶ τοῦ δικαίου κρίσιν ἀκριβεστέραν ταύτης εὕροιμεν τῆς ὑπὸ μὲν τῶν ἐχθρῶν ἐγνωσμένης, ἐν δὲ ταῖς ἡμετέραις δυσπραξίαις γεγενημένης;", "st": "6.30"}, {"sp": "N", "t": "τὸ τοίνυν μαντεῖον, ὃ πάντες ἂν ὁμολογήσειαν ἀρχαιότατον εἶναι καὶ κοινότατον καὶ πιστότατον, οὐ μόνον ἔγνω τόθ’ ἡμετέραν εἶναι Μεσσήνην, ὅτε διδόντων ἡμῖν αὐτὴν τῶν Κρεσφόντου παίδων προσέταξε δέχεσθαι τὴν δωρεὰν καὶ βοηθεῖν τοῖς ἀδικουμένοις, ἀλλὰ καὶ τοῦ πολέμου μακροῦ γιγνομένου πεμψάντων ἀμφοτέρων εἰς Δελφούς, κἀκείνων μὲν σωτηρίαν αἰτούντων, ἡμῶν δ’ ἐπερωτώντων ὅτῳ τρόπῳ τάχιστ’ ἂν κρατήσαιμεν τῆς πόλεως, τοῖς μὲν οὐδὲν ἀνεῖλεν ὡς οὐ δικαίαν ποιουμένοις τὴν αἴτησιν, ἡμῖν δ’ ἐδήλωσε καὶ τὰς θυσίας ἃς ἔδει ποιήσασθαι καὶ βοήθειαν παρ’ ὧν μεταπέμψασθαι.", "st": "6.31"}, {"sp": "N", "t": "καίτοι πῶς ἄν τις μαρτυρίαν μείζω καὶ σαφεστέραν τούτων παράσχοιτο; φαινόμεθα γὰρ πρῶτον μὲν παρὰ τῶν κυρίων τὴν χώραν λαβόντες (οὐδὲν γὰρ κωλύει πάλιν διὰ βραχέων περὶ αὐτῶν διελθεῖν), ἔπειτα κατὰ πόλεμον αὐτὴν ἑλόντες, ὅνπερ τρόπον αἱ πλεῖσται τῶν πόλεων περὶ ἐκείνους τοὺς χρόνους ᾠκίσθησαν, ἔτι δὲ τοὺς ἠσεβηκότας εἰς τοὺς παῖδας τοὺς Ἡρακλέους ἐκβεβληκότες, οἳ δικαίως ἂν ἐξ ἁπάσης τῆς οἰκουμένης ὑπερωρίσθησαν, πρὸς δὲ τούτοις καὶ τῷ πλήθει τοῦ χρόνου καὶ τῇ τῶν ἐχθρῶν κρίσει καὶ ταῖς τοῦ θεοῦ μαντείαις προσηκόντως ἔχοντες αὐτήν.", "st": "6.32"}, {"sp": "N", "t": "ὧν ἓν ἕκαστον ἱκανόν ἐστι διαλῦσαι τοὺς λόγους τῶν τολμώντων κατηγορεῖν ὡς ἢ νῦν διὰ πλεονεξίαν οὐ ποιούμεθα τὴν εἰρήνην, ἢ τότε τῶν ἀλλοτρίων ἐπιθυμοῦντες ἐπολεμήσαμεν πρὸς Μεσσηνίους. περὶ μὲν οὖν τῆς κτήσεως ἔνεστι μὲν ἴσως πλείω τούτων εἰπεῖν, οὐ μήν ἀλλὰ καὶ ταῦθ’ ἱκανῶς εἰρῆσθαι νομίζω.", "st": "6.33"}, {"sp": "N", "t": "λέγουσι δ’ οἱ συμβουλεύοντες ἡμῖν ποιεῖσθαι τὴν εἰρήνην, ὡς χρὴ τοὺς εὖ φρονοῦντας μὴ τὴν αὐτὴν γνώμην ἔχειν περὶ τῶν πραγμάτων εὐτυχοῦντας καὶ δυστυχοῦντας, ἀλλὰ πρὸς τὸ παρὸν ἀεὶ βουλεύεσθαι καὶ ταῖς τύχαις ἐπακολουθεῖν καὶ μὴ μεῖζον φρονεῖν τῆς δυνάμεως, μηδὲ τὸ δίκαιον ἐν τοῖς τοιούτοις καιροῖς ἀλλὰ τὸ συμφέρον ζητεῖν.", "st": "6.34"}, {"sp": "N", "t": "ἐγὼ δὲ περὶ μὲν τῶν ἄλλων ὁμολογῶ τούτοις, ὅπως δὲ χρὴ τοῦ δικαίου ποιεῖσθαί τι προὐργιαίτερον οὐδεὶς ἄν με λέγων πείσειεν. ὁρῶ γὰρ καὶ τοὺς νόμους ἕνεκα τούτου κειμένους, καὶ τοὺς ἄνδρας τοὺς καλοὺς κἀγαθοὺς ἐπὶ τούτῳ φιλοτιμουμένους, καὶ τὰς εὖ πολιτευομένας πόλεις περὶ τούτου μάλιστα σπουδαζούσας,", "st": "6.35"}, {"sp": "N", "t": "ἔτι δὲ τοὺς πολέμους τοὺς προγεγενημένους οὐ κατὰ τὰς δυνάμεις ἀλλὰ κατὰ τὸ δίκαιον τὸ τέλος ἅπαντας εἰληφότας, ὅλως δὲ τὸν βίον τὸν τῶν ἀνθρώπων διὰ μὲν κακίαν ἀπολλύμενον, δι’ ἀρετὴν δὲ σωζόμενον. ὥστ’ οὐκ ἀθυμεῖν δεῖ τοὺς ὑπὲρ τῶν δικαίων κινδυνεύειν μέλλοντας, ἀλλὰ πολὺ μᾶλλον τοὺς ὑβρίζοντας καὶ τοὺς τὰς εὐτυχίας μὴ μετρίως φέρειν ἐπισταμένους.", "st": "6.36"}, {"sp": "N", "t": "ἔπειτα κἀκεῖνο χρὴ σκοπεῖν· νυνὶ γὰρ περὶ μὲν τοῦ δικαίου πάντες τὴν αὐτὴν γνώμην ἔχομεν, περὶ δὲ τοῦ συμφέροντος ἀντιλέγομεν. δυοῖν δὲ προτεινομένοιν ἀγαθοῖν, καὶ τοῦ μὲν ὄντος προδήλου τοῦ δὲ ἀγνοουμένου, πῶς οὐκ ἂν ποιήσαιτε καταγέλαστον, εἰ τὸ μὲν ὁμολογούμενον ἀποδοκιμάσαιτε, τὸ δ’ ἀμφισβητούμενον ἑλέσθαι δόξειεν ὑμῖν, ἄλλως τε καὶ τῆς αἱρέσεως τοσοῦτον διαφερούσης;", "st": "6.37"}, {"sp": "N", "t": "ἐν μὲν γὰρ τοῖς ἐμοῖς λόγοις ἔνεστι μηδὲν μὲν προέσθαι τῶν ὑμετέρων αὐτῶν μηδ’ αἰσχύνῃ μηδεμιᾷ τὴν πόλιν περιβαλεῖν, ὑπὲρ δὲ τῶν δικαίων κινδυνεύοντας ἐλπίζειν ἄμεινον ἀγωνιεῖσθαι τῶν ἐχθρῶν, ἐν δὲ τοῖς τούτων ἀφεστάναι μὲν ἤδη Μεσσήνης, προεξαμαρτόντας δὲ τοῦτ’ εἰς ὑμᾶς αὐτοὺς τυχὸν καὶ τοῦ συμφέροντος καὶ τοῦ δικαίου καὶ τῶν ἄλλων ἁπάντων ὧν προσδοκᾶτε διαμαρτεῖν.", "st": "6.38"}, {"sp": "N", "t": "καὶ γὰρ οὐδὲ τοῦτό πω φανερόν ἐστιν, ὡς ἂν ποιήσωμεν τὰ κελευόμενα, βεβαίως ἤδη τὴν εἰρήνην ἄξομεν. οἶμαι γὰρ ὑμᾶς οὐκ ἀγνοεῖν ὅτι πάντες εἰώθασι πρὸς μὲν τοὺς ἀμυνομένους περὶ τῶν δικαίων διαλέγεσθαι, τοῖς δὲ λίαν ἑτοίμως ποιοῦσι τὸ προσταττόμενον ἀεὶ πλείω προσεπιβάλλειν οἷς ἂν ἐξ ἀρχῆς διανοηθῶσιν, ὥστε συμβαίνειν βελτίονος εἰρήνης τυγχάνειν τοὺς πολεμικῶς διακειμένους τῶν ῥᾳδίως τὰς ὁμολογίας ποιουμένων.", "st": "6.39"}, {"sp": "N", "t": "ἵνα δὲ μὴ δοκῶ περὶ ταῦτα πολὺν χρόνον διατρίβειν, ἁπάντων τῶν τοιούτων ἀφέμενος ἐπὶ τὸν ἁπλούστατον ἤδη τρέψομαι τῶν λόγων. εἰ μὲν γὰρ μηδένες πώποτε τῶν δυστυχησάντων ἀνέλαβον αὑτοὺς μηδ’ ἐπεκράτησαν τῶν ἐχθρῶν, οὐδ’ ἡμᾶς εἰκὸς ἐλπίζειν περιγενήσεσθαι πολεμοῦντας· εἰ δὲ πολλάκις γέγονεν ὥστε καὶ τοὺς μείζω δύναμιν ἔχοντας ὑπὸ τῶν ἀσθενεστέρων κρατηθῆναι καὶ τοὺς πολιορκοῦντας ὑπὸ τῶν κατακεκλειμένων διαφθαρῆναι, τί θαυμαστὸν εἰ καὶ τὰ νῦν καθεστῶτα λήψεταί τινα μετάστασιν;", "st": "6.40"}, {"sp": "N", "t": "ἐπὶ μὲν οὖν τῆς ἡμετέρας πόλεως οὐδὲν ἔχω τοιοῦτον εἰπεῖν· ἐν γὰρ τοῖς ἐπέκεινα χρόνοις οὐδένες πώποτε κρείττους ἡμῶν εἰς ταύτην τὴν χώραν εἰσέβαλον· ἐπὶ δὲ τῶν ἄλλων πολλοῖς ἄν τις παραδείγμασι χρήσαιτο, καὶ μάλιστ’ ἐπὶ τῆς πόλεως τῆς Ἀθηναίων.", "st": "6.41"}, {"sp": "N", "t": "τούτους γὰρ εὑρήσομεν, ἐξ ὧν μὲν τοῖς ἄλλοις προσέταττον, πρὸς τοὺς Ἕλληνας διαβληθέντας, ἐξ ὧν δὲ τοὺς ὑβρίζοντας ἠμύναντο, παρὰ πᾶσιν ἀνθρώποις εὐδοκιμήσαντας. τοὺς μὲν οὖν παλαιοὺς κινδύνους εἰ διεξιοίην, οὓς ἐποιήσαντο πρὸς Ἀμαζόνας ἢ Θρᾷκας ἢ Πελοποννησίους τοὺς μετ’ Εὐρυσθέως εἰς τὴν χώραν αὐτῶν εἰσβαλόντας, ἴσως ἀρχαῖα καὶ πόρρω τῶν νῦν παρόντων λέγειν ἂν δοκοίην· ἐν δὲ τῷ Περσικῷ πολέμῳ τίς οὐκ οἶδεν ἐξ οἵων συμφορῶν εἰς ὅσην εὐδαιμονίαν κατέστησαν;", "st": "6.42"}, {"sp": "N", "t": "μόνοι γὰρ τῶν ἔξω Πελοποννήσου κατοικούντων, ὁρῶντες τὴν τῶν βαρβάρων δύναμιν ἀνυπόστατον οὖσαν, οὐκ ἠξίωσαν βουλεύσασθαι περὶ τῶν προσταττομένων αὐτοῖς, ἀλλ’ εὐθὺς εἵλοντο περιιδεῖν ἀνάστατον τὴν πόλιν γεγενημένην μᾶλλον ἢ δουλεύουσαν. ἐκλιπόντες δὲ τὴν χώραν, καὶ πατρίδα μὲν τὴν ἐλευθερίαν νομίσαντες, κοινωνήσαντες δὲ τῶν κινδύνων ἡμῖν, τοσαύτης μεταβολῆς ἔτυχον, ὥστε ὀλίγας ἡμέρας στερηθέντες τῶν αὑτῶν πολὺν χρόνον τῶν ἄλλων δεσπόται κατέστησαν.", "st": "6.43"}, {"sp": "N", "t": "οὐ μόνον δ’ ἐπὶ ταύτης ἄν τις τῆς πόλεως ἐπιδείξειε τὸ τολμᾶν ἀμύνεσθαι τοὺς ἐχθρούς, ὡς πολλῶν ἀγαθῶν αἴτιόν ἐστιν, ἀλλὰ καὶ Διονύσιος ὁ τύραννος καταστὰς εἰς πολιορκίαν ὑπὸ Καρχηδονίων, οὐδεμιᾶς αὐτῷ σωτηρίας ὑποφαινομένης, ἀλλὰ καὶ τῷ πολέμῳ κατεχόμενος καὶ τῶν πολιτῶν δυσκόλως πρὸς αὐτὸν διακειμένων, αὐτὸς μὲν ἐμέλλησεν ἐκπλεῖν, τῶν δὲ χρωμένων τινὸς τολμήσαντος εἰπεῖν ὡς καλόν ἐστιν ἐντάφιον ἡ τυραννίς,", "st": "6.44"}, {"sp": "N", "t": "αἰσχυνθεὶς ἐφ’ οἷς διενοήθη καὶ πάλιν ἐπιχειρήσας πολεμεῖν, πολλὰς μὲν μυριάδας Καρχηδονίων διέφθειρεν, ἐγκρατεστέραν δὲ τὴν ἀρχὴν τὴν τῶν πολιτῶν κατεστήσατο, πολὺ δὲ μείζω τὴν δύναμιν τὴν αὑτοῦ τῆς πρότερον ὑπαρχούσης ἐκτήσατο, τυραννῶν δὲ τὸν βίον διετέλεσε, καὶ τὸν υἱὸν ἐν ταῖς αὐταῖς τιμαῖς καὶ δυναστείαις, ἐν αἷσπερ αὐτὸς ἦν, κατέλιπεν.", "st": "6.45"}, {"sp": "N", "t": "παραπλήσια δὲ τούτοις Ἀμύντας ὁ Μακεδόνων βασιλεὺς ἔπραξεν. ἡττηθεὶς γὰρ ὑπὸ τῶν βαρβάρων τῶν προσοικούντων μάχῃ καὶ πάσης Μακεδονίας ἀποστερηθεὶς τὸ μὲν πρῶτον ἐκλιπεῖν τὴν χώραν διενοήθη καὶ τὸ σῶμα διασώζειν, ἀκούσας δέ τινος ἐπαινοῦντος τὸ πρὸς Διονύσιον ῥηθέν, καὶ μεταγνοὺς ὥσπερ ἐκεῖνος, χωρίον μικρὸν καταλαβὼν καὶ βοήθειαν ἐνθένδε μεταπεμψάμενος ἐντὸς μὲν τριῶν μηνῶν κατέσχεν ἅπασαν Μακεδονίαν, τὸν δ’ ἐπίλοιπον χρόνον βασιλεύων γήρᾳ τὸν βίον ἐτελεύτησεν.", "st": "6.46"}, {"sp": "N", "t": "ἀπείποιμεν δ’ ἂν ἀκούοντές τε καὶ λέγοντες, εἰ πάσας τὰς τοιαύτας πράξεις ἐξετάζοιμεν, ἐπεὶ καὶ τῶν περὶ Θήβας πραχθέντων εἰ μνησθείημεν, ἐπὶ μὲν τοῖς γεγενημένοις ἂν λυπηθεῖμεν, περὶ δὲ τῶν μελλόντων βελτίους ἐλπίδας ἂν λάβοιμεν. τολμησάντων γὰρ αὐτῶν ὑπομεῖναι τὰς εἰσβολὰς καὶ τὰς ἀπειλὰς τὰς ἡμετέρας, εἰς τοῦθ’ ἡ τύχη τὰ πράγματ’ αὐτῶν περιέστησεν, ὥστε τὸν ἄλλον χρόνον ὑφ’ ἡμῖν ὄντες νῦν ἡμῖν προστάττειν ἀξιοῦσιν.", "st": "6.47"}, {"sp": "N", "t": "ὅστις οὖν ὁρῶν τοσαύτας μεταβολὰς γεγενημένας ἐφ’ ἡμῶν οἴεται παύσεσθαι, λίαν ἀνόητός ἐστιν· ἀλλὰ δεῖ καρτερεῖν ἐπὶ τοῖς παροῦσι καὶ θαρρεῖν περὶ τῶν μελλόντων, ἐπισταμένους ὅτι τὰς τοιαύτας συμφορὰς αἱ πόλεις ἐπανορθοῦνται πολιτείᾳ χρηστῇ καὶ ταῖς περὶ τὸν πόλεμον ἐμπειρίαις. περὶ ὧν οὐδεὶς ἂν τολμήσειεν ἀντειπεῖν, ὡς οὐ τὴν μὲν ἐμπειρίαν μᾶλλον τῶν ἄλλων ἔχομεν, πολιτείαν δ’ οἵαν εἶναι χρή, παρὰ μόνοις ἡμῖν ἐστιν. ὧν ὑπαρχόντων οὐκ ἔστιν ὅπως οὐκ ἄμεινον πράξομεν τῶν μηδετέρου τούτων πολλὴν ἐπιμέλειαν πεποιημένων.", "st": "6.48"}, {"sp": "N", "t": "κατηγοροῦσι δέ τινες τοῦ πολέμου, καὶ διεξέρχονται τὴν ἀπιστίαν αὐτοῦ, τεκμηρίοις ἄλλοις τε πολλοῖς χρώμενοι καὶ μάλιστα τοῖς περὶ ἡμᾶς γεγενημένοις, καὶ θαυμάζουσιν εἴ τινες οὕτω χαλεπῷ καὶ παραβόλῳ πράγματι πιστεύειν ἀξιοῦσιν. ἐγὼ δὲ πολλοὺς μὲν οἶδα διὰ τὸν πόλεμον μεγάλην εὐδαιμονίαν κτησαμένους, πολλοὺς δὲ τῆς ὑπαρχούσης ἀποστερηθέντας διὰ τὴν εἰρήνην·", "st": "6.49"}, {"sp": "N", "t": "οὐδὲν γὰρ τῶν τοιούτων ἐστὶν ἀποτόμως οὔτε κακὸν οὔτ’ ἀγαθόν, ἀλλ’ ὡς ἂν χρήσηταί τις τοῖς πράγμασι καὶ τοῖς καιροῖς, οὕτως ἀνάγκη καὶ τὸ τέλος ἐκβαίνειν ἐξ αὐτῶν. χρὴ δὲ τοὺς μὲν εὖ πράττοντας τῆς εἰρήνης ἐπιθυμεῖν· ἐν ταύτῃ γὰρ τῇ καταστάσει πλεῖστον ἄν τις χρόνον τὰ παρόντα διαφυλάξειεν· τοὺς δὲ δυστυχοῦντας τῷ πολέμῳ προσέχειν τὸν νοῦν· ἐκ γὰρ τῆς ταραχῆς καὶ τῆς καινουργίας θᾶττον ἂν μεταβολῆς τύχοιεν. ὧν ἡμεῖς δέδοικα μὴ τἀναντία πράττοντες φανῶμεν·", "st": "6.50"}, {"sp": "N", "t": "ὅτε μὲν γὰρ ἐξῆν ἡμῖν τρυφᾶν, πλείους τοὺς πολέμους ἐποιούμεθα τοῦ δέοντος, ἐπειδὴ δ’ εἰς ἀνάγκην καθέσταμεν ὥστε κινδυνεύειν, ἡσυχίας ἐπιθυμοῦμεν καὶ περὶ ἀσφαλείας βουλευόμεθα. καίτοι χρὴ τοὺς βουλομένους ἐλευθέρους εἶναι τὰς μὲν ἐκ τῶν ἐπιταγμάτων συνθήκας φεύγειν ὡς ἐγγὺς δουλείας οὔσας, ποιεῖσθαι δὲ τὰς διαλλαγάς, ὅταν ἢ περιγένωνται τῶν ἐχθρῶν ἢ τὴν δύναμιν τὴν αὑτῶν ἐξισώσωσιν τῇ τῶν πολεμίων· ὡς τοιαύτην ἕκαστοι τὴν εἰρήνην ἕξουσιν, οἵαν περ ἂν τοῦ πολέμου ποιήσωνται τὴν κατάλυσιν.", "st": "6.51"}, {"sp": "N", "t": "ὧν ἐνθυμουμένους χρὴ μὴ προπετῶς ὑμᾶς αὐτοὺς ἐμβαλεῖν εἰς αἰσχρὰς ὁμολογίας, μηδὲ ῥᾳθυμότερον ὑπὲρ τῆς πατρίδος ἢ τῶν ἄλλων φανῆναι βουλευομένους. ἀναμνήσθητε δὲ πρὸς ὑμᾶς αὐτοὺς ὅτι τὸν παρελθόντα χρόνον, εἰ πολιορκουμένῃ τινὶ τῶν πόλεων τῶν συμμαχίδων εἷς μόνος Λακεδαιμονίων βοηθήσειεν, ὑπὸ πάντων ἂν ὡμολογεῖτο παρὰ τοῦτον γενέσθαι τὴν σωτηρίαν αὐτοῖς. καὶ τοὺς μὲν πλείστους τῶν τοιούτων ἀνδρῶν παρὰ τῶν πρεσβυτέρων ἄν τις ἀκούσειεν, τοὺς δ’ ὀνομαστοτάτους ἔχω κἀγὼ διελθεῖν.", "st": "6.52"}, {"sp": "N", "t": "Πεδάριτος μὲν γὰρ εἰς Χίον εἰσπλεύσας τὴν πόλιν αὐτῶν διέσωσε· Βρασίδας δ’ εἰς Ἀμφίπολιν εἰσελθών, ὀλίγους περὶ αὑτὸν τῶν πολιορκουμένων συνταξάμενος, πολλοὺς ὄντας τοὺς πολιορκοῦντας ἐνίκησε μαχόμενος· Γύλιππος δὲ Συρακοσίοις βοηθήσας οὐ μόνον ἐκείνους διέσωσεν, ἀλλὰ καὶ τὴν δύναμιν τὴν κρατοῦσαν αὐτῶν καὶ κατὰ γῆν καὶ κατὰ θάλατταν ἅπασαν αἰχμάλωτον ἔλαβεν.", "st": "6.53"}, {"sp": "N", "t": "καίτοι πῶς οὐκ αἰσχρὸν τότε μὲν ἕκαστον ἡμῶν ἱκανὸν εἶναι τὰς ἀλλοτρίας πόλεις διαφυλάττειν, νυνὶ δὲ πάντας μηδὲ πειρᾶσθαι τὴν ἡμετέραν αὐτῶν διασώζειν; καὶ τὴν μὲν Εὐρώπην καὶ τὴν Ἀσίαν μεστὴν πεποιηκέναι τροπαίων ὑπὲρ τῶν ἄλλων πολεμοῦντας, ὑπὲρ δὲ τῆς πατρίδος οὕτω φανερῶς ὑβριζομένης μηδὲ μίαν μάχην ἀξίαν λόγου φαίνεσθαι μεμαχημένους;", "st": "6.54"}, {"sp": "N", "t": "ἀλλ’ ἑτέρας μὲν πόλεις ὑπὲρ τῆς ἡμετέρας ἀρχῆς τὰς ἐσχάτας ὑπομεῖναι πολιορκίας, αὐτοὺς δ’ ἡμᾶς, ὑπὲρ τοῦ μηδὲν ἀναγκασθῆναι παρὰ τὸ δίκαιον ποιεῖν, μηδὲ μικρὰν οἴεσθαι δεῖν ὑπενεγκεῖν κακοπάθειαν, ἀλλὰ ζεύγη μὲν ἵππων ἀδηφαγούντων ἔτι καὶ νῦν ὁρᾶσθαι τρέφοντας, ὥσπερ δὲ τοὺς εἰς τὰς δεινοτάτας ἀνάγκας ἀφιγμένους καὶ τῶν καθ’ ἡμέραν ἐνδεεῖς ὄντας, οὕτω ποιεῖσθαι τὴν εἰρήνην;", "st": "6.55"}, {"sp": "N", "t": "ὃ δὲ πάντων σχετλιώτατον, εἰ φιλοπονώτατοι δοκοῦντες εἶναι τῶν Ἑλλήνων ῥᾳθυμότερον τῶν ἄλλων βουλευσόμεθα περὶ τούτων. τίνας γὰρ ἴσμεν, ὧν καὶ ποιήσασθαι μνείαν ἄξιόν ἐστιν, οἵτινες ἅπαξ ἡττηθέντες καὶ μιᾶς εἰσβολῆς γενομένης οὕτως ἀνάνδρως ὡμολόγησαν πάντα τὰ προσταττόμενα ποιήσειν; πῶς δ’ ἂν οἱ τοιοῦτοι πολὺν χρόνον δυστυχοῦντες ἀνταρκέσειαν;", "st": "6.56"}, {"sp": "N", "t": "τίς δ’ οὐκ ἂν ἐπιτιμήσειεν ἡμῖν, εἰ Μεσσηνίων ὑπὲρ ταύτης τῆς χώρας εἴκοσιν ἔτη πολιορκηθέντων ἡμεῖς οὕτω ταχέως κατὰ συνθήκας αὐτῆς ἀποσταίημεν, καὶ μηδὲ τῶν προγόνων μνησθείημεν, ἀλλ’ ἣν ἐκεῖνοι μετὰ πολλῶν πόνων καὶ κινδύνων ἐκτήσαντο, ταύτην ἡμεῖς ὑπὸ λόγων πεισθέντες ἀποβάλοιμεν;", "st": "6.57"}, {"sp": "N", "t": "ὧν οὐδὲν ἔνιοι φροντίσαντες, ἀλλὰ πάσας τὰς αἰσχύνας ὑπεριδόντες, τοιαῦτα συμβουλεύουσιν ὑμῖν, ἐξ ὧν εἰς ὀνείδη τὴν πόλιν καταστήσουσιν. οὕτω δὲ προθύμως ἐπάγουσιν ὑμᾶς πρὸς τὸ παραδοῦναι Μεσσήνην, ὥστε καὶ διεξελθεῖν ἐτόλμησαν τήν τε τῆς πόλεως ἀσθένειαν καὶ τὴν τῶν πολεμίων δύναμιν, καὶ κελεύουσιν, ἀποκρίνασθαι τοὺς ἐναντιουμένους αὐτοῖς, πόθεν βοήθειαν προσδοκῶντες ἥξειν διακελευόμεθα πολεμεῖν.", "st": "6.58"}, {"sp": "N", "t": "ἐγὼ δὲ μεγίστην ἡγοῦμαι συμμαχίαν εἶναι καὶ βεβαιοτάτην τὸ τὰ δίκαια πράττειν (εἰκὸς γὰρ καὶ τὴν τῶν θεῶν εὔνοιαν γενέσθαι μετὰ τούτων, εἴπερ χρὴ περὶ τῶν μελλόντων τεκμαίρεσθαι τοῖς ἤδη γεγενημένοις), πρὸς δὲ ταύτῃ τὸ καλῶς πολιτεύεσθαι καὶ σωφρόνως ζῆν καὶ μέχρι θανάτου μάχεσθαι τοῖς πολεμίοις ἐθέλειν καὶ μηδὲν οὕτω δεινὸν νομίζειν ὡς τὸ κακῶς ἀκούειν ὑπὸ τῶν πολιτῶν· ἃ μᾶλλον ἡμῖν ἢ τοῖς ἄλλοις ἀνθρώποις ὑπάρχει.", "st": "6.59"}, {"sp": "N", "t": "μεθ’ ὧν ἐγὼ πολὺ ἂν ἥδιον πολεμοίην ἢ μετὰ πολλῶν μυριάδων· οἶδα γὰρ καὶ τοὺς πρώτους ἡμῶν εἰς ταύτην τὴν χώραν ἀφικομένους οὐ τῷ πλήθει τῶν ἄλλων περιγενομένους, ἀλλὰ ταῖς ἀρεταῖς ταῖς ταῖς ὑπ’ ἐμοῦ προειρημέναις. ὥστ’ οὐκ ἄξιον διὰ τοῦτο φοβεῖσθαι τοὺς πολεμίους, ὅτι πολλοὶ τυγχάνουσιν ὄντες, ἀλλὰ πολὺ μᾶλλον ἐπ’ ἐκείνοις θαρρεῖν, ὅταν ὁρῶμεν ἡμᾶς μὲν αὐτοὺς οὕτως ἐνηνοχότας τὰς συμφορὰς ὡς οὐδένες ἄλλοι πώποτε,", "st": "6.60"}, {"sp": "N", "t": "καὶ τοῖς τε νόμοις καὶ τοῖς ἐπιτηδεύμασιν ἐμμένοντας οἷς ἐξ ἀρχῆς κατεστησάμεθα, τοὺς δὲ μηδὲ τὰς εὐτυχίας φέρειν δυναμένους, ἀλλὰ διατεταραγμένους, καὶ τοὺς μὲν τὰς συμμαχίδας πόλεις καταλαμβάνοντας, τοὺς δὲ τἀναντία τούτοις πράττοντας, ἄλλους δὲ περὶ χώρας τοῖς ὁμόροις ἀμφισβητοῦντας, τοὺς δὲ μᾶλλον ἀλλήλοις φθονοῦντας ἢ πρὸς ἡμᾶς πολεμοῦντας. ὥστε θαυμάζω τῶν μείζω συμμαχίαν ζητούντων, ὧν οἱ πολέμιοι τυγχάνουσιν ἐξαμαρτάνοντες.", "st": "6.61"}, {"sp": "N", "t": "εἰ δὲ δεῖ καὶ περὶ τῶν ἔξωθεν βοηθειῶν εἰπεῖν, ἡγοῦμαι πολλοὺς ἔσεσθαι τοὺς βουλομένους ἐπαμύνειν ἡμῖν. ἐπίσταμαι γὰρ πρῶτον μὲν Ἀθηναίους, εἰ καὶ μὴ πάντα μεθ’ ἡμῶν εἰσιν, ἀλλ’ ὑπέρ γε τῆς σωτηρίας τῆς ἡμετέρας ὁτιοῦν ἂν ποιήσοντας· ἔπειτα τῶν ἄλλων πόλεων ἔστιν ἃς ὁμοίως ἂν ὑπὲρ τῶν ἡμῖν συμφερόντων ὥσπερ τῶν αὑταῖς βουλευσομένας·", "st": "6.62"}, {"sp": "N", "t": "ἔτι δὲ Διονύσιον τὸν τύραννον καὶ τὸν Αἰγυπτίων βασιλέα καὶ τοὺς ἄλλους τοὺς κατὰ τὴν Ἀσίαν δυνάστας, καθ’ ὅσον ἕκαστοι δύνανται, προθύμως ἂν ἡμῖν ἐπικουρήσοντας· πρὸς δὲ τούτοις καὶ τῶν Ἑλλήνων τοὺς ταῖς οὐσίαις προέχοντας καὶ ταῖς δόξαις πρωτεύοντας καὶ βελτίστων πραγμάτων ἐπιθυμοῦντας, εἰ καὶ μήπω συνεστήκασιν, ἀλλὰ ταῖς γ’ εὐνοίαις μεθ’ ἡμῶν ὄντας, ἐν οἷς περὶ τῶν μελλόντων εἰκότως ἂν μεγάλας ἐλπίδας ἔχοιμεν.", "st": "6.63"}, {"sp": "N", "t": "οἶμαι δὲ καὶ τὸν ἄλλον ὄχλον τὸν ἐν Πελοποννήσῳ καὶ τὸν δῆμον, ὃν οἰόμεθα μάλιστα πολεμεῖν ἡμῖν, ποθεῖν ἤδη τὴν ἡμετέραν ἐπιμέλειαν. οὐδὲν γὰρ αὐτοῖς ἀποστᾶσι γέγονεν ὧν προσεδόκησαν, ἀλλ’ ἀντὶ μὲν τῆς ἐλευθερίας τοὐναντίον ἀποβέβηκεν (ἀπολέσαντες γὰρ αὑτῶν τοὺς βελτίστους ἐπὶ τοῖς χειρίστοις τῶν πολιτῶν γεγόνασιν), ἀντὶ δὲ τῆς αὐτονομίας εἰς πολλὰς καὶ δεινὰς ἀνομίας ἐμπεπτώκασιν,", "st": "6.64"}, {"sp": "N", "t": "εἰθισμένοι δὲ τὸν ἄλλον χρόνον μεθ’ ἡμῶν ἐφ’ ἑτέρους ἰέναι, νῦν τοὺς ἄλλους ὁρῶσιν ἐφ’ αὑτοὺς στρατευομένους, καὶ τὰς στάσεις, ἃς ἐπυνθάνοντο πρότερον παρ’ ἑτέροις οὔσας, νῦν παρ’ αὑτοῖς ὀλίγου δεῖν καθ’ ἑκάστην τὴν ἡμέραν γιγνομένας, οὕτω δ’ ὡμαλισμένοι ταῖς συμφοραῖς εἰσιν, ὥστε μηδένα διαγνῶναι δύνασθαι τοὺς κάκιστα πράττοντας αὐτῶν· οὐδεμία γάρ ἐστι τῶν πόλεων ἀκέραιος,", "st": "6.65"}, {"sp": "N", "t": "οὐδ’ ἥ τις οὐχ ὁμόρους ἔχει τοὺς κακῶς ποιήσοντας, ὥστε τετμῆσθαι μὲν τὰς χώρας, πεπορθῆσθαι δὲ τὰς πόλεις, ἀναστάτους δὲ γεγενῆσθαι τοὺς οἴκους τοὺς ἰδίους, ἀνεστράφθαι δὲ τὰς πολιτείας καὶ καταλελύσθαι τοὺς νόμους, μεθ’ ὧν οἰκοῦντες εὐδαιμονέστατοι τῶν Ἑλλήνων ἦσαν.", "st": "6.66"}, {"sp": "N", "t": "οὕτω δ’ ἀπίστως τὰ πρὸς σφᾶς αὐτοὺς καὶ δυσμενῶς ἔχουσιν, ὥστε μᾶλλον τοὺς πολίτας ἢ τοὺς πολεμίους δεδίασιν· ἀντὶ δὲ τῆς ἐφ’ ἡμῶν ὁμονοίας καὶ τῆς παρ’ ἀλλήλων εὐπορίας εἰς τοσαύτην ἀμιξίαν ἐληλύθασιν, ὥσθ’ οἱ μὲν κεκτημένοι τὰς οὐσίας ἥδιον ἂν εἰς τὴν θάλατταν τὰ σφέτερ’ αὐτῶν ἐκβάλοιεν ἢ τοῖς δεομένοις ἐπαρκέσειαν, οἱ δὲ καταδεέστερον πράττοντες οὐδ’ ἂν εὑρεῖν δέξαιντο μᾶλλον ἢ τὰ τῶν ἐχόντων ἀφελέσθαι·", "st": "6.67"}, {"sp": "N", "t": "καταλύσαντες δὲ τὰς θυσίας ἐπὶ τῶν βωμῶν σφάττουσιν ἀλλήλους· πλείους δὲ φεύγουσι νῦν ἐκ μιᾶς πόλεως ἢ πρότερον ἐξ ἁπάσης τῆς Πελοποννήσου. καὶ τοσούτων ἀπηριθμημένων κακῶν, πολὺ πλείω τὰ παραλελειμμένα τῶν εἰρημένων ἐστίν· οὐδὲν γὰρ ὅ τι τῶν δεινῶν ἢ χαλεπῶν οὐκ ἐνταῦθα συνδεδράμηκεν.", "st": "6.68"}, {"sp": "N", "t": "ὧν οἱ μὲν ἤδη μεστοὶ τυγχάνουσιν ὄντες, οἱ δὲ διὰ ταχέων ἐμπλησθήσονται, καὶ ζητήσουσί τινα τῶν παρόντων πραγμάτων εὑρεῖν ἀπαλλαγήν. μὴ γὰρ οἴεσθ’ αὐτοὺς μενεῖν ἐπὶ τούτοις· οἵτινες γὰρ εὖ πράττοντες ἀπεῖπον, πῶς ἂν οὗτοι κακοπαθοῦντες πολὺν χρόνον καρτερήσειαν; ὥστ’ οὐ μόνον ἢν μαχόμενοι νικήσωμεν, ἀλλ’ ἐὰν ἡσυχίαν ἔχοντες περιμείνωμεν, ὄψεσθ’ αὐτοὺς μεταβαλλομένους μένους καὶ τὴν ἡμετέραν συμμαχίαν σωτηρίαν αὑτῶν εἶναι νομίζοντας. τὰς μὲν οὖν ἐλπίδας ἔχω τοιαύτας.", "st": "6.69"}, {"sp": "N", "t": "τοσοῦτον δ’ ἀπέχω τοῦ ποιῆσαί τι τῶν προσταττομένων, ὥστ’ εἰ μηδὲν γίγνοιτο τούτων μηδὲ βοηθείας μηδαμόθεν τυγχάνοιμεν, ἀλλὰ τῶν Ἑλλήνων οἱ μὲν ἀδικοῖεν ἡμᾶς οἱ δὲ περιορῷεν, οὐδ’ ἂν οὕτω μεταγνοίην, ἀλλὰ πάντας ἂν τοὺς ἐκ τοῦ πολέμου κινδύνους ὑπομείναιμι πρὶν ποιήσασθαι τὰς ὁμολογίας ταύτας. αἰσχυνθείην γὰρ ἂν ὑπὲρ ἀμφοτέρων, εἴτε καταγνοίημεν τῶν προγόνων ὡς ἀδίκως Μεσσηνίους ἀφείλοντο τὴν χώραν, εἴτ’ ἐκείνων ὀρθῶς κτησαμένων καὶ προσηκόντως ἡμεῖς παρὰ τὸ δίκαιον συγχωρήσαιμέν τι περὶ αὐτῆς.", "st": "6.70"}, {"sp": "N", "t": "τούτων μὲν οὖν οὐδέτερον ποιητέον, σκεπτέον δ’ ὅπως ἀξίως ἡμῶν αὐτῶν πολεμήσομεν, καὶ μὴ τοὺς εἰθισμένους ἐγκωμιάζειν τὴν πόλιν ἐλέγξομεν ψευδεῖς ὄντας, ἀλλὰ τοιούτους ἡμᾶς αὐτοὺς παρασχήσομεν, ὥστε δοκεῖν ἐκείνους ἐλάττω τῶν ὑπαρχόντων εἰρηκέναι περὶ ἡμῶν.", "st": "6.71"}, {"sp": "N", "t": "οἶμαι μὲν οὖν οὐδὲν συμβήσεσθαι δεινότερον τῶν νῦν παρόντων, ἀλλὰ τοὺς ἐχθροὺς τοιαῦτα βουλεύσεσθαι καὶ πράξειν, ἐξ ὧν ἐπανορθώσουσιν ἡμᾶς· ἂν δ’ ἄρα ψευσθῶμεν τῶν ἐλπίδων καὶ πανταχόθεν ἐξειργώμεθα καὶ μηδὲ τὴν πόλιν ἔτι δυνώμεθα διαφυλάττειν, χαλεπὰ μέν ἐστιν ἃ μέλλω λέγειν, ὅμως δ’ οὐκ ὀκνήσω παρρησιάσασθαι περὶ αὐτῶν. καὶ γὰρ ἐξαγγελθῆναι τοῖς Ἕλλησι καλλίω ταῦτ’ ἐστί, καὶ μᾶλλον ἁρμόττοντα τοῖς ἡμετέροις φρονήμασιν, ὧν ἔνιοί τινες ἡμῖν συμβουλεύουσιν.", "st": "6.72"}, {"sp": "N", "t": "φημὶ γὰρ χρῆναι τοὺς μὲν γονέας τοὺς ἡμετέρους αὐτῶν καὶ τοὺς παῖδας καὶ τὰς γυναῖκας καὶ τὸν ὄχλον τὸν ἄλλον ἐκ τῆς πόλεως ἐκπέμψαι, τοὺς μὲν εἰς Σικελίαν, τοὺς δ’ εἰς Κυρήνην, τοὺς δ’ εἰς τὴν ἤπειρον (ἄσμενοι δ’ αὐτοὺς ἅπαντες οὗτοι δέξονται καὶ χώρᾳ πολλῇ καὶ ταῖς ἄλλαις ταῖς περὶ τὸν βίον εὐπορίαις, οἱ μὲν χάριν ἀποδιδόντες ὧν εὖ πεπόνθασιν, οἱ δὲ κομιεῖσθαι προσδοκῶντες ὧν ἂν προϋπάρξωσιν),", "st": "6.73"}, {"sp": "N", "t": "ὑπολειφθέντας δὲ τοὺς βουλομένους καὶ δυναμένους κινδυνεύειν τῆς μὲν πόλεως ἀφεῖσθαι καὶ τῶν ἄλλων κτημάτων, πλὴν ὅσα ἂν οἷοί τ’ ὦμεν ἀπενέγκασθαι μεθ’ ἡμῶν αὐτῶν, καταλαβόντας δὲ χωρίον, ὅ τι ἂν ἐχυρώτατον ᾖ καὶ πρὸς τὸν πόλεμον συμφορώτατον, ἄγειν καὶ φέρειν τοὺς πολεμίους καὶ κατὰ γῆν καὶ κατὰ θάλατταν, ἕως ἂν παύσωνται τῶν ἡμετέρων ἀμφισβητοῦντες.", "st": "6.74"}, {"sp": "N", "t": "καὶ ταῦτ’ ἐὰν τολμήσωμεν καὶ μὴ κατοκνήσωμεν, ὄψεσθε τοὺς νῦν ἐπιτάττοντας ἱκετεύοντας καὶ δεομένους ἡμῶν Μεσσήνην ἀπολαβεῖν καὶ ποιήσασθαι τὴν εἰρήνην. ποία γὰρ ἂν τῶν πόλεων τῶν ἐν Πελοποννήσῳ τοιοῦτον πόλεμον ὑπομείνειεν, οἷον εἰκὸς γενέσθαι βουληθέντων ἡμῶν; τίνες δ’ οὐκ ἂν ἐκπλαγεῖεν καὶ δείσαιεν στρατόπεδον συνιστάμενον τοιαῦτα μὲν διαπεπραγμένον, δικαίως δὲ τοῖς αἰτίοις τούτων ὠργισμένον, ἀπονενοημένως δὲ πρὸς τὸ ζῆν διακείμενον,", "st": "6.75"}, {"sp": "N", "t": "καὶ τῷ μὲν σχολὴν ἄγειν καὶ μηδὲ περὶ ἓν ἄλλο διατρίβειν ἢ περὶ τὸν πόλεμον τοῖς ξενικοῖς στρατεύμασιν ὡμοιωμένον, ταῖς δ’ ἀρεταῖς καὶ τοῖς ἐπιτηδεύμασι τοιοῦτον οἷον ἐξ ἁπάντων ἀνθρώπων οὐδεὶς ἂν συντάξειεν, ἔτι δὲ μηδεμιᾷ πολιτείᾳ τεταγμένῃ χρώμενον, ἀλλὰ θυραυλεῖν καὶ πλανᾶσθαι κατὰ τὴν χώραν δυνάμενον καὶ ῥᾳδίως μὲν ὅμορον οἷς ἂν βούληται γιγνόμενον, τοὺς δὲ τόπους ἅπαντας τοὺς πρὸς τὸν πόλεμον συμφέροντας πατρίδας εἶναι νομίζον;", "st": "6.76"}, {"sp": "N", "t": "ἐγὼ μὲν γὰρ οἶμαι τῶν λόγων μόνον ῥηθέντων τούτων καὶ διασπαρέντων εἰς τοὺς Ἕλληνας εἰς πολλὴν ταραχὴν καταστήσεσθαι τοὺς ἐχθροὺς ἡμῶν, ἔτι δὲ μᾶλλον, ἢν καὶ τέλος ἐπιθεῖναι τούτοις ἀναγκασθῶμεν. τίνα γὰρ οἰηθῶμεν αὐτοὺς γνώμην ἕξειν, ὅταν αὐτοὶ μὲν κακῶς πάσχωσιν, ἡμᾶς δὲ μηδὲν δύνωνται ποιεῖν;", "st": "6.77"}, {"sp": "N", "t": "καὶ τὰς μὲν αὑτῶν πόλεις ἴδωσιν εἰς πολιορκίαν καθεστηκυίας, τὴν δ’ ἡμετέραν οὕτω διεσκευασμένην ὥστε μηκέτι τῇ συμφορᾷ ταύτῃ περιπεσεῖν; ἔτι δὲ τὴν τῶν σωμάτων τροφὴν ἡμῖν μὲν ῥᾳδίαν οὖσαν ἔκ τε τῶν ὑπαρχόντων καὶ τῶν ἐκ τοῦ πολέμου γιγνομένων, αὑτοῖς δὲ χαλεπὴν διὰ τὸ μὴ ταὐτὸν εἶναι στρατόπεδόν τε τοιοῦτον διοικεῖν καὶ τοὺς ὄχλους τοὺς ἐν ταῖς πόλεσι διατρέφειν;", "st": "6.78"}, {"sp": "N", "t": "ὃ δὲ πάντων ἄλγιστον ἐκείνοις, ὅταν τοὺς μὲν ἡμετέρους οἰκείους ἐν πολλαῖς εὐπορίαις πυνθάνωνται γεγενημένους, τοὺς δ’ αὑτῶν ὁρῶσιν καθ’ ἑκάστην τὴν ἡμέραν τῶν ἀναγκαίων ἐνδεεῖς ὄντας, καὶ μηδ’ ἐπικουρῆσαι δύνωνται τοῖς κακοῖς τούτοις, ἀλλ’ ἐργαζόμενοι μὲν τὴν χώραν τὰ σπέρματα προσαπολλύωσιν, ἀργὸν δὲ περιορῶντες μηδένα χρόνον ἀνταρκεῖν οἷοί τ’ ὦσιν.", "st": "6.79"}, {"sp": "N", "t": "ἀλλὰ γὰρ ἴσως ἀθροισθέντες καὶ κοινὸν ποιησάμενοι στρατόπεδον παρακολουθήσουσι, καὶ κωλύσουσιν ἡμᾶς κακῶς ποιεῖν αὐτούς. καὶ τί ἂν εὐξαίμεθα μᾶλλον ἢ λαβεῖν πλησιάζοντας καὶ παρατεταγμένους καὶ περὶ τὰς αὐτὰς δυσχωρίας ἡμῖν ἀντιστρατοπεδεύοντας ἀνθρώπους ἀτάκτους καὶ μιγάδας καὶ πολλοῖς ἄρχουσι χρωμένους; οὐδὲν γὰρ ἂν πολλῆς πραγματείας δεήσειεν, ἀλλὰ ταχέως ἂν αὐτοὺς ἐξαναγκάσαιμεν ἐν τοῖς ἡμετέροις καιροῖς ἀλλὰ μὴ τοῖς αὑτῶν ποιήσασθαι τοὺς κινδύνους.", "st": "6.80"}, {"sp": "N", "t": "ἐπιλίποι δ’ ἂν τὸ λοιπὸν μέρος τῆς ἡμέρας, εἰ τὰς πλεονεξίας τὰς ἐσομένας λέγειν ἐπιχειρήσαιμεν. ἐκεῖνο δ’ οὖν πᾶσι φανερόν, ὅτι τῶν Ἑλλήνων διενηνόχαμεν οὐ τῷ μεγέθει τῆς πόλεως οὐδὲ τῷ πλήθει τῶν ἀνθρώπων, ἀλλ’ ὅτι τὴν πολιτείαν ὁμοίαν κατεστησάμεθα στρατοπέδῳ καλῶς διοικουμένῳ καὶ πειθαρχεῖν ἐθέλοντι τοῖς ἄρχουσιν. ἢν οὖν εἰλικρινὲς τοῦτο ποιήσωμεν, ὃ μιμησαμένοις ἡμῖν συνήνεγκεν, οὐκ ἄδηλον ὅτι ῥᾳδίως τῶν πολεμίων ἐπικρατήσομεν.", "st": "6.81"}, {"sp": "N", "t": "ἴσμεν δὲ καὶ τοὺς οἰκιστὰς ταυτησὶ τῆς πόλεως γενομένους, ὅτι μικρὸν μὲν στρατόπεδον εἰς τὴν Πελοπόννησον εἰσῆλθον ἔχοντες, πολλῶν δὲ καὶ μεγάλων πόλεων ἐκράτησαν. καλὸν οὖν μιμήσασθαι τοὺς προγόνους, καὶ πάλιν ἐπὶ τὴν ἀρχὴν ἐπανελθόντας, ἐπειδὴ προσεπταίκαμεν, πειραθῆναι τὰς τιμὰς καὶ τὰς δυναστείας ἀναλαβεῖν, ἃς πρότερον ἐτυγχάνομεν ἔχοντες.", "st": "6.82"}, {"sp": "N", "t": "πάντων δ’ ἂν δεινότατον ποιήσαιμεν, εἰ συνειδότες Ἀθηναίοις ἐκλιποῦσι τὴν αὑτῶν χώραν ὑπὲρ τῆς τῶν Ἑλλήνων ἐλευθερίας, ἡμεῖς μηδ’ ὑπὲρ τῆς ἡμετέρας αὐτῶν σωτηρίας ἀφέσθαι τῆς πόλεως τολμήσαιμεν, ἀλλὰ δέον ἡμᾶς παράδειγμα τῶν τοιούτων ἔργων τοῖς ἄλλοις παρέχειν, μηδὲ μιμήσασθαι τὰς ἐκείνων πράξεις ἐθελήσαιμεν.", "st": "6.83"}, {"sp": "N", "t": "ἔτι δὲ τούτου καταγελαστότερον, εἰ Φωκαεῖς μὲν φεύγοντες τὴν βασιλέως τοῦ μεγάλου δεσποτείαν, ἐκλιπόντες τὴν Ἀσίαν εἰς Μασσαλίαν ἀπῴκησαν, ἡμεῖς δ’ εἰς τοσοῦτον μικροψυχίας ἔλθοιμεν ὥστε τὰ προστάγματα τούτων ὑπομεῖναι, ὧν ἄρχοντες ἅπαντα τὸν χρόνον διετελέσαμεν.", "st": "6.84"}, {"sp": "N", "t": "χρὴ δὲ μὴ περὶ τὴν ἡμέραν ταύτην ταῖς ψυχαῖς διατρίβειν, ἐν ᾗ δεήσει χωρίζειν τοὺς οἰκειοτάτους ἀφ’ ἡμῶν αὐτῶν, ἀλλ’ ἐπ’ ἐκείνους τοὺς χρόνους ἀφορᾶν, ἐν οἷς περιγενόμενοι τῶν ἐχθρῶν ἀνορθώσομεν μὲν τὴν πόλιν, κομιούμεθα δὲ τοὺς ἡμετέρους αὐτῶν, ἐπιδειξόμεθα δὲ πᾶσιν ὅτι νῦν μὲν ἀδίκως δεδυστυχήκαμεν, τὸν δὲ παρελθόντα χρόνον δικαίως τῶν ἄλλων πλέον ἔχειν ἠξιοῦμεν.", "st": "6.85"}, {"sp": "N", "t": "ἔχει δ’ οὕτως· ἐγὼ τούτους εἴρηκα τοὺς λόγους, οὐχ ὡς δέον ἡμᾶς ἤδη ταῦτα πράττειν, οὐδ’ ὡς οὐδεμιᾶς ἄλλης ἐνούσης ἐν τοῖς πράγμασι σωτηρίας, ἀλλὰ βουλόμενος ὑμῶν προτρέψασθαι τὰς γνώμας, ὡς καὶ ταύτας τὰς συμφορὰς καὶ πολὺ δεινοτέρας τούτων ὑπομενετέον ἡμῖν, πρὶν ὑπὲρ Μεσσήνης ποιήσασθαι συνθήκας οἵας κελεύουσιν ἡμᾶς.", "st": "6.86"}, {"sp": "N", "t": "οὐχ οὕτω δ’ ἂν προθύμως ἐπὶ τὸν πόλεμον ὑμᾶς παρεκάλουν, εἰ μὴ τὴν εἰρήνην ἑώρων ἐξ ὧν μὲν ἐγὼ λέγω καλὴν καὶ βεβαίαν γενησομένην, ἐξ ὧν δ’ ἔνιοί τινες συμβουλεύουσιν, οὐ μόνον αἰσχρὰν ἐσομένην, ἀλλ’ οὐδὲ χρόνον οὐδένα παραμενοῦσαν. ἢν γὰρ παρακατοικισώμεθα τοὺς Εἵλωτας καὶ τὴν πόλιν ταύτην περιίδωμεν αὐξηθεῖσαν, τίς οὐκ οἶδεν ὅτι πάντα τὸν βίον ἐν ταραχαῖς καὶ κινδύνοις διατελοῦμεν ὄντες; ὥσθ’ οἱ περὶ ἀσφαλείας διαλεγόμενοι λελήθασιν αὑτοὺς τὴν μὲν εἰρήνην ὀλίγας ἡμέρας ἡμῖν ποιοῦντες, τὸν δὲ πόλεμον εἰς ἅπαντα τὸν χρόνον κατασκευάζοντες.", "st": "6.87"}, {"sp": "N", "t": "ἡδέως δ’ ἂν αὐτῶν πυθοίμην, ὑπὲρ τίνων οἴονται χρῆναι μαχομένους ἡμᾶς ἀποθνήσκειν· οὐχ ὅταν οἱ πολέμιοι προστάττωσί τι παρὰ τὸ δίκαιον καὶ τῆς χώρας ἀποτέμνωνται καὶ τοὺς οἰκέτας ἐλευθερῶσι; καὶ τούτους μὲν κατοικίζωσιν εἰς ταύτην ἣν ἡμῖν οἱ πατέρες κατέλιπον, ἡμᾶς δὲ μὴ μόνον τῶν ὄντων ἀποστερῶσιν, ἀλλὰ καὶ πρὸς τοῖς ἄλλοις κακοῖς εἰς ὀνείδη καθιστῶσιν;", "st": "6.88"}, {"sp": "N", "t": "ἐγὼ μὲν γὰρ ὑπὲρ τούτων οὐ μόνον πόλεμον ἀλλὰ καὶ φυγὰς καὶ θανάτους οἴομαι προσήκειν ἡμῖν ὑπομένειν· πολὺ γὰρ κρεῖττον ἐν ταῖς δόξαις αἷς ἔχομεν τελευτῆσαι τὸν βίον μᾶλλον ἢ ζῆν ἐν ταῖς ἀτιμίαις, ἃς ληψόμεθα ποιήσαντες ἃ προστάττουσιν ἡμῖν. εἰ δὲ δεῖ μηδὲν ὑποστειλάμενον εἰπεῖν, αἱρετώτερον ἡμῖν ἐστιν ἀναστάτοις γενέσθαι μᾶλλον ἢ καταγελάστοις ὑπὸ τῶν ἐχθρῶν. τοὺς γὰρ ἐν ἀξιώμασι καὶ φρονήμασι τηλικούτοις βεβιωκότας δυοῖν δεῖ θάτερον, ἢ πρωτεύειν ἐν τοῖς Ἕλλησιν, ἢ παντάπασιν ἀνῃρῆσθαι, μηδὲν ταπεινὸν διαπραξαμένους ἀλλὰ καλὴν τὴν τελευτὴν τοῦ βίου ποιησαμένους.", "st": "6.89"}, {"sp": "N", "t": "ἃ χρὴ διαλογισαμένους μὴ φιλοψυχεῖν, μηδ’ ἐπακολουθεῖν ταῖς τῶν συμμάχων γνώμαις, ὧν ἡγεῖσθαι πρότερον ἠξιοῦμεν, ἀλλ’ αὐτοὺς σκεψαμένους ἑλέσθαι μὴ τὸ τούτοις ῥᾷστον, ἀλλ’ ὃ πρέπον ἔσται τῇ Λακεδαίμονι καὶ τοῖς πεπραγμένοις ἡμῖν. περὶ γὰρ τῶν αὐτῶν οὐχ ὁμοίως ἅπασι βουλευτέον, ἀλλ’ ὡς ἂν ἐξ ἀρχῆς ἕκαστοι τοῦ βίου ποιήσωνται τὴν ὑπόθεσιν.", "st": "6.90"}, {"sp": "N", "t": "Ἐπιδαυρίοις μὲν γὰρ καὶ Κορινθίοις καὶ Φλιασίοις οὐδεὶς ἂν ἐπιπλήξειεν, εἰ μηδενὸς ἄλλου φροντίζοιεν ἢ τοῦ διαγενέσθαι καὶ περιποιῆσαι σφᾶς αὐτούς· Λακεδαιμονίους δ’ οὐχ οἷόν τ’ ἐστὶν ἐκ παντὸς τρόπου ζητεῖν τὴν σωτηρίαν, ἀλλ’ ἂν μὴ προσῇ τὸ καλῶς τῷ σώζεσθαι, τὸν θάνατον ἡμῖν μετ’ εὐδοξίας αἱρετέον ἐστί. τοῖς γὰρ ἀρετῆς ἀμφισβητοῦσιν ὑπὲρ οὐδενὸς οὕτω σπουδαστέον, ὡς ὑπὲρ τοῦ μηδὲν αἰσχρὸν φανῆναι πράττοντας.", "st": "6.91"}, {"sp": "N", "t": "εἰσὶ δ’ αἱ τῶν πόλεων κακίαι καταφανεῖς οὐχ ἧττον ἐν τοῖς τοιούτοις βουλεύμασιν ἢ τοῖς ἐν τῷ πολέμῳ κινδύνοις. τῶν μὲν γὰρ ἐκεῖ γιγνομένων τὸ πλεῖστον μέρος τῇ τύχῃ μέτεστι, τὸ δ’ ἐνθάδε γνωσθὲν αὐτῆς τῆς διανοίας σημεῖόν ἐστιν. ὥσθ’ ὁμοίως ἡμῖν φιλονικητέον ἐστὶν ὑπὲρ τῶν ἐνθάδε ψηφισθησομένων, ὥσπερ ὑπὲρ τῶν ἐν τοῖς ὅπλοις ἀγώνων.", "st": "6.92"}, {"sp": "N", "t": "θαυμάζω δὲ τῶν ὑπὲρ μὲν τῆς ἰδίας δόξης ἀποθνήσκειν ἐθελόντων, ὑπὲρ δὲ τῆς κοινῆς μὴ τὴν αὐτὴν γνώμην ἐχόντων· ὑπὲρ ἧς ὁτιοῦν πάσχειν ἄξιον, ὥστε μὴ καταισχῦναι τὴν πόλιν, μηδὲ περιιδεῖν τὴν τάξιν λιποῦσαν, εἰς ἣν οἱ πατέρες κατέστησαν αὐτήν. πολλῶν δὲ πραγμάτων ἡμῖν καὶ δεινῶν ἐφεστώτων, ἃ δεῖ διαφυγεῖν,", "st": "6.93"}, {"sp": "N", "t": "ἐκεῖνο μάλιστα φυλακτέον, ὅπως μηδὲν ἀνάνδρως φανησόμεθα διαπραττόμενοι μηδὲ συγχωροῦντες τοῖς πολεμίοις παρὰ τὸ δίκαιον. αἰσχρὸν γὰρ τοὺς ἄρξαι τῶν Ἑλλήνων ἀξιωθέντας ὀφθῆναι τὸ προσταττόμενον ποιοῦντας, καὶ τοσοῦτον ἀπολειφθῆναι τῶν προγόνων, ὥστε τοὺς μὲν ὑπὲρ τοῦ τοῖς ἄλλοις ἐπιτάττειν ἐθέλειν ἀποθνήσκειν, ἡμᾶς δ’ ὑπὲρ τοῦ μὴ ποιεῖν τὸ κελευόμενον μὴ τολμᾶν διακινδυνεύειν.", "st": "6.94"}, {"sp": "N", "t": "ἄξιον δὲ καὶ τὴν Ὀλυμπιάδα καὶ τὰς ἄλλας αἰσχυνθῆναι πανηγύρεις, ἐν αἷς ἕκαστος ἡμῶν ζηλωτότερος ἦν καὶ θαυμαστότερος τῶν ἀθλητῶν τῶν ἐν τοῖς ἀγῶσι τὰς νίκας ἀναιρουμένων. εἰς ἃς τίς ἂν ἐλθεῖν τολμήσειεν, ἀντὶ μὲν τοῦ τιμᾶσθαι καταφρονηθησόμενος, ἀντὶ δὲ τοῦ περίστατος ὑπὸ πάντων δι’ ἀρετὴν εἶναι περίβλεπτος ὑπὸ τῶν αὐτῶν ἐπὶ κακία γενησόμενος,", "st": "6.95"}, {"sp": "N", "t": "ἔτι δὲ πρὸς τούτοις ὀψόμενος μὲν τοὺς οἰκέτας ἀπὸ τῆς χώρας ἧς οἱ πατέρες ἡμῖν κατέλιπον ἀπαρχὰς καὶ θυσίας μείζους ἡμῶν ποιουμένους, ἀκουσόμενος δ’ αὐτῶν τοιαύταις βλασφημίαις χρωμένων, οἵαις περ εἰκὸς τοὺς χαλεπώτερον μὲν τῶν ἄλλων δεδουλευκότας, ἐξ ἴσου δὲ νῦν τὰς συνθήκας τοῖς δεσπόταις πεποιημένους· ἐφ’ αἷς ἕκαστος ἡμῶν οὕτως ἂν ἀλγήσειεν, ὡς οὐδεὶς ἂν τῶν ζώντων διὰ λόγου δηλώσειεν.", "st": "6.96"}, {"sp": "N", "t": "ὑπὲρ ὧν χρὴ βουλεύεσθαι, καὶ μὴ τότ’ ἀγανακτεῖν ὅτ’ οὐδὲν ἡμῖν ἔσται πλέον, ἀλλὰ νῦν σκοπεῖν ὅπως μηδὲν συμβήσεται τοιοῦτον. ὡς ἔστιν ἓν τῶν αἰσχρῶν πρότερον μὲν μηδὲ τὰς τῶν ἐλευθέρων ἰσηγορίας ἀνέχεσθαι, νῦν δὲ καὶ τὴν τῶν δούλων παρρησίαν ὑπομένοντας φαίνεσθαι.", "st": "6.97"}, {"sp": "N", "t": "δόξομεν γὰρ τὸν παρελθόντα χρόνον ἀλαζονεύεσθαι, καὶ τὴν μὲν φύσιν ὅμοιοι τοῖς ἄλλοις εἶναι, ταῖς δ’ αὐθαδείαις καὶ ταῖς σεμνότησιν οὐκ ἀληθιναῖς ἀλλὰ πεπλασμέναις κεχρῆσθαι. μηδὲν οὖν ἐνδῶμεν τοιοῦτον τοῖς εἰθισμένοις ἡμᾶς κακολογεῖν, ἀλλὰ τοὺς λόγους αὐτῶν ἐξελέγξαι πειραθῶμεν, ὅμοιοι γενόμενοι τοῖς τῶν προγόνων ἔργοις.", "st": "6.98"}, {"sp": "N", "t": "ἀναμνήσθητε δὲ τῶν ἐν Διπαίᾳ πρὸς Ἀρκάδας ἀγωνισαμένων, οὕς φασιν ἐπὶ μιᾶς ἀσπίδος παραταξαμένους τρόπαιον στῆσαι πολλῶν μυριάδων, καὶ τῶν τριακοσίων τῶν ἐν Θυρέαις ἅπαντας Ἀργείους μάχῃ νικησάντων, καὶ τῶν χιλίων τῶν εἰς Θερμοπύλας ἀπαντησάντων,", "st": "6.99"}, {"sp": "N", "t": "οἳ πρὸς ἑβδομήκοντα μυριάδας τῶν βαρβάρων συμβαλόντες οὐκ ἔφυγον οὐδ’ ἡττήθησαν, ἀλλ’ ἐνταῦθα τὸν βίον ἐτελεύτησαν οὗ περ ἐτάχθησαν, τοιούτους αὑτοὺς παρασχόντες ὥστε τοὺς μετὰ τέχνης ἐγκωμιάζοντας μὴ δύνασθαι τοὺς ἐπαίνους ἐξισῶσαι ταῖς ἐκείνων ἀρεταῖς.", "st": "6.100"}, {"sp": "N", "t": "ἁπάντων οὖν τούτων ἀναμνησθέντες ἐρρωμενέστερον ἀντιλαβώμεθα τοῦ πολέμου, καὶ μὴ περιμένωμεν ὡς ἄλλων τινῶν τὰς παρούσας ἀτυχίας ἰασομένων, ἀλλ’ ἐπειδή περ ἐφ’ ἡμῶν γεγόνασιν, ἡμεῖς αὐτὰς καὶ διαλῦσαι πειραθῶμεν. χρὴ δὲ τοὺς ἄνδρας τοὺς ἀγαθοὺς ἐν τοῖς τοιούτοις καιροῖς φαίνεσθαι διαφέροντας·", "st": "6.101"}, {"sp": "N", "t": "αἱ μὲν γὰρ εὐτυχίαι καὶ τοῖς φαύλοις τῶν ἀνθρώπων τὰς κακίας συγκρύπτουσιν, αἱ δὲ δυσπραξίαι ταχέως καταφανεῖς ποιοῦσιν, ὁποῖοί τινες ἕκαστοι τυγχάνουσιν ὄντες· ἐν αἷς ἡμῖν ἐπιδεικτέον ἐστίν, εἴ τι τῶν ἄλλων ἄμεινον τεθράμμεθα καὶ πεπαιδεύμεθα πρὸς ἀρετήν.", "st": "6.102"}, {"sp": "N", "t": "ἔστι δ’ οὐδὲν ἀνέλπιστον ἐκ τῶν νῦν παρόντων συμβῆναί τι τῶν δεόντων ἡμῖν. οἶμαι γὰρ ὑμᾶς οὐκ ἀγνοεῖν ὅτι πολλαὶ πράξεις ἤδη τοιαῦται γεγόνασιν, ἃς ἐν ἀρχῇ μὲν ἅπαντες ὑπέλαβον εἶναι συμφοράς, καὶ τοῖς παθοῦσι συνηχθέσθησαν, ὕστερον δὲ τὰς αὐτὰς ταύτας ἔγνωσαν μεγίστων ἀγαθῶν αἰτίας γεγενημένας.", "st": "6.103"}, {"sp": "N", "t": "καὶ τί δεῖ τὰ πόρρω λέγειν; ἀλλὰ καὶ νῦν τὰς πόλεις τάς γε πρωτευούσας, λέγω δὲ τὴν Ἀθηναίων καὶ Θηβαίων, εὕροιμεν ἂν οὐκ ἐκ τῆς εἰρήνης μεγάλην ἐπίδοσιν λαβούσας, ἀλλ’ ἐξ ὧν ἐν τῷ πολέμῳ προδυστυχήσασαι πάλιν αὑτὰς ἀνέλαβον, ἐκ δὲ τούτων τὴν μὲν ἡγεμόνα τῶν Ἑλλήνων καταστᾶσαν, τὴν δ’ ἐν τῷ παρόντι τηλικαύτην γεγενημένην ὅσην οὐδεὶς πώποτ’ ἔσεσθαι προσεδόκησεν· αἱ γὰρ ἐπιφάνειαι καὶ λαμπρότητες οὐκ ἐκ τῆς ἡσυχίας ἀλλ’ ἐκ τῶν ἀγώνων γίγνεσθαι φιλοῦσιν.", "st": "6.104"}, {"sp": "N", "t": "ὧν ἡμᾶς ὀρέγεσθαι προσήκει, μήτε τῶν σωμάτων μήτε τῆς ψυχῆς μήτε τῶν ἄλλων ὧν ἔχομεν μηδενὸς φειδομένους. ἢν γὰρ κατορθώσωμεν καὶ τὴν πόλιν εἰς ταὐτὸ καταστῆσαι δυνηθῶμεν, ἐξ ὧνπερ ἐκπέπτωκε, καὶ τῶν προγεγενημένων μᾶλλον θαυμασθησόμεθα, καὶ τοῖς ἐπιγιγνομένοις οὐδεμίαν ὑπερβολὴν ἀνδραγαθίας καταλείψομεν, ἀλλὰ καὶ τοὺς βουλομένους εὐλογεῖν ἡμᾶς ἀπορεῖν ποιήσομεν, ὅ τι τῶν πεπραγμένων ἡμῖν ἄξιον ἐροῦσιν.", "st": "6.105"}, {"sp": "N", "t": "δεῖ δὲ μηδὲ τοῦτο λανθάνειν ὑμᾶς, ὅτι πάντες τῷ συλλόγῳ τούτῳ καὶ τοῖς γνωσθησομένοις ὑφ’ ἡμῶν προσέχουσι τὸν νοῦν. ὥσπερ οὖν ἐν κοινῷ θεάτρῳ τῶν Ἑλλήνων διδοὺς ἔλεγχον ἕκαστος ὑμῶν τῆς αὑτοῦ φύσεως, οὕτω διακείσθω τὴν γνώμην.", "st": "6.106"}, {"sp": "N", "t": "ἔστι δ’ ἁπλοῦν τὸ καλῶς βουλεύσασθαι περὶ τούτων. ἢν μὲν γὰρ ἐθέλωμεν ἀποθνήσκειν ὑπὲρ τῶν δικαίων. οὐ μόνον εὐδοκιμήσομεν, ἀλλὰ καὶ τὸν ἐπίλοιπον χρόνον ἀσφαλῶς ἡμῖν ἐξέσται ζῆν· εἰ δὲ φοβησόμεθα τοὺς κινδύνους, εἰς πολλὰς ταραχὰς καταστήσομεν ἡμᾶς αὐτούς.", "st": "6.107"}, {"sp": "N", "t": "παρακαλέσαντες οὖν ἀλλήλους ἀποδῶμεν τὰ τροφεῖα τῇ πατρίδι, καὶ μὴ περιίδωμεν ὑβρισθεῖσαν τὴν Λακεδαίμονα καὶ καταφρονηθεῖσαν, μηδὲ ψευσθῆναι ποιήσωμεν τῶν ἐλπίδων τοὺς εὔνους ἡμῖν ὄντας, μηδὲ περὶ πλείονος φανῶμεν ποιούμενοι τὸ ζῆν τοῦ παρὰ πᾶσιν ἀνθρώποις εὐδοκιμεῖν,", "st": "6.108"}, {"sp": "N", "t": "ἐνθυμηθέντες ὅτι κάλλιόν ἐστιν ἀντὶ θνητοῦ σώματος ἀθάνατον δόξαν ἀντικαταλλάξασθαι, καὶ ψυχῆς ἣν οὐχ ἕξομεν ὀλίγων ἐτῶν πρίασθαι τοιαύτην εὔκλειαν ἣ πάντα τὸν αἰῶνα τοῖς ἐξ ἡμῶν γενομένοις παραμενεῖ, πολὺ μᾶλλον ἢ μικροῦ χρόνου γλιχομένους μεγάλαις αἰσχύναις ἡμᾶς αὐτοὺς περιβαλεῖν.", "st": "6.109"}, {"sp": "N", "t": "ἡγοῦμαι δ’ οὕτως ἂν ὑμᾶς μάλιστα παροξυνθῆναι πρὸς τὸν πόλεμον, εἰ ταῖς διανοίαις ὥσπερ παρεστῶτας ἴδοιτε τοὺς γονέας καὶ τοὺς παῖδας τοὺς ὑμετέρους αὐτῶν, τοὺς μὲν παρακελευομένους μὴ καταισχῦναι τὸ τῆς Σπάρτης ὄνομα, μηδὲ τοὺς νόμους ἐν οἷς ἐπαιδεύθημεν, μηδὲ τὰς μάχας τὰς ἐφ’ αὑτῶν γενομένας, τοὺς δ’ ἀπαιτοῦντας τὴν χώραν ἣν οἱ πρόγονοι κατέλιπον, καὶ τὴν δυναστείαν τὴν ἐν τοῖς Ἕλλησι, καὶ τὴν ἡγεμονίαν ἥνπερ αὐτοὶ παρὰ τῶν πατέρων παρελάβομεν· πρὸς οὓς οὐδὲν ἂν ἔχοιμεν εἰπεῖν ὡς οὐκ ἀμφότεροι δίκαια τυγχάνουσι λέγοντες.", "st": "6.110"}, {"sp": "N", "t": "οὐκ οἶδ’ ὅ τι δεῖ μακρολογεῖν, πλὴν τοσοῦτον, ὡς πλείστων τῇ πόλει ταύτῃ πολέμων καὶ κινδύνων γεγενημένων οὐδεπώποθ’ οἱ πολέμιοι τρόπαιον ἡμῶν ἔστησαν ἡγουμένου βασιλέως ἐκ τῆς οἰκίας τῆς ἡμετέρας. ἔστι δὲ νοῦν ἐχόντων ἀνδρῶν, οἷσπερ ἂν ἐν ταῖς μάχαις ἡγεμόσι χρώμενοι κατορθῶσι, τούτοις καὶ περὶ τῶν μελλόντων κινδύνων συμβουλεύουσι μᾶλλον ἢ τοῖς ἄλλοις πείθεσθαι.", "st": "6.111"}], []);})();
